RG.HK["24"] = [{"id":"24_ise_naiku","n":"伊勢神宮 内宮（皇大神宮）と宇治橋","yomi":"いせじんぐう ないくう（こうたいじんぐう）とうじばし","cat":"寺社","rank":"S","y":690,"era":["asuka","heian","edo"],"sh":"","ad":"伊勢市宇治館町","st":"近鉄五十鈴川駅・宇治山田駅、JR・近鉄伊勢市駅からバスで «内宮前» 下車すぐ","la":34.4551,"lo":136.7253,"hook":"宇治橋を渡ったとたん、空気が変わる。1300年以上、20年ごとに «まったく同じ新しい社» を建てつづけてきた日本の心のふるさと。","lead":"内宮は、皇室の祖先の神とされる «天照大御神（あまてらすおおみかみ）» をまつる神社です。正式な名前は «皇大神宮»。五十鈴川にかかる宇治橋を渡ると、玉砂利の参道の先に、白木のままの素朴な正宮が建っています。20年に一度、社殿をすべて建て替える «式年遷宮» が、古代から続いています。","story":["宇治橋の前に立つと、大きな木の鳥居が見えます。その先には長さ100mほどの橋。下を流れる五十鈴川は、驚くほど水がすんでいます。«なぜ神さまの家の前に、わざわざ川と橋があるの?» ——橋は、ふだんの世界と神さまの世界の境目だと考えられてきました。橋を渡ることが、心を切りかえる最初の一歩なのです。","『日本書紀』には、こんな話が書かれています。天照大御神を鎮める場所をさがして、垂仁天皇の皇女・倭姫命（やまとひめのみこと）が近江や美濃など各地をめぐり、最後にたどり着いたのが伊勢でした。神さまは «この国に居たいと思う» と告げたといいます。もちろんこれは神話の世界の話で、実際に内宮がいつ始まったのかは、学者のあいだでも議論が続いています。","はっきり記録に残るのは、690年（持統天皇4年）に内宮で最初の式年遷宮が行われたこと。20年ごとに正殿も鳥居も御装束も、同じ形で新しく作り直します。戦国時代には費用が集まらず、120年以上も遷宮が途絶えた時期もありました。それでも尼僧の慶光院清順や周養らが各地をまわって寄付を集め、外宮、つづいて内宮の遷宮を復活させたと伝わります。","«なぜ20年なの?» ——理由は書かれていません。白木と萱ぶきの建物がきれいに保てる年数だから、宮大工の技を親から子へ伝えるのにちょうどよい長さだから、など諸説があります。2013年の第62回遷宮では、檜だけで1万本以上が使われたといわれます。いつ行っても «新しいのに古い» 不思議な社が見られるのは、このしくみのおかげです。","参道を進むと、五十鈴川の «御手洗場（みたらし）» で手を清められます。正宮は石段の上、四重の垣根に囲まれていて、参拝者が入れるのは一番外側の御門の前まで。中の正殿はほとんど見えません。見えないからこそ想像がふくらむ——それも伊勢の魅力です。帰りに宇治橋をふり返ると、朝夕の光で鳥居の見え方が変わるのにも気づくはずです。"],"tl":[["伝承（垂仁天皇の代）","倭姫命が天照大御神を伊勢にまつったと『日本書紀』に記される"],["673年ごろ","天武天皇が皇女の大来皇女を斎王として伊勢に遣わす"],["690年","内宮で最初の式年遷宮が行われたとされる"],["15〜16世紀","戦乱で遷宮が長く途絶える"],["1585年","約120年ぶりに内宮の遷宮が復活"],["江戸時代","«お蔭参り» で数百万人が参拝した年もあると伝わる"],["2013年","第62回式年遷宮"]],"who":[["天照大御神","内宮にまつられる神。皇室の祖先神とされる"],["倭姫命","神を伊勢に導いたと伝わる皇女。別宮の倭姫宮にまつられる"],["持統天皇","最初の式年遷宮のころの天皇（天武天皇の皇后）"],["慶光院清順","戦国時代に遷宮の復活に力をつくしたと伝わる尼僧"]],"deep":["正殿の建築様式は «唯一神明造»。高床の倉のような形で、屋根の両端の «千木» の先が水平に切られているのが内宮、垂直なのが外宮と、細かな違いがあります。","宇治橋の両端の大鳥居は、遷宮で役目を終えた正殿の «棟持柱（むなもちばしら）» を再利用したものといわれます。古い材木を捨てずに次の場所で使うリサイクルの仕組みです。","伊勢神宮は内宮・外宮だけでなく、別宮・摂社・末社などあわせて125の宮社の総称です。正式名称はただ «神宮»。«伊勢» をつけないのは、それだけ特別な存在と考えられてきたからです。","遷宮は «次の敷地» をとなりに用意しておき、交互に建て替えます。いまの正宮のとなりの空き地は «古殿地（こでんち）» と呼ばれ、中央に小さな覆い屋（心御柱を守るもの）が見えます。","古代、伊勢神宮は天皇だけが幣帛をたてまつる場所で、一般の人の個人的な祈りは禁じられていました（私幣禁断）。庶民が気軽にお参りするようになったのは、中世以降に «御師» が広めてからです。","内宮の別宮 «荒祭宮（あらまつりのみや）» には天照大御神の «荒御魂»（活動的な面）がまつられています。正宮の北、少し奥まった場所にあり、参拝の順番として正宮のあとに寄る人が多いです。"],"look":["宇治橋と大鳥居（冬至のころは鳥居の真ん中から朝日が昇る）","五十鈴川の御手洗場","正宮の石段と四重の垣","となりの古殿地","別宮・荒祭宮","神楽殿と参集殿の休み処"],"q":["内宮の社殿を20年ごとに建て替える行事を何という？","«式年遷宮»。690年に内宮で初めて行われたとされ、2013年に第62回が行われました。"],"koji":[{"w":"常若（とこわか）","m":"いつも若々しく、みずみずしくあること。式年遷宮の精神を表すことばとしてよく使われる"}],"myth":"倭姫命の巡行と内宮の創建年代は神話・伝承で、成立時期は諸説。遷宮を20年とした理由も諸説。","img":["伊勢神宮","神宮式年遷宮","五十鈴川","倭姫命"],"wp":"皇大神宮","rel":{"ev":[],"grave":[]},"ph":[["c:8/8d/Naiku_04.jpg",3000,2000,"皇大神宮"],["c:e/e3/Naiku_001.jpg",4288,2848,"伊勢神宮"],["c:8/84/Ise_Shrine_Naiku_1953-8-26_cropped.jpg",984,1188,"神宮式年遷宮"],["c:4/4e/Isejinguu.JPG",960,720,"五十鈴川"],["c:7/7d/PrincessYamatoHime.jpg",875,1000,"倭姫命"]]},{"id":"24_ise_geku","n":"伊勢神宮 外宮（豊受大神宮）","yomi":"いせじんぐう げくう（とようけだいじんぐう）","cat":"寺社","rank":"S","y":478,"era":["kofun","kamakura","edo"],"sh":"","ad":"伊勢市豊川町","st":"JR・近鉄伊勢市駅から歩いて約5分","la":34.4876,"lo":136.7032,"hook":"神さまのごはんを、1500年近く毎日二回つくり続けている場所がある——それが外宮。","lead":"外宮は、衣食住や産業を守る «豊受大御神（とようけのおおみかみ）» をまつる神社です。天照大御神の食事を担当する神さまとして、丹波国から迎えられたと伝わります。伊勢参りは «外宮から先に» が昔からの習わしで、伊勢市駅から歩いてすぐの場所にあります。","story":["804年にまとめられた記録『止由気宮儀式帳（とゆけぐうぎしきちょう）』には、こんな話があります。雄略天皇の夢に天照大御神があらわれ、«ひとりでは食事も安らかにとれない。丹波国の等由気大神（とゆけのおおかみ）を呼んでほしい» と告げた——。こうして豊受大御神が伊勢の山田原に迎えられたと伝わります。«神さまもひとりでごはんは寂しいの?» と思わず聞きたくなる、ちょっと人間らしい話です。","外宮の中心は、神さまの食事をささげる «御饌殿（みけでん）»。ここでは毎日朝と夕方、«日別朝夕大御饌祭（ひごとあさゆうおおみけさい）» というお祭りが行われています。火は木と木をこすり合わせておこし、水は外宮の «上御井神社» の井戸からくむ。ごはん、お水、塩、野菜、魚、果物……。雨の日も台風の日も、この営みは続いてきたとされます。","外宮では、神職の家柄である度会（わたらい）氏が大きな力を持っていました。鎌倉時代の終わりから南北朝時代にかけて、度会家行らは «伊勢神道（度会神道）» という考え方をまとめます。外宮の神は天地のはじめの神でもあると説き、外宮の地位を高めようとしたのです。内宮と外宮のあいだでは、どちらが上かをめぐって激しい争いが起きたこともありました。","江戸時代、伊勢参りの旅人は «外宮先祭（げくうせんさい）»、つまりお祭りも参拝も外宮から先に、というきまりにしたがって、まず山田の町に入りました。外宮の門前には御師（おんし）の屋敷や宿がびっしり並び、全国からの参拝者を迎えました。いまの伊勢市駅前の商店街は、その門前町の名残です。","境内に入ると、火除橋を渡った先に大きな杉林が広がります。勾玉池のそばには «せんぐう館»（2012年開館）があり、正殿の一部を実物大で再現した模型や、遷宮で新しくされる御装束神宝が展示されています。建物の中を見られない正宮の «中身» を知るには、ここに寄るのが近道です。"],"tl":[["478年（伝承）","雄略天皇の代、豊受大御神が丹波国から迎えられたと伝わる"],["692年","外宮で最初の式年遷宮が行われたとされる"],["804年","『止由気宮儀式帳』が朝廷に提出される"],["鎌倉〜南北朝時代","度会家行らが伊勢神道を体系化"],["1563年","慶光院清順の尽力で、途絶えていた外宮の遷宮が復活"],["2012年","せんぐう館が開館"],["2013年","第62回式年遷宮"]],"who":[["豊受大御神","外宮にまつられる神。食物・産業の守り神"],["雄略天皇","夢のお告げで豊受大御神を迎えたと伝わる天皇"],["度会家行","外宮の神職。伊勢神道をまとめた"],["御師","全国から参拝者を案内し、宿を世話した神職たち"]],"deep":["«雄略天皇22年» は西暦に直すと478年ごろにあたりますが、これは儀式帳の記す伝承で、実際の創建年代を確かめる手がかりにはなりません。","外宮の正殿は内宮とほぼ同じ唯一神明造ですが、千木の先端が垂直に切られている（外削ぎ）、鰹木の数が9本（内宮は10本）など、偶数・奇数の違いがあるといわれます。","御饌殿は正宮の垣の内側にある建物で、板を井桁に組んだ «板校倉（いたあぜくら）» という古い形式です。内宮には御饌殿がなく、内宮の神さまの食事も外宮で調えます。","度会家行の伊勢神道は、のちに南朝の北畠親房（『神皇正統記』の著者）の思想にも影響を与えたといわれます。三重県の南北朝史とつながる意外な接点です。","別宮 «多賀宮（たかのみや）» は、豊受大御神の荒御魂をまつる外宮第一の別宮。98段ほどの石段を上った小高い場所にあり、正宮とあわせて参拝するのが一般的です。","明治のはじめ、政府は御師の制度を廃止しました。これにより外宮門前の «御師の町» は大きく姿を変え、旅館や土産物屋の町へと移り変わっていきました。"],"look":["火除橋と表参道の杉並木","正宮（外玉垣南御門から参拝）","多賀宮へ上る石段","御饌殿の屋根（垣の外からわずかに見える）","勾玉池とせんぐう館","三ツ石（遷宮の儀式で使われる場所。触れないこと）"],"q":["伊勢参りは外宮と内宮、どちらから先に参るのが習わし？","外宮から。«外宮先祭» といい、お祭りも外宮から先に行われます。"],"koji":[],"myth":"丹波国からの遷座と雄略天皇の夢告は『止由気宮儀式帳』の伝承。元の鎮座地（丹後の «元伊勢»）には諸説。","img":["伊勢神宮","伊勢神道","度会家行","御師"],"wp":"豊受大神宮","rel":{"ev":[],"grave":[]},"ph":[["c:2/2c/Geku_003.jpg",3000,2000,"豊受大神宮"],["c:e/e3/Naiku_001.jpg",4288,2848,"伊勢神宮"],["c:6/63/Geku20051116.JPG",1600,1200,"度会家行"],["c:7/7a/Oshi_20190826a.jpg",4454,2927,"御師"]]},{"id":"24_okage_yokocho","n":"おはらい町・おかげ横丁（お蔭参りの門前町）","yomi":"おはらいまち・おかげよこちょう","cat":"町","rank":"A","y":1705,"era":["edo","heisei"],"sh":"","ad":"伊勢市宇治中之切町・宇治今在家町","st":"バス «神宮会館前» または «内宮前» から歩いてすぐ","la":34.4602,"lo":136.7249,"hook":"江戸時代、仕事も家もほうり出して «伊勢へ行こう!» と数百万人が歩いた。その熱気の終点がこの町だ。","lead":"おはらい町は、内宮の宇治橋へ続く約800mの参道の町です。その中ほどに、江戸から明治の町並みを再現した «おかげ横丁» があります。«おかげ» という名前は、江戸時代に何度も起きた爆発的な伊勢参りのブーム «お蔭参り» にちなんでいます。","story":["«一生に一度はお伊勢さん» ——江戸時代の人々は、そう言って伊勢をめざしました。当時は自由に旅ができない時代。でも «伊勢参り» なら、関所も通りやすく、許されることが多かったのです。村でお金を積み立てて代表を送る «伊勢講» というしくみもありました。","ところが数十年に一度、とんでもないことが起こります。ある日とつぜん、子どもや奉公人が主人に断りもなく家を飛び出し、伊勢をめざして歩き始めるのです。これが «お蔭参り»（抜け参り）。1705年、1771年、1830年には特に大きなブームが起こり、1830年には数百万人が参ったと伝わります。当時の日本の人口は3000万人ほど。なんと数人に一人の計算です。","«お金もないのにどうやって旅したの?» ——道すがらの人々が、おにぎりやわらじ、宿を無料でふるまったといいます。伊勢参りの人を助けることも «おかげ»、つまり神さまのめぐみを分けてもらうことだと考えられたからです。飼い主の代わりに首に袋をさげて参った «おかげ犬» の話まで伝わっています。","おはらい町の名前は、御師の家で «お祓い» をしてもらったことに由来するといわれます。明治になって御師の制度がなくなり、やがて車社会になると、参道のにぎわいは失われていきました。そこで地元の老舗・赤福が中心となって町並みを見直し、1993年、伊勢の伝統的な建物を移築・再現した «おかげ横丁» が生まれました。","いま、切妻屋根を道に向けた «妻入り» の建物が並び、伊勢うどんや手こね寿司、赤福餅の香りが漂います。«おかげ» ということばには、神さまや周りの人への感謝がこめられています。江戸の旅人たちも、長い旅の終わりにこの道を歩いて、ほっと息をついたのでしょう。"],"tl":[["江戸時代初め","伊勢講が各地に広まる"],["1705年","大規模なお蔭参りが起こる"],["1771年","再びお蔭参りのブーム"],["1830年","最大級のお蔭参り。数百万人が参ったと伝わる"],["1867年","«ええじゃないか» の騒ぎが東海・近畿を中心に広がる"],["1871年","御師の制度が廃止される"],["1993年","おかげ横丁が開業"]],"who":[["御師","各地をまわって伊勢参りを勧め、参拝者を自宅に泊めて案内した神職"],["お蔭参りの人々","子どもや奉公人も多く加わった、江戸時代の «旅する庶民»"],["赤福","門前の老舗。おかげ横丁の整備を中心になって進めた"]],"deep":["お蔭参りがなぜ約60年ごとに起きたのかは、はっきりしません。«伊勢のお札が空から降った» といううわさがきっかけになった例もあり、社会不安や民衆の心理との関係が研究されています。","伊勢の町家の特徴は «妻入り»。屋根の三角形の面を通りに向けた建て方で、神宮の正殿が «平入り» なのでそれを避けたという説がありますが、確かな根拠はありません。","伊勢参りの旅は、伊勢だけで終わりませんでした。多くの人が帰りに奈良・京都・大坂を見物し、なかには四国の金毘羅まで足をのばす人もいました。«お参り» は «観光» の始まりでもあったのです。","1867年の «ええじゃないか» は、空からお札が降ったといううわさとともに人々が歌い踊った騒ぎで、お蔭参りと同じ流れの中にあるとも考えられています。幕末の政治と結びつける説もあります。","伊勢うどんは、太くやわらかいめんに黒いたれをからめて食べる郷土料理。長旅でつかれた参拝客の胃にやさしいように、と言われますが、これは後から語られた由来とも言われます。"],"look":["妻入りの町家が続くおはらい町の通り","おかげ横丁の «おかげ座»（お蔭参りの様子をジオラマで紹介）","五十鈴川沿いの川原と «すし久» など古い建物","赤福本店の «かまど»","宇治橋へのつながり（町の南端）"],"q":["江戸時代、奉公人などが主人に断りなく伊勢へ向かったことを何と呼んだ？","«抜け参り»。お蔭参りの年には、道中の人々が食べ物や宿をふるまって助けました。"],"koji":[{"w":"おかげさまで","m":"人や神仏の助けに感謝するあいさつ。«お蔭参り» の «おかげ» と同じ考え方"}],"myth":"各年のお蔭参りの参加人数は記録ごとに差がある推計。«おかげ犬» や伊勢うどん・妻入りの由来は伝承。","img":["おかげ参り","御師","赤福","ええじゃないか"],"wp":"おかげ横丁","rel":{"ev":[],"grave":[]},"ph":[["c:a/a4/Okage_Yokocho01.JPG",4000,2672,"おかげ横丁"],["c:8/8a/Ando_hiroshige_miyakawanowatashi.jpg",2400,1233,"おかげ参り"],["c:7/7a/Oshi_20190826a.jpg",4454,2927,"御師"],["c:b/b9/Akafuku-mochi_001.jpg",4288,2848,"赤福"],["c:3/37/EeJaNaiKaScene.jpg",1300,929,"ええじゃないか"]]},{"id":"24_saiku","n":"斎宮跡（天皇の代わりに仕えた皇女の都）","yomi":"さいくうあと","cat":"遺跡","rank":"S","y":674,"era":["asuka","nara","heian"],"sh":"国指定史跡","ad":"多気郡明和町斎宮","st":"近鉄斎宮駅からすぐ（斎宮歴史博物館まで歩いて約15分）","la":34.5376,"lo":136.6168,"hook":"都から遠く離れた伊勢に、少女が «天皇の代わり» として暮らす、もうひとつの小さな都があった。","lead":"斎宮（さいくう）は、天皇に代わって伊勢神宮の神に仕えた未婚の皇女 «斎王（さいおう）» の住まいと、それを支える役所があった場所です。飛鳥時代から南北朝時代まで、約660年のあいだに60人あまりの斎王がいたといわれます。いまは田畑の中に発掘された跡が広がり、平安時代の建物が一部復元されています。","story":["斎王は、天皇が代わるたびに、皇族の未婚の女性の中から占いで選ばれました。選ばれた皇女は、都の中で1年、さらに «野宮（ののみや）» で1年、心身を清める暮らしをします。そしていよいよ伊勢へ。この旅を «群行（ぐんこう）» と言い、数百人の行列が5泊6日ほどかけて伊勢へ向かったとされます。","出発の日、天皇は斎王の額に小さな櫛をさし、«京の方におもむきたまうな»（都のほうへ帰ってくるな）と告げたと伝わります。«別れの御櫛» です。«どうしてそんな悲しいことを言うの?» ——斎王が都に戻るのは、天皇の代替わりか、身内の不幸のときだけ。つまり «帰ってくるな» は、天皇の世が長く続くようにという祈りでもあったのです。","最初の斎王とされるのは、天武天皇の皇女・大来皇女（おおくのひめみこ）です。壬申の乱に勝った天武天皇は、伊勢の神への感謝の気持ちから、娘を送り出したといわれます。大来皇女は弟・大津皇子が謀反の疑いで命を落としたとき、その死を悲しむ歌を『万葉集』に残しています。","発掘調査で、斎宮はとても大きな «役所の町» だったことがわかってきました。東西約2km、南北約700mの範囲に、碁盤の目のように区画された道路が走り、500人以上が働いていたとも考えられています。出土品には、都でしか使われないような高級な焼き物や、硯として使われた土器も見つかっています。","南北朝時代、朝廷の力が弱まると斎王の制度も途絶えました。やがて斎宮の場所は田んぼになり、人々の記憶から薄れていきます。1970年代の発掘で «幻の宮» はよみがえり、1979年に国の史跡に。いま、復元された平安時代の建物 «さいくう平安の杜» に立つと、遠い都を思いながらここで暮らした少女たちの姿が、少しだけ近く感じられます。"],"tl":[["673〜674年ごろ","大来皇女が斎王として伊勢へ（制度として確かな最初とされる）"],["8世紀","律令で斎宮寮が整えられる"],["平安時代前期","碁盤目状の区画が整備され、斎宮がもっとも栄える"],["14世紀","後醍醐天皇の代の祥子内親王を最後に斎王が途絶える"],["1970年","本格的な発掘調査が始まる"],["1979年","国の史跡に指定"],["1989年","斎宮歴史博物館が開館"],["2015年","«さいくう平安の杜» で建物3棟を復元"]],"who":[["大来皇女","天武天皇の皇女。確かな記録のある最初の斎王とされる"],["天武天皇","壬申の乱の勝者。斎王の制度を整えたとされる"],["祥子内親王","後醍醐天皇の皇女。最後の斎王とされる"],["在原業平","『伊勢物語』で斎王との恋が描かれる人物（物語上の話）"]],"deep":["斎王の数は、伝説上の人物（倭姫命など）を含めるかどうかで変わり、«60人あまり» や «約60人» と数え方に幅があります。","斎宮寮には «十三司» と呼ばれる部署があり、食事・衣服・馬・掃除などを分担していたと『延喜式』に記されています。まさに小さな朝廷でした。","『伊勢物語』第69段 «狩の使» では、主人公の男と斎王が一夜を語らう場面が描かれ、モデルは在原業平と恬子内親王ともいわれます。ただし物語であり、事実かどうかはわかりません。","斎宮跡からは、ひらがなで文字が書かれた土器（いろは歌の一部を書いたものなど）が見つかっていて、平安時代の文字の広がりを知る貴重な史料になっています。","斎宮と伊勢神宮は約15kmはなれています。斎王が神宮に出向くのは、年に3回の大きなお祭り（三節祭）のときだけでした。ふだんは斎宮で身を清めて暮らしていました。","斎宮歴史博物館の近くには、斎宮の区画全体を10分の1で再現した大きな模型（いつきのみや歴史体験館の周辺）があり、広さを体で感じられます。"],"look":["さいくう平安の杜（復元された正殿・西脇殿・東脇殿）","斎宮歴史博物館（映像展示と出土品）","10分の1史跡全体模型","いつきのみや歴史体験館（十二単や貝合わせの体験）","斎王の森（斎王宮跡とされてきた場所の碑）"],"q":["斎王が伊勢へ向かうとき、天皇が額にさしたものは？","«別れの御櫛»。«都のほうへ帰ってくるな» と告げたと伝わります。"],"koji":[],"myth":"«別れの御櫛» のことばは史料に残る儀式だが、場面の細部は後世の伝え。『伊勢物語』の恋は物語で、モデルも諸説。","img":["斎王","斎宮歴史博物館","大来皇女","伊勢物語"],"wp":"斎宮","rel":{"ev":[],"grave":[]},"ph":[["c:b/ba/Saiku_Heian_no_Mori_1.jpg",4608,3456,"斎宮"],["c:6/66/Saio.jpg",377,700,"斎王"],["c:d/d7/Saik%C3%BB_Historical_Museum2.jpg",4128,3096,"斎宮歴史博物館"],["c:d/de/Shunsho-ise-monogatari.jpg",686,956,"伊勢物語"]]},{"id":"24_sekijuku","n":"関宿（東海道の町並みが丸ごと残る宿場）","yomi":"せきじゅく","cat":"街道","rank":"S","y":1601,"era":["nara","edo"],"sh":"国の重要伝統的建造物群保存地区","ad":"亀山市関町中町・新所・木崎","st":"JR関西本線 関駅から歩いて約10分","la":34.8526,"lo":136.3925,"hook":"電線のない通りに、江戸時代の宿場が1.8kmも続く。«関の山» ということばが生まれた町を歩いてみよう。","lead":"関宿は、江戸と京都を結ぶ東海道五十三次の47番目の宿場町です。約1.8kmの通りに、江戸時代後期から明治にかけての町家がたくさん残り、1984年に国の «重要伝統的建造物群保存地区» に選ばれました。古代には、日本の三つの大きな関所のひとつ «鈴鹿関» があった場所でもあります。","story":["«関» という地名は、古代の関所 «鈴鹿関» に由来します。奈良時代、都を守るために東の入り口に置かれた三つの関所（鈴鹿関・不破関・愛発関）を «三関» と呼びました。天皇が亡くなるなどの大事件が起きると、この関を固く閉じる «固関（こげん）» が行われたのです。«なぜ都からこんなに離れた場所で守るの?» ——東国で反乱が起きても、ここで食い止めるためでした。","江戸時代、1601年に徳川家康が東海道の宿場を定めると、関は交通の要として栄えました。町の東の入り口 «東の追分» からは伊勢神宮へ向かう伊勢別街道が、西の入り口 «西の追分» からは奈良へ向かう大和街道が分かれます。伊勢参りの旅人、大名行列、商人……。いろいろな人がこの町を通っていきました。","町の中には、大名が泊まる «本陣»、ふつうの旅人が泊まる «旅籠（はたご）» がありました。旅籠 «玉屋» は «関で泊まるなら鶴屋か玉屋» とうたわれたほどの有名な宿で、いまは資料館として中を見学できます。2階の小さな部屋に座ると、旅人が格子窓から通りをながめた気分が味わえます。","関宿の祭りには、かつて16台もの山車（やま）が出たといわれます。«これ以上は無理» という意味の «関の山» は、«関の山車ほどりっぱなものはない»、あるいは «関の山車が通れるいっぱいの道幅» から生まれたことばだと伝えられています。ことばの由来には諸説ありますが、町のにぎわいがしのばれます。","明治になって鉄道が別のルートを通ると、関宿は «時間が止まった町» になりました。でもそのおかげで、古い町並みがこわされずに残ったのです。いまは住民が暮らしながら家並みを守っています。瓦屋根に «虫籠窓（むしこまど）»、軒下の «幕板»——ゆっくり見上げながら歩くのが、この町の楽しみ方です。"],"tl":[["7〜8世紀","鈴鹿関が置かれる"],["672年","壬申の乱で大海人皇子側が鈴鹿の山道を押さえる"],["789年","三関が廃止される（固関の儀式は後も続く）"],["1601年","東海道の宿駅制度が定められ、関が宿場となる"],["江戸時代後期","伊勢参りの流行で大いににぎわう"],["1890年","関西鉄道の関駅が開業"],["1984年","国の重要伝統的建造物群保存地区に選定"]],"who":[["徳川家康","東海道に宿場を置き、交通網を整えた"],["歌川広重","『東海道五十三次』で «関 本陣早立» を描いた浮世絵師"],["伊勢参りの旅人","関で東海道から伊勢別街道へ入っていった"]],"deep":["鈴鹿関の正確な位置は長く不明でしたが、亀山市の発掘調査で、関町の西側に築地塀（土の塀）の跡などが見つかり、関の範囲がわかってきています。","関宿は «東追分» «木崎» «中町» «新所» «西追分» の地区に分かれ、中町がもっとも宿場の中心らしいにぎわいを見せた区域です。","«関の地蔵に振袖着せて奈良の大仏婿にとる» という俗謡があるほど、関地蔵院の地蔵菩薩は親しまれてきました。一休さんがこの地蔵の開眼供養をしたという伝説も残っています（伝承）。","宿場の東の入り口にある一の鳥居は、伊勢神宮の宇治橋の鳥居を、式年遷宮のあとで移したものと言われます。つまり伊勢の «古材» がここまで旅をしてきたのです。","関宿の町家には «幕板»（ひさしの下の雨よけの板）や «庵看板»（屋根つきの看板）など、宿場町ならではの工夫が見られます。«百六里庭» という休憩所の «眺関亭» からは、屋根の連なりを見下ろせます。"],"look":["東の追分の鳥居と道標","旅籠玉屋歴史資料館","関まちなみ資料館","関地蔵院の本堂","眺関亭から見る瓦屋根の連なり","西の追分の «ひだりはいがやまとみち» の道標"],"q":["«関の山» ということばの由来と伝わるのは何？","関宿の祭りの «山車»。これ以上ないりっぱな山車、または道幅いっぱいの山車から生まれたといわれます（諸説あり）。"],"koji":[{"w":"関の山","m":"精いっぱいできる限度。«これくらいが関の山だ» のように使う"}],"myth":"«関の山» の語源、一休さんの地蔵開眼、一の鳥居が宇治橋の鳥居の移設である話は伝承・諸説。","img":["鈴鹿関","東海道","関地蔵院","東海道五十三次"],"wp":"関宿","rel":{"ev":["k_tokaido"],"grave":[]},"ph":[["c:e/eb/Tokaido53_Seki.jpg",2987,1938,"関宿"],["c:8/85/Suzuka_no_Seki%2C_1st_excavation_area.jpg",5562,3702,"鈴鹿関"],["c:f/f5/Jizo-in_Seki_main_hall_ac_%282%29.jpg",5973,3971,"関地蔵院"],["c:f/f7/Hiroshige_le_pont_Nihonbashi_%C3%A0_l%27aube.jpg",1618,1080,"東海道五十三次"]]},{"id":"24_iga_ueno_jo","n":"伊賀上野城（藤堂高虎の高石垣）","yomi":"いがうえのじょう","cat":"城","rank":"S","y":1611,"era":["azuchi","edo","showa"],"sh":"国指定史跡","ad":"伊賀市上野丸之内","st":"伊賀鉄道 上野市駅から歩いて約10分","la":34.7702,"lo":136.126,"hook":"堀の水面から約30m。のぞきこむと足がすくむ «日本一級の高石垣» は、大坂の豊臣家をにらむために積まれた。","lead":"伊賀上野城は、上野台地の北の端に築かれた城です。はじめに筒井定次が城を築き、のちに «築城の名人» 藤堂高虎が大きく作りかえました。とくに西側の高石垣は高さ約30mもあり、大坂城と並ぶ日本屈指の高さです。いまの天守は昭和になって建てられた «模擬天守» です。","story":["関ヶ原の戦いから8年後の1608年、伊賀を治めていた筒井定次が、とつぜん領地を取り上げられます。代わりにやってきたのが藤堂高虎でした。«なぜ高虎がここに?» ——伊賀は、大坂と江戸を結ぶ道の途中にあります。まだ大坂城には豊臣秀頼がいました。家康は、もっとも信頼する築城家を、この要の場所に置いたのです。","高虎は、城を西向きに大きく作りかえました。筒井時代の城は東の伊勢側を意識していましたが、高虎は西の大坂への備えを第一に考えたのです。そして本丸の西側に、堀の底から天をつくような石垣を積み上げました。角の部分は長い石を交互に組む «算木積み»。鋭い反りのない、まっすぐな勾配が特徴です。","ところが1612年、建設中の五重の天守が、完成を目前にして暴風で倒れてしまいます。«せっかくの天守がどうして?» ——その後、1615年の大坂夏の陣で豊臣家がほろびると、天守を建てる理由そのものがなくなりました。こうして伊賀上野城は、長いあいだ天守のない城として江戸時代を過ごします。","時がたって昭和の初め、地元出身の代議士・川崎克（かわさき かつ）が «伊賀の文化と産業の象徴を» と私財を投じ、1935年に木造の三層の天守を建てました。これが現在の «伊賀文化産業城»。白い壁が美しく、«白鳳城» という愛称で呼ばれています。史実の天守の姿を再現したものではない、という点には注意が必要です。","天守の中には、藤堂家ゆかりの甲冑などが展示され、最上階の天井には著名人が寄せた書画の色紙がはめこまれています。城のある上野公園には、松尾芭蕉ゆかりの «俳聖殿» や伊賀流忍者博物館もあり、城・俳諧・忍者と、伊賀の歴史をまとめてたどることができます。"],"tl":[["1585年","筒井定次が伊賀に入り、上野に城を築く"],["1608年","筒井定次が改易され、藤堂高虎が伊賀・伊勢に入る"],["1611年","高虎が城の大改修を始め、高石垣を築く"],["1612年","建設中の五重天守が暴風で倒壊"],["1615年","大坂夏の陣。豊臣家がほろぶ"],["1871年","廃藩置県。やがて城の建物は失われる"],["1935年","川崎克が模擬天守（伊賀文化産業城）を建設"]],"who":[["藤堂高虎","築城の名人。津藩の初代藩主として城を大改修"],["筒井定次","最初の城主。のちに改易される"],["川崎克","伊賀出身の政治家。私財で模擬天守を建てた"],["徳川家康","高虎を伊賀・伊勢に配置した"]],"deep":["高石垣の高さは «約30m» とされ、大坂城の本丸東側の高石垣と並んで日本最高クラスとよく言われます。どこから測るか（堀の水面か底か）で数字は少し変わります。","高石垣の上には、忍び返しのような «犬走り（いぬばしり）» がほとんどなく、石垣の天端（てんば）ぎりぎりまで塀が迫っていたと考えられます。攻め手が取りつく場所を与えない設計です。","高虎は伊賀上野城と津城を «本城と支城» のように使い分けました。藩主は津に住み、伊賀には城代家老を置く体制が江戸時代を通じて続きます。","模擬天守は1935年の建築で、木造の再建天守としては早い時期のものです。鉄筋コンクリートではない点で、昭和初期の «復興天守ブーム» の中でもめずらしい例です。","筒井定次の改易の理由は、家臣の訴えや素行の問題など複数が伝わり、はっきりしていません。«豊臣に近すぎた» という見方もありますが推測の域を出ません。"],"look":["本丸西側の高石垣（堀の外側の遊歩道から見上げる）","算木積みの石垣の角","模擬天守の最上階の天井画","城の北側の上野公園の眺め","俳聖殿（芭蕉の旅姿をかたどった建物）"],"q":["伊賀上野城で建設中の五重天守が倒れた原因は？","1612年の暴風です。その後、大坂の陣で豊臣家がほろんだため、天守は再建されませんでした。"],"koji":[{"w":"良禽は木を択んで棲む","m":"かしこい鳥は良い木を選んで巣をつくる。主君を何度も変えた藤堂高虎の生き方を表すことばとしてよく引かれる"}],"myth":"«良禽は木を択んで棲む» を高虎自身の言葉とするのは後世の伝え。石垣の高さは測り方で差がある。","img":["藤堂高虎","筒井定次","俳聖殿"],"wp":"伊賀上野城","rel":{"ev":["jinshin"],"grave":[]},"ph":[["c:a/a0/Igauenozyo.jpg",800,600,"伊賀上野城"],["c:e/e2/Toudou_Takatora.jpg",1056,1096,"藤堂高虎"],["c:2/21/Tsutsui_Sadatsugu_01.jpg",732,1098,"筒井定次"],["c:d/db/Haiseiden.jpg",2592,1944,"俳聖殿"]]},{"id":"24_kagiya_tsuji","n":"鍵屋の辻（伊賀越の仇討ち）","yomi":"かぎやのつじ","cat":"事件","rank":"S","y":1634,"era":["edo"],"sh":"県指定史跡","ad":"伊賀市小田町","st":"伊賀鉄道 上野市駅から歩いて約20分","la":34.77,"lo":136.137,"hook":"«荒木又右衛門の三十六人斬り» ——講談で大げさに語られたその決闘の、本当の舞台がこの辻だ。","lead":"1634年、伊賀上野の城下の入り口 «鍵屋の辻» で、岡山藩士の渡辺数馬が、義兄の荒木又右衛門の助けを借りて、弟のかたき河合又五郎を討ちました。曾我兄弟、赤穂浪士の討ち入りと並ぶ «日本三大仇討ち» のひとつです。いまは史跡公園として整えられ、資料館が建っています。","story":["事件の始まりは1630年、岡山藩（池田家）の城下でした。藩士・河合又五郎が、同じ藩の渡辺源太夫を斬って江戸へ逃げたのです。又五郎は旗本の屋敷にかくまわれました。«大名の家来をなぜ旗本がかばうの?» ——これが大名と旗本のメンツの争いにまで発展し、幕府を巻きこむ大問題になります。","岡山藩主・池田忠雄は、又五郎を討つことを強く望んだまま1632年に亡くなったと伝わります。結局、又五郎は江戸を追われることになりました。殺された源太夫の兄・渡辺数馬は、かたき討ちの許しを得て旅に出ます。助太刀を頼んだのは、姉の夫で、大和郡山藩で剣術を教えていた荒木又右衛門でした。","1634年（寛永11年）11月7日の朝。又五郎の一行が伊賀上野の城下に入ることを知った数馬たちは、城下の東の入り口、伊勢へ向かう道と奈良へ向かう道が分かれる «鍵屋の辻» で待ち伏せしました。辻の角の茶屋 «鍵屋» で身を隠していたといわれます。数馬側はわずか4人、相手は十数人ともいわれる、不利な戦いでした。","斬り合いは長く続きました。又右衛門は護衛の武士たちを相手に戦い、数馬と又五郎の一騎打ちは、数時間におよんだと伝わります。«いつになったら決着がつくのか» と周りが息をのむ中、ついに数馬が又五郎を討ち取りました。のちの講談では «又右衛門の三十六人斬り» と語られましたが、実際に又右衛門が斬ったのは数人だったと考えられています。","かたき討ちのあと、数馬と又右衛門は伊賀を治める藤堂家に身を預けられ、数年後に鳥取藩へ引き取られました。又右衛門はその後まもなく亡くなります。いま辻には «数馬茶屋» が建ち、資料館では決闘のようすを知ることができます。講談や映画で有名になった物語の «ほんとうの姿» を考えながら歩いてみましょう。"],"tl":[["1630年","河合又五郎が岡山藩士・渡辺源太夫を斬って江戸へ逃げる"],["1632年","岡山藩主・池田忠雄が亡くなる"],["1634年11月7日（旧暦）","鍵屋の辻で渡辺数馬と荒木又右衛門が又五郎を討つ"],["1638年","荒木又右衛門が鳥取で亡くなる"],["江戸時代後期〜明治","講談・歌舞伎で «伊賀越» ものが大人気に"],["昭和","史跡として整備され、資料館が建つ"]],"who":[["渡辺数馬","殺された源太夫の兄。かたき討ちの本人"],["荒木又右衛門","数馬の義兄で剣の達人。助太刀として活躍"],["河合又五郎","源太夫を殺して逃げた岡山藩士。討たれた側"],["池田忠雄","岡山藩主。又五郎を討つことを望んだと伝わる"]],"deep":["この事件の本質は «大名対旗本» の対立だったと言われます。旗本側は «外様大名に家来を渡すな» と結束し、幕府の裁定が長引きました。単なる個人の復讐ではない、政治の問題でした。","«三十六人斬り» は講談の誇張です。記録から考えると、又右衛門が討ったのは数人とみられ、数馬側の死者も出ています。講談がつくった «剣豪・又右衛門» 像と史実を区別して楽しみたいところです。","江戸時代の仇討ちは、主君の許しを受け、奉行所に届けを出した «公認の制度» でした。親や兄など目上の者のかたきを討つのが原則で、弟のかたきを兄が討つこの事件は例外的とも言われます。","又右衛門の死は鳥取に移ってすぐだったため、毒殺説などさまざまな憶測を呼びましたが、確かな証拠はありません。","浄瑠璃『伊賀越道中双六』（1783年初演）はこの事件を題材にした作品で、登場人物の名前は変えられています。«沼津» の段は今も歌舞伎で上演される名場面です。"],"look":["鍵屋の辻史跡公園の石碑","伊賀越資料館（決闘の図や関係資料）","数馬茶屋","辻の «道の分かれ目» の地形（伊勢方面と奈良方面）"],"q":["鍵屋の辻の仇討ちで、渡辺数馬の助太刀をした剣の達人は？","荒木又右衛門。数馬の姉の夫で、大和郡山藩の剣術指南役でした。"],"koji":[],"myth":"«三十六人斬り» は講談の誇張。双方の人数、一騎打ちの時間、池田忠雄の遺言、又右衛門の死因は伝承・諸説。","img":["荒木又右衛門","池田忠雄","伊賀越道中双六"],"wp":"伊賀越の仇討ち","rel":{"ev":[],"grave":[]},"ph":[["c:2/2f/IgagoeFukusyuSekihi.jpg",1201,1701,"伊賀越の仇討ち"],["c:1/1e/Araki_Mataemon_%E8%8D%92%E6%9C%A8_%E5%8F%88%E5%8F%B3%E8%A1%9B%E9%96%80_%28BM_2008%2C3037.00101%29.jpg",1050,1530,"荒木又右衛門"],["c:0/0b/%E6%B1%A0%E7%94%B0%E5%BF%A0%E9%9B%84.jpg",1278,2887,"池田忠雄"]]},{"id":"24_motoori_kyotaku","n":"本居宣長旧宅（鈴屋）","yomi":"もとおりのりながきゅうたく（すずのや）","cat":"学び","rank":"S","y":1782,"era":["edo"],"sh":"国指定特別史跡","ad":"松阪市殿町（松坂城跡内）","st":"JR・近鉄松阪駅から歩いて約15分","la":34.5746,"lo":136.5268,"hook":"疲れると鈴を鳴らした、という学者がいた。その小さな2階の書斎で、35年かけて『古事記伝』は書かれた。","lead":"江戸時代の国学者・本居宣長が、12歳から72歳で亡くなるまで暮らした家です。2階の書斎を、宣長は鈴を愛したことから «鈴屋（すずのや）» と名づけました。この家で宣長は、日本最古の歴史書『古事記』を読み解く大著『古事記伝』を書きあげました。明治時代に松坂城跡に移築され、国の特別史跡になっています。","story":["宣長は1730年、松阪の木綿問屋の家に生まれました。でも商売はまったく向いていません。«この子は商人にはなれない» と見ぬいた母は、宣長を京都へ医学の勉強に出します。宣長は医者になって松阪に戻り、昼は子どもの病気を診る町医者として働きながら、夜は古典の研究を続けました。","1763年、宣長の人生を決める出会いがありました。伊勢神宮へ向かう途中の国学者・賀茂真淵が、松阪の宿 «新上屋» に泊まったのです。宣長は真淵をたずね、夜遅くまで語り合いました。«『古事記』を研究したいのです» と言う宣長に、真淵は «まず『万葉集』で古いことばを学びなさい» と助言したといいます。これが有名な «松阪の一夜» です。","宣長と真淵が直接会ったのは、このたった一度だけ。あとは手紙で質問と答えをやりとりしました。翌1764年、宣長は『古事記伝』に取りかかります。漢字ばかりで書かれ、当時ほとんど読めなくなっていた『古事記』を、一語ずつ «古代の日本語» として読み直すという、気の遠くなる作業でした。","1782年、宣長は家の物置だった2階を書斎に作りかえました。4畳半の小さな部屋です。床の間の柱には鈴をたくさん下げた «柱掛鈴» をかけ、研究に疲れると鈴を鳴らして気分を変えたと伝わります。«なぜ鈴なの?» ——澄んだ音が好きだったから、というのが一番の理由のようです。書斎への上り口には、はしごのような階段があり、上ったあとは板でふたをしたといわれます。","1798年、ついに『古事記伝』全44巻が書きあがりました。取りかかってから35年。宣長は69歳になっていました。宣長の門人は全国に約500人。宣長が亡くなったあと、その学問は平田篤胤らに受けつがれ、幕末の思想にも大きな影響を与えます。静かな町医者の小さな書斎から、日本の歴史を動かす考え方が生まれたのです。"],"tl":[["1730年","松阪の商家に生まれる"],["1741年","12歳。この家（魚町）に移り住む"],["1752年","京都へ医学の勉強に出る"],["1763年","賀茂真淵と会う（松阪の一夜）"],["1764年","『古事記伝』を書き始める"],["1782年","2階を書斎に改造し «鈴屋» と名づける"],["1798年","『古事記伝』の執筆を終える"],["1801年","72歳で亡くなる"],["1909年","旧宅が魚町から松坂城跡へ移築される"],["1953年","国の特別史跡に指定"]],"who":[["本居宣長","国学者・医師。『古事記伝』の著者"],["賀茂真淵","国学者。宣長の生涯ただ一度の対面の師"],["平田篤胤","宣長の没後に門人を名乗った国学者"],["本居春庭","宣長の長男。目が不自由になりながら国語学で業績を残す"]],"deep":["«松阪の一夜» は、明治時代に国語の教科書にのって広く知られるようになりました。対面の日付は宣長の日記から宝暦13年5月25日とわかりますが、会話の中身は後世の再構成を含みます。","旧宅はもとは魚町にあり、その跡地（本居宣長宅跡）には家の礎石や松の木などが残っていて、旧宅と合わせて特別史跡に指定されています。長男の本居春庭の旧宅も魚町に残ります。","宣長は、日記・家計簿・患者の記録など膨大な記録を残しました。医者として診察した患者の数や、受け取った薬代まで記録されており、江戸時代の町医者の暮らしを知る第一級の史料です。","宣長の «もののあはれ» 論は、『源氏物語』を仏教や儒教の教えではなく、人の心の動きを描いた作品として読むことを提唱したもので、文学研究でも評価されています。","となりの本居宣長記念館には、『古事記伝』の自筆稿本をはじめ、宣長が子どものころに描いた地図や、自画像などが収められています。"],"look":["鈴屋の書斎（2階は外から見上げる。ふだんは立入不可）","柱掛鈴（記念館に実物やレプリカ）","旧宅の台所・店の間などの間取り","となりの本居宣長記念館","魚町の本居宣長宅跡"],"q":["本居宣長が35年かけて書いた、『古事記』の注釈書の名前は？","『古事記伝』（全44巻）。1764年に書き始め、1798年に書き終えました。"],"koji":[{"w":"敷島の大和心を人問はば朝日に匂ふ山桜花","m":"日本人の心とは何かと問われたら、朝日に照り映える山桜の花のようなものだ、と答えよう——宣長の自画像に添えられた歌"}],"myth":"«松阪の一夜» の会話の細部、鈴を鳴らして気分転換した話は伝承を含む。","img":["本居宣長","古事記伝","賀茂真淵","本居宣長記念館"],"wp":"本居宣長旧宅","rel":{"ev":[],"grave":[]},"ph":[["c:4/48/Suzunoya_Gaikan.jpg",4128,3096,"本居宣長旧宅"],["c:f/f6/%E6%9C%AC%E5%B1%85%E5%AE%A3%E9%95%B702.jpg",1345,1544,"本居宣長"],["c:0/09/Kojiki_den.jpg",4128,3096,"古事記伝"],["c:2/24/Kamo_no_Mabuchi.jpg",1462,1498,"賀茂真淵"]]},{"id":"24_nagashima_ikki","n":"長島一向一揆（願証寺跡と千人塚）","yomi":"ながしまいっこういっき（がんしょうじあととせんにんづか）","cat":"古戦場","rank":"S","y":1574,"era":["muromachi","azuchi"],"sh":"","ad":"桑名市長島町又木ほか","st":"近鉄・JR長島駅から歩いて約20分〜（場所が点在するので車か自転車が便利）","la":35.1,"lo":136.698,"hook":"川にかこまれた «輪中» の島々に、門徒たちが立てこもった。織田信長が三度攻め、最後は二万人ともいわれる人々が炎にのまれた。","lead":"木曽川・長良川・揖斐川が海に注ぐ河口の中州、長島。ここには浄土真宗の寺 «願証寺» を中心に、門徒（信者）たちの自治の世界がありました。1570年から1574年にかけて、門徒たちは織田信長と戦い、三度の攻撃を受けて最後は全滅に近い悲劇を迎えました。いま願証寺の跡には碑が立ち、犠牲者を弔う塚が残っています。","story":["長島は、三つの大きな川がつくる迷路のような中州の島々です。まわりを堤防で囲んだ集落 «輪中（わじゅう）» が点在し、船でしか行き来できない場所も多くありました。«攻めにくく守りやすい» ——ここに、浄土真宗本願寺の一門の寺・願証寺が建ち、周辺の門徒たちが集まって、大名の支配を受けない独自の社会をつくっていました。","1570年、本願寺の顕如は全国の門徒に、信長と戦うよう呼びかけます。長島の門徒たちも立ち上がり、近くの小木江城（尾張）を攻めました。城を守っていた信長の弟・織田信興は、追いつめられて自害します。«弟を殺された信長の怒りはどれほどだったのか»。ここから、長島をめぐる長い戦いが始まりました。","1571年、信長は長島を攻めますが、湿地と川にはばまれて失敗。退くときに門徒の反撃を受け、重臣の氏家卜全が討ち死にしました。1573年の二度目の攻撃も、大きな成果を上げられないまま引き上げます。数や武器でまさっても、水の迷路の中では思うように戦えなかったのです。","1574年、信長は三度目の攻撃に、数万ともいわれる大軍と、九鬼嘉隆らの水軍を動員しました。陸と川と海から長島を完全に囲み、食べ物が入らないようにしたのです。やがて門徒たちは飢えに苦しみ、降伏を申し出て城を出ました。ところが『信長公記』によれば、船で退く人々に鉄砲が撃ちかけられ、激しい戦いになります。","最後まで残った中江・屋長島の砦では、周りを柵で囲まれたうえで火がかけられ、男女二万人ほどが亡くなったと『信長公記』は記しています。数字には誇張がふくまれる可能性もありますが、戦国時代でも特に多くの命が失われた戦いのひとつです。いま長島の町を歩くと、願証寺跡の碑や、犠牲者をまつった塚が静かにたたずんでいます。手を合わせて、この地で亡くなった人々をしのびましょう。"],"tl":[["15世紀末〜16世紀初め","本願寺の蓮淳（蓮如の子）が長島に願証寺をひらく"],["1570年","石山合戦が始まる。長島の門徒が蜂起し、小木江城の織田信興が自害"],["1571年","信長の第一次長島攻め。退却中に氏家卜全が戦死"],["1573年","第二次長島攻め。信長軍は再び撤退"],["1574年","第三次長島攻め。兵糧攻めののち、長島一帯が制圧される"],["1580年","石山本願寺が信長と和睦し、大坂を退去"],["1959年","伊勢湾台風で長島も大きな被害（別カード）"]],"who":[["織田信長","三度にわたって長島を攻めた"],["顕如","本願寺の宗主。全国の門徒に信長との戦いを呼びかけた"],["織田信興","信長の弟。小木江城で門徒に攻められ自害"],["氏家卜全","美濃の武将。第一次長島攻めの退却中に戦死"],["九鬼嘉隆","志摩の水軍の将。第三次長島攻めで海上から包囲"]],"deep":["«二万人» の数字は『信長公記』の記述によるものです。当時の記録の数字には誇張がありうるため、実際の犠牲者数を確かめる方法はありませんが、多くの人が亡くなったことは確かです。","願証寺は、本願寺の一族が住職をつとめる «一家衆» の寺で、伊勢・尾張・美濃の門徒を束ねる地域の中心でした。一揆は寺の命令だけでなく、村々の門徒の結びつきによって支えられていました。","降伏した人々への攻撃について、信長側の記録は «門徒がだまし討ちをした» ようには書かず、信長の強い意志をうかがわせる書き方をしています。比叡山焼き討ち（1571年）と並べて論じられることが多い事件です。","長島の城は、一揆のあと滝川一益の城となり、のちの江戸時代には長島藩の城になりました。現在の長島中学校付近がその跡とされます。","長島一向一揆の戦場は、いまの行政区分でいうと三重県桑名市・愛知県愛西市などにまたがります。川の流れ自体、明治時代の «木曽三川分流工事» で大きく変わっているため、当時の地形を想像するには古地図が役立ちます。"],"look":["願証寺跡の碑（長島町又木）","犠牲者を弔う千人塚などの供養塚","長島城跡（長島中学校付近）","木曽三川が並んで流れる河口の風景"],"q":["長島一向一揆で、門徒たちが拠点にした浄土真宗の寺の名前は？","願証寺。本願寺の一族が住職をつとめ、伊勢・尾張・美濃の門徒の中心でした。"],"koji":[],"myth":"犠牲者数（«二万人» など）は『信長公記』の記述で、実数は不明。願証寺の創建年や千人塚の由来には諸説。","img":["願証寺","石山合戦","織田信興","氏家直元"],"wp":"長島一向一揆","rel":{"ev":[],"grave":[]},"ph":[["c:9/9b/Battle_of_Nagashima.jpg",2000,964,"長島一向一揆"],["c:8/8d/Gansh%C5%8D-ji_in_Kuwana.jpg",1280,960,"願証寺"],["c:6/61/Ishiyama10.jpg",2797,1893,"石山合戦"]]},{"id":"24_yokkaichi_zensoku","n":"四日市ぜんそく（磯津と公害資料館）","yomi":"よっかいちぜんそく（いそづとこうがいしりょうかん）","cat":"昭和","rank":"S","y":1972,"era":["showa"],"sh":"","ad":"四日市市安島（四日市公害と環境未来館）／塩浜地区・磯津","st":"近鉄四日市駅から歩いて約3分（未来館）","la":34.9656,"lo":136.6208,"hook":"«空気を吸うだけで、なぜ苦しいの?» ——豊かさを生んだ工場の煙は、海辺の町の子どもやお年寄りの胸をしめつけた。","lead":"1960年代、四日市の石油化学コンビナートから出た煙にふくまれる亜硫酸ガス（二酸化硫黄）によって、たくさんの人がぜんそくに苦しみました。これが «四日市ぜんそく» で、日本の «四大公害病» のひとつです。1972年、患者たちが起こした裁判で企業の責任が認められ、日本の公害対策を大きく変えました。","story":["戦後、四日市の海岸には、旧海軍の燃料工場の跡地を利用して、大きな石油化学コンビナートがつくられました。1959年ごろから本格的に動き始めると、工場の煙突からは昼も夜も煙が出続けます。町は «日本の工業の未来» として注目され、働く場所も増えました。けれども、その影でおかしなことが起こり始めます。","まず、伊勢湾でとれる魚が «油くさい» と言われ、売れなくなりました。次に、コンビナートのすぐそばの塩浜地区、とくに川をはさんで向かい側の漁師町・磯津で、せきが止まらない人、夜中に息ができなくなる人が急に増えます。«かぜがなかなか治らない» と思っていた人たちが、実は同じ病気にかかっていたのです。窓を閉めても、においと煙は入りこんできました。","三重県立大学の医学者・吉田克己らは、地区ごとの患者数と空気の汚れを調べ、ぜんそくと亜硫酸ガスの関係を明らかにしていきます。一方で、病気の苦しさの中で命を落とす人も出ました。«このままでは、子どもたちの未来がない»——1967年、磯津の患者9人が、コンビナートの6つの会社を相手に、裁判を起こしました。","1972年7月、津地方裁判所四日市支部は、6社が一緒になって空気を汚し、健康被害を引き起こした責任があると認め、患者側の勝訴を言い渡しました。«工場が何社もあって、どこの煙のせいかわからない» という会社側の主張は退けられたのです。この判決をきっかけに、国は公害で病気になった人を補償する法律をつくり、工場から出るガスの量をきびしく規制するようになりました。","いまの四日市の空は、当時とくらべものにならないほどきれいになりました。それは自然にそうなったのではなく、苦しんだ人々が声を上げ、記録を残した人々がいたからです。近鉄四日市駅近くの «四日市公害と環境未来館» では、患者や家族の証言、裁判の記録を見ることができます。亡くなった方々を思いながら、«豊かさ» と «命» のバランスを考えてみましょう。"],"tl":[["1950年代半ば","旧海軍燃料廠の跡地の払い下げが決まり、コンビナート建設へ"],["1959年","第1コンビナートが本格的に稼働"],["1960年ごろ","伊勢湾の «異臭魚» が問題に。塩浜地区でぜんそく患者が増え始める"],["1965年","四日市市が独自に患者の医療費を救済する制度を始める"],["1967年","磯津の患者9人が6社を相手に提訴"],["1972年7月","津地裁四日市支部で原告勝訴の判決"],["1973年","公害健康被害補償法が制定される"],["2015年","四日市公害と環境未来館が開館"]],"who":[["磯津の患者と家族","裁判を起こし、被害を社会に訴えた"],["吉田克己","三重県立大学の医学者。疫学調査で原因を明らかにした"],["澤井余志郎","患者の声や公害の記録を長年書き残した市民"],["野田之一","原告の一人。のちに語り部として体験を伝えた"]],"deep":["四大公害病は、水俣病・新潟水俣病・イタイイタイ病・四日市ぜんそくの4つ。このうち四日市ぜんそくだけが大気汚染によるもので、原因が複数の工場にまたがる点が特徴でした。","判決は、コンビナートの企業どうしが «共同不法行為» にあたるとし、それぞれの工場の煙の量をはっきり分けられなくても、全体として責任を負うと判断しました。これは公害裁判の大きな転換点になりました。","判決のあと、三重県は工場から出る硫黄酸化物を地域全体の量で規制する «総量規制» をいち早く取り入れ、排煙から硫黄分を取り除く装置の導入も進みました。","四日市の煙突は、煙を遠くへ散らすために高くされた時期がありましたが、これは汚れを別の場所に広げるだけで、根本的な解決ではないと批判されました。«薄めればよい» という考え方の限界を示す例です。","未来館は四日市市立博物館と同じ建物にあり、当時の教室でマスクをしてうがいをする子どもたちの写真など、日常の中の公害のようすがわかる展示があります。"],"look":["四日市公害と環境未来館の証言映像","裁判の記録と判決文の展示","当時の塩浜小学校のようすを伝える写真","磯津の漁港と鈴鹿川の河口（対岸にコンビナートが見える）"],"q":["四日市ぜんそくの主な原因となった、工場の煙にふくまれていたガスは？","亜硫酸ガス（二酸化硫黄）。石油を燃やしたときなどに出ます。"],"koji":[],"myth":"","img":["四大公害病","公害","四日市市"],"wp":"四日市ぜんそく","rel":{"ev":[],"grave":[]},"ph":[["c:5/58/%E5%9B%9B%E6%97%A5%E5%B8%82%E3%82%B3%E3%83%B3%E3%83%93%E3%83%8A%E3%83%BC%E3%83%88_-_panoramio.jpg",1200,820,"四日市ぜんそく"],["c:f/ff/Air-pollution-taiwan.JPG",1600,1200,"公害"],["c:9/9c/Yokkaichi_Montage.jpg",800,962,"四日市市"]]},{"id":"24_kumano_kodo_ise","n":"熊野古道伊勢路（馬越峠の石畳）","yomi":"くまのこどういせじ（まごせとうげのいしだたみ）","cat":"街道","rank":"S","y":1700,"era":["heian","edo"],"sh":"国指定史跡（熊野参詣道）・世界遺産","ad":"北牟婁郡紀北町〜尾鷲市（馬越峠）","st":"JR紀勢本線 相賀駅から登り口まで歩いて約25分、峠まで登り約1時間","la":34.093,"lo":136.187,"hook":"苔むした石が、ヒノキの森の奥へどこまでも続く。雨の国・尾鷲の人々が «雨に負けない道» をつくった。","lead":"熊野古道伊勢路は、伊勢神宮から熊野三山（本宮・速玉・那智）へ向かう参詣の道です。尾鷲市と紀北町の境にある馬越峠（まごせとうげ）には、江戸時代に敷かれた美しい石畳がよく残っています。2004年、«紀伊山地の霊場と参詣道» の一部として世界遺産に登録されました。","story":["熊野への道はいくつもありますが、伊勢路は «伊勢参りのあとに熊野へ» という人々が歩いた道です。江戸時代には «伊勢へ七度、熊野へ三度» ということばがあったほど、伊勢と熊野の両方に参ることは大きな願いでした。熊野の先には、西国三十三所の一番札所・那智山青岸渡寺も待っています。","伊勢路の難所は、海に向かって山がせまる «峠» の連続です。馬越峠もそのひとつ。峠道に入ると、両側にはすらりとしたヒノキの林が広がり、足元には大きな平たい石がびっしりと敷かれています。«どうして山の中にこんなに立派な石畳が?» ——その理由は、この土地の雨にあります。","尾鷲は、日本でも有数の «雨の多い町»。年間の雨の量は東京の2倍以上といわれます。土の道のままでは、大雨のたびに道が流され、ぬかるんで歩けなくなってしまいます。そこで人々は、近くでとれる石を一つひとつ運び、すき間なく敷きつめ、水を逃がす «洗い越し» や溝もつくりました。石畳は、雨と闘ってきた人々の知恵のかたまりなのです。","峠の途中には、旅人の安全を見守ってきた地蔵や石碑がひっそり立っています。夜泣きする子どものために祈ったと伝わる地蔵もあります。峠の頂上（標高約325m）に着くと、そこから天狗倉山（てんぐらさん）へ足をのばせば、山の上の大岩から尾鷲湾と町並みを見下ろせます。昔の旅人も、ここで遠くの海を見て、熊野まであと少しと励まされたのかもしれません。","明治時代以降、海沿いに道路や鉄道ができると、峠道は使われなくなり、石畳は長く森の中にうもれていました。地元の人々が掃除や保存活動を続けたことで、いまのように歩ける道として残ったのです。雨の日のあとの石畳はとてもすべります。しっかりした靴で、昔の旅人の気持ちになって一歩ずつ進みましょう。"],"tl":[["平安時代","上皇や貴族の熊野詣でがさかんになる（主に紀伊路・中辺路）"],["室町〜江戸時代","庶民の伊勢参り・熊野詣でが広がり、伊勢路が多く使われる"],["江戸時代","馬越峠などに石畳が整備される"],["明治以降","海沿いの道路・鉄道の開通で峠道が使われなくなる"],["2002年","伊勢路が国の史跡 «熊野参詣道» に追加される"],["2004年","世界遺産 «紀伊山地の霊場と参詣道» に登録"]],"who":[["伊勢参りの旅人","伊勢から熊野、那智の青岸渡寺へと巡礼を続けた"],["尾鷲・紀北の人々","石畳を敷き、のちに保存活動で道を守った"],["西国巡礼者","一番札所・青岸渡寺をめざして伊勢路を歩いた"]],"deep":["世界遺産の «参詣道» には、紀伊路・中辺路・大辺路・小辺路・伊勢路・大峯奥駈道などがあり、伊勢路は三重県側を通る唯一のルートです。道そのものが世界遺産に登録されるのは、国内では珍しい例です。","石畳の石は、地元でとれる硬い岩を使ったといわれます。石の面を平らにそろえ、坂では段をつけて歩きやすくするなど、場所によって敷き方が工夫されています。","馬越峠の道の周りのヒノキ林は、«尾鷲ヒノキ» の産地として知られる人工林です。雨が多く土地がやせているため、ゆっくり育って年輪がつまった丈夫な木になるといわれます。","平安時代の上皇たちの熊野詣では主に京都から紀伊半島の西側を通りました。伊勢路は、東国の庶民が伊勢参りと組み合わせて歩いた «庶民の道» という性格が強いとされます。","伊勢路には、馬越峠のほかにツヅラト峠、八鬼山越え（やきやまごえ）など多くの峠道があり、八鬼山越えは «西国一の難所» とも呼ばれました。"],"look":["馬越峠の石畳（紀北町側の登り口から）","洗い越し・排水の溝の工夫","峠道の地蔵や石碑","峠の頂上と天狗倉山の大岩からの眺め","ふもとの «道の駅 海山» と熊野古道の案内"],"q":["馬越峠の道に立派な石畳が敷かれた一番の理由は？","雨がとても多い土地で、土の道だと大雨で流されたり、ぬかるんだりするからです。"],"koji":[{"w":"伊勢へ七度、熊野へ三度","m":"伊勢神宮と熊野三山への信心の深さを表したことば。何度でも参りたいという気持ちを表す"}],"myth":"石畳の整備年代は区間により異なり、細かな年代は諸説。«夜泣き地蔵» の由来は伝承。","img":["紀伊山地の霊場と参詣道","熊野三山","青岸渡寺"],"wp":"熊野参詣道","rel":{"ev":[],"grave":[]},"ph":[["c:7/73/Daimonzaka25_2048.jpg",1536,2048,"紀伊山地の霊場と参詣道"],["c:b/bb/Seigantoji01.JPG",3264,2448,"青岸渡寺"]]},{"id":"24_tensho_iga","n":"丸山城跡（天正伊賀の乱の発端）","yomi":"まるやまじょうあと（てんしょういがのらん）","cat":"古戦場","rank":"S","y":1579,"era":["azuchi"],"sh":"県指定史跡","ad":"伊賀市枅川（ひじきがわ）","st":"伊賀鉄道 丸山駅から歩いて約15分","la":34.724,"lo":136.133,"hook":"築きかけの城が一夜で燃えた。伊賀の «自由な国» と織田家の、長く苦い戦いはここから始まった。","lead":"丸山城は、織田信長の次男・織田信雄が伊賀を攻める拠点として築こうとした城です。ところが伊賀の侍たちに襲われて焼かれ、これをきっかけに «天正伊賀の乱» が起こりました。一度は伊賀側が信雄軍を打ち破りますが、1581年、信長自身が大軍を送り、伊賀の国は焼きつくされました。","story":["戦国時代の伊賀には、国全体を治める大名がいませんでした。小さな領主（地侍）たちが寄り合いで物事を決め、外から敵が来たら力を合わせて戦う «惣国一揆（そうこくいっき）» という仕組みで国を守っていたのです。«殿さまがいなくて、どうやってまとまるの?» ——掟を定めた文書が残っていて、村々の結束の強さがわかります。","1578年ごろ、伊勢を手に入れていた織田信雄は、伊賀を攻める足がかりとして、家臣の滝川雄利に丸山に城を築かせました。これを知った伊賀の侍たちは、完成前の城に一斉に攻めかかります。城はあっという間に焼かれ、雄利は伊勢へ逃げ帰ったと伝わります。","怒った信雄は、1579年、父の信長にも相談しないまま、三方から伊賀へ攻めこみました。しかし、山や谷を知りつくした伊賀勢は夜討ちやゲリラ戦で反撃し、信雄軍は大敗。重臣の柘植保重（つげ やすしげ）も討ち死にしました。これが «第一次天正伊賀の乱» です。","この知らせを聞いた信長は激しく怒り、信雄にきびしい叱責の手紙を送ったといわれます。«勝手に戦を始め、大事な家臣を失うとは何事か» ——。そして1581年、信長は数万の大軍で伊賀を四方から攻めさせました。«第二次天正伊賀の乱» です。寺社も村も焼かれ、多くの人が命を落としたと伝わります。","丸山城跡は、いまは木の茂る小高い丘です。登ってみると、石垣の一部や曲輪（くるわ）の跡が残り、天守台とみられる場所もあります。ここから見える伊賀の盆地は、山に囲まれた «小さな国» そのもの。伊賀の人々が必死に守ろうとした土地と、戦で失われた命を思いながら歩いてみてください。"],"tl":[["1569年","織田信長が伊勢の北畠氏を降し、信雄が北畠家の養子に"],["1578年ごろ","信雄の命で滝川雄利が丸山城を築き始め、伊賀勢に焼かれる"],["1579年9月","信雄が独断で伊賀に侵攻し大敗（第一次天正伊賀の乱）"],["1581年9月","信長の命で大軍が伊賀に侵攻（第二次天正伊賀の乱）"],["1581年10月ごろ","伊賀が平定される"],["1582年","本能寺の変。直後に伊賀で一揆が再び起こる"]],"who":[["織田信雄","信長の次男。伊賀攻めを始めて失敗した"],["滝川雄利","信雄の家臣。丸山城の築城を任された"],["柘植保重","信雄の重臣。第一次の戦いで討ち死に"],["織田信長","第二次の戦いで大軍を送り、伊賀を平定させた"]],"deep":["『伊賀惣国一揆掟書』は、伊賀の地侍たちが外敵に備えて定めた掟とされる文書で、若者の動員や、敵に通じる者への罰などが書かれています。年代は1560年代とする説が有力ですが、確定はしていません。","天正伊賀の乱の経過を詳しく描く『伊乱記』は、江戸時代に書かれた軍記物で、伊賀側の視点で語られています。犠牲者数や合戦の細部には創作や誇張が含まれるとみられ、そのまま史実とすることはできません。","信長の信雄あての叱責状は『信長公記』などに内容が伝わり、«親子の縁を切るぞ» と書いたといわれます。信長が息子に対してここまで怒った例として有名です。","第二次天正伊賀の乱ののち、伊賀の «忍び» たちが各地に散らばったとされ、これが江戸時代の «伊賀者» の広がりにつながったという見方があります。ただし忍者の実態は史料が少なく、多くは後世のイメージです。","第二次の攻撃では、伊賀・甲賀・大和・伊勢など複数の方向から軍勢が入ったとされ、ルートや人数は史料によって違いがあります。"],"look":["丸山城跡の石垣の残り","天守台とみられる高まり","曲輪の平らな地形と空堀","城跡から見わたす伊賀盆地"],"q":["伊賀の地侍たちが寄り合いで国を守った仕組みを何という？","«惣国一揆»。大名を持たず、掟を定めて団結しました。"],"koji":[],"myth":"丸山城の焼き討ちの経過、第二次の軍勢の数・犠牲者数は『伊乱記』など後世の軍記による部分が大きく諸説。","img":["織田信雄","滝川雄利","伊賀惣国一揆"],"wp":"天正伊賀の乱","rel":{"ev":[],"grave":[]},"ph":[["c:b/be/Oda_Nobukatu.jpg",1285,2393,"織田信雄"]]},{"id":"24_jinshin_iga","n":"壬申の乱 大海人皇子の伊勢路（迹太川の遥拝）","yomi":"じんしんのらん おおあまのおうじのいせじ（とおかわのようはい）","cat":"古戦場","rank":"S","y":672,"era":["asuka"],"sh":"","ad":"四日市市（朝明川流域・大矢知町周辺）ほか伊賀・伊勢の道すじ","st":"近鉄富田駅・JR富田駅周辺から朝明川沿いへ（遥拝の地の碑は事前に場所の確認を）","la":35.008,"lo":136.601,"hook":"吉野を出てわずか3日。追いつめられた皇子は、川のほとりで遠く伊勢の方角に手を合わせた——古代最大の内乱の転機だった。","lead":"672年の «壬申の乱» は、天智天皇の弟・大海人皇子（のちの天武天皇）と、天智天皇の子・大友皇子が皇位を争った古代最大の内乱です。吉野を出た大海人皇子は、伊賀・伊勢を通って美濃へ向かいました。その途中、伊勢の «迹太川（とおかわ）» のほとりで天照大神を遥かに拝んだと『日本書紀』は記しています。","story":["671年、天智天皇は病の床で、弟の大海人皇子に後を継ぐよう求めました。けれど大海人皇子は «出家して吉野に入ります» と断ります。«なぜ断ったの?» ——ここで引き受ければ、天皇の子・大友皇子を推す人々に命をねらわれると考えたからだといわれます。こうして大海人皇子は、わずかな家族と家来をつれて吉野の山に退きました。","翌672年6月、近江の朝廷が兵を集めているという知らせが届きます。大海人皇子は吉野を出発。妻の鸕野讃良皇女（うののさららのひめみこ、のちの持統天皇）もいっしょでした。一行は夜を徹して宇陀から名張へ進み、伊賀の山道を越えていきます。途中の «積殖（つみえ）の山口»（いまの伊賀市柘植あたり）で、近江を脱出してきた長男の高市皇子と合流しました。","鈴鹿の山道を越えて伊勢に入った一行は、6月26日の朝、朝明郡（あさけのこおり）の迹太川のほとりにいました。『日本書紀』はここで、大海人皇子が «天照太神を望拝（たよせにおがむ）» したと記しています。わずかな兵しかいない中、伊勢の神に勝利を祈ったこの場面は、壬申の乱の大きな節目として語られてきました。","その後、大海人皇子は桑名を経て美濃の不破（いまの岐阜県関ケ原町あたり）に本陣を置きます。東国の兵が次々と集まり、高市皇子が全軍を率いて近江へ攻めこみました。1か月ほどの戦いの末、大友皇子は自ら命を絶ち、乱は終わります。翌673年、大海人皇子は飛鳥で即位し、天武天皇となりました。","天武天皇は、この勝利を伊勢の神のおかげと考えたのかもしれません。即位のあと、娘の大来皇女を斎王として伊勢に送り、伊勢神宮の祭りを重んじました。内宮の最初の式年遷宮が行われたのも、天武天皇の妻・持統天皇の時代です。迹太川での祈りは、その後の伊勢神宮の歴史にもつながっているのです。"],"tl":[["671年10月","大海人皇子が出家して吉野に入る"],["671年12月","天智天皇が亡くなる"],["672年6月24日","大海人皇子が吉野を出発"],["672年6月25日ごろ","伊賀の積殖の山口で高市皇子と合流"],["672年6月26日","迹太川のほとりで天照太神を望拝"],["672年7月23日","大友皇子が自害し、乱が終わる"],["673年","大海人皇子が即位（天武天皇）"],["673〜674年ごろ","大来皇女が斎王として伊勢へ"]],"who":[["大海人皇子（天武天皇）","乱に勝って即位した。伊勢の神を重んじた"],["鸕野讃良皇女（持統天皇）","大海人皇子の妻。吉野からの逃避行に同行"],["高市皇子","大海人皇子の長男。軍を率いて活躍"],["大友皇子","天智天皇の子。近江朝廷の中心。乱に敗れる"]],"deep":["«迹太川» がどの川かは諸説あり、四日市市を流れる朝明川とする説が有力です。四日市市内には «天武天皇迹太川御遥拝所跡» とされる碑が建てられていますが、正確な地点は確かめられていません。","日付はすべて『日本書紀』の記事（旧暦）によります。吉野から迹太川まで約3日で進んだ強行軍で、途中の伊賀では «隠（なばり）の駅家» を焼いたと記されています。","大友皇子は即位していたかどうかが古くから議論され、明治時代になって «弘文天皇» の名が贈られました。","『日本書紀』は天武天皇の命で編纂が始まった歴史書なので、乱の記述は勝った側の視点で書かれています。迹太川での遥拝も、伊勢の神の加護を強調する意図があるという見方があります。","伊賀の «積殖の山口» は、のちに徳川家康の «伊賀越え» でも通ったといわれる柘植のあたりとされます。古代と戦国の二つの逃避行が、同じ伊賀の道で重なっているのです。"],"look":["朝明川の流れ（迹太川の有力候補）","遥拝所跡とされる碑","伊賀市柘植あたりの山あいの地形（積殖の山口）","鈴鹿の山並みの眺め"],"q":["壬申の乱のさなか、大海人皇子が迹太川のほとりで遥かに拝んだ神は？","天照太神（天照大御神）。『日本書紀』に «望拝» したと記されています。"],"koji":[],"myth":"迹太川の比定地、遥拝所跡の碑の位置は諸説。記事は勝者側の『日本書紀』による。","img":["天武天皇","高市皇子","弘文天皇","持統天皇"],"wp":"壬申の乱","rel":{"ev":[],"grave":[]},"ph":[["c:f/f3/Fuwanoseki2.JPG",4000,3000,"壬申の乱"],["c:b/b9/%E5%A4%A9%E6%AD%A6%E5%A4%A9%E7%9A%87%E5%BE%A1%E5%BD%B1%E3%80%81%E9%87%91%E5%89%9B%E5%B1%B1%E5%AF%BA%E6%89%80%E8%94%B5.jpg",425,591,"天武天皇"],["c:b/b6/Emperor_Koubunn.jpg",1409,1641,"弘文天皇"],["c:9/9f/Empress_Jito_by_Katsukawa_Shunsho.png",1162,1598,"持統天皇"]]},{"id":"24_shinkun_igagoe","n":"神君伊賀越え（家康の決死の逃避行）","yomi":"しんくんいがごえ","cat":"事件","rank":"S","y":1582,"era":["azuchi"],"sh":"","ad":"伊賀市柘植町（徳永寺）ほか、亀山市加太・鈴鹿市白子など","st":"JR関西本線 柘植駅から歩いて約15分（徳永寺）","la":34.8445,"lo":136.232,"hook":"«本能寺で信長が討たれた!» ——わずかな供と堺にいた家康は、敵だらけの山道を三河へ走った。家康自身が «生涯一の危機» だったとされる3日間。","lead":"1582年6月2日、本能寺の変で織田信長が明智光秀に討たれました。そのとき徳川家康は、わずかな家臣と堺の見物をしていました。家康は明智方や落ち武者狩りの危険の中、伊賀・伊勢の山道を越えて本拠の三河へ逃げ帰ります。これを «神君伊賀越え» と呼びます。ルートには諸説あり、三重県内にも家康ゆかりと伝わる場所が点在します。","story":["その年の5月、家康は信長に招かれて安土城でもてなしを受け、そのあと堺を見物していました。供はわずか30人ほどだったといわれます。6月2日、京都へ向かう途中、家康は京の商人・茶屋四郎次郎から信じられない知らせを聞きます。«信長さまが本能寺で討たれました»。","家康は一時、«京へ行って知恩院で腹を切る» と言い出したと伝わります。«ここで死ぬのは犬死にです。三河に帰って、兵を挙げるべきです» ——そう言って止めたのは、本多忠勝ら家臣たちだったといわれます。こうして、生きて三河へ帰るための逃避行が始まりました。","京都や大坂を通る道は明智方がおさえています。家康一行は、山城の宇治田原から近江の信楽、そして伊賀へと山道を進みました。伊賀は前年の «天正伊賀の乱» で織田家にひどい目にあわされた土地。家康は織田家の同盟相手ですから、いつ襲われてもおかしくありません。途中、落ち武者狩りに襲われた話も伝わります。いっしょに堺にいた穴山梅雪は、別の道を進んで命を落としました。","一行を助けたのが、甲賀や伊賀の地侍たちでした。伊賀出身の家臣・服部半蔵正成が、地元の者に護衛を頼んだともいわれます。伊賀市柘植の徳永寺には、家康が休んだと伝わり、そのお礼に寺が葵の紋の使用を許されたという話が残っています。一行は加太峠を越えて伊勢へ入り、白子あたりの浜から船で三河へ渡ったとされます。","6月4日ごろ、家康はようやく岡崎城にたどり着きました。のちに家康は、伊賀越えで世話になった伊賀の者たちを召し抱え、服部半蔵のもとで江戸城の警護などにあたる «伊賀者» として重く用いたといわれます。家康にとって命の恩人ともいえる伊賀とのつながりは、江戸幕府の時代まで続いていったのです。"],"tl":[["1582年5月","家康が安土城で信長にもてなされ、その後堺を見物"],["1582年6月2日","本能寺の変。家康は河内・飯盛山付近で知らせを受けたとされる"],["6月2〜3日","宇治田原・信楽を経て伊賀の山道を越える"],["6月3〜4日","加太峠から伊勢に入り、白子付近から船で三河へ"],["6月4日ごろ","岡崎城に帰り着く"],["6月13日","山崎の戦いで羽柴秀吉が明智光秀を破る"]],"who":[["徳川家康","逃避行の主人公。のちの江戸幕府初代将軍"],["服部半蔵正成","伊賀にゆかりのある家臣。伊賀者との仲立ちをしたと伝わる"],["本多忠勝","自害を思いとどまらせたと伝わる重臣"],["茶屋四郎次郎","京の豪商。本能寺の変を知らせ、道中の資金を用意したと伝わる"],["穴山梅雪","家康と堺にいた武田旧臣。別行動をとり途中で殺害された"]],"deep":["«神君» は江戸時代に家康を敬って呼んだことば。伊賀越えのルートは、伊賀の北部（御斎峠越え）を通った説と、甲賀から柘植へ抜けた説などがあり、今も議論が続いています。","近年の研究では、家康一行は伊賀の中心部を通らず、甲賀の地侍の助けで甲賀ルートを主に進んだとする見方も出ています。«伊賀越え» の名前自体、後から整えられた物語の面があります。","伊勢から三河への船出の場所も、白子（鈴鹿市）とする説のほか、長太（なご）や四日市などの説があります。船で着いたのは三河の大浜（碧南市）とする記録が多いです。","家康は晩年、この出来事を人生の大きな危機の一つとして語ったと伝わり、«三方ヶ原の戦い» などとともに «家康の三大危機» に数えられることがあります。","服部半蔵は «忍者» のイメージで知られますが、正成本人は槍の名手の武将でした。«半蔵門» の名は、服部家の屋敷が近くにあったことに由来するといわれます。"],"look":["徳永寺（伊賀市柘植町）の葵の紋","柘植の山あいの道と加太峠方面の地形","白子の浜（鈴鹿市）","伊賀と甲賀の境の山並み"],"q":["本能寺の変のあと、家康一行を伊賀で助けたと伝わる、家康の家臣で伊賀にゆかりのある人物は？","服部半蔵正成。のちに伊賀者を率いる立場になりました。"],"koji":[],"myth":"ルート（御斎峠説・甲賀経由説など）、船出の地、徳永寺の葵紋の由来、自害を止めた場面は伝承・諸説。","img":["本能寺の変","服部正成","穴山信君","茶屋四郎次郎"],"wp":"神君伊賀越え","rel":{"ev":[],"grave":[]},"ph":[["c:e/e3/Honnoj.jpg",3200,1565,"本能寺の変"],["c:a/a4/Anayama_Nobukimi.jpg",1935,1635,"穴山信君"]]},{"id":"24_isewan_taifu","n":"伊勢湾台風（長島・木曽岬の記憶）","yomi":"いせわんたいふう（ながしま・きそさきのきおく）","cat":"昭和","rank":"S","y":1959,"era":["showa"],"sh":"","ad":"桑名市長島町・桑名郡木曽岬町ほか","st":"近鉄長島駅から歩いて町内へ（木曽岬町は車かバスが便利）","la":35.075,"lo":136.74,"hook":"1959年9月26日の夜、海が堤防をこえて押し寄せた。日本の防災の仕組みは、この夜の悲しみから生まれ変わった。","lead":"伊勢湾台風は、1959年9月26日に紀伊半島に上陸し、東海地方を中心に大きな被害をもたらした台風です。死者・行方不明者は5,000人をこえ、明治以降の台風災害で最悪の被害となりました。海抜ゼロメートル地帯の長島や木曽岬では、高潮で広い範囲が長く水につかりました。","story":["その日、台風は非常に強い勢力のまま和歌山県の潮岬付近に上陸し、紀伊半島を北上しました。夜になって、伊勢湾の奥にある名古屋・桑名・長島・木曽岬に、南からの猛烈な風が吹きつけます。風に吹き寄せられた海水が、ちょうど満ち潮の時刻と重なって、ふだんより数メートルも高い «高潮» となって襲いかかりました。","長島や木曽岬は、木曽三川の河口にある低い土地です。もともと «輪中» と呼ばれる堤防に囲まれた集落で、土地の多くは海面より低い場所にありました。«堤防の内側なら安全» ——多くの人がそう信じていました。けれどこの夜、堤防があちこちで切れ、海水が一気に流れこみます。家は流され、暗闇と停電の中で、多くの人が命を落としました。","名古屋港の近くでは、貯木場に置かれていた巨大な丸太が高潮で流され、家々を押しつぶして被害をさらに大きくしました。«なぜこんなに被害が広がったのか?» ——台風の強さに加えて、低い土地に住宅が増えていたこと、夜で避難がむずかしかったこと、警報の意味が住民に伝わりきらなかったことなど、いくつもの理由が重なっていました。","台風が過ぎても、水は引きませんでした。切れた堤防から海水が出入りし、長島や木曽岬の一部では、数か月にわたって水につかったままの地域もあったといいます。自衛隊や消防団、全国から集まったボランティアが、ボートで人を助け、堤防をふさぐ作業を続けました。","この災害をきっかけに、1961年、国は «災害対策基本法» をつくり、国・県・市町村がそれぞれ防災の計画を立てる仕組みを整えました。伊勢湾の沿岸には、より高く丈夫な堤防がきずかれています。長島や木曽岬には、犠牲になった人々をしのぶ慰霊碑が建ち、毎年9月26日前後には祈りがささげられています。碑の前で静かに手を合わせ、«もし今夜、同じ台風が来たら» と考えてみましょう。"],"tl":[["1959年9月21日","マリアナ諸島の東の海上で台風が発生"],["1959年9月26日夕方","和歌山県潮岬付近に上陸"],["1959年9月26日夜","伊勢湾奥部に高潮が押し寄せ、堤防が決壊"],["1959年秋〜冬","長島・木曽岬などで長期間の浸水が続く"],["1961年","災害対策基本法が制定される"],["その後","伊勢湾沿岸で高潮堤防の整備が進む"]],"who":[["長島・木曽岬の住民","高潮で家族や家を失い、復興を担った"],["自衛隊・消防団","救助や堤防の締め切り作業にあたった"],["全国からの支援者","物資や人手で被災地を支えた"]],"deep":["死者・行方不明者は5,098人とされ、1995年の阪神・淡路大震災まで、戦後最悪の自然災害でした。被害は愛知・三重の両県に集中しています。","名古屋港では、平均海面から約3.9mの高潮を記録したとされます。台風の進路の東側は、台風自身の進む速さと風が重なって風が強くなる «危険半円» にあたり、伊勢湾はまさにその位置にありました。","貯木場の «ラワン材» などの丸太が流れ出して住宅地を襲ったことは、被害を大きくした要因として知られ、その後、貯木場の移転や管理の見直しが進みました。","輪中は、江戸時代から水害と戦ってきた地域の知恵ですが、伊勢湾台風では海からの高潮という、川の洪水とは違う力に直撃されました。輪中の «水屋»（高い場所に建てた避難用の蔵）の考え方が見直されるきっかけにもなりました。","伊勢湾台風の教訓は、その後の気象レーダー網の整備や予報の改善、«警報が出たら早めに逃げる» という避難の呼びかけ方の見直しにもつながりました。"],"look":["長島・木曽岬の慰霊碑","伊勢湾岸の高潮堤防","木曽三川の河口の低い土地（標高の案内板）","輪中の堤防の名残"],"q":["伊勢湾台風をきっかけに、1961年につくられた防災の基本となる法律は？","災害対策基本法。国・都道府県・市町村が防災計画を立てる仕組みが整えられました。"],"koji":[],"myth":"","img":["高潮","輪中","災害対策基本法"],"wp":"伊勢湾台風","rel":{"ev":[],"grave":[]},"ph":[["c:8/8b/Typhoon_Vera_analysis_23_Sep_1959.png",816,825,"伊勢湾台風"]]},{"id":"24_matsusaka_jo","n":"松坂城（蒲生氏郷の石垣）","yomi":"まつさかじょう","cat":"城","rank":"A","y":1588,"era":["azuchi","edo"],"sh":"国指定史跡","ad":"松阪市殿町","st":"JR・近鉄松阪駅から歩いて約15分","la":34.5764,"lo":136.5268,"hook":"建物はひとつも残っていない。それでも «石垣だけで名城» と呼ばれる城が、商人の町・松阪の真ん中にある。","lead":"松坂城は、1588年に戦国武将・蒲生氏郷が «四五百森（よいほのもり）» と呼ばれる丘に築いた城です。天守や櫓はすべて失われましたが、自然の石を積み上げた «野面積み» の石垣が見事に残り、国の史跡、日本100名城に選ばれています。いまの松阪の町は、この城とともに生まれました。","story":["蒲生氏郷は、近江（滋賀県）の日野出身の武将です。少年時代に人質として織田信長のもとへ送られましたが、その才能を見ぬいた信長は、自分の娘を氏郷の妻にしました。«人質だったのに、なぜ娘をあげたの?» ——それほど信長は氏郷を気に入っていたのです。信長の死後、氏郷は豊臣秀吉に仕え、伊勢の松ヶ島城を任されます。","松ヶ島は海に近い低地で、城下町を広げるには向いていませんでした。そこで氏郷は、少し内陸の丘に新しい城を築き、町ごと引っ越すことにします。1588年に完成した城の名前は «松坂»。«松ヶ島の松と、大坂の坂をとった» と伝わります。«大坂のように栄えてほしい» という願いがこめられていたのかもしれません。","氏郷は城下町づくりにも力を注ぎました。税や規制をゆるくして商売をしやすくする «楽市楽座» を行い、ふるさとの日野から商人を呼び寄せたといわれます。道を折れ曲がらせて敵が進みにくくする工夫もされました。この町から、のちに三井家をはじめとする «松阪商人» が次々と江戸へ羽ばたいていきます。","ところが氏郷自身は、城を築いてわずか2年後の1590年、秀吉の命令で遠い会津（福島県）へ移ることになりました。東北の伊達政宗ににらみをきかせるためです。その後、松坂城の城主は何度か代わり、1619年からは紀州藩（和歌山）の領地となって、城代が置かれました。天守は江戸時代のはじめに、大風で倒れたと伝わります。","いま城跡に上ると、高さのちがう曲輪（くるわ）が階段のように重なり、石垣がそれを支えています。角が鋭くそびえる石垣、ゆるやかにカーブする石垣——形を見くらべるのも楽しみです。本丸からは松阪の町並みが見わたせ、城内には本居宣長の旧宅や、紀州藩士が住んだ «御城番屋敷» も残っています。"],"tl":[["1584年","蒲生氏郷が伊勢・松ヶ島城に入る"],["1588年","四五百森に松坂城を築き、城下町を移す"],["1590年","氏郷が会津へ移る"],["1619年","紀州藩の領地となり、城代が置かれる"],["1644年ごろ","天守が大風で倒れたと伝わる"],["1863年","城の警護のため御城番屋敷が建てられる"],["2011年","国の史跡に指定"]],"who":[["蒲生氏郷","築城者。信長の娘婿。茶人・キリシタン大名としても知られる"],["織田信長","少年時代の氏郷を見いだし、娘を嫁がせた"],["豊臣秀吉","氏郷を伊勢、さらに会津へ配置した"],["徳川頼宣","紀州藩の初代藩主。松坂を領地に加えた"]],"deep":["石垣は、自然の石をあまり加工せずに積む «野面積み» が中心です。場所によって積み方や時期が違い、江戸時代に修理された部分と氏郷時代の部分を見分ける研究が進んでいます。","氏郷はキリスト教の洗礼を受け、«レオン» という洗礼名を持っていました。また千利休の高弟 «利休七哲» の一人にも数えられる茶人でした。","«松坂» と «松阪» の表記の違いは、江戸時代まで «松坂» が一般的で、明治以降に «松阪» が使われるようになったためです。城の名前は歴史的な表記として «松坂城» と書くのが一般的です。","天守の倒壊は正保元年（1644年）とする伝えがありますが、詳しい記録は多くありません。天守の形（三層か五層か）もはっきりしていません。","城内の松阪市立歴史民俗資料館は明治時代の図書館の建物で、松阪木綿や商人の暮らしに関する展示があります。"],"look":["本丸・二の丸へ続く野面積みの石垣","天守台の跡","表門跡の枡形","本丸からの松阪の町の眺め","城内の本居宣長旧宅と歴史民俗資料館"],"q":["松坂城を築いた武将は？","蒲生氏郷。1588年に築城し、城下町もつくりました。"],"koji":[],"myth":"«松坂» の名の由来、天守倒壊の年代・天守の形は伝承・諸説。","img":["蒲生氏郷","伊勢商人","御城番屋敷"],"wp":"松坂城","rel":{"ev":[],"grave":[]},"ph":[["c:c/ca/%E6%9D%BE%E5%9D%82%E5%9F%8E1.jpg",1891,1186,"松坂城"],["c:1/16/Gam%C5%8D_Ujisato_%28Saik%C5%8Dji_Nishiazu%29.jpg",539,779,"蒲生氏郷"],["c:3/36/Gojoban_Yashiki01.jpg",1800,1350,"御城番屋敷"]]},{"id":"24_gojoban","n":"御城番屋敷（紀州藩士の長屋）","yomi":"ごじょうばんやしき","cat":"町","rank":"A","y":1863,"era":["edo","meiji"],"sh":"国の重要文化財","ad":"松阪市殿町","st":"JR・近鉄松阪駅から歩いて約15分（松坂城跡の南東すぐ）","la":34.5758,"lo":136.5283,"hook":"江戸時代に建てられた武士の長屋に、いまも子孫が暮らしている。まっすぐな石畳と槙の生垣は、幕末からずっと同じ景色だ。","lead":"御城番屋敷は、幕末の1863年、紀州藩が松坂城の警護のために置いた武士たち «御城番» の住まいとして建てられた長屋です。石畳の道をはさんで2棟の長屋が向かい合い、槙の生垣が続きます。国の重要文化財で、今も子孫の方々が住み、1戸が公開されています。","story":["江戸時代、松坂は紀州藩（和歌山）の領地でした。殿さまは和歌山にいるので、城には城代や警護の武士が置かれていました。幕末の1863年、紀州藩は城の守りを固めるため、藩士たちを松坂に移し、城のそばに住まわせます。«なぜ幕末になって急に?» ——外国船が日本の近海にあらわれ、世の中が不安定になっていた時代です。","藩士たちのために建てられたのが、この長屋でした。まっすぐにのびる石畳の道の両側に、2棟の長い屋敷が向かい合っています。それぞれの家には玄関と小さな庭があり、道に面して槙（まき）の生垣が並びます。«武士の住宅» というと広い屋敷を思い浮かべますが、ここは質素で、同じ形の家がきちんと並ぶ «武士の団地» のようなつくりです。","明治になって武士の身分がなくなると、御城番の人々は仕事を失いました。ふつうなら屋敷は売られてばらばらになるところです。ところが彼らは、みんなでお金を出し合って組織をつくり、屋敷と土地を共同で持つことにしました。«苗秀社（びょうしゅうしゃ）» と呼ばれるこの組織は、今も子孫たちによって続き、屋敷を管理しています。","だから御城番屋敷は、«博物館» ではなく «今も人が暮らす家» なのです。見学できるのは公開されている1戸だけで、ほかの家は住まいなので、のぞきこんだり勝手に入ったりしないようにしましょう。公開されている家では、武士の家の間取りや、座敷から見る庭のようすを体験できます。","城跡の石垣を背にして石畳の道に立つと、両側の生垣が遠くまで続き、時が止まったような静けさがあります。春には周辺の桜が咲き、秋には木々が色づきます。古い建物を «使いつづけて守る» ということの意味を、この長屋は静かに教えてくれます。"],"tl":[["1619年","松坂が紀州藩の領地となる"],["1863年","紀州藩士（御城番）の住まいとして長屋が建てられる"],["明治初め","武士の身分がなくなり、藩士たちは組織をつくって屋敷を共同で所有"],["2004年","国の重要文化財に指定"],["現在","子孫が住み続け、1戸を一般公開"]],"who":[["御城番の藩士たち","松坂城の警護を任された紀州藩の武士"],["苗秀社","御城番の子孫がつくる組織。屋敷を今も守る"],["紀州藩","御城番を置いた藩。松坂を領地としていた"]],"deep":["御城番として松坂に来た藩士は、もとは紀州藩の田辺（和歌山県田辺市）の与力だったとされます。身分や移住の経緯には細かな議論があります。","長屋の屋根は瓦ぶきで、各戸の間取りはほぼ同じですが、端の家などで少しずつ違いがあります。重要文化財には、長屋とあわせて、敷地の裏手にある土蔵（米蔵）なども含まれています。","武士の組屋敷（同じ身分の武士がまとまって住む住宅）が、このように一列そろって、しかも住まいとして使われ続けている例は全国的にもめずらしいとされます。","槙の生垣は、手入れを続けないとすぐに形がくずれます。住民による日々の手入れがあってこそ、この景観が保たれています。","近くの松坂城跡、本居宣長旧宅とあわせて歩くと、戦国の城、江戸の学者、幕末の武士という三つの時代を、数百メートルの範囲で体験できます。"],"look":["石畳の道と槙の生垣の続く景色","公開されている1戸の座敷と庭","長屋の玄関が同じ形で並ぶようす","裏手の土蔵","背後の松坂城跡の石垣"],"q":["御城番屋敷を明治から今まで守っている、子孫たちの組織の名前は？","苗秀社（びょうしゅうしゃ）。屋敷と土地を共同で所有・管理しています。"],"koji":[],"myth":"御城番の出身（田辺与力とされる）や移住の経緯には細かな諸説。","img":["松坂城","紀州藩","松阪市"],"wp":"御城番屋敷","rel":{"ev":[],"grave":[]},"ph":[["c:3/36/Gojoban_Yashiki01.jpg",1800,1350,"御城番屋敷"],["c:c/ca/%E6%9D%BE%E5%9D%82%E5%9F%8E1.jpg",1891,1186,"松坂城"],["c:b/b7/Wakayama_Castle_2011_Kuruwa.jpg",1936,1296,"紀州藩"]]},{"id":"24_motoori_okuhaka","n":"本居宣長奥墓（山室山）","yomi":"もとおりのりながおくつき（やまむろやま）","cat":"墓所","rank":"A","y":1801,"era":["edo"],"sh":"国指定史跡","ad":"松阪市山室町（山室山）","st":"JR・近鉄松阪駅から車で約20分。駐車場から山道を歩いて登る","la":34.5255,"lo":136.4885,"hook":"«墓はこう作れ、桜はこれを植えよ»——死ぬ前に自分の墓の設計図まで描いた学者が、山の上で静かに眠る。","lead":"本居宣長は、亡くなる前の年に詳しい遺言書を書き、自分の墓を松阪の町を見下ろす山室山につくるよう指示しました。山頂近くにある «奥墓（おくつき）» には、宣長の自筆をもとにした «本居宣長之奥墓» の文字が刻まれ、後ろには山桜が植えられています。町の寺・樹敬寺にも墓があり、宣長の墓は二か所に分かれています。","story":["1800年、71歳の宣長は、自分の死に備えて長い遺言書を書きました。そこには驚くほど細かいことが書かれていました。«亡くなったら、夜のうちにこっそり山室山へ運ぶこと»、«墓の後ろには山桜を植えること»、«墓石の文字はこう書くこと» ——さらに、墓の形を描いた図まで添えられていたのです。","«なぜそこまで自分で決めたの?» ——宣長は、古い日本の人々の考え方を研究するうちに、仏教の決まりごとにとらわれない、自分らしい眠り方をしたいと考えたのかもしれません。一方で、町の菩提寺である樹敬寺でのお葬式や墓も大事にするよう書いています。家族や世間を困らせないよう、ていねいに両方を用意したのです。","宣長は桜をこよなく愛しました。自画像には «敷島の大和心を人問はば朝日に匂ふ山桜花» という歌を書き添えています。山室山の墓についても、«山室に ちとせの春の 宿しめて 風に知られぬ 花をこそ見め»（山室山に永遠の春の住まいを定めて、風に散らされることのない花を見よう）という歌を残しました。","1801年、宣長は72歳で亡くなりました。遺言どおり、奥墓は山室山につくられ、墓の後ろには山桜が植えられました。宣長の没後、その学問を慕う人々がこの墓を訪れるようになります。国学者の平田篤胤は宣長と一度も会ったことがありませんでしたが、宣長の «死後の門人» を名乗り、宣長を深く敬いました。","山道を登って奥墓の前に立つと、木々の間から松阪の町や伊勢の海の方角が見えます。ひっそりとした場所ですが、春には山桜が咲き、今も多くの人が花を手向けに訪れています。一生をかけて日本の古いことばと心を探った学者が、自分で選んだ «最後の書斎» ——そう思って静かにお参りしたい場所です。"],"tl":[["1730年","宣長、松阪に生まれる"],["1800年","遺言書を書き、山室山の墓の図などを指示"],["1801年","72歳で亡くなる。樹敬寺と山室山に墓がつくられる"],["江戸時代後期","門人や国学者の参拝が続く"],["明治以降","宣長の顕彰が進み、奥墓が整えられる"],["昭和","国の史跡に指定される"]],"who":[["本居宣長","国学者。自分の墓の場所と形を遺言で指定した"],["本居大平","宣長の養子。宣長の没後、鈴屋の学問を受けついだ"],["平田篤胤","宣長の «死後の門人» を名乗った国学者"]],"deep":["«奥墓» は、宣長自身が遺言で使ったことばで、ふつうの墓（詣り墓）とは別の、なきがらを葬る墓という意味合いがあります。町の樹敬寺の墓とあわせて «両墓制» のような形になっています。","遺言書は本居宣長記念館に伝わり、墓の図、葬列の順番、法事のやり方まで細かく書かれています。国の重要文化財の «本居宣長関係資料» の一部です。","山桜は代々植え継がれていて、今の木は宣長の時代のものではありません。宣長の «桜を植えよ» という願いを、後の人々が守り続けているのです。","山室山の麓には妙楽寺があり、奥墓への登り口になっています。宣長は生前、この地を下見してから墓所を決めたといわれます。","奥墓の近くには、宣長を慕った平田篤胤の歌碑があるとされ、篤胤と宣長の «会ったことのない師弟» の関係を伝えています。"],"look":["«本居宣長之奥墓» の墓石","墓の後ろの山桜","山道の途中の案内板と石段","木々の間から見える松阪方面の眺め","麓の妙楽寺"],"q":["本居宣長の墓が二か所あるのはなぜ？","遺言で、町の菩提寺・樹敬寺での墓と、山室山の奥墓の両方を用意するよう指示したからです。"],"koji":[],"myth":"山室山を下見した話、篤胤の歌碑の由来には伝承を含む。","img":["平田篤胤","本居大平"],"wp":"本居宣長","rel":{"ev":[],"grave":[]},"ph":[["c:f/f6/%E6%9C%AC%E5%B1%85%E5%AE%A3%E9%95%B702.jpg",1345,1544,"本居宣長"],["c:7/7f/Portrait_of_Atsutane_Hirata.jpg",1015,969,"平田篤胤"],["c:2/24/Motoori_Taihei.jpg",1506,1377,"本居大平"]]},{"id":"24_matsusaka_shonin","n":"松阪商人の館（小津清左衛門家）","yomi":"まつさかしょうにんのやかた（おづせいざえもんけ）","cat":"町","rank":"A","y":1653,"era":["edo"],"sh":"","ad":"松阪市本町","st":"JR・近鉄松阪駅から歩いて約10分","la":34.5779,"lo":136.5306,"hook":"«江戸に多きもの、伊勢屋、稲荷に犬の糞»。江戸じゅうに店を出した伊勢商人の «本拠地» の家を、のぞいてみよう。","lead":"松阪商人の館は、江戸で紙の商売をして大成功した豪商・小津清左衛門の家を公開したものです。江戸の大伝馬町に店を持ち、家族や本家は松阪に住む «江戸店持ち（えどだなもち）» という商いのかたちを、今に伝えています。千両箱が置かれた蔵や、店の間などを見学できます。","story":["江戸時代、江戸の町を歩くと «伊勢屋» という看板があちこちに見えたといいます。«江戸に多きもの、伊勢屋、稲荷に犬の糞» ということばがあるほどでした。その伊勢商人の中でも、とくに成功した人々の多くが松阪の出身です。«なぜ松阪から、こんなに商人が出たの?» ——理由のひとつは、蒲生氏郷の時代に近江から商人を呼んだことに始まる、商いの伝統でした。","松阪の周りでは «松阪木綿» と呼ばれる縞模様の木綿がつくられ、江戸で大人気になりました。伊勢参りの旅人がたくさん通るので、全国の情報も集まります。松阪商人たちは江戸に大きな店を構え、手代たちに店をまかせて、自分や家族は松阪に住み続けました。これが «江戸店持ち» です。","小津清左衛門家は、1653年に江戸の大伝馬町で紙の店 «小津屋» を開いたのが始まりとされます。紙は、帳簿や手紙、障子や本など、江戸の暮らしに欠かせないものでした。店は大きく成長し、小津家は松阪を代表する豪商になりました。松阪の家には、表に店の間、奥に座敷や庭、そして大きな蔵が並んでいます。","蔵の中には、お金を入れる «千両箱» が置かれています。«千両箱って、どれくらい重いの?» ——小判千枚が入ると、重さは十数キロから20キロほどにもなったといわれます。帳場の格子や大きな金庫、使い込まれた箱階段なども見どころです。豪華さよりも、きちんと整えられた «堅実さ» が、松阪商人らしさを感じさせます。","じつは本居宣長も、松阪の小津一族の家に生まれました（のちに «本居» と名乗ります）。三井越後屋を開いた三井高利も松阪の出身です。さらに映画監督の小津安二郎は、父が松阪の小津家の出身で、少年時代を松阪で過ごしました。ひとつの小さな町から、商人、学者、映画監督まで、日本を動かした人々が次々に生まれたのです。"],"tl":[["1588年","蒲生氏郷が松坂の城下町をつくり、商人を呼び寄せる"],["1653年","小津清左衛門家が江戸・大伝馬町に紙店を開く"],["1673年","松阪出身の三井高利が江戸に越後屋を開く"],["1730年","本居宣長が松阪の小津家に生まれる"],["江戸時代","松阪木綿が江戸で大流行する"],["平成","小津清左衛門家の旧宅が «松阪商人の館» として公開される"]],"who":[["小津清左衛門","江戸・大伝馬町で紙店を営んだ松阪の豪商"],["三井高利","松阪出身。越後屋（のちの三越）を開いた"],["本居宣長","松阪の小津一族の出身。のちに国学者となる"],["小津安二郎","映画監督。父が松阪の小津家の出で、少年時代を松阪で過ごした"]],"deep":["«江戸店持ち» の商人は、江戸の店の手代を松阪から採用し、何年か勤めると松阪に帰す仕組みをとっていたといわれます。店と故郷をつなぐ «人の行き来» が商売を支えました。","大伝馬町は、木綿を扱う問屋が集まった江戸の商業の中心地で、伊勢商人の店が多く並んでいました。","三井高利は松阪で生まれ、若いころ江戸の兄の店で修業したのち、52歳で越後屋を開いて «現金掛け値なし»（定価で現金販売）という新しい売り方で大成功しました。","松阪にはほかにも、国の重要文化財に指定された旧長谷川治郎兵衛家など、豪商の家が残っています。あわせて見学すると、商家どうしの違いもわかります。","小津安二郎と松阪の小津清左衛門家との関係については、同じ小津一族であるとされますが、家どうしの細かなつながりには諸説があります。"],"look":["店の間と帳場","千両箱が置かれた蔵","箱階段と奥座敷","商家の中庭","近くの旧長谷川治郎兵衛家と三井家発祥の地（外から）"],"q":["江戸に店を持ちながら、本家は地元に住み続けた伊勢商人の商いのかたちを何という？","«江戸店持ち»。店は手代にまかせ、主人や家族は松阪に住みました。"],"koji":[{"w":"江戸に多きもの、伊勢屋、稲荷に犬の糞","m":"江戸の町にはどこにでも伊勢商人の店があったことをからかったことば"}],"myth":"小津安二郎と小津清左衛門家の具体的な血縁関係は諸説。千両箱の重さは中身の小判の種類で異なる。","img":["伊勢商人","三井高利","小津安二郎","本居宣長"],"wp":"小津清左衛門","rel":{"ev":[],"grave":[]},"ph":[["c:0/08/Ozu_washi-1.jpg",3216,2136,"小津清左衛門"],["c:1/18/Mitsui_Takatoshi.jpg",5899,4871,"三井高利"],["c:8/85/Yasujiro_Ozu_01.jpg",500,600,"小津安二郎"],["c:f/f6/%E6%9C%AC%E5%B1%85%E5%AE%A3%E9%95%B702.jpg",1345,1544,"本居宣長"]]},{"id":"24_tsu_jo","n":"津城（藤堂高虎の築いた城）","yomi":"つじょう","cat":"城","rank":"A","y":1608,"era":["azuchi","edo"],"sh":"県指定史跡","ad":"津市丸之内","st":"近鉄 津新町駅から歩いて約10分／JR・近鉄津駅からバス","la":34.7188,"lo":136.5073,"hook":"«伊勢は津で持つ、津は伊勢で持つ»。伊勢参りの港町を、築城の名人が «城下町ごと» 作りかえた。","lead":"津城は、はじめ織田信長の弟・織田信包が築き、1608年に藤堂高虎が入ってから大きく改修された城です。高虎は城だけでなく、伊勢街道を城下に通して町をつくり、津を伊勢参りの旅人でにぎわう町に育てました。いまは «お城公園» として、石垣と堀の一部、模擬の三重櫓が残っています。","story":["津は古くから «安濃津（あのつ）» と呼ばれる港町で、中国の書物に «日本の三つの大きな港» のひとつとして書かれたほどでした。戦国時代、この港を見下ろす場所に、信長の弟・織田信包が城を築き、五層の天守を建てたといわれます。","1600年、関ヶ原の戦いの直前、津城は大きな戦いの舞台になります。東軍の富田信高が城にこもり、毛利秀元らの西軍の大軍に囲まれたのです。«味方はわずか、敵は何倍も» という戦いで、城は激しく攻められ、最後は開城しました。このとき、信高の妻が鎧を着て自ら戦ったという話も伝わっています。","1608年、伊予（愛媛県）今治から藤堂高虎がやってきました。高虎は «築城の名人» として知られ、伊賀上野城とともに津城を大きく作りかえます。本丸のまわりに広い堀をめぐらし、高い石垣を築きました。けれど天守は建てず、代わりに櫓を配置しました。«なぜ天守を建てなかったの?» ——幕府への遠慮、あるいは実用本位の考え方など、理由には諸説あります。","高虎がもうひとつ力を入れたのが町づくりです。伊勢神宮へ向かう伊勢街道を城下の中に通し、旅人が津の町を通るようにしました。こうして津は、伊勢参りの人々でにぎわう宿場町・城下町として発展していきます。«伊勢は津で持つ、津は伊勢で持つ» という伊勢音頭の一節は、その深い結びつきを表しています。","明治になって城の建物は取りこわされ、堀の多くも埋められました。いまのお城公園には、本丸の石垣と堀の一部が残り、1958年に建てられた模擬の三重櫓が立っています。公園の中には馬に乗った高虎の銅像もあります。石垣の角に立って堀の水面を見下ろすと、江戸時代の城の大きさを少しだけ想像できます。"],"tl":[["1570年代〜1580年ごろ","織田信包が城を築き、五層の天守を建てたといわれる"],["1600年","安濃津城の戦い。富田信高が籠城ののち開城"],["1608年","藤堂高虎が伊予今治から入城"],["1611年ごろ","高虎による城の大改修が進む"],["1871年","廃藩置県。やがて城の建物が取りこわされる"],["1958年","模擬の三重櫓が建てられる"],["2011年","お城公園に藤堂高虎の騎馬像が建てられる"]],"who":[["藤堂高虎","津藩の初代藩主。城と城下町を大改修した"],["織田信包","信長の弟。津城を最初に本格的に築いた"],["富田信高","関ヶ原の前に津城に籠城した東軍の城主"],["毛利秀元","津城を攻めた西軍の武将"]],"deep":["«安濃津» は中国・明の書物『武備志』に、日本の三大港（三津）のひとつとして «洞津» の名で記されているといわれます。港は1498年の明応の大地震で大きな被害を受けたと伝わります。","模擬の三重櫓は、江戸時代の «丑寅櫓（うしとらやぐら）» があった場所の近くに建てられましたが、形は当時の櫓を正確に再現したものではありません。","高虎は生涯に多くの城に関わり、石垣を高く積み、堀を広くとる設計で知られます。津城では本丸を囲む内堀の幅が広く、攻め手を寄せつけない構えでした。","安濃津城の戦いでの «富田信高の妻の奮戦» は、軍記物などに記された話で、細部には脚色があるとみられます。","お城公園の西側には、藩校・有造館の正門だった «入徳門» が移築されています。津城と藩校をあわせて見ると、城下町の «武» と «文» の両面がわかります。"],"look":["本丸の石垣と残る内堀","模擬三重櫓","藤堂高虎の騎馬像","有造館の入徳門","石垣の角の算木積み"],"q":["«伊勢は津で持つ、津は伊勢で持つ» と歌われる、津と伊勢の結びつきを生んだ道は？","伊勢街道。藤堂高虎が城下に通し、伊勢参りの人々で津がにぎわいました。"],"koji":[{"w":"伊勢は津で持つ、津は伊勢で持つ","m":"伊勢参りと津の町が互いに支え合っていたことを表す伊勢音頭の一節"}],"myth":"織田信包の天守の姿、天守を建てなかった理由、富田信高の妻の奮戦は伝承・諸説。","img":["藤堂高虎","織田信包","安濃津城の戦い","富田信高"],"wp":"津城","rel":{"ev":[],"grave":[]},"ph":[["c:d/d5/140405_Tsu_Castle_Tsu_MIe_pref_Japan16s3.jpg",6000,4000,"津城"],["c:e/e2/Toudou_Takatora.jpg",1056,1096,"藤堂高虎"],["c:7/7d/Oda_Nobukane.jpg",2441,3291,"織田信包"],["c:4/47/Tsu_Castle.jpg",800,600,"安濃津城の戦い"],["c:0/02/Tomita_Nobutaka_and_his_wife.jpg",1299,1912,"富田信高"]]},{"id":"24_yuzokan","n":"有造館跡（津藩校）と入徳門","yomi":"ゆうぞうかんあと（つはんこう）とにゅうとくもん","cat":"学び","rank":"B","y":1820,"era":["edo"],"sh":"県指定史跡（入徳門）","ad":"津市丸之内（お城公園の西側）","st":"近鉄 津新町駅から歩いて約10分","la":34.719,"lo":136.5055,"hook":"«徳に入る門» をくぐった少年たちは、儒学も、西洋の医学も学んだ。幕末の津藩の «頭脳» を育てた学校の門が、今も残る。","lead":"有造館は、1820年に津藩の藩主・藤堂高兌（たかさわ）がつくった藩校（藩の学校）です。藩士の子どもたちが儒学や武芸を学び、のちには西洋の学問も取り入れました。校舎はなくなりましたが、正門の講堂の門だった «入徳門» が、津城跡のお城公園に移されて残っています。","story":["江戸時代の後半、多くの藩が財政の苦しさや世の中の変化に直面していました。«これからの藩を支えるのは人だ» ——そう考えた津藩10代藩主・藤堂高兌は、1820年、城のそばに藩校を開きます。名前の «有造» は、中国の古典『詩経』のことばから取られたといわれ、«若者を立派に育て上げる» という願いがこめられています。","初代の督学（校長）には、学者の津坂東陽（つさか とうよう）が選ばれました。藩士の子どもたちは、ここで『論語』などの儒学の本を読み、字を習い、剣術や槍術などの武芸にも励みました。門の名前 «入徳門» は «徳に入る門»、つまり «人として大事なことを学び始める入り口» という意味です。","有造館をさらに有名にしたのが、のちに督学になった斎藤拙堂（さいとう せつどう）です。拙堂は文章の名人として全国に知られ、奈良の月ヶ瀬の梅林をたずねて書いた『月瀬記勝（げっせきしょう）』は、月ヶ瀬を梅の名所として世に広めました。«文章ひとつで、人を旅に誘うことができる» ——拙堂の文は、まさにそんな力を持っていました。","拙堂は、古い学問だけにこだわりませんでした。外国船があらわれる幕末、«西洋のことも知らなければならない» と考え、有造館に洋学を学ぶ場を設けたといわれます。また、天然痘を防ぐ «種痘» を津藩に広めることにも力を尽くしました。有造館は、儒学と西洋の学問が出会う場所でもあったのです。","明治になって藩校は廃止されましたが、その学びの伝統は、のちの津の学校へ受けつがれたといわれます。お城公園の入徳門の前に立ち、ここをくぐった少年たちの姿を想像してみましょう。«学びの入り口» は、いつの時代も小さな門から始まるのかもしれません。"],"tl":[["1820年","藤堂高兌が藩校・有造館を開く"],["1820年代","津坂東陽が初代督学をつとめる"],["天保年間ごろ","斎藤拙堂が督学となり、学風を広げる"],["幕末","洋学の学習や種痘の普及が進む"],["1871年","廃藩置県。やがて藩校は廃止される"],["昭和","入徳門がお城公園内に移される"]],"who":[["藤堂高兌","津藩10代藩主。有造館を創設した"],["津坂東陽","儒学者。有造館の初代督学"],["斎藤拙堂","儒学者・文章家。督学として洋学・種痘の導入も進めた"]],"deep":["«有造» は『詩経』大雅の «肆成人有徳、小子有造»（大人には徳があり、子どもは造り上げられる）という句に由来するといわれます。","«入徳» は、儒学の書物『大学』を «初学入徳の門»（学び始めた者が徳に入る門）とした宋の学者のことばに通じるといわれます。","藤堂高兌は、有造館とあわせて伊賀上野にも藩校（崇広堂）を開いたとされ、津と伊賀の両方で教育を整えました。崇広堂は現在も伊賀市に残っています。","斎藤拙堂の『月瀬記勝』は漢文で書かれた紀行文で、頼山陽ら多くの文人が月ヶ瀬を訪れるきっかけになったといわれます。","藩校の数は全国で200を超えたとされ、有造館はその中でも規模の大きい藩校のひとつでした。入徳門は、その規模をしのばせる数少ない遺構です。"],"look":["入徳門（お城公園の西側）","門の扁額と屋根の造り","津城跡の石垣とあわせた散策","近くの有造館跡を示す案内板"],"q":["有造館の門 «入徳門» の «入徳» とはどんな意味？","«徳に入る»。人として大切なことを学び始める入り口、という意味です。"],"koji":[{"w":"小子有造","m":"子どもは教えによって立派に造り上げられる、という『詩経』のことば。有造館の名の由来とされる"}],"myth":"館名の典拠、入徳門の移築の経緯、洋学所の開設時期は伝承・諸説を含む。","img":["藤堂高兌","月ヶ瀬梅林","藩校"],"wp":"斎藤拙堂","rel":{"ev":[],"grave":[]},"ph":[["c:e/ee/Todo_Takasawa.jpg",1346,1514,"藤堂高兌"],["c:d/df/Tsukigase_05.jpg",1200,1800,"月ヶ瀬梅林"],["c:6/6b/Koudoukan.JPG",1024,768,"藩校"]]},{"id":"24_kitabatake_yakata","n":"北畠氏館跡（北畠神社庭園）","yomi":"きたばたけしやかたあと（きたばたけじんじゃていえん）","cat":"城","rank":"A","y":1530,"era":["muromachi"],"sh":"国指定史跡・名勝","ad":"津市美杉町上多気","st":"JR名松線 伊勢奥津駅からコミュニティバスまたは車で約15分","la":34.5049,"lo":136.2628,"hook":"山奥の小さな盆地に、240年も «伊勢の国司» の都があった。石組みの庭だけが、戦国の優雅さを今に伝えている。","lead":"南北朝時代から戦国時代にかけて、伊勢国司の北畠氏が本拠地とした «多気（たげ）» の館の跡です。いまは北畠顕能をまつる北畠神社になっていて、境内に室町時代の武将がつくったと伝わる庭園が残っています。この庭は «日本三大武家庭園» のひとつに数えられます。","story":["南北朝時代、南朝の重臣・北畠親房の子、北畠顕能（あきよし）は伊勢国司に任じられ、伊勢の山奥・多気に館を構えました。«なぜこんな山の中に?» ——多気は伊勢と大和（奈良）を結ぶ道の途中にあり、南朝の拠点・吉野とも近く、敵に攻められにくい場所だったからです。","北畠氏は、南北朝の戦いが終わったあとも伊勢の南部を治める大名として続きました。多気には館だけでなく、家臣の屋敷や寺、町が広がり、«多気の都» と呼ばれるほどのにぎわいがあったといわれます。公家の出身でありながら武家として生きた北畠氏は、和歌や学問にも親しむ文化の高い一族でした。","館の跡に残る庭園は、室町幕府の管領・細川高国がつくったと伝わります。高国は北畠家の娘を妻にしていて、その縁でこの地を訪れたといわれます。池は «米» という字の形に入り組み、そのまわりに石が力強く組まれています。«戦国の武将が、どうしてこんなに美しい庭を?» ——庭は、客をもてなし、自分の教養を示す大切な場でもあったのです。","1576年、北畠氏の運命は大きく変わります。織田信長の次男・信雄を養子に迎えていた北畠家で、前の当主・北畠具教（とものり）が、信長の命を受けた者たちに三瀬（みせ）の館で殺されたのです（«三瀬の変»）。北畠一族の多くも命を落とし、約240年続いた伊勢国司家はここで事実上終わりを迎えました。","いま北畠神社の境内に入ると、静かな山あいの空気の中に、苔むした石組みと池が広がっています。館そのものは残っていませんが、発掘調査で石垣や建物の跡が見つかり、背後の霧山城とあわせて国の史跡になっています。庭の石の配置をじっくり眺めていると、この山奥に確かに «都» があったことが感じられます。"],"tl":[["1342年ごろ","北畠顕能が伊勢国司となり、多気に拠点を置く"],["1392年","南北朝の合一。北畠氏は伊勢国司として続く"],["1530年ごろ","細川高国が館の庭園をつくったと伝わる"],["1569年","大河内城の戦いののち、信長の次男を養子に迎える"],["1576年","三瀬の変で北畠具教が殺害される"],["昭和初期","北畠氏館跡庭園が国の史跡・名勝に指定"],["2006年","館跡・霧山城跡などが «多気北畠氏遺跡» として国の史跡に"]],"who":[["北畠顕能","初代伊勢国司。北畠神社の祭神"],["北畠親房","顕能の父。南朝の重臣で『神皇正統記』の著者"],["細川高国","室町幕府の管領。庭園をつくったと伝わる"],["北畠具教","北畠家の当主。剣術にすぐれたといわれ、三瀬の変で殺害された"]],"deep":["«日本三大武家庭園» は、この北畠氏館跡庭園と、福井県の一乗谷朝倉氏庭園、岐阜県の江馬氏館跡庭園の3つを指すことが多いですが、選び方には決まった根拠はありません。","細川高国の作とする説は伝承で、確かな記録はありません。ただ、高国が北畠材親の娘を妻にしていたことは知られており、両家のつながりは確かです。","«米字池» は、池の形を上から見ると «米» の字に見えることからの呼び名です。池の護岸の石組み（とくに «須弥山石組» とされる部分）が見どころとされます。","北畠具教は剣豪・塚原卜伝から «一の太刀» を伝授されたと伝わる人物で、三瀬の変のときも奮戦したと語られています（伝承）。","多気の城下町の跡は、発掘によって道路や屋敷地の区画が確認されていて、中世の山間部の «城下町» を知る貴重な例とされます。"],"look":["米字池と石組み","北畠神社の社殿","館跡の石垣（発掘で確認された部分）","背後の霧山城への登山口","北畠氏の歴史を紹介する資料館"],"q":["北畠氏館跡の庭園をつくったと伝わる、室町幕府の管領は？","細川高国。北畠家の娘を妻にしていた縁で、この地を訪れたといわれます。"],"koji":[],"myth":"庭園の作者（細川高国）、«多気の都» の規模、具教の剣術の話は伝承・諸説。","img":["北畠顕能","北畠親房","北畠具教","細川高国"],"wp":"北畠神社","rel":{"ev":[],"grave":[]},"ph":[["c:b/bf/Kitabatake_Shrine.jpg",2592,1944,"北畠神社"],["c:d/dc/Kitabatake_Akiyoshi_statue.jpg",2000,1800,"北畠顕能"],["c:2/2c/Kitabatake_Tomonori.jpg",721,577,"北畠具教"],["c:6/60/Hosokawa_Takakuni.jpg",1385,3074,"細川高国"]]},{"id":"24_kiriyama_jo","n":"霧山城（伊勢国司北畠氏の詰城）","yomi":"きりやまじょう","cat":"城","rank":"A","y":1342,"era":["muromachi"],"sh":"国指定史跡","ad":"津市美杉町上多気（霧山）","st":"JR名松線 伊勢奥津駅から車で約15分。北畠神社から登山道で約1時間","la":34.5085,"lo":136.2575,"hook":"館のすぐ裏、霧にかくれる山の頂に、いざという時の «最後の砦» があった。","lead":"霧山城は、伊勢国司・北畠氏の館の裏山（霧山）に築かれた山城です。ふだんは山のふもとの館で暮らし、敵が攻めてきたときに立てこもる «詰城（つめのしろ）» の役割を持っていました。山頂近くには曲輪や堀切の跡が残り、館跡とあわせて国の史跡 «多気北畠氏遺跡» になっています。","story":["中世の武士たちは、ふだんは平地の館に住み、戦いのときは近くの山の城にこもる、という «二段がまえ» で身を守っていました。北畠氏の場合、館は多気の盆地に、詰城は館の真後ろにそびえる霧山に置かれました。«なぜ霧山っていうの?» ——山あいで霧が発生しやすく、山頂が霧に包まれることが多いから、と言われています。","北畠顕能が多気に入ったとき、この山にも城を築いたと伝わります。南北朝の戦いでは、北朝方の軍勢が伊勢に攻めこむこともありました。山の城は、少ない兵でも大軍を防げるように、尾根を切って道をふさぐ «堀切»、斜面を削った «切岸» など、地形をいかした工夫がこらされています。","戦国時代、北畠氏は伊勢の南部で勢力を保ち続けましたが、1569年、織田信長の大軍が伊勢に攻めこみます。北畠氏は大河内城で戦ったのち和睦し、信長の次男を養子に迎えました。そして1576年の «三瀬の変» で北畠一族の多くが殺害されると、霧山城も織田方に攻められ、落城したと伝わります。","登山道を登っていくと、杉やヒノキの森の中に、平らにならされた曲輪の跡がいくつも現れます。山頂部には «本丸» と «鐘突堂（かねつきどう）» と呼ばれる二つの高まりがあり、そこから多気の盆地を見下ろせます。山城の «ほんとうの姿» は、木々が茂った今、少し見えにくくなっていますが、足元の段差や溝に目をこらすと、当時の工夫が見えてきます。","山を下りてふもとの北畠神社に戻ると、館と詰城がいかに近い距離にあったかがよくわかります。«館で暮らし、山で守る»。およそ240年続いた伊勢国司の歴史は、この小さな盆地と裏山の間で紡がれていたのです。登山道は急な場所や滑りやすい場所もあるので、歩きやすい靴で、時間に余裕をもって出かけましょう。"],"tl":[["1342年ごろ","北畠顕能が多気に入り、霧山に城を築いたと伝わる"],["南北朝時代","北朝方の軍勢との戦いが伊勢で続く"],["1569年","信長の伊勢侵攻。北畠氏は大河内城で戦い和睦"],["1576年","三瀬の変。霧山城も攻められ落城したと伝わる"],["2006年","館跡とあわせ «多気北畠氏遺跡» として国の史跡に"]],"who":[["北畠顕能","初代伊勢国司。多気に拠点を定めた"],["北畠具教","戦国時代の北畠家の当主。三瀬の変で殺害される"],["織田信長","伊勢を攻め、北畠氏を事実上ほろぼした"]],"deep":["«詰城» とは、ふだん住む館や平城の背後に置く、戦いのときの立てこもり用の城のことです。越前の一乗谷朝倉氏遺跡の一乗谷城など、中世の大名によく見られる形です。","霧山城の主な遺構は、山頂の曲輪群、尾根を断ち切る堀切、竪堀などで、石垣はほとんど使われていない «土の城» です。","«鐘突堂» と呼ばれる曲輪には、合図のための鐘があったと伝わりますが、呼び名の由来は確かではありません。","霧山城と館跡は、北畠氏の居館・詰城・城下町がセットで残る例として評価され、2006年にまとめて «多気北畠氏遺跡» として国の史跡に指定されました。","築城年は顕能が多気に入った14世紀半ばと伝わりますが、現在見られる遺構の多くは戦国時代に改修されたものとみられています。"],"look":["登山道の途中の曲輪の段差","尾根を断ち切る堀切","山頂の本丸と鐘突堂の二つの高まり","山頂からの多気盆地の眺め","ふもとの北畠神社との位置関係"],"q":["ふだんは館に住み、戦いのときに立てこもるための裏山の城を何という？","«詰城（つめのしろ）»。霧山城は北畠氏の詰城でした。"],"koji":[],"myth":"築城年、落城の経緯、«鐘突堂» の名の由来は伝承・諸説。","img":["北畠顕能","北畠具教","北畠氏"],"wp":"霧山城","rel":{"ev":[],"grave":[]},"ph":[["c:9/99/Kiriyama_Castle_ruins.jpg",2592,1944,"霧山城"],["c:d/dc/Kitabatake_Akiyoshi_statue.jpg",2000,1800,"北畠顕能"],["c:2/2c/Kitabatake_Tomonori.jpg",721,577,"北畠具教"],["c:5/5b/Sasa_Rind%C5%8D_inverted.png",1675,1675,"北畠氏"]]},{"id":"24_okawachi_jo","n":"大河内城（信長と北畠の籠城戦）","yomi":"おかわちじょう","cat":"城","rank":"A","y":1569,"era":["muromachi","azuchi"],"sh":"県指定史跡","ad":"松阪市大河内町","st":"JR・近鉄松阪駅から車で約20分","la":34.527,"lo":136.47,"hook":"天下に手をかけた信長の大軍が、山あいの城を50日かけても落とせなかった。最後は «息子を養子に出す» 和睦で決着した。","lead":"大河内城は、伊勢国司・北畠氏の城のひとつで、川にはさまれた丘の上に築かれました。1569年、織田信長は大軍でこの城を囲みましたが、北畠具教・具房親子は約50日も持ちこたえます。最後は、信長の次男を北畠家の養子にするという条件で和睦しました。","story":["1568年に足利義昭を連れて京都に入った信長は、次に伊勢をねらいます。北伊勢の豪族たちを次々と従わせ、1569年、南伊勢を治める北畠氏を攻めました。北畠具教と子の具房は、多気の館を出て、守りの固い大河内城に立てこもります。","大河内城は、阪内川と矢津川にはさまれた丘の上にあり、まわりは深い谷と急な崖。«どこから攻めればいいのか» ——信長軍は数万ともいわれる大軍で城を囲みましたが、正面から攻めても城兵に撃ち返され、夜討ちもうまくいきません。城の近くには、攻め手を苦しめたと伝わる «まむし谷» という谷の名も残っています。","信長は兵糧攻めに切りかえ、城のまわりに柵をめぐらして、食べ物が入らないようにしました。城の中はしだいに苦しくなっていきます。けれど信長の側も、長く兵を引きとめておくのはたいへんでした。こうして両者の間で、和睦の話し合いが始まります。","約50日後、ついに決着がつきました。条件は、信長の次男・茶筅丸（のちの織田信雄）を具房の養子にし、北畠家を継がせること。«戦に負けたわけではないのに、家を乗っ取られる» ——北畠家にとっては、実質的な降伏でした。具教は城を出て、のちに三瀬の館に移ります。そして7年後の三瀬の変で命を落とすことになるのです。","いま城跡に登ると、本丸・二の丸などの平らな曲輪や、空堀の跡が残っています。本丸跡には城の歴史を伝える石碑が立ち、二つの川にはさまれた地形がよくわかります。天下統一へ進む信長が «力ずくで落とせなかった城»。その理由を、地形を見ながら考えてみましょう。"],"tl":[["1415年ごろ","北畠氏の一族が大河内城を築いたと伝わる"],["1568年","信長が足利義昭を奉じて上洛"],["1569年8月","信長が大軍で大河内城を包囲"],["1569年10月","約50日の籠城ののち和睦。茶筅丸（信雄）が北畠家の養子に"],["1576年","三瀬の変で北畠具教が殺害される"]],"who":[["北畠具教","北畠家の前当主。籠城戦を指揮した"],["北畠具房","具教の子。当主として籠城した"],["織田信長","大軍で城を囲み、和睦で伊勢を手に入れた"],["織田信雄（茶筅丸）","信長の次男。和睦の条件で北畠家の養子となった"],["木下秀吉（のちの豊臣秀吉）","信長の伊勢攻めに加わり、周辺の城攻めでも活躍した"]],"deep":["信長の軍勢の数は、『信長公記』などで «7万» «8万» などとされますが、誇張を含む可能性があります。いずれにしても、当時としては非常に大きな軍勢でした。","大河内城は、1415年に北畠満雅が幕府に反乱したときに、一族の大河内氏の城として築かれたと伝わります。«大河内御所» と呼ばれた北畠一族がここに住んだといわれます。","籠城の期間は «約50日» とされます。攻めあぐねた信長側が、雨の中で夜襲をかけて失敗した話なども伝わっています。","和睦の条件だった茶筅丸は当時まだ10代前半の少年でした。のちに北畠具豊、さらに信意（のぶおき）と名乗り、北畠家の実権を握っていきます。","城跡は現在、公園として整えられた部分と山林の部分があり、曲輪の配置や空堀が見られます。二つの川が天然の堀の役割を果たしていたことが、地形からよくわかります。"],"look":["本丸跡の石碑","二の丸・西の丸などの曲輪","空堀の跡","まむし谷の地形","阪内川と矢津川にはさまれた丘の全景"],"q":["大河内城の戦いの和睦で、北畠家の養子になった信長の息子は？","次男の茶筅丸（のちの織田信雄）です。"],"koji":[],"myth":"築城年・築城者、信長軍の人数、まむし谷の由来は伝承・諸説。","img":["大河内城の戦い","北畠具教","北畠具房","織田信雄"],"wp":"大河内城","rel":{"ev":[],"grave":[]},"ph":[["c:2/2c/Kitabatake_Tomonori.jpg",721,577,"北畠具教"],["c:1/1e/%E5%8C%97%E7%95%A0%E5%85%B7%E6%88%BF%E3%81%AE%E8%8A%B1%E6%8A%BC.jpg",1536,1773,"北畠具房"],["c:b/be/Oda_Nobukatu.jpg",1285,2393,"織田信雄"]]},{"id":"24_asaka_jo","n":"阿坂城（白米城伝説）","yomi":"あさかじょう（はくまいじょうでんせつ）","cat":"城","rank":"B","y":1415,"era":["muromachi","azuchi"],"sh":"国指定史跡","ad":"松阪市大阿坂町","st":"JR・近鉄松阪駅から車で約20分。登山口から山頂まで歩いて約40分〜1時間","la":34.6035,"lo":136.475,"hook":"水を断たれた城で、兵たちは馬に «白い米» を浴びせた。遠くから見ると、まるで水で洗っているように見えた——。","lead":"阿坂城は、標高約300mの山の上に築かれた北畠氏の城です。1415年、北畠満雅が室町幕府に反乱を起こしたとき、この城に立てこもったといわれます。水を断たれたとき、米を水に見せかけて敵をだましたという «白米城伝説» が伝わり、«白米城» とも呼ばれます。","story":["南北朝の合一のあと、室町幕府は «次の天皇は南朝と北朝から交互に出す» という約束を守りませんでした。1415年、南朝の流れを大切にする伊勢国司・北畠満雅は、これに怒って兵を挙げます。幕府は大軍を送り、満雅は阿坂城にこもって戦いました。","山の上の城でいちばん困るのは水です。幕府軍は城に水を運ぶ道を断ち、城の中はたちまち水不足になりました。«このままでは水がないことが敵に知られてしまう» ——そこで城兵たちは、馬を敵から見える場所に引き出し、ひしゃくで白い米を馬の背に何度もかけたといいます。遠くから見ると、まるでたっぷりの水で馬を洗っているように見えたのです。","«城にはまだ水がたくさんあるのか» と思った幕府軍は、長い包囲をあきらめたと伝わります。これが «白米城伝説» です。ただし、同じような話は全国の山城にいくつも伝わっていて、どこまで本当にあったことなのかはわかりません。«米で水をよそおう» という知恵の物語が、人々に愛されて各地に広まったとも考えられています。","それから150年以上たった1569年、今度は織田信長の軍勢が伊勢に攻めこみます。阿坂城は北畠方の城として守られていましたが、信長の家臣・木下藤吉郎（のちの豊臣秀吉）らに攻められて落城しました。このとき秀吉が矢で傷を負ったという話も伝わっています。阿坂城の陥落は、大河内城の戦いへとつながっていきました。","山頂へは、ふもとから山道を登っていきます。頂上近くには南北二つの曲輪があり、土塁や堀切の跡が残っています。晴れた日には伊勢湾まで見わたせ、この山が見張りにぴったりの場所だったことがよくわかります。«米で水をよそおった兵たち» の姿を思い浮かべながら、ゆっくり登ってみましょう。"],"tl":[["1392年","南北朝の合一"],["1415年","北畠満雅が幕府に反乱。阿坂城で籠城し、白米城伝説が生まれたと伝わる"],["1428年","満雅が再び挙兵し、戦死する"],["1569年","信長の伊勢侵攻で木下藤吉郎らに攻められ落城"],["1982年","周辺の城跡とあわせて国の史跡に指定"]],"who":[["北畠満雅","伊勢国司。南朝の皇統を支持して幕府に反乱した"],["木下藤吉郎（豊臣秀吉）","1569年に阿坂城を攻め落とした"],["大宮大之丞","1569年に阿坂城を守ったと伝わる北畠方の武将"]],"deep":["国の史跡としての名称は «阿坂城跡 附 高城跡・枳城跡（からたちじょうあと）»。阿坂城のまわりの小さな城もあわせて指定されています。","«白米城伝説» は全国に数十か所以上あるといわれ、民俗学の研究テーマにもなっています。阿坂城の話はそのなかでも古い時代の合戦と結びついた例です。","北畠満雅は1428年、称光天皇が亡くなったのを機に再び挙兵しましたが、幕府方の守護・土岐氏らとの戦いで戦死しました。北畠氏はその後も伊勢国司として存続します。","1569年の攻略で秀吉が負傷したという話は、後世の記録によるもので、確かな一次史料での裏付けは十分ではありません。","阿坂城の山頂からは、平野の向こうに伊勢湾が見え、北畠氏の本拠である南伊勢と、北伊勢を結ぶ道を見張る位置にあったことがわかります。"],"look":["山頂の南北二つの曲輪（本丸・二の丸）","土塁と堀切の跡","白米城の伝説を伝える案内板","山頂からの伊勢湾の眺め"],"q":["阿坂城の兵が、水がたっぷりあるように見せかけるために馬にかけたものは？","白い米。遠くから見ると水で馬を洗っているように見えたと伝わります（白米城伝説）。"],"koji":[],"myth":"白米城伝説は全国に類話があり史実かどうか不明。1569年の秀吉負傷、守将の名は伝承。","img":["北畠満雅","北畠氏","豊臣秀吉"],"wp":"阿坂城","rel":{"ev":[],"grave":[]},"ph":[["c:b/be/%E5%8C%97%E7%95%A0%E6%BA%80%E9%9B%85%E3%81%AE%E4%BD%8D%E7%BD%B2%E3%81%A8%E8%8A%B1%E6%8A%BC.jpg",1320,2231,"北畠満雅"],["c:5/5b/Sasa_Rind%C5%8D_inverted.png",1675,1675,"北畠氏"]]},{"id":"24_tamaru_jo","n":"田丸城（紀州藩の伊勢の拠点）","yomi":"たまるじょう","cat":"城","rank":"A","y":1575,"era":["muromachi","azuchi","edo"],"sh":"県指定史跡","ad":"度会郡玉城町田丸","st":"JR参宮線 田丸駅から歩いて約10分","la":34.488,"lo":136.6366,"hook":"南朝の砦として生まれ、信長の息子が三重の天守を建て、最後は紀州藩の «伊勢の出張所» になった、三つの顔をもつ城。","lead":"田丸城は、伊勢神宮にほど近い小高い丘の上にあった城の跡です。南北朝時代に南朝方の北畠氏が砦を置いたのが始まりと伝わり、戦国時代には織田信長の次男・信雄（のぶかつ）が大きく作り直しました。江戸時代は紀州藩の家老・久野（くの）氏が守り、いまは石垣と堀が残る公園になっています。","story":["田丸の丘は、伊勢神宮へ向かう道と、熊野へ向かう道が分かれるあたりにあります。南北朝時代、吉野の南朝を支えた北畠氏は、この丘に砦を置いたと伝わります。«伊勢と熊野、両方の道をにらめる場所をおさえよ»。道が交わる所を押さえることは、いつの時代も戦の基本でした。","戦国時代、伊勢の国司だった北畠家に、織田信長は次男の信雄を養子として送り込みました。北畠家をじわじわと乗っ取るためです。信雄はこの田丸城を大きく作り直し、三重の天守をもつ立派な城にしました。伊勢の人々は、見上げる天守に «新しい支配者が来た» と感じたことでしょう。","ところが天守は、完成から数年で火事によって焼けてしまったと伝わります。信雄は田丸を離れ、海に近い松ヶ島城へ本拠を移しました。なぜ移ったのでしょう。城が焼けたこともありますが、海の道と商人の町を押さえたかったから、とも考えられています。","江戸時代になると、この地は紀州徳川家の領地になりました。和歌山から遠く離れた伊勢の領地をまとめるため、紀州藩は家老の久野氏を田丸城に置きました。久野氏は «付家老» と呼ばれる家柄で、明治維新までここを治めました。«殿さまは和歌山、城には家老»。ちょっと変わった城だったのです。","明治になって城は取り壊されましたが、高い石垣や堀は今もよく残っています。本丸の天守台に立つと、玉城の町と田んぼが広がり、遠く伊勢の山々も見えます。春には桜の名所としてにぎわい、戦の城は町の人のいこいの場所になりました。"],"tl":[["1336年ごろ","南朝方の北畠氏が砦を築いたと伝わる"],["1575年ごろ","織田信雄が城を大改修し、三重の天守を建てる"],["1580年ごろ","天守が焼失したと伝わる。信雄は松ヶ島城へ移る"],["1619年","紀州徳川家の領地となり、家老の久野氏が城主に"],["1869年ごろ","明治維新で城としての役目を終える"],["現在","城跡は公園として整備され、石垣と堀が残る"]],"who":[["北畠親房・顕能","南朝を支えた北畠一族。田丸に砦を置いたと伝わる"],["織田信雄","信長の次男。北畠家の養子となり、田丸城を大改修"],["久野宗成","紀州藩の付家老。久野氏初代の田丸城主"],["徳川頼宣","紀州藩初代藩主。伊勢の領地を久野氏に任せた"]],"deep":["城の始まりの年は、1336年（延元元年）に北畠氏が築いたという説が知られますが、はっきりした史料は少なく、諸説あります。","信雄が建てた天守は «三重» とされ、伊勢地方では早い時期の天守の一つと考えられています。焼失の年や原因は伝承に頼る部分が多いです。","«付家老» とは、徳川家康が親藩（尾張・紀州・水戸）につけた重臣の家のこと。久野氏のほか、紀州の安藤氏・水野氏などが知られます。","紀州藩の伊勢の領地は «勢州領» と呼ばれ、田丸・松阪・白子（しろこ）などに役所が置かれました。田丸はその中心の一つでした。","城の門の一部は、明治の取り壊しのあと民家やお寺に移されたと伝わり、町を歩くと城の名残に出会えることがあります。","本丸・二の丸・北の丸などの区画が石垣でよく分かり、戦国から江戸にかけての石垣の積み方の違いを見比べるのも楽しみです。"],"look":["本丸の天守台（石垣と眺め）","城の外まわりの堀","大手の石垣と坂道","春の桜並木"],"q":["江戸時代、田丸城を守ったのはどこの藩の家老？","紀州（和歌山）藩の付家老・久野氏です。殿さまのいる和歌山から遠い伊勢の領地をまとめました。"],"koji":[],"myth":"築城年（1336年説）や天守の焼失年は伝承・諸説あり。","img":["織田信雄","北畠氏"],"wp":"田丸城","rel":{"ev":[],"grave":[]},"ph":[["c:9/91/Tamaru_Castle_Site_in_Spring_2013.jpg",3182,2334,"田丸城"],["c:b/be/Oda_Nobukatu.jpg",1285,2393,"織田信雄"],["c:5/5b/Sasa_Rind%C5%8D_inverted.png",1675,1675,"北畠氏"]]},{"id":"24_toba_jo","n":"鳥羽城（九鬼水軍の海の城）","yomi":"とばじょう","cat":"城","rank":"A","y":1594,"era":["azuchi","edo"],"sh":"","ad":"鳥羽市鳥羽3丁目","st":"JR・近鉄 鳥羽駅から歩いて約10分","la":34.4818,"lo":136.8466,"hook":"大手門が海に向いていた城。表玄関から船で出入りした、«海賊大名» 九鬼嘉隆ならではの城。","lead":"鳥羽城は、九鬼水軍をひきいた九鬼嘉隆（くき よしたか）が安土桃山時代に築いた城の跡です。城の正面の門（大手門）が海に向いて作られ、«浮城» とも呼ばれました。今は建物は残っていませんが、石垣と、海を見わたす本丸跡が公園になっています。","story":["鳥羽の港を見下ろす小山の上に、かつて城がありました。ふつうの城は、正面の門が町や街道の方を向いています。ところが鳥羽城は、表の門が海の方に開いていたといわれます。«わしらの道は海だ»。水軍の大将・九鬼嘉隆らしい考え方でした。","嘉隆は志摩の小さな豪族の出身でしたが、織田信長に仕えて大出世しました。大坂の石山本願寺を助ける毛利の水軍と戦ったとき、嘉隆は大きな船を作って勝利したと伝わります。その功績で志摩一国をまかされ、豊臣秀吉の時代に築いたのが、この鳥羽城でした。","城は海に突き出た地形を生かし、三方を海に囲まれていたといいます。天守もあったとされ、海から見上げると、まるで海に浮かんでいるようだったのでしょう。船で出入りし、いざとなれば船ですぐ戦いに出る。まさに «海の城» でした。","ところが1600年の関ヶ原の戦いで、九鬼家は父と子で東西に分かれました。父の嘉隆は西軍、息子の守隆は東軍です。«どちらが負けても家は残る»。そんな思いがあったともいわれます。戦のあと嘉隆は自害し、鳥羽城は守隆が受けつぎました。","やがて九鬼家は内陸の藩へ移され、鳥羽城にはいくつもの大名が入れかわり、江戸時代の中ごろからは稲垣氏が明治まで治めました。明治に城は取り壊され、海も埋め立てられて、今は港の景色の中に石垣だけが静かに残っています。"],"tl":[["1594年ごろ","九鬼嘉隆が鳥羽城を築いたと伝わる"],["1600年","関ヶ原の戦い。嘉隆は西軍、守隆は東軍に"],["1600年","嘉隆が答志島で自害。守隆が鳥羽藩主に"],["1633年","九鬼家が摂津三田・丹波綾部へ移される"],["1725年","稲垣氏が鳥羽藩主となり、明治まで続く"],["明治時代","城が取り壊され、跡地は学校などに使われる"]],"who":[["九鬼嘉隆","九鬼水軍の大将。鳥羽城を築いた"],["九鬼守隆","嘉隆の子。関ヶ原で東軍につき鳥羽藩を守った"],["織田信長","嘉隆を取り立て、水軍を重く用いた"],["稲垣氏","江戸時代中ごろから明治まで鳥羽を治めた大名家"]],"deep":["大手門が海側にあった点は、鳥羽城の最大の特徴として語られます。陸側の門は «搦手（からめて）» で、ふつうの城とは逆だったといわれます。","城跡の一部は長く小学校や市役所の用地として使われ、近年は石垣の調査と整備が進められています。","天守は三重（または三重四階）だったとされますが、残された絵図によって描かれ方がちがい、はっきりしない点があります。","九鬼家が内陸へ移されたのは、守隆の死後に起きた家督争い（お家騒動）がきっかけといわれます。海の大名が海を失ったのです。","鳥羽藩は江戸時代、城主がたびたび入れかわり、内藤・土井・松平・板倉・戸田・稲垣などの家が治めました。","城跡からは鳥羽湾に浮かぶ島々が見え、九鬼水軍がどんな海を舞台にしていたかを実感できます。"],"look":["本丸跡からの鳥羽湾の眺め","残された石垣","城山のふもとの海沿いの道（かつての海岸線を想像）","近くの鳥羽みなとまち文学館や港の景色"],"q":["鳥羽城の正面の門（大手門）は、どちらを向いていた？","海の方です。水軍の大将・九鬼嘉隆の城らしく、船で出入りするつくりだったといわれます。"],"koji":[],"myth":"築城年、天守の姿、関ヶ原で父子が東西に分かれた理由は諸説。","img":["九鬼嘉隆","九鬼守隆","鳥羽藩"],"wp":"鳥羽城","rel":{"ev":[],"grave":[]},"ph":[["c:9/91/%E9%B3%A5%E7%BE%BD%E5%9F%8E2.jpg",1691,1342,"鳥羽城"],["c:3/3c/Kukiyoshitaka2.jpg",1141,2101,"九鬼嘉隆"]]},{"id":"24_kuki_yoshitaka","n":"九鬼嘉隆の首塚・胴塚（答志島）","yomi":"くきよしたかのくびづか・どうづか","cat":"墓所","rank":"A","y":1600,"era":["azuchi"],"sh":"","ad":"鳥羽市答志町（答志島・和具）","st":"鳥羽マリンターミナル（佐田浜港）から市営定期船で和具港へ約30分、港から歩いて約10〜20分","la":34.525,"lo":136.888,"hook":"«海賊大名» 九鬼嘉隆は、最後に自分の城が見える島で命を絶った。首と体は、別々の場所に眠っている。","lead":"答志島（とうしじま）は、鳥羽の沖に浮かぶ島です。1600年、関ヶ原の戦いで西軍についた九鬼嘉隆は、この島で自害しました。島には、嘉隆の体を葬った «胴塚» と、首を葬った «首塚» が別々にあります。首塚は、鳥羽城の方を向くように作られたと伝わります。","story":["1600年、天下分け目の関ヶ原の戦い。九鬼家は、父の嘉隆が西軍、息子の守隆が東軍につきました。戦いは東軍の勝利。西軍に味方した嘉隆は、鳥羽を出て答志島へのがれたといわれます。","一方、息子の守隆は、徳川家康に父の命を助けてほしいと願い出ました。家康はこれを許したと伝わります。«父上、助かりましたぞ»。守隆の使いは急いで答志島へ向かいました。","ところが、その知らせが届く前に、嘉隆は島で自害してしまいました。家臣から «家を守るため、ここはお覚悟を» とすすめられたともいわれます。知らせがあと少し早ければ――。答志島の嘉隆の最期は、戦国の悲劇として今も語られます。","嘉隆の首は、家康のもとへ運ばれて確認されたのち、島に戻されて葬られたと伝わります。首塚は島の高い所にあり、嘉隆が築いた鳥羽城の方角を向いているといわれます。体は、自害した場所に近い所に «胴塚» として葬られました。","信長のもとで大きな鉄の船を作ったといわれ、秀吉の朝鮮出兵でも水軍をひきいた嘉隆。その «海の男» が最後に選んだのは、海に囲まれた小さな島でした。塚の前に立つと、潮風の中に、父と子の悲しい行き違いが思い出されます。"],"tl":[["1542年","九鬼嘉隆が生まれる"],["1578年","第二次木津川口の戦いで、嘉隆の大船が毛利水軍を破る"],["1594年ごろ","鳥羽城を築く"],["1597年ごろ","家督を子の守隆にゆずり隠居"],["1600年","関ヶ原の戦い。嘉隆は西軍、守隆は東軍"],["1600年","嘉隆が答志島で自害。首塚・胴塚が作られる"]],"who":[["九鬼嘉隆","九鬼水軍の大将。答志島で自害した"],["九鬼守隆","嘉隆の子。東軍につき、父の助命を願い出た"],["徳川家康","守隆の願いを聞き入れ、嘉隆の助命を許したと伝わる"],["豊田五郎右衛門","嘉隆に自害をすすめたと伝わる家臣。のちに守隆に罰せられたといわれる"]],"deep":["«首塚» と «胴塚» が別々にあるのは、首が首実検（本人確認）のために運ばれたためと考えられています。戦国時代の武将の墓にはこうした例がいくつもあります。","第二次木津川口の戦いで使われた大船は «鉄甲船» と呼ばれ、船体に鉄板を張っていたとされますが、どの程度鉄で覆われていたかは研究者の間で議論があります。","九鬼家が東西に分かれたことを、家を残すための作戦と見る説もありますが、確かな史料で裏付けられているわけではありません。","助命の知らせが間に合わなかった話や、自害をすすめた家臣の話は、九鬼家に伝わる話や地元の伝承によるところが大きいです。","答志島は古くから漁業の島で、九鬼水軍の拠点の一つだったともいわれます。今も «寝屋子（ねやこ）» と呼ばれる若者の共同生活の習わしが残ることで知られます。"],"look":["首塚（鳥羽城の方角を向くといわれる）","胴塚","塚へ向かう島の坂道と集落の風景","島から見る鳥羽の町と海"],"q":["九鬼嘉隆の首塚は、どこの方角を向いているといわれる？","嘉隆が築いた鳥羽城の方角です。"],"koji":[],"myth":"助命の知らせが間に合わなかった話、自害をすすめた家臣の話、首塚の向きの話は伝承。","img":["答志島","九鬼水軍","木津川口の戦い"],"wp":"九鬼嘉隆","rel":{"ev":[],"grave":[]},"ph":[["c:3/3c/Kukiyoshitaka2.jpg",1141,2101,"九鬼嘉隆"],["c:a/af/Tobaj1.jpg",893,1289,"九鬼水軍"]]},{"id":"24_kameyama_jo","n":"亀山城 多門櫓","yomi":"かめやまじょう たもんやぐら","cat":"城","rank":"A","y":1590,"era":["azuchi","edo"],"sh":"県指定史跡","ad":"亀山市本丸町","st":"JR関西本線 亀山駅から歩いて約15分","la":34.8556,"lo":136.4508,"hook":"«まちがえて天守を壊された» という、ちょっと気の毒な言い伝えをもつ城。その天守台に、三重県で唯一の江戸時代の城の建物が立つ。","lead":"伊勢亀山城は、東海道の宿場町・亀山を見下ろす丘にあった城です。天守台の石垣の上に建つ «多門櫓（たもんやぐら）» は、江戸時代から残る貴重な建物で、三重県内に残る唯一の城の建物といわれます。白い壁の櫓が、今も町のシンボルになっています。","story":["亀山は、東海道と、伊勢や大和へ向かう道が集まる交通の要でした。この丘には中世から関氏の城がありましたが、豊臣秀吉の時代、岡本宗憲（むねのり）がこの地に新しい城を築いたとされます。","この城には、ちょっと気の毒な言い伝えがあります。江戸時代の初め、幕府が «丹波の亀山城（京都府）の天守を壊せ» と命じたのに、伝えまちがいで伊勢の亀山城の天守が壊されてしまった、というのです。«えっ、うちの天守が?»。本当の話かどうかは分かりませんが、名前が同じ城ならではの話です。","天守が失われたあと、その天守台の上に建てられたのが多門櫓です。細長い建物で、武器をしまったり、敵を見張ったりするためのものでした。城主はたびたび入れかわり、江戸時代の中ごろからは石川氏が明治まで治めました。","明治になると、城のほとんどの建物は取り壊されました。多門櫓も城としての役目を終えましたが、取り壊されずに残り、やがて県の史跡として大切に守られることになりました。","平成の保存修理では、江戸時代の姿を目指して壁や瓦が直され、白く美しい姿がよみがえりました。石垣の上に立つ櫓を見上げると、宿場町を行き交った旅人たちも同じ景色を見たのだろうと思えてきます。"],"tl":[["1590年","岡本宗憲が亀山城を築いたとされる"],["1632年ごろ","天守が取り壊される（丹波亀山城とまちがえたという伝承がある）"],["江戸時代前期","天守台の上に多門櫓が建てられる"],["1744年","石川総慶が城主となり、以後石川氏が明治まで治める"],["明治初め","城の建物の多くが取り壊される"],["2011〜2013年ごろ","多門櫓の保存修理が行われる"]],"who":[["岡本宗憲","豊臣秀吉の家臣。亀山城を築いたとされる"],["堀尾忠晴","天守の取り壊しを担当したと伝わる大名"],["石川総慶","石川氏の亀山藩主。以後石川氏が明治まで続く"],["関氏","中世にこの地を治めた一族"]],"deep":["«丹波亀山とまちがえて天守を壊した» という話は有名ですが、それを直接示す確かな史料はなく、伝承として扱われています。","多門櫓は、天守台の石垣の上に建つ «単層の櫓» です。天守の跡に櫓が建つという点でも珍しい例です。","京都府の亀山城（丹波亀山）は、明智光秀が築いたことで知られ、明治に «亀岡» と地名が変わりました。名前がまぎらわしかったのが理由の一つといわれます。","亀山藩は東海道の宿場町を城下にもち、参勤交代の大名や旅人の通行を見守る役目もありました。","保存修理では、古い写真や調査をもとに、江戸時代の姿に近づけるよう壁のつくりなどが見直されました。"],"look":["天守台の石垣と多門櫓","多門櫓の内部公開（公開日を確認）","本丸跡からの亀山の町並み","近くの亀山宿の町並み"],"q":["亀山城の天守が壊された理由として伝わる «まちがい» とは？","同じ名前の «丹波亀山城» の天守を壊すはずが、伊勢の亀山城が壊されたという話です（伝承）。"],"koji":[],"myth":"天守を «まちがえて壊した» 話は伝承で、確かな史料はない。","img":["亀山藩","亀山宿"],"wp":"亀山城 (伊勢国)","rel":{"ev":["k_tokaido"],"grave":[]},"ph":[["c:b/b0/%E4%BA%80%E5%B1%B1%E5%9F%8E%E5%A4%9A%E8%81%9E%E6%AB%93.JPG",3072,2304,"亀山城 (伊勢国)"],["c:7/7d/Hiroshige_matin_clair_d%27hiver_%C3%A0_Kameyama.jpg",909,600,"亀山宿"]]},{"id":"24_kuwana_jo","n":"桑名城（本多忠勝の城）","yomi":"くわなじょう","cat":"城","rank":"A","y":1601,"era":["edo"],"sh":"","ad":"桑名市吉之丸（九華公園）","st":"JR・近鉄 桑名駅から歩いて約20分","la":35.0663,"lo":136.6947,"hook":"生涯57回の戦で傷ひとつ負わなかったといわれる猛将・本多忠勝。その最後の仕事は、戦ではなく «町づくり» だった。","lead":"桑名城は、徳川四天王の一人・本多忠勝が江戸時代の初めに大きく整えた城です。揖斐川（いびがわ）の河口に面した «水城» で、町も城といっしょに作り直されました。今は «九華公園（きゅうかこうえん）» になっていて、堀と石垣、忠勝の銅像が見られます。","story":["関ヶ原の戦いのあと、徳川家康は桑名を大事な場所と考えました。東海道が海をわたる «七里の渡し» の港があり、西の大名ににらみをきかせる入り口だったからです。家康がここに送りこんだのが、信頼する猛将・本多忠勝でした。","忠勝といえば、鹿の角のかぶとに長い槍 «蜻蛉切（とんぼきり）»。戦で一度も傷を負わなかったと伝わる名将です。ところが桑名での忠勝は、槍ではなく «町づくり» に力を注ぎました。川の流れを整え、堀をほり、町を区画し直したのです。これは «慶長の町割» と呼ばれています。","城には四重六階の天守がそびえていたといわれます。しかし1701年の大火事で焼けてしまい、その後は再建されませんでした。なぜでしょう。天守を建て直すには大変なお金がかかり、平和な江戸時代には必要とされなくなっていたからだと考えられます。","江戸時代の終わり、桑名藩主は松平定敬（さだあき）。京都で幕府を守る仕事をしていたため、戊辰戦争では新政府軍と戦う立場になりました。桑名城は戦わずに明けわたされ、城の櫓の一つは焼かれたと伝わります。","いま九華公園には、桜やツツジが咲き、忠勝の銅像が堀を見守っています。川沿いには、堤防の施設として外観が復元された «蟠龍櫓（ばんりゅうやぐら）» も立ち、水城だったころの雰囲気を伝えています。"],"tl":[["1601年","本多忠勝が桑名に入り、城と町の大改修（慶長の町割）を始める"],["1610年","本多忠勝が桑名で亡くなる"],["1617年","松平（久松）定勝が桑名藩主となる"],["1701年","大火で天守が焼失。以後再建されず"],["1868年","戊辰戦争。桑名城が新政府軍に明けわたされる"],["2003年","蟠龍櫓が外観復元される"]],"who":[["本多忠勝","徳川四天王の一人。桑名城と城下町を大きく整えた"],["本多忠政","忠勝の子。のちに姫路城主となる"],["松平定勝","家康の異父弟。桑名藩主"],["松平定敬","幕末の桑名藩主。京都所司代をつとめた"]],"deep":["«九華公園» の «九華» は «くわな» と読める当て字で、公園の名前に城下の地名がかくれています。","本多忠勝の «生涯57回の戦で傷を負わなかった» という話は有名ですが、数字は後世の軍記物などによるもので、確かめようがありません。","蟠龍櫓は、歌川広重の «東海道五十三次 桑名» にも描かれた櫓を参考に、水門の管理施設として外観を復元したものです。","桑名城は川と海の水を堀に引きこんだ «水城» で、城の周りは水路が入り組んでいました。今も堀の一部が残っています。","本多忠勝の墓は桑名市内の浄土寺にあり、城下の町とあわせて訪ねることができます。"],"look":["本多忠勝の銅像","九華公園の堀と石垣","蟠龍櫓（川沿い）","近くの七里の渡し跡"],"q":["本多忠勝が桑名で行った、城と町を大きく作り直した事業を何という？","«慶長の町割» です。川の流れを整え、町を区画し直しました。"],"koji":[{"w":"家康に過ぎたるもの二つあり、唐のかしらに本多平八","m":"家康には似合わないほど立派なものが二つある、それは唐のかぶと飾りと本多忠勝だ、という意味の落書（らくしょ）。忠勝の強さを表す言葉"}],"myth":"«57回の戦で無傷» は後世の伝承。天守の階数も史料により異なる。","img":["本多忠勝","九華公園","蟠龍櫓"],"wp":"桑名城","rel":{"ev":["k_tokaido"],"grave":[]},"ph":[["c:2/2c/Kuwana_castle_tower_foundation_%28ruin_of_Donjon%29.JPG",4000,3000,"桑名城"],["c:4/40/Portrait-Honda-Tadakatsu.jpg",824,1189,"本多忠勝"],["c:3/3c/Kyuka_Park01.jpg",4000,3000,"九華公園"]]},{"id":"24_nagashima_jo","n":"長島城","yomi":"ながしまじょう","cat":"城","rank":"B","y":1574,"era":["muromachi","azuchi","edo"],"sh":"","ad":"桑名市長島町西外面","st":"近鉄名古屋線 近鉄長島駅から歩いて約15分","la":35.0875,"lo":136.698,"hook":"大きな川にはさまれた «輪中（わじゅう）» の島で、信長を何年も苦しめた一向一揆。その舞台に立っていた城。","lead":"長島城は、木曽川・長良川・揖斐川という三つの大きな川の河口にはさまれた、長島の地にあった城です。戦国時代、ここは一向宗（浄土真宗）の門徒たちの拠点になり、織田信長と激しく戦いました。江戸時代には長島藩の城となり、今は学校の敷地に一本の松などがわずかに名残をとどめています。","story":["長島は、三つの大河が海に流れこむあたりの低い土地です。川にぐるりと囲まれた土地を、人々は堤防で守って暮らしてきました。こうした土地を «輪中» といいます。水に囲まれた長島は、攻めにくい天然の要塞でもありました。","戦国時代、長島には一向宗の大きな寺・願証寺（がんしょうじ）があり、たくさんの門徒が集まっていました。«仏さまのためなら命もおしまない»。門徒たちは信長の支配に立ち向かい、長島一向一揆が起こります。長島城も一揆方の拠点の一つとなりました。","信長は何度も長島を攻めましたが、川と湿地にはばまれて苦戦し、弟や家臣を失いました。1574年、信長は大軍と水軍で長島を取り囲み、城や砦にこもった人々を追い詰めました。このとき多くの門徒が命を落としたと伝わります。戦国時代でもとくに悲しい戦いの一つです。","一揆のあと、長島城には信長の家臣・滝川一益が入りました。その後、信長の次男・信雄も長島を拠点にしたと伝わります。江戸時代には長島藩の城となり、増山氏が明治まで治めました。","明治になって城は取り壊され、跡地は学校になりました。城の門は近くのお寺の山門として移されたと伝わります。静かな住宅地を歩くと、ここが川と戦の歴史の舞台だったとは思えないほどです。"],"tl":[["15世紀後半ごろ","長島に一向宗の願証寺が開かれたといわれる"],["1570年","長島一向一揆が起こる"],["1574年","信長が長島を総攻撃し、一揆を鎮圧"],["1574年","滝川一益が長島城に入る"],["1702年","増山氏が長島藩主となり、明治まで続く"],["明治時代","城が取り壊され、跡地は学校に"]],"who":[["織田信長","長島一向一揆を攻め、鎮圧した"],["滝川一益","信長の家臣。一揆のあと長島城主となる"],["織田信雄","信長の次男。長島を拠点にした時期があると伝わる"],["増山氏","江戸時代中ごろから明治まで長島藩を治めた"]],"deep":["長島一向一揆は1570年から1574年にかけての戦いで、信長は少なくとも3度大がかりな攻撃を行いました。亡くなった人の数は «2万人» などといわれますが、確かな数は分かりません。","信長の弟・織田信興は一揆方に攻められて自害し、これが信長の怒りを強めたといわれます。","1585年の天正地震では、長島周辺も大きな被害を受けたといわれ、城にも影響があったと伝わります。","江戸時代の長島藩は小さな藩で、城主の家は何度か入れかわりました。","城の大手門とされる門が、近くのお寺の山門として残っていると伝わります。","長島一帯は明治時代にオランダ人技師デ・レーケらが関わった «木曽三川分流工事» で、川の姿が大きく変わりました。"],"look":["本丸跡とされる学校敷地の松（外から見学）","移築されたと伝わる城門（お寺の山門）","長島の輪中の地形と堤防","願証寺（一向一揆ゆかりの寺）"],"q":["川に囲まれ、堤防で守られた土地のことを何という？","«輪中（わじゅう）» です。長島もその一つで、攻めにくい天然の要塞でした。"],"koji":[],"myth":"一揆で亡くなった人の数、城門の移築の話には諸説がある。","img":["長島一向一揆","願証寺","輪中"],"wp":"長島城","rel":{"ev":[],"grave":[]},"ph":[["c:9/95/Nagashima_castle_ootemon.JPG",3072,2304,"長島城"],["c:9/9b/Battle_of_Nagashima.jpg",2000,964,"長島一向一揆"],["c:8/8d/Gansh%C5%8D-ji_in_Kuwana.jpg",1280,960,"願証寺"]]},{"id":"24_kanbe_jo","n":"神戸城（天守台の石垣）","yomi":"かんべじょう","cat":"城","rank":"B","y":1580,"era":["muromachi","azuchi","edo"],"sh":"県指定史跡","ad":"鈴鹿市神戸5丁目（神戸公園）","st":"近鉄鈴鹿線 鈴鹿市駅から歩いて約10分","la":34.8813,"lo":136.581,"hook":"信長の三男・信孝がそびえ立たせた五重の天守。いまは、ごつごつとした石垣だけが、その高さを語る。","lead":"神戸城（かんべじょう）は、鈴鹿市の中心にあった城の跡です。戦国時代に伊勢の豪族・神戸氏が築き、のちに織田信長の三男・信孝が大きな天守を建てました。いま残る天守台の石垣は、自然の石をそのまま積んだ «野面積（のづらづみ）» で、戦国の城の力強さを感じさせます。","story":["神戸という地名を «かんべ» と読むのは、伊勢神宮に仕える土地（神戸＝かんべ）だったことに由来するといわれます。この地に城を築いたのが、伊勢の豪族・神戸氏でした。","伊勢に進出した織田信長は、神戸氏と和睦し、三男の信孝を神戸家の養子に入れました。«三男坊を送りこみ、家ごと取りこむ»。信長が伊勢を手に入れるためによく使った作戦です。こうして信孝は «神戸信孝» となりました。","信孝は神戸城を大きく作り直し、五重の天守を建てたといわれます。伊勢平野を見わたす高い天守は、信長の子としての力を見せつけるものだったのでしょう。しかし1582年、本能寺の変で父・信長が倒れると、信孝の運命は大きく変わります。","信孝は兄の信雄や羽柴秀吉と対立し、翌年、追い詰められて自害しました。主を失った神戸城の天守は、のちに解体され、桑名城に移されたと伝わります。«神戸櫓» と呼ばれたといわれ、城の命は形を変えて続いたのです。","江戸時代には神戸藩の城となり、本多氏が明治まで治めました。今は神戸公園として整備され、天守台の石垣と堀の一部が残っています。石垣の上に立つと、ここに五重の天守がそびえていた姿を思い浮かべることができます。"],"tl":[["1550年ごろ","神戸氏が神戸城を築いたといわれる"],["1568年ごろ","織田信孝が神戸氏の養子となる"],["1580年ごろ","信孝が五重の天守を建てたと伝わる"],["1583年","信孝が自害する"],["1595年ごろ","天守が解体され、桑名城に移されたと伝わる"],["1732年","本多氏が神戸藩主となり、明治まで続く"]],"who":[["神戸具盛","神戸氏の当主。信孝を養子に迎えた"],["織田信孝","信長の三男。神戸城に五重天守を建てた"],["織田信長","信孝を神戸家に送りこみ、伊勢を支配した"],["本多氏","江戸時代中ごろから明治まで神戸藩を治めた"]],"deep":["天守台の石垣は、形を整えない自然の石を積む «野面積» で、戦国時代の特徴をよく残しています。","五重天守の姿を描いた確かな絵図はなく、天守の規模は伝承や記録をもとに推測されています。","天守が桑名城に移されたという話は «神戸櫓» の名とともに伝わりますが、詳しいことは分かっていません。","信孝の自害の地は尾張の野間（愛知県美浜町）とされ、辞世の句が伝わります。","神戸藩の本多氏は、徳川四天王・本多忠勝の家とは別の系統の本多家です。","神戸城の近くには、信孝が城下の町を整えたときに集めたともいわれる寺や町の名前が残り、城下町の広がりを感じることができます。","天守台は高さ数メートルほどの石垣で、上に登ることができます。石の大きさや形がそろっていない積み方は、江戸時代の整った石垣と比べるとちがいがよく分かります。"],"look":["天守台の野面積の石垣","残された堀","神戸公園の桜","城下町・神戸の町並み"],"q":["信長の三男・信孝は、なぜ «神戸» 信孝と名乗った？","伊勢の豪族・神戸氏の養子になったからです。信長が伊勢を支配するための作戦でした。"],"koji":[],"myth":"五重天守の規模と、天守が桑名城に移された話は伝承。","img":["織田信孝","神戸藩"],"wp":"神戸城","rel":{"ev":[],"grave":[]},"ph":[["c:7/77/%E7%A5%9E%E6%88%B8%E5%9F%8E%E6%9C%AC%E4%B8%B8%E3%82%92%E6%92%AE%E5%BD%B1.jpg",520,410,"神戸城"],["c:b/b0/Oda_Nobutaka.jpg",950,1390,"織田信孝"]]},{"id":"24_akagi_jo","n":"赤木城（北山一揆と藤堂高虎の縄張り）","yomi":"あかぎじょう","cat":"城","rank":"A","y":1589,"era":["azuchi"],"sh":"国指定史跡","ad":"熊野市紀和町赤木","st":"JR紀勢本線 熊野市駅から車で約50分（公共交通では行きにくい）","la":33.9025,"lo":136.047,"hook":"山奥にそびえる、まるで «天空の城» のような石垣。けれどここは、一揆に立ち上がった村人たちを押さえるために築かれた城だった。","lead":"赤木城は、熊野の山深い里にある城の跡です。豊臣秀吉の時代、この地で起きた北山一揆を押さえるため、築城の名人として知られる藤堂高虎が築いたといわれます。美しい石垣がほぼそのまま残り、国の史跡になっています。","story":["熊野の山あいを車で走っていくと、ふいに丘の上に石垣が現れます。春には桜、秋には紅葉に囲まれ、まるで絵のような景色です。けれど、この城が生まれた理由を知ると、少し胸が痛くなります。","豊臣秀吉が天下を治めはじめたころ、熊野の山々は秀吉の弟・羽柴秀長の領地になりました。秀長の家臣たちは、山の木を切り出し、年貢や検地を進めました。«山は昔からわしらの暮らしの場だ»。山に生きてきた北山の人々は反発し、一揆を起こしたと伝わります。","一揆を押さえるため、秀長の家臣だった藤堂高虎がこの地に入り、赤木城を築いたといわれます。高虎はのちに今治城や津城、江戸城の工事にも関わった築城の名人です。赤木城の石垣にも、その腕前が表れているといわれます。","城の近くの田平子峠（たびらことうげ）には、一揆に加わった人々が処刑されたと伝わる場所があり、供養の碑が立っています。城の美しさと、その陰で失われた命。赤木城は、その両方を静かに伝えています。","江戸時代になると、赤木城は使われなくなりました。人里はなれた山の中だったことで、石垣は大きく壊されずに残りました。発掘と整備が進められ、今では戦国末期の城の姿を知る貴重な場所になっています。"],"tl":[["1585年ごろ","熊野の地が羽柴秀長の領地となる"],["1589年","北山一揆が起こったと伝わる"],["1589年ごろ","藤堂高虎が赤木城を築いたといわれる"],["江戸時代初め","城が使われなくなる"],["1989年","国の史跡に指定される"],["平成時代","発掘調査と石垣の整備が進む"]],"who":[["藤堂高虎","羽柴秀長の家臣。赤木城を築いたといわれる築城の名人"],["羽柴秀長","秀吉の弟。熊野を含む紀伊・大和などを治めた"],["北山の人々","山の暮らしを守ろうと一揆を起こした村人たち"]],"deep":["北山一揆は天正年間（1580年代）に起こったとされますが、何度あったのか、正確な年はいつかについては諸説あります。","赤木城は «高虎の築城» とされますが、それを示す史料は限られ、後の記録や城の特徴から考えられている部分もあります。","城の石垣は、自然石を積んだ野面積を中心に、角の部分に大きな石を組み合わせる工夫が見られます。","主郭（本丸）を中心に、周りに曲輪が段々に配置され、小さいながらもよく計算されたつくりになっています。","田平子峠の刑場跡は、赤木城とともに一揆の歴史を伝える場所として、地元で大切に供養されています。","熊野の紀和町は、古くから銅の鉱山で知られた地域で、山の資源をめぐる争いが一揆の背景にあったとも考えられています。","赤木城の周辺は «紀州鉱山» などの鉱山でも知られた地域で、近くには鉱山の歴史を伝える資料館もあり、山の暮らしの歴史をあわせて学べます。"],"look":["本丸の石垣（角の積み方）","段々に並ぶ曲輪のつくり","城跡から見る山あいの景色","近くの田平子峠の供養碑"],"q":["赤木城を築いたといわれる、築城の名人はだれ？","藤堂高虎です。のちに津城や今治城も築きました。"],"koji":[],"myth":"北山一揆の年や回数、高虎の築城かどうかは諸説あり。","img":["藤堂高虎","羽柴秀長","北山一揆"],"wp":"赤木城","rel":{"ev":[],"grave":[]},"ph":[["c:a/aa/Akagi_Castle_View.jpg",2340,1560,"赤木城"],["c:e/e2/Toudou_Takatora.jpg",1056,1096,"藤堂高虎"],["c:9/95/Hidenaga_Toyotomi.jpg",560,658,"羽柴秀長"]]},{"id":"24_shichiri_watashi","n":"七里の渡し（桑名の伊勢国一の鳥居）","yomi":"しちりのわたし","cat":"街道","rank":"A","y":1601,"era":["edo"],"sh":"県指定史跡","ad":"桑名市船馬町","st":"JR・近鉄 桑名駅から歩いて約20分","la":35.0684,"lo":136.6953,"hook":"東海道でただ一つの «海の道»。船をおりた旅人を最初にむかえたのは、伊勢神宮の «一の鳥居» だった。","lead":"七里の渡しは、江戸時代の東海道で、熱田（宮宿・名古屋市）と桑名宿の間を船で結んだ海の道です。距離が «七里（約27km）» だったことからこの名がつきました。桑名側の港には、伊勢国の入り口を示す大きな鳥居が立っています。","story":["江戸から京へのびる東海道。その途中の熱田から桑名までは、川と湿地が広がって陸の道を通すのがむずかしく、旅人は船で海をわたりました。これが «七里の渡し» です。天気がよければ数時間の船旅でした。","ところが、海はいつも穏やかとはかぎりません。風が強い日は船が出せず、旅人は何日も足止めされることもありました。船酔いに苦しむ人もいたでしょう。«やっと着いた!»。桑名の港に着いた旅人は、ほっと胸をなでおろしたはずです。","港に着くと、目の前に大きな鳥居が立っていました。これが «伊勢国一の鳥居»。ここから先は伊勢国、つまり伊勢神宮のある国に入るという目印です。伊勢参りの人々にとっては、いよいよ神宮に近づいたという感動の場所でした。","この鳥居は、伊勢神宮の式年遷宮（20年に一度の建て替え）にあわせて、神宮の古い鳥居の材を使って建て替えられてきたといわれます。«神宮とつながる鳥居»。桑名の人々はそれを誇りにしてきました。","今は港の近くに堤防が築かれ、昔の渡し場の雰囲気は少し変わりましたが、鳥居と常夜灯、そばの蟠龍櫓が、にぎやかだった港町の記憶を伝えています。歌川広重の «東海道五十三次» にも、桑名の港と城が描かれています。"],"tl":[["1601年","東海道の宿駅が定められ、宮宿と桑名宿の間が海路に"],["1782年","伊勢国一の鳥居が建てられたといわれる"],["1833年ごろ","歌川広重の «東海道五十三次» に桑名が描かれる"],["明治時代","鉄道の開通で渡し船の役目が小さくなる"],["昭和時代","三重県の史跡に指定される"],["現在","伊勢神宮の式年遷宮にあわせ鳥居の建て替えが続く"]],"who":[["歌川広重","«東海道五十三次» で桑名の渡し場と城を描いた浮世絵師"],["本多忠勝","桑名城主。港と城下町を整えた"],["伊勢参りの人々","江戸時代、渡し船に乗って伊勢神宮をめざした旅人たち"]],"deep":["七里は約27.5kmにあたります。実際の船の道は、潮の満ち引きによって沖の方を回ることもあったといわれます。","熱田と桑名の間には、さらに佐屋（さや）宿を経由する «三里の渡し»（佐屋街道）もあり、海が苦手な人はこちらを選んだと伝わります。","伊勢国一の鳥居は、伊勢神宮の «宇治橋» の外側の鳥居の古材を使って建て替えられてきたといわれます。","渡し場のそばの蟠龍櫓は、水門を管理する施設として、桑名城の櫓の姿を参考に外観が復元されました。","熱田側（名古屋市熱田区）にも «七里の渡し跡（宮の渡し）» が残り、両方を訪ねると東海道の海路の旅を実感できます。","渡し船の乗り場の近くには、船の出入りを見張る番所や、旅人を泊める本陣・旅籠が並び、桑名宿は東海道でも指折りの大きな宿場でした。旅人の名物は «焼きはまぐり» だったといわれます。"],"look":["伊勢国一の鳥居","常夜灯","すぐそばの蟠龍櫓","揖斐川の河口の景色"],"q":["七里の渡しは、どこの宿場とどこの宿場を結んでいた？","熱田の宮宿（名古屋市）と桑名宿です。東海道でただ一つの海の道でした。"],"koji":[],"myth":"鳥居の古材の由来や建立年については、資料により表現が異なる。","img":["桑名宿","宮宿","蟠龍櫓"],"wp":"七里の渡し","rel":{"ev":["k_tokaido"],"grave":[]},"ph":[["c:d/de/%E5%AE%AE%E3%81%AE%E6%B8%A1%E3%81%97%E5%85%AC%E5%9C%92.jpg",704,478,"七里の渡し"],["c:7/75/Tokaido42_Kuwana.jpg",920,600,"桑名宿"],["c:7/7c/Hiroshige42_miya.jpg",2153,1410,"宮宿"]]},{"id":"24_rokkaen","n":"六華苑（諸戸清六邸とコンドル設計の洋館）","yomi":"ろっかえん","cat":"近代","rank":"A","y":1913,"era":["taisho"],"sh":"国の重要文化財","ad":"桑名市桃栄町","st":"JR・近鉄 桑名駅から歩いて約25分、またはバスで最寄り停留所から歩いて約5分","la":35.0612,"lo":136.6955,"hook":"鹿鳴館を設計したイギリス人建築家が、地方の実業家のために描いた洋館。その塔は、施主の注文で «4階» に伸びた。","lead":"六華苑（ろっかえん）は、桑名の実業家・二代目 諸戸清六（もろと せいろく）の住まいとして大正時代に建てられた邸宅です。洋館は、東京の鹿鳴館などを設計したイギリス人建築家ジョサイア・コンドルの設計。洋館と和館、池のある庭がいっしょに見られ、国の重要文化財になっています。","story":["明治時代、桑名に «山林王» と呼ばれた実業家がいました。初代 諸戸清六です。米の商売で財をなし、山林を買い集め、大きな財産を築きました。その跡をついだ息子が、二代目 諸戸清六です。","二代目が新しい住まいの洋館を頼んだのは、ジョサイア・コンドル。明治政府にまねかれて来日し、鹿鳴館やニコライ堂などを手がけた «日本の近代建築の父» とも呼ばれる人です。東京の建築家が、なぜ桑名の家を?。それだけ諸戸家の力が大きかったのでしょう。","洋館の角には、水色の壁の塔がそびえています。コンドルの設計は3階建ての塔だったといわれますが、清六の希望で4階建てになったと伝わります。«揖斐川の流れを見わたしたい»。そんな思いがあったともいわれます。","洋館のとなりには、畳の部屋が続く和館がつながっています。洋館でお客をもてなし、和館で家族が暮らす。明治・大正のお金持ちの家では、こうした «和洋館並列» のつくりがよく見られました。","戦後、邸宅は桑名市のものとなり、整備されて一般に公開されました。池を中心にした庭園を歩くと、大正時代の豊かな暮らしと、洋と和がとけ合った美しさを感じることができます。映画やドラマの撮影にもよく使われています。"],"tl":[["1846年","初代 諸戸清六が生まれる"],["1906年","初代 諸戸清六が亡くなり、息子が名前を継ぐ"],["1913年","洋館が完成する（ジョサイア・コンドル設計）"],["1920年","ジョサイア・コンドルが亡くなる"],["1991年ごろ","桑名市の所有となる"],["1997年","洋館・和館などが国の重要文化財に指定される"]],"who":[["二代目 諸戸清六","六華苑を建てた実業家"],["初代 諸戸清六","«山林王» と呼ばれた父。諸戸家の財産を築いた"],["ジョサイア・コンドル","洋館を設計したイギリス人建築家。鹿鳴館などを設計"]],"deep":["六華苑の洋館は、コンドルが設計した建物のうち、東京以外に残る数少ない作品として知られます。","塔の階数は «設計では3階、施主の希望で4階に» という話が伝わりますが、細かないきさつは確かめられていません。","«六華» は雪の結晶（六角形）を表すことばで、諸戸家の «六» にちなんだ名前ともいわれます。","初代 諸戸清六は、井戸水の悪さに悩む桑名の町のために自費で水道を引いたとされ、その «諸戸水道» の遺構も知られています。","となりの «諸戸氏庭園» は初代清六ゆかりの庭で、国の名勝に指定され、特別公開の時期に見学できます。","洋館と和館はそれぞれ別の設計者によるもので、和館は地元の大工の手によるとされます。一つの家の中で西洋と日本の技術が出会っているのが見どころです。"],"look":["水色の4階建ての塔","洋館の暖炉や窓などの室内","洋館と和館のつながり","池泉回遊式の庭園"],"q":["六華苑の洋館を設計した建築家はだれ？","ジョサイア・コンドルです。東京の鹿鳴館などを設計したイギリス人建築家です。"],"koji":[],"myth":"塔が4階になったいきさつ、«六華» の名の由来は伝承・諸説。","img":["諸戸清六","ジョサイア・コンドル"],"wp":"六華苑","rel":{"ev":[],"grave":[]},"ph":[["c:4/4c/%E5%85%AD%E8%8F%AF%E5%AE%9B%E5%BB%BA%E7%89%A9%E5%A4%96%E8%A6%B3%EF%BC%92.jpg",6000,4000,"六華苑"],["c:b/b5/Josiah-Conder-Portrait-1.jpg",537,788,"ジョサイア・コンドル"]]},{"id":"24_horeki_chisui","n":"宝暦治水 薩摩義士の墓（海蔵寺）","yomi":"ほうれきちすい さつまぎしのはか（かいぞうじ）","cat":"事件","rank":"A","y":1755,"era":["edo"],"sh":"県指定史跡","ad":"桑名市北寺町（海蔵寺）","st":"JR・近鉄 桑名駅から歩いて約10分","la":35.064,"lo":136.688,"hook":"遠く九州の薩摩から来た武士たちが、見知らぬ土地の川と戦った。工事が終わったとき、その責任者は命を絶った。","lead":"江戸時代の中ごろ、幕府は薩摩藩（鹿児島県）に、木曽川・長良川・揖斐川の治水工事を命じました。これを «宝暦治水» といいます。工事は大変な苦労の末に完成しましたが、多くの薩摩藩士が命を落としました。桑名の海蔵寺には、工事の責任者・平田靱負（ゆきえ）ら薩摩藩士の墓があります。","story":["木曽川・長良川・揖斐川の三つの大河が集まる濃尾平野の南の地域は、昔から洪水に苦しめられてきました。1753年、幕府はこの川の工事を、遠く離れた薩摩藩に命じます。«なぜ薩摩に?»。大きな力をもつ薩摩藩の財力を弱めるため、ともいわれています。","薩摩藩の家老・平田靱負は、総奉行として約千人ともいわれる藩士をひきいてやって来ました。お金はすべて薩摩藩の負担。慣れない土地、きびしい幕府の役人の目、何度も流される堤防。工事は困難をきわめました。","工事の途中、病気で亡くなる人が相次ぎました。さらに、幕府の役人とのもめごとや工事のやり直しに抗議して、自ら命を絶った藩士もいたと伝わります。故郷から遠く離れた地で、彼らは何を思ったでしょうか。","1755年、工事はついに完成しました。しかしその直後、平田靱負は美濃の宿舎で亡くなりました。莫大な費用と多くの犠牲の責任をとって自害したと伝わります。«住みなれし里も今更名残にて»。そう始まる辞世の歌が伝わっています。","平田らの遺体は、薩摩藩とゆかりのあった桑名の海蔵寺などに葬られました。いま海蔵寺の墓の前には花が絶えず、毎年供養が行われています。宝暦治水で亡くなった人々を静かにしのび、手を合わせたい場所です。"],"tl":[["1753年","幕府が薩摩藩に木曽三川の治水工事を命じる"],["1754年","工事が始まる"],["1754〜1755年","病気や自害で多くの藩士が亡くなる"],["1755年","工事が完成。総奉行・平田靱負が亡くなる"],["1938年","岐阜県に平田らをまつる治水神社が創建される"],["現在","海蔵寺で毎年供養が続けられる"]],"who":[["平田靱負","薩摩藩家老。宝暦治水の総奉行"],["島津重年","当時の薩摩藩主"],["薩摩藩士たち","工事にあたり、多くが現地で亡くなった"]],"deep":["亡くなった藩士の数は «自害51人、病死33人» などと伝えられますが、当時の記録では自害は表向き伏せられたともいわれ、正確な数には諸説があります。","工事費は約40万両にのぼったといわれ、薩摩藩は大きな借金を背負いました。","平田靱負の死も «自害» と伝わりますが、公式には病死として届けられたとされ、はっきりしない点があります。","工事の一つ «油島（あぶらじま）の締切堤» には、薩摩から持ちこんだといわれる松が植えられ、今も «千本松原» として残ります（岐阜県海津市）。","宝暦治水のあとも川の問題は完全には解決せず、明治時代にオランダ人技師デ・レーケらの指導で «木曽三川分流工事» が行われました。","鹿児島県と岐阜県は、この歴史をきっかけに姉妹県の関係を結んでいます。"],"look":["海蔵寺の薩摩義士の墓","平田靱負の墓","寺に伝わる義士の記録や説明板","あわせて訪ねたい岐阜県の治水神社・千本松原"],"q":["宝暦治水の工事を幕府に命じられたのはどこの藩？","薩摩藩（今の鹿児島県）です。遠く離れた地の川の工事を、藩のお金で行いました。"],"koji":[],"myth":"犠牲者の数、自害の事実、平田の辞世の歌は伝承・諸説がある。","img":["平田靱負","木曽三川","治水神社"],"wp":"宝暦治水事件","rel":{"ev":[],"grave":[]},"ph":[["c:7/74/Statue_of_Yukie_Hirata_in_Kaizu_03.jpg",4000,3000,"宝暦治水事件"],["c:c/cb/%E6%B2%BB%E6%B0%B4%E7%A5%9E%E7%A4%BE.jpg",1136,852,"平田靱負"],["c:3/36/Kiso_Three_Rivers_and_N%C5%8Dbi_Plain_from_Mount_Tado.jpg",2560,1280,"木曽三川"]]},{"id":"24_tado_taisha","n":"多度大社（上げ馬神事）","yomi":"たどたいしゃ","cat":"寺社","rank":"A","y":763,"era":["nara","azuchi","edo"],"sh":"","ad":"桑名市多度町多度","st":"養老鉄道 多度駅から歩いて約20分","la":35.1297,"lo":136.6245,"hook":"«お伊勢参らばお多度もかけよ、お多度かけねば片参り»。伊勢神宮とセットで参るべきとうたわれた、北伊勢の大社。","lead":"多度大社は、多度山のふもとにある古い神社で、«北伊勢大神宮» とも呼ばれてきました。天照大神の子とされる天津彦根命（あまつひこねのみこと）をまつります。毎年5月の «上げ馬神事» では、若者が馬に乗って急な坂をかけ上がり、その年の米の出来を占います。","story":["多度山は、濃尾平野の西の端にそびえる山です。古くから山そのものが神さまと考えられ、ふもとに神社がまつられました。«お伊勢参らばお多度もかけよ»。伊勢神宮と並んで大事な神社として、多くの人がお参りしました。","奈良時代には、神社のそばに «多度神宮寺» というお寺が建てられました。満願（まんがん）という僧が、神さまのために仏教の寺を開いたと伝わります。神と仏をいっしょにまつる «神仏習合» の早い例として知られています。","戦国時代、多度大社に大きな災いがおそいます。長島の一向一揆を攻めた織田信長の軍によって、社殿が焼かれてしまったのです。神社は長い間さびれましたが、江戸時代になり、桑名城主・本多忠勝らによって再興されたと伝わります。","毎年5月4日・5日に行われるのが上げ馬神事です。若い騎手が馬に乗り、高い土の壁のある急坂をかけ上がります。馬が上がりきった回数で、その年の稲の出来を占うといわれます。«上がった!»。成功するたびに、大きな歓声がわきます。","近年、上げ馬神事は «馬への負担が大きいのではないか» という声を受けて、坂の形や運営のしかたが見直されています。長く受けつがれてきた伝統を、命あるものへの配慮とどう両立させるか。多度の人々は今、その答えを探しています。"],"tl":[["古代","多度山を神の山としてまつる信仰が始まる"],["763年","満願によって多度神宮寺が開かれたと伝わる"],["平安時代","«延喜式» の名神大社に数えられる"],["1571年","信長の長島攻めで社殿が焼かれる"],["江戸時代初め","本多忠勝らの支援で再興されたと伝わる"],["2020年代","上げ馬神事の方法が見直される"]],"who":[["天津彦根命","多度大社の主祭神。天照大神の子とされる"],["満願","奈良時代の僧。多度神宮寺を開いたと伝わる"],["織田信長","長島攻めの際に社殿を焼いた"],["本多忠勝","桑名城主。多度大社の再興を助けたと伝わる"]],"deep":["«多度神宮寺伽藍縁起并資財帳» は、奈良時代の神宮寺の様子を伝える貴重な史料で、国の重要文化財に指定されています。","多度大社の別宮 «一目連（いちもくれん）神社» は、嵐や雨をつかさどる神をまつるといわれ、扉のない社殿で知られます。","上げ馬神事は三重県の無形民俗文化財に指定されていますが、動物愛護の観点から近年大きな議論となり、運営方法が改められています。","«白馬伝説»: 多度の神は白い馬に乗って現れるといわれ、境内には神馬がいます。","多度大社は、伊勢神宮の天照大神の子をまつることから、伊勢との深いつながりが語られてきました。","多度山は標高約400mの山で、山頂付近からは濃尾平野と木曽三川、晴れた日には名古屋の町まで見わたせます。山そのものを神と仰いだ古い信仰を実感できます。"],"look":["本宮と一目連神社","上げ馬神事の坂","境内を流れる清流と滝","神馬（白馬）"],"q":["上げ馬神事で、馬が坂をかけ上がった回数で占うものは？","その年の稲（米）の出来です。"],"koji":[{"w":"お伊勢参らばお多度もかけよ、お多度かけねば片参り","m":"伊勢神宮に参るなら多度大社にも参りなさい、でないと半分しかお参りしたことにならない、という意味の古いうた"}],"myth":"神宮寺の創建年、本多忠勝の再興の関わり方、白馬伝説は伝承を含む。","img":["上げ馬神事","多度山"],"wp":"多度大社","rel":{"ev":[],"grave":[]},"ph":[["c:8/8d/Tado-taisha%2C_hongu_and_betsugu.jpg",5562,3702,"多度大社"],["c:5/5a/Mount_Tado_from_east_2009-09-20.jpg",1280,854,"多度山"]]},{"id":"24_matsudaira_sadaaki","n":"松平定敬と桑名藩（鎮国守国神社）","yomi":"まつだいらさだあき と くわなはん（ちんこくしゅこくじんじゃ）","cat":"幕末","rank":"B","y":1868,"era":["edo","meiji"],"sh":"","ad":"桑名市吉之丸（九華公園内）","st":"JR・近鉄 桑名駅から歩いて約20分","la":35.066,"lo":136.694,"hook":"兄は会津の松平容保。弟の定敬は、京都で兄と肩を並べて幕府を守り、最後は箱館まで戦い続けた。","lead":"松平定敬（さだあき）は、幕末の桑名藩主です。兄の会津藩主・松平容保（かたもり）とともに京都で幕府を支え、京都所司代をつとめました。戊辰戦争では旧幕府側として各地を転戦しました。桑名城跡の九華公園には、桑名藩主の祖先をまつる鎮国守国神社があります。","story":["定敬は、美濃の高須藩主の家に生まれました。兄弟には、尾張藩主の徳川慶勝、一橋家をついだ徳川茂徳（もちなが）、会津藩主の松平容保がいて、«高須四兄弟» と呼ばれます。定敬は桑名藩の養子となり、若くして藩主になりました。","幕末の京都は、尊王攘夷をさけぶ志士たちで騒がしくなっていました。兄の容保が京都守護職として治安を守る一方、定敬は京都所司代となり、兄と力を合わせました。新選組もこの «会津・桑名» の下で働いたことで知られます。","1868年、鳥羽・伏見の戦いで旧幕府軍は敗れます。定敬は将軍・徳川慶喜とともに大坂から船で江戸へ向かいました。«殿のいない桑名をどうするか»。国元の家臣たちは話し合い、城を戦わずに新政府軍へ明けわたす道を選びました。","しかし定敬と一部の家臣は戦いをやめませんでした。越後の柏崎、会津、そして北の箱館（函館）へ。桑名藩士の中には、若い立見鑑三郎（のちの陸軍大将・立見尚文）のように各地で活躍した人もいました。","箱館からいったん国外へ出たのち、定敬は帰国して新政府に降伏しました。のちに許され、晩年は日光東照宮の宮司をつとめたといわれます。九華公園の鎮国守国神社を訪ねると、嵐のような時代を生きた桑名藩の人々の姿が浮かんできます。"],"tl":[["1847年","松平定敬が高須藩主の家に生まれる"],["1859年","桑名藩の養子となり藩主をつぐ"],["1864年","京都所司代となる"],["1868年","鳥羽・伏見の戦い。桑名城は新政府軍に明けわたされる"],["1869年","箱館戦争が終わり、のち定敬は降伏"],["1908年","松平定敬が亡くなる"]],"who":[["松平定敬","幕末の桑名藩主。京都所司代"],["松平容保","定敬の兄。会津藩主で京都守護職"],["徳川慶喜","江戸幕府最後の将軍。定敬とともに江戸へ戻った"],["立見鑑三郎","桑名藩士。戊辰戦争で活躍し、のちに陸軍大将"]],"deep":["鎮国守国神社の «鎮国» は桑名藩松平家の祖・松平定綱、«守国» は寛政の改革で知られる松平定信をまつることに由来します。","定信の子孫が桑名藩主となったのは1823年で、白河から桑名への移動は «三方領知替え» の一つとして知られます。","京都で «一会桑（いちかいそう）» と呼ばれた勢力は、一橋慶喜・会津藩・桑名藩の頭文字をとった呼び名です。","定敬が箱館から国外へ出た行き先は上海とされ、その後帰国して降伏したと伝わります。","桑名藩の国元が城を明けわたした際、先代藩主の子・万之助（のちの松平定教）を立てて恭順したといわれ、その判断が町を戦火から守ったとも評価されます。","高須四兄弟は、明治になって東京で再会し、記念の写真を撮ったといわれます。幕末に敵味方に分かれた兄弟のその後を物語る一枚として知られています。"],"look":["鎮国守国神社","九華公園の堀と石垣","本多忠勝の銅像（あわせて）","神社の宝物館（公開日を確認）"],"q":["松平定敬の兄で、京都守護職をつとめた会津藩主はだれ？","松平容保です。兄弟で京都の治安を守りました。"],"koji":[],"myth":"晩年の経歴や国外脱出の行程には資料により細部の違いがある。","img":["桑名藩","松平容保","鎮国守国神社"],"wp":"松平定敬","rel":{"ev":["k_tokaido"],"grave":[]},"ph":[["c:6/67/Matudaira_Sadaaki.jpg",540,660,"松平定敬"],["c:5/59/Kuwanajou001.jpg",800,600,"桑名藩"],["c:9/90/Matudaira_Katamori.jpg",993,1548,"松平容保"],["c:9/9b/%E9%8E%AE%E5%9B%BD%E5%AE%88%E5%9B%BD%E7%A5%9E%E7%A4%BE_-_5.jpg",3637,2728,"鎮国守国神社"]]},{"id":"24_yokkaichi_juku","n":"四日市宿","yomi":"よっかいちしゅく","cat":"街道","rank":"B","y":1601,"era":["edo"],"sh":"","ad":"四日市市北町・中町・南町など","st":"近鉄 四日市駅、またはJR四日市駅から歩いて約10分","la":34.97,"lo":136.625,"hook":"毎月 «四» のつく日に市が立ったから «四日市»。広重は、この宿場を «風で笠が飛ばされる旅人» の姿で描いた。","lead":"四日市宿は、江戸時代の東海道五十三次の43番目の宿場です。毎月4のつく日に市が開かれたことが地名の由来といわれます。港があり、伊勢参りの道も近くで分かれる交通の要として、とてもにぎわいました。","story":["四日市の名前は、中世から «四のつく日» に市が立っていたことに由来するといわれます。人と物が集まる町は、江戸時代に東海道の宿場に選ばれ、さらににぎやかになりました。","四日市には港もありました。熱田から船で直接四日市へ向かう «十里の渡し» もあったといわれ、陸と海の両方から旅人がやってきました。宿場には本陣や旅籠がずらりと並び、夜も明かりが絶えなかったことでしょう。","歌川広重の «東海道五十三次 四日市» には、強い風の中、飛ばされた笠を追いかける旅人が描かれています。«おおい、待ってくれ!»。どこかユーモラスなその姿は、川と海に近い四日市の風の強さを伝えているのかもしれません。","宿場の南には、東海道と伊勢参宮の道が分かれる «日永の追分» があり、伊勢参りの人々もたくさん四日市を通りました。宿場の中心には諏訪神社があり、今も町の人々の祭りの場になっています。","明治以降、四日市は港と工業の町として大きく発展しました。1945年の空襲で町の多くが焼け、宿場の面影はあまり残っていませんが、旧東海道を歩くと、道の曲がり方や道標に、昔の宿場町の名残を見つけることができます。"],"tl":[["中世","四のつく日に市が立ち «四日市» と呼ばれるようになったといわれる"],["1601年","東海道の宿場に定められる"],["1833年ごろ","歌川広重の «東海道五十三次» に描かれる"],["1843年","本陣2軒、旅籠が約100軒あったとされる"],["1899年","四日市港が開港場に指定される"],["1945年","四日市空襲で町の多くが焼ける"]],"who":[["歌川広重","«東海道五十三次 四日市» を描いた浮世絵師"],["旅人・伊勢参りの人々","東海道と伊勢道を行き来した"],["四日市の商人たち","市と港を支え、町を発展させた"]],"deep":["«東海道宿村大概帳»（天保14年・1843年ごろ）では、四日市宿の旅籠は98軒と記され、東海道の中でも大きな宿場でした。","広重の «四日市» の絵は «三重川» とも題され、川にかかる橋と、風に吹かれる旅人が描かれています。","宿場の東の港からは、熱田方面への船も出ていたとされ、七里の渡しを避けて四日市から船に乗る人もいたといわれます。","戦後、四日市は石油化学コンビナートの町となり、1960年代には «四日市ぜんそく» と呼ばれる公害が起こりました。宿場の町は、日本の近代化の光と影の両方を見てきました。","旧東海道には、昔の道標や常夜灯がいくつか残っており、町歩きで探すことができます。","四日市の港は、明治時代に地元の実業家・稲葉三右衛門らが私財を投じて整備したといわれ、港の発展が近代の四日市の基礎になりました。","宿場の近くを流れる三滝川にかかる橋は、広重の絵に描かれた橋のモデルの一つと考えられています。"],"look":["旧東海道の道すじ","諏訪神社","道標や常夜灯","四日市市立博物館（宿場の展示）"],"q":["«四日市» という名前の由来は？","毎月4のつく日に市が立ったことに由来するといわれます。"],"koji":[],"myth":"«十里の渡し» の運行実態や地名の由来には諸説がある。","img":["東海道五十三次","諏訪神社 (四日市市)"],"wp":"四日市宿","rel":{"ev":["k_tokaido"],"grave":[]},"ph":[["c:8/8f/Tokaido43_Yokkaichi.jpg",934,600,"四日市宿"],["c:f/f7/Hiroshige_le_pont_Nihonbashi_%C3%A0_l%27aube.jpg",1618,1080,"東海道五十三次"],["c:2/28/Suwa-jinja_yokkaichi.jpg",958,719,"諏訪神社 (四日市市)"]]},{"id":"24_hinaga_oiwake","n":"日永の追分（東海道と伊勢街道の分かれ道）","yomi":"ひながのおいわけ","cat":"街道","rank":"A","y":1774,"era":["edo"],"sh":"県指定史跡","ad":"四日市市追分1丁目","st":"四日市あすなろう鉄道 内部線 追分駅から歩いて約5分","la":34.9313,"lo":136.5935,"hook":"«右 京大坂道、左 いせ参宮道»。江戸時代の旅人はここで、人生の旅の行き先を選んだ。","lead":"日永の追分（ひながのおいわけ）は、東海道から伊勢神宮へ向かう伊勢参宮道（伊勢街道）が分かれる地点です。ここには伊勢神宮を遠くから拝むための鳥居が立ち、道しるべと湧き水が残っています。伊勢参りの人々にとって、いよいよ伊勢への道に入る記念の場所でした。","story":["江戸時代、«一生に一度はお伊勢参り» と、たくさんの人々が伊勢神宮をめざしました。江戸から東海道を歩いてきた旅人は、四日市の南にあるこの分かれ道で東海道と別れ、伊勢参宮道へ進みました。","分かれ道には道しるべが立ち、どちらへ行けば何があるかを教えてくれました。«ここから先が伊勢の道か»。長い旅をしてきた人たちは、胸が高鳴ったことでしょう。京や大坂へ向かう人は、そのまままっすぐ東海道を進みました。","追分には鳥居が立っています。伊勢神宮まで行けない人でも、ここから神宮を拝むことができるように、と建てられたといわれます。江戸時代の中ごろ、江戸に住んでいた人の寄付で建てられたと伝わり、今も伊勢神宮の式年遷宮にあわせて建て替えられています。","鳥居のそばには、今も «追分の清水» と呼ばれる湧き水があります。旅人はここでのどをうるおし、一息ついたといわれます。現代の人々もペットボトルを持って水をくみに来るほどで、地元で大切にされています。","いまは車が行き交う交差点になっていますが、鳥居と道しるべ、湧き水が、分かれ道のにぎわいを伝えています。«右へ行くか、左へ行くか»。昔の旅人の気持ちになって、立ち止まってみたくなる場所です。"],"tl":[["江戸時代初め","東海道と伊勢参宮道の分かれ道として人の行き来が増える"],["1774年","伊勢神宮を遥拝する鳥居が建てられたと伝わる"],["1830年","«おかげ参り» で多くの人が伊勢へ向かう"],["江戸時代後期","分かれ道に道しるべが建てられる"],["昭和時代","三重県の史跡に指定される"],["現在","式年遷宮にあわせて鳥居が建て替えられる"]],"who":[["伊勢参りの人々","江戸時代、全国から伊勢神宮をめざした旅人"],["渡辺六兵衛","江戸に住み、鳥居を寄進したと伝わる人物"],["歌川広重","東海道や伊勢参りの風景を描いた浮世絵師"]],"deep":["«追分（おいわけ）» とは道が二つに分かれる場所のことで、全国に地名として残っています。","1830年の «おかげ参り» では、数か月の間に数百万人が伊勢へ向かったといわれ、日永の追分も大変な人の波だったと考えられます。","鳥居を寄進した人物については、江戸の商人・渡辺六兵衛とする伝えがありますが、詳しい経歴ははっきりしません。","鳥居の建て替えには伊勢神宮の古材が使われてきたといわれ、桑名の «伊勢国一の鳥居» と同じく神宮とのつながりを示しています。","近くを走る四日市あすなろう鉄道はナローゲージ（線路の幅がとても狭い鉄道）で、もとは近鉄の路線でした。鉄道好きにも知られています。","伊勢参宮道は、日永の追分から神戸・白子・津・松阪を通って伊勢神宮へ向かいます。宿場ごとに伊勢参りの人々を迎える文化が生まれ、街道筋には今も古い町並みが残ります。"],"look":["伊勢神宮遥拝の鳥居","道しるべ","追分の清水（湧き水）","四日市あすなろう鉄道の小さな電車"],"q":["日永の追分で、東海道から分かれていく道はどこへ向かう？","伊勢神宮へ向かう伊勢参宮道（伊勢街道）です。"],"koji":[],"myth":"鳥居・道標の建立年と寄進者は伝承による部分がある。","img":["伊勢街道","お蔭参り"],"wp":"日永の追分","rel":{"ev":[],"grave":[]},"ph":[["c:6/64/Hinaga-no-oiwake_Yokkaichi.jpg",896,672,"日永の追分"],["c:8/8a/Ando_hiroshige_miyakawanowatashi.jpg",2400,1233,"お蔭参り"]]},{"id":"24_ishiyakushi_juku","n":"石薬師宿（佐佐木信綱のふるさと）","yomi":"いしやくしじゅく","cat":"街道","rank":"B","y":1616,"era":["edo","meiji"],"sh":"","ad":"鈴鹿市石薬師町","st":"JR関西本線 加佐登駅から歩いて約20分","la":34.899,"lo":136.547,"hook":"«卯の花の匂う垣根に»――唱歌 «夏は来ぬ» の作詞者が生まれた、東海道の小さな宿場。","lead":"石薬師宿は、東海道五十三次の44番目の宿場です。宿場の名前は、町の入り口にある石薬師寺に由来します。明治時代に生まれた歌人・国文学者の佐佐木信綱のふるさととしても知られ、記念館や生家が残っています。","story":["四日市宿と庄野宿の間は距離が長く、旅人は途中で休む場所を必要としていました。そこで江戸時代の初め、1616年に新しく作られたのが石薬師宿です。宿場としては小さく、静かな町でした。","宿場の名前のもとになった石薬師寺には、大きな石に刻まれた薬師如来がまつられています。平安時代の僧・空海が、自然の石に一夜で薬師さまを刻んだと伝わります。«病が治りますように»。旅人たちはここで手を合わせ、道中の無事を祈りました。","宿場の近くには «蒲桜（かばざくら）» という桜があります。源頼朝の弟・源範頼（のりより）が、戦勝を祈ってむちを地面にさしたところ、それが根づいて桜になったという言い伝えがあります。範頼は «蒲冠者（かばのかじゃ）» と呼ばれていたので、この名がついたといわれます。","明治時代、この宿場町に一人の男の子が生まれました。のちに歌人・国文学者として活躍する佐佐木信綱です。信綱は、唱歌 «夏は来ぬ» の作詞者としても知られます。«卯の花の匂う垣根に ほととぎす早も来鳴きて»。ふるさとの初夏の景色が、歌の中に生きているのかもしれません。","今も石薬師の町並みには、昔ながらの家が点在し、宿場の雰囲気が残っています。道ばたには、信綱の短歌を刻んだ石柱が並び、歌を読みながら旧東海道を歩くことができます。"],"tl":[["平安時代","空海が石に薬師如来を刻んだと伝わる"],["1616年","東海道の宿場として石薬師宿が作られる"],["1833年ごろ","歌川広重の «東海道五十三次» に描かれる"],["1872年","佐佐木信綱が石薬師で生まれる"],["1896年","唱歌 «夏は来ぬ» が発表される"],["1970年","佐佐木信綱記念館が開館する"]],"who":[["佐佐木信綱","石薬師出身の歌人・国文学者。«夏は来ぬ» の作詞者"],["空海","石薬師寺の薬師如来を刻んだと伝わる僧"],["源範頼","源頼朝の弟。«蒲桜» の伝説が残る"],["歌川広重","石薬師宿を描いた浮世絵師"]],"deep":["石薬師宿は、それまで宿場のなかった区間に «あとから» 作られた宿場の一つで、1616年（元和2年）の設置とされます。","広重の «石薬師» には、秋の田んぼと石薬師寺の門前が描かれ、のどかな宿場の様子が伝わります。","佐佐木信綱は «万葉集» の研究で大きな業績を残し、第1回の文化勲章を受けた一人です。","石薬師寺の本尊は «秘仏» とされ、ふだんは見ることができないといわれます。","宿場の中心には小沢本陣があり、江戸時代の宿帳など、宿場の記録が伝わっているといわれます。","«夏は来ぬ» の作曲は小山作之助で、作詞の佐佐木信綱とともに明治の唱歌を代表する一曲として、今も学校や地域で歌われています。","石薬師宿は、四日市宿と亀山宿のあいだの長い区間を埋めるために作られた宿場で、同じ理由で庄野宿も少しあとに作られました。宿場が増えたことで、人馬の継ぎ立て（リレー）がしやすくなりました。"],"look":["石薬師寺","佐佐木信綱記念館と生家","蒲桜","旧東海道沿いの信綱の歌碑"],"q":["佐佐木信綱が作詞した、初夏の景色をうたった唱歌は？","«夏は来ぬ» です。«卯の花の匂う垣根に» で始まります。"],"koji":[],"myth":"空海の一夜彫り、範頼の蒲桜は伝承。本陣の宿帳の話は詳細未確認。","img":["佐佐木信綱","石薬師寺","夏は来ぬ"],"wp":"石薬師宿","rel":{"ev":[],"grave":[]},"ph":[["c:f/ff/Hiroshige%2C_Great_Tokaido_Series_Ishiyakushi.jpg",1024,678,"石薬師宿"],["c:e/e4/Nobutsuna_Sasaki.jpg",519,818,"佐佐木信綱"],["c:8/83/Ishiyakushiji_hondou.JPG",2048,1536,"石薬師寺"]]},{"id":"24_shono_juku","n":"庄野宿（広重「白雨」の地）","yomi":"しょうのじゅく","cat":"街道","rank":"B","y":1624,"era":["edo"],"sh":"","ad":"鈴鹿市庄野町","st":"JR関西本線 加佐登駅から歩いて約15分","la":34.8733,"lo":136.525,"hook":"とつぜんの夕立に、かごも旅人も坂をかけ出す――。広重の «庄野 白雨» は、日本の浮世絵の中でもとびきり有名な «雨» の絵だ。","lead":"庄野宿は、東海道五十三次の45番目の宿場で、江戸時代の初めに作られました。歌川広重の «東海道五十三次» の中で最高傑作の一つといわれる «庄野 白雨（はくう）» の舞台として知られます。宿場の資料館では、昔の宿場の暮らしを知ることができます。","story":["庄野宿は、石薬師宿と亀山宿の間に、1624年に作られた宿場です。東海道の宿場の中では、かなりあとになってから作られた宿場の一つでした。はじめは人も少なく、近くの村から人を呼び寄せて宿場を整えたといわれます。","庄野の名物は «焼米（やきごめ）» でした。お米を炒って平たくしたもので、旅人の保存食やおやつとして喜ばれたといわれます。«焼米を一つおくれ»。そんな声が、宿場の店先で聞こえたことでしょう。","庄野の名を全国に知らせたのは、歌川広重です。«東海道五十三次 庄野» の絵では、激しい夕立の中、かごをかつぐ人や、かさを傾けた旅人が、坂道を急いでいます。斜めの線で描かれた雨と、竹やぶが風にしなる様子が、まるで音が聞こえてくるようです。","«白雨» とは夕立のこと。広重が実際にこの場所で夕立にあったのかは分かりません。でも、晴れていた空が急に暗くなり、雨がどっと降り出す。そんな夏の東海道の一瞬を、広重は見事に切り取りました。この絵は海外でも高く評価されています。","今の庄野宿には、宿場の家を使った «庄野宿資料館» があり、宿場の道具や高札などが展示されています。静かな町並みを歩きながら、広重の夕立の絵を思い浮かべてみてください。"],"tl":[["1624年","東海道の宿場として庄野宿が作られる"],["江戸時代","名物 «焼米» が旅人に親しまれる"],["1833年ごろ","歌川広重の «庄野 白雨» が描かれる"],["1843年","本陣1軒、脇本陣1軒、旅籠15軒ほどがあったとされる"],["明治時代","鉄道の開通で宿場としての役目を終える"],["平成時代","旧家を利用した庄野宿資料館が開館する"]],"who":[["歌川広重","«庄野 白雨» を描いた浮世絵師"],["庄野宿の人々","新しい宿場を作り、焼米を名物にした"],["旅人","東海道を行き来し、宿場で休んだ"]],"deep":["«東海道宿村大概帳» では、庄野宿の旅籠は15軒ほどと記され、東海道の宿場の中では小さな規模でした。","«庄野 白雨» は、広重の保永堂版 «東海道五十三次» の中で «蒲原 夜之雪» などと並ぶ傑作とされます。","絵に描かれた坂や竹やぶは、実際の庄野の地形とは異なるともいわれ、広重の想像で描いた部分があると考えられています。","庄野宿資料館の建物は、江戸時代の油屋だった旧小林家の住宅を利用したものです。","焼米は «焼米俵» と呼ばれる小さな俵に入れて売られたといわれます。","庄野宿は、近くの村々から人を移り住ませて新しく作られた宿場といわれ、宿場がどのようにして生まれたのかを考えるうえで興味深い場所です。"],"look":["庄野宿資料館","旧東海道の町並み","宿場の高札（資料館の展示）","少し足をのばして、女人堤防の碑（鈴鹿市）"],"q":["広重の絵の題名にある «白雨（はくう）» とはどんな雨？","夕立のことです。«庄野 白雨» は、激しい夕立に急ぐ人々を描いています。"],"koji":[],"myth":"広重が実景を描いたかどうかは諸説。","img":["東海道五十三次 (浮世絵)","歌川広重"],"wp":"庄野宿","rel":{"ev":[],"grave":[]},"ph":[["c:8/8b/Hiroshige%2C_Travellers_surprised_by_sudden_rain.jpg",3033,1950,"庄野宿"],["c:a/ad/Catalogue_of_HIROSHIGE.jpg",4408,3052,"東海道五十三次 (浮世絵)"],["c:f/f1/Memorial_Portrait_of_Hiroshige%2C_by_Kunisada.jpg",2631,3841,"歌川広重"]]},{"id":"24_kameyama_juku","n":"亀山宿","yomi":"かめやましゅく","cat":"街道","rank":"B","y":1601,"era":["edo"],"sh":"","ad":"亀山市東町・西町・本町など","st":"JR関西本線 亀山駅から歩いて約15分","la":34.8545,"lo":136.453,"hook":"城下町と宿場町が一つになった町。広重はここを、雪の朝の急な坂道で描いた。","lead":"亀山宿は、東海道五十三次の46番目の宿場で、亀山城の城下町でもありました。町の入り口には «江戸口門» と «京口門» があり、城を守るしくみと、旅人をもてなす宿場のしくみが組み合わさっていました。今も旧東海道沿いに古い家並みが残っています。","story":["亀山は、城と宿場が一つになった町でした。町には武士の屋敷と、商人や旅籠の町が並びます。ほかの多くの宿場とちがい、殿さまの城が町を見下ろしていたのです。","城下町は、敵が攻めこみにくいよう、道がわざと曲げられたり、見通しを悪くしたりしてありました。亀山宿の旧東海道も、曲がりくねりながら町を抜けていきます。«まっすぐ行けないのは、守りのため»。町を歩くと、その工夫を体で感じることができます。","町の西の入り口には «京口門»、東には «江戸口門» がありました。門の前には見張りの番所があり、出入りする人に目を光らせていたといわれます。京口門は坂の上に立つ立派な門で、広重も絵に描いています。«通るなら、きちんと名乗ってからにせよ»。門は宿場の出入り口であると同時に、城下の守りの最前線でもありました。","広重の «東海道五十三次 亀山 雪晴» は、雪が積もった朝の急な坂道を、大名行列が登っていく姿を描いた作品です。白い雪、澄んだ空、斜めに走る坂道。静かで冷たい朝の空気まで伝わってくるようです。","明治になって城も門も失われましたが、町には古い商家や町家が残り、旧舘家住宅などが見学できます。東海道を歩く人々が、今も亀山の町並みを楽しみながら通り過ぎていきます。"],"tl":[["1590年ごろ","亀山城が築かれ、城下町が整えられる"],["1601年","東海道の宿場に定められる"],["1744年","石川氏が亀山藩主となる"],["1833年ごろ","広重の «亀山 雪晴» が描かれる"],["1843年","本陣1軒、脇本陣1軒、旅籠21軒ほどがあったとされる"],["明治時代","城と門が取り壊される"]],"who":[["歌川広重","«亀山 雪晴» を描いた浮世絵師"],["石川氏","江戸時代中ごろから明治まで亀山藩を治めた"],["大名行列","参勤交代で亀山宿を通った"]],"deep":["亀山宿は旅籠の数が少なめで、大名や旅人は隣の関宿に泊まることも多かったといわれます。","«亀山 雪晴» は保永堂版 «東海道五十三次» の中で、雪の風景を描いた数少ない作品の一つです。","京口門は、石垣の上に門を構えた立派なもので、坂の上から見下ろすように旅人をむかえていたといわれます。","旧舘家住宅は、江戸時代の終わりから明治にかけての商家の建物で、亀山市が公開しています。","亀山宿の町並みの一部は、亀山市の «歴史的町並み» として保存・整備が進められています。","亀山宿の西の端にある京口門跡の坂は、広重の «雪晴» の絵に描かれた坂の場所とされ、今も急な坂道が当時の地形をしのばせます。","亀山は東海道と伊勢別街道・大和街道が近くで分かれる交通の要所で、城と宿場が同じ町にあることには、交通を見守る意味もあったと考えられます。"],"look":["旧東海道の曲がりくねった道","京口門跡・江戸口門跡","旧舘家住宅","亀山城多門櫓（あわせて）","旧東海道沿いの古い町家と格子戸"],"q":["広重が描いた «亀山» の絵は、どんな天気の風景？","雪の晴れた朝（雪晴）です。雪の坂道を大名行列が登っていきます。"],"koji":[],"myth":"","img":["亀山城 (伊勢国)","東海道五十三次 (浮世絵)"],"wp":"亀山宿","rel":{"ev":["k_tokaido"],"grave":[]},"ph":[["c:7/7d/Hiroshige_matin_clair_d%27hiver_%C3%A0_Kameyama.jpg",909,600,"亀山宿"],["c:b/b0/%E4%BA%80%E5%B1%B1%E5%9F%8E%E5%A4%9A%E8%81%9E%E6%AB%93.JPG",3072,2304,"亀山城 (伊勢国)"],["c:a/ad/Catalogue_of_HIROSHIGE.jpg",4408,3052,"東海道五十三次 (浮世絵)"]]},{"id":"24_sakashita_juku","n":"坂下宿","yomi":"さかしたじゅく","cat":"街道","rank":"B","y":1650,"era":["edo"],"sh":"","ad":"亀山市関町坂下","st":"JR関西本線 関駅からコミュニティバスで約20分（本数が少なく、車が便利）","la":34.8807,"lo":136.344,"hook":"«坂は照る照る 鈴鹿は曇る あいの土山 雨が降る»。鈴鹿峠のふもとで、旅人はここで一息ついてから山に挑んだ。","lead":"坂下宿は、東海道五十三次の48番目の宿場で、東海道の難所・鈴鹿峠のすぐ手前にありました。峠越えの前後に泊まる旅人でにぎわい、本陣が3軒もある大きな宿場でした。今は山あいの静かな集落となり、宿場の跡を示す碑が点々と残っています。","story":["京へ向かう旅人の前に立ちはだかるのが鈴鹿峠です。坂下宿は、その峠のふもとにある宿場でした。«明日はいよいよ峠越えだ»。旅人たちはここで体を休め、わらじを新しくして山に向かいました。","坂下宿は、峠を越えてきた人、これから越える人の両方でにぎわいました。本陣が3軒、脇本陣が1軒あったとされ、山あいの宿場としてはとても大きな宿場でした。大名の行列が泊まることも多かったのです。","宿場は、もとはもっと峠に近い場所にありましたが、江戸時代の初めに大きな洪水で流されてしまい、今の場所に移ったと伝わります。山の中の宿場は、自然の厳しさと隣り合わせでした。","坂下の近くには «筆捨山（ふですてやま）» という山があります。室町時代の画家・狩野元信がこの山を描こうとしたところ、景色が刻々と変わるので描ききれず、筆を捨てたという言い伝えがあります。広重も «坂之下 筆捨嶺» としてこの山を描きました。","«坂は照る照る 鈴鹿は曇る あいの土山 雨が降る»。鈴鹿馬子唄は、坂下と鈴鹿峠、その先の土山の天気の違いをうたったものといわれます。今は旅籠も本陣も残っていませんが、山あいの道に立つと、馬子唄が聞こえてくるような気がします。"],"tl":[["江戸時代初め","東海道の宿場として坂下宿が置かれる"],["1650年","洪水で宿場が流され、今の場所へ移ったと伝わる"],["1833年ごろ","広重の «坂之下 筆捨嶺» が描かれる"],["1843年","本陣3軒、脇本陣1軒、旅籠48軒ほどがあったとされる"],["明治時代","鉄道が別のルートを通り、宿場がさびれる"],["現在","旧坂下小学校の校舎が «鈴鹿峠自然の家» として活用されている"]],"who":[["狩野元信","筆捨山の伝説に登場する室町時代の画家"],["歌川広重","«坂之下 筆捨嶺» を描いた浮世絵師"],["馬子","馬で旅人や荷物を運び、鈴鹿馬子唄をうたった人々"]],"deep":["本陣は «大竹屋»«梅屋»«松屋» の3軒があったとされ、現地に跡を示す碑が立っています。","坂下宿の移転は1650年（慶安3年）の洪水によるものとされ、それ以前の場所は «古町» と呼ばれるといわれます。","筆捨山の伝説の画家を «狩野法眼元信» とする話が広く知られていますが、あくまで伝承です。","鈴鹿馬子唄は、もとは街道で馬を引く馬子たちがうたった仕事唄で、地域によって歌詞にいろいろな形があります。","明治時代に鉄道（関西鉄道）は鈴鹿峠を避けて柘植方面を通ったため、坂下は交通の主役から外れました。","坂下宿のあたりは、鈴鹿川の上流にあたり、川沿いの細い谷に家が並ぶ地形です。宿場の家並みが谷に沿って細長く続いていた様子を想像できます。"],"look":["本陣跡の碑（大竹屋・梅屋・松屋）","鈴鹿峠自然の家（旧坂下小学校）","筆捨山","峠へ続く旧東海道"],"q":["筆捨山の名前の由来として伝わる話は？","画家が山を描こうとしたけれど、景色が次々変わるので描ききれず、筆を捨てたという言い伝えです。"],"koji":[{"w":"坂は照る照る鈴鹿は曇る あいの土山雨が降る","m":"鈴鹿馬子唄の一節。峠をはさんで天気がまったく違う山の気候をうたったものといわれる"}],"myth":"筆捨山の伝説、宿場移転の詳細は伝承。","img":["鈴鹿峠","筆捨山"],"wp":"坂下宿","rel":{"ev":[],"grave":[]},"ph":[["c:7/79/Tokaido48_Sakanoshita.jpg",874,600,"坂下宿"],["c:e/e4/Suzuka_Pass.jpg",2048,1536,"鈴鹿峠"],["c:f/f2/Mount_Fudesute%2C_Sakashita.jpg",552,374,"筆捨山"]]},{"id":"24_suzuka_toge","n":"鈴鹿峠（鈴鹿の山賊と坂上田村麻呂）","yomi":"すずかとうげ","cat":"街道","rank":"A","y":886,"era":["heian","edo"],"sh":"","ad":"亀山市関町坂下（滋賀県甲賀市との境）","st":"JR関西本線 関駅から車で約20分。坂下の集落から旧東海道の山道を歩いて約30〜40分","la":34.882,"lo":136.312,"hook":"山賊が出る、鬼が出る――。都と東国を結ぶ大動脈は、何百年もの間 «こわい峠» として恐れられた。","lead":"鈴鹿峠は、三重県と滋賀県の境にある東海道の峠です。平安時代に道が開かれ、都と東国を結ぶ大切な道になりました。一方で山賊が出る難所としても知られ、坂上田村麻呂が鬼を退治したという伝説も残ります。","story":["平安時代の886年、伊勢と近江を結ぶ新しい道が鈴鹿峠を越えて開かれたと記録されています。それまでより近道となったこの道は、やがて都と東国を結ぶ大動脈になりました。","けれど、山深い峠は危険な場所でもありました。«鈴鹿山には山賊が出る»。平安時代の物語や記録にも、旅人がおそわれた話が残っています。峠の近くには «鏡岩» という大きな岩があり、山賊がこの岩に映る旅人の姿を見て待ちぶせした、という言い伝えがあります。","鈴鹿山には、鬼や女盗賊の話も伝わります。美しい女性の姿をした «鈴鹿御前» と、坂上田村麻呂の物語はとくに有名です。鬼を退治したとも、田村麻呂と力を合わせて鬼を退治したともいわれ、話にはいくつもの形があります。","坂上田村麻呂は、平安時代の初めに東北地方へ遠征した実在の武将です。その強さから、各地で «鬼退治の英雄» としての伝説が生まれました。峠をはさんだ滋賀県側の田村神社には、田村麻呂がまつられています。","江戸時代になると、鈴鹿峠は大名行列や伊勢参りの人々が行き交う東海道の峠になりました。今は国道がトンネルで山を抜けていきますが、旧道には石畳や常夜灯が残り、ハイキングで昔の旅人の気分を味わうことができます。"],"tl":[["886年","鈴鹿峠を越える «阿須波道» が開かれたと記録される"],["平安時代","山賊の出る難所として物語に登場する"],["室町時代","鈴鹿御前と田村麻呂の物語が広まる"],["1601年","東海道の宿駅制度が始まり、峠は東海道の一部に"],["江戸時代","峠の滋賀県側に «万人講常夜灯» が建てられる"],["昭和時代","国道1号の鈴鹿トンネルが開通する"]],"who":[["坂上田村麻呂","平安初期の武将。鈴鹿山の鬼退治の伝説で知られる"],["鈴鹿御前","鈴鹿山の伝説に登場する女性。鬼とも天女ともいわれる"],["山賊たち","峠で旅人をおそったと伝わる"],["大名行列・旅人","江戸時代に峠を越えた人々"]],"deep":["886年（仁和2年）に新しい道が開かれたことは、平安時代の歴史書 «日本三代実録» に記されています。","峠の標高は約380mで、箱根峠にくらべると低いものの、急な坂と深い森が旅人を苦しめました。","鏡岩は三重県の天然記念物に指定されている大きな岩で、断層の動きでこすれて表面がなめらかになったものと考えられています。","鈴鹿御前の話は、室町時代の物語 «田村の草子» などに見られ、地域によって筋がかなり違います。","万人講常夜灯は、四国の金毘羅参りの人々の寄進によって建てられたといわれる大きな石の灯籠です（滋賀県側）。","鈴鹿峠は古代の «鈴鹿関» とも関わりの深い場所で、峠の東のふもとに関が置かれていました。","鈴鹿峠の三重県側の旧道は、近年ハイキングコースとして整備され、石畳や案内板が置かれています。"],"look":["旧東海道の石畳の山道","鏡岩","峠の頂上付近の景色","滋賀県側の万人講常夜灯"],"q":["鈴鹿山の鬼退治の伝説で知られる、平安時代の武将はだれ？","坂上田村麻呂です。東北へ遠征した実在の武将で、各地に英雄伝説が残ります。"],"koji":[],"myth":"鈴鹿御前と田村麻呂の鬼退治、鏡岩の山賊の話は伝説。","img":["坂上田村麻呂","鈴鹿御前","東海道"],"wp":"鈴鹿峠","rel":{"ev":[],"grave":[]},"ph":[["c:e/e4/Suzuka_Pass.jpg",2048,1536,"鈴鹿峠"],["c:8/8d/Sakanoue_Tamuramaro_sw.jpg",1513,1680,"坂上田村麻呂"],["c:a/a2/Kuniyoshi_Tsuchiyama.jpg",742,1089,"鈴鹿御前"]]},{"id":"24_suzuka_seki","n":"鈴鹿関跡（古代三関のひとつ）","yomi":"すずかのせきあと","cat":"遺跡","rank":"A","y":672,"era":["asuka","nara"],"sh":"","ad":"亀山市関町新所・古厩など","st":"JR関西本線 関駅から歩いて約10〜15分","la":34.852,"lo":136.393,"hook":"都で天皇が亡くなると、まず «関を閉じよ» と命じられた。国の運命を左右した、古代の三つの関所の一つ。","lead":"鈴鹿関（すずかのせき）は、飛鳥・奈良時代に置かれた関所です。美濃の不破関、越前の愛発関（あらちのせき）とともに «三関（さんげん）» と呼ばれ、都を守るとても大切な関でした。関宿の町の名前も、この関に由来します。近年の発掘調査で、関を囲んだ土の塀の跡が見つかっています。","story":["672年、天智天皇が亡くなったあと、弟の大海人皇子（おおあまのみこ）と、天智天皇の子・大友皇子が争う «壬申の乱» が起こりました。吉野を出た大海人皇子は伊勢に入り、まず «鈴鹿の道をふさげ» と命じたと «日本書紀» に記されています。","なぜ鈴鹿だったのでしょう。鈴鹿は、都のある近江・大和と、東国を結ぶ道の «のど元» だったからです。ここを押さえれば、東国の兵を味方につけ、敵の動きを止めることができます。大海人皇子は勝利し、天武天皇となりました。","その後、鈴鹿には正式に関所が置かれました。都で天皇が亡くなったり、反乱が起きたりすると、朝廷はすぐに使いを送って三つの関を閉じさせました。これを «固関（こげん）» といいます。«都で何かあれば、まず関を閉じよ»。関は、国の非常ボタンのような存在でした。","789年、三関はいったん廃止されますが、その後も «固関» の儀式は長く続けられたといわれます。関そのものの建物はやがて失われ、場所もはっきりしなくなっていきました。けれど «関» という地名は残り、江戸時代には東海道の関宿としてにぎわいました。","2000年代から行われた発掘調査で、関を囲んでいたとみられる築地塀（土をつき固めた塀）の跡が見つかり、鈴鹿関のようすが少しずつ分かってきました。関宿の町並みの奥に、1300年前の国の守りの跡が眠っているのです。"],"tl":[["672年","壬申の乱。大海人皇子が鈴鹿の道をふさがせる"],["7世紀後半〜8世紀","鈴鹿関が置かれ、三関の一つとなる"],["8世紀","天皇の死や反乱のたびに «固関» が行われる"],["789年","三関が廃止される"],["平安時代以降","«固関» の儀式が形として続く"],["2000年代","発掘調査で築地塀の跡が見つかる"]],"who":[["大海人皇子（天武天皇）","壬申の乱で鈴鹿の道をふさがせた"],["大友皇子","天智天皇の子。壬申の乱で大海人皇子と戦った"],["朝廷の使い（固関使）","非常時に関を閉じるため派遣された役人"]],"deep":["三関は、鈴鹿関（伊勢）・不破関（美濃）・愛発関（越前）の三つ。平安時代の初めには、愛発関に代わって近江の逢坂関が三関に数えられるようになりました。","«固関» は、天皇の死や譲位、反乱などの非常時に行われました。764年の藤原仲麻呂の乱などの際にも行われたことが記録されています。","789年の三関廃止は、桓武天皇の時代に行われたもので、使われなくなった関の施設を取り払う命令が出されたとされます。","発掘では、関の西側を区切るとみられる築地塀の跡が見つかり、関の規模を考える手がかりになっています。関の全体像はまだ研究が続いています。","«関» の町名は鈴鹿関にちなむもので、のちの東海道・関宿（国の重要伝統的建造物群保存地区）へと歴史がつながっています。"],"look":["築地塀が見つかった場所の説明板","関宿の町並み（重要伝統的建造物群保存地区）","関まちなみ資料館","西の追分（東海道と大和街道の分かれ道）"],"q":["非常時に朝廷が三つの関を閉じさせることを何という？","«固関（こげん）» です。都で天皇が亡くなったときなどに行われました。"],"koji":[],"myth":"関の正確な位置・範囲はなお研究中。","img":["壬申の乱","関宿","三関"],"wp":"鈴鹿関","rel":{"ev":["k_tokaido"],"grave":[]},"ph":[["c:8/85/Suzuka_no_Seki%2C_1st_excavation_area.jpg",5562,3702,"鈴鹿関"],["c:f/f3/Fuwanoseki2.JPG",4000,3000,"壬申の乱"],["c:e/eb/Tokaido53_Seki.jpg",2987,1938,"関宿"],["c:5/53/Three_barriers_in_Japan.png",902,1074,"三関"]]},{"id":"24_seki_jizoin","n":"関地蔵院","yomi":"せきじぞういん","cat":"寺社","rank":"B","y":741,"era":["nara","muromachi","edo"],"sh":"国の重要文化財","ad":"亀山市関町新所","st":"JR関西本線 関駅から歩いて約10分","la":34.8514,"lo":136.3924,"hook":"«関の地蔵に振袖着せて 奈良の大仏むこにとる»。民謡にもうたわれた、日本で最も古い地蔵菩薩の一つと伝わるお地蔵さま。","lead":"関地蔵院は、東海道の宿場・関宿の中ほどにあるお寺です。奈良時代に高僧・行基が開いたと伝わり、本尊の地蔵菩薩は日本で最も古いお地蔵さまの一つといわれます。一休さんにまつわる楽しい言い伝えも残り、本堂などは国の重要文化財です。","story":["奈良時代の741年、この地に疫病がはやり、人々は苦しんでいました。そこへやって来た僧・行基が、地蔵菩薩をまつって人々の無事を祈ったのが始まりと伝わります。関の人々にとって、お地蔵さまは町を守る大切な仏さまになりました。","室町時代、とんちで有名な一休さん（一休宗純）がここを訪れたという話が伝わっています。お地蔵さまの開眼（魂を入れる儀式）を頼まれた一休さんは、なんとお地蔵さまに小便をかけてしまったというのです。«なんということを!»。人々は怒りましたが、その後、不思議なことが起こった――。そんな楽しい言い伝えです。","江戸時代、関宿は東海道の宿場としてにぎわい、関地蔵院にも旅人がたくさんお参りしました。«関の地蔵に振袖着せて 奈良の大仏むこにとる»。大きな奈良の大仏さまをおむこさんにしようという、大らかな民謡がうたわれました。","今の本堂は江戸時代の初めに建てられたもので、愛染堂や鐘楼とともに国の重要文化財に指定されています。どっしりとした屋根の本堂は、宿場の町並みの中でひときわ目を引きます。","関宿は、江戸時代の町並みがよく残り、国の重要伝統的建造物群保存地区になっています。格子戸の町家が続く通りを歩き、関地蔵院で手を合わせると、昔の旅人と同じ気持ちになれるかもしれません。"],"tl":[["741年","行基が地蔵菩薩をまつったと伝わる"],["室町時代","一休宗純が訪れたという伝説が生まれる"],["1601年","関が東海道の宿場に定められる"],["江戸時代前期","現在の本堂が建てられる"],["1984年","関宿が重要伝統的建造物群保存地区に選ばれる"],["平成時代","本堂・愛染堂・鐘楼が国の重要文化財に指定される"]],"who":[["行基","奈良時代の僧。関地蔵院を開いたと伝わる"],["一休宗純","室町時代の禅僧。開眼の伝説が残る"],["関宿の人々","お地蔵さまを町の守り本尊として大切にしてきた"]],"deep":["本尊の地蔵菩薩が «日本最古» といわれるのは寺の伝えによるもので、仏像の制作年代については研究者の見方が分かれます。","一休さんの開眼の話には、小便をかけたあとで «これで開眼した» と言ったなど、いくつもの形があり、伝説として楽しむものです。","本堂・愛染堂・鐘楼はいずれも江戸時代以前にさかのぼる古い建物で、関宿の町並みの中でもとくに歴史のある建築群です。","関宿は «東の追分»（伊勢別街道）と «西の追分»（大和街道）にはさまれ、三つの道が集まる交通の要でした。","関宿の町並みは約1.8kmにわたり、江戸から明治にかけての町家が200軒以上残るといわれます。","関地蔵院では、毎年夏に地蔵盆の行事が行われ、宿場の人々とお地蔵さまのつながりが今も続いています。"],"look":["本堂（国の重要文化財）","愛染堂と鐘楼","境内のお地蔵さま","関宿の町並み"],"q":["関地蔵院の開眼の伝説に登場する、とんちで有名なお坊さんはだれ？","一休さん（一休宗純）です。お地蔵さまに小便をかけたという楽しい言い伝えが残ります。"],"koji":[{"w":"関の地蔵に振袖着せて 奈良の大仏むこにとる","m":"関のお地蔵さまに振袖を着せて、奈良の大仏さまをおむこさんにしよう、という民謡の一節。関の人々の大らかさとお地蔵さまへの親しみが表れている"}],"myth":"行基の開創、日本最古の地蔵、一休の開眼は伝承。","img":["関宿","行基","一休宗純"],"wp":"関地蔵院","rel":{"ev":["k_tokaido"],"grave":[]},"ph":[["c:f/f5/Jizo-in_Seki_main_hall_ac_%282%29.jpg",5973,3971,"関地蔵院"],["c:e/eb/Tokaido53_Seki.jpg",2987,1938,"関宿"],["c:8/8d/Gyouki_1.jpg",400,300,"行基"],["c:4/40/Portrait_of_Ikky%C5%AB_by_Bokusai.jpg",224,268,"一休宗純"]]},{"id":"24_nobono","n":"能褒野王塚古墳（ヤマトタケルの墓とされる）","yomi":"のぼのおうつかこふん","cat":"墓所","rank":"A","y":390,"era":["kofun"],"sh":"","ad":"亀山市田村町","st":"JR関西本線 井田川駅から歩いて約30分（車が便利）","la":34.894,"lo":136.492,"hook":"«大和は国のまほろば»。ふるさとをしのびながら倒れた英雄ヤマトタケルは、ここで白い鳥になって飛び立ったと伝わる。","lead":"能褒野王塚古墳（のぼのおうつかこふん）は、亀山市にある大きな前方後円墳です。古事記や日本書紀に登場する英雄・ヤマトタケル（日本武尊）の墓 «能褒野墓（のぼののはか）» として、宮内庁が管理しています。北伊勢で最大級の古墳で、周りは林に囲まれた静かな場所です。","story":["ヤマトタケルは、景行天皇の皇子とされる伝説の英雄です。西の熊襲（くまそ）、東の蝦夷（えみし）と、父の命令で各地を戦い歩いたと、古事記や日本書紀に描かれています。","東国からの帰り道、ヤマトタケルは伊吹山の神を退治しに向かいますが、神の怒りにふれて重い病にかかってしまいます。体が弱り、足も思うように動かないまま、ふるさとの大和をめざして歩き続けました。","«大和は国のまほろば たたなづく青垣 山ごもれる 大和しうるわし»。古事記では、ヤマトタケルがふるさとをしのんで歌ったと伝えます。しかし大和へ帰ることはかなわず、能褒野の地で亡くなったとされます。","物語はここで終わりません。ヤマトタケルのたましいは白い鳥となって飛び立ち、大和の方へ飛んでいったと伝えられます。人々は白い鳥が降りた場所にも墓を作ったといわれ、奈良県や大阪府にも «白鳥陵» があります。","明治時代、宮内庁の前身の役所は、この王塚古墳をヤマトタケルの能褒野墓と定めました。墳丘の中には入れませんが、となりの能褒野神社から拝むことができます。静かな森の中で、ふるさとを思いながら倒れた英雄の物語に思いをはせてみてください。"],"tl":[["4世紀後半ごろ","王塚古墳が造られたと考えられる"],["8世紀初め","古事記・日本書紀にヤマトタケルの能褒野での死が記される"],["江戸時代","ヤマトタケルの墓の場所をめぐり、いくつかの説が出る"],["1879年","明治政府が王塚古墳を «能褒野墓» と定める"],["明治時代","となりに能褒野神社がまつられる"],["現在","宮内庁が管理。墳丘には立ち入れない"]],"who":[["ヤマトタケル（日本武尊）","伝説の英雄。能褒野で亡くなったとされる"],["景行天皇","ヤマトタケルの父とされる天皇"],["宮内庁","能褒野墓として古墳を管理している"]],"deep":["王塚古墳は全長約90mの前方後円墳で、北伊勢地方では最大級の古墳とされます。","この古墳が本当にヤマトタケルの墓かどうかは分かりません。ヤマトタケル自体が、何人かの人物の話が一つにまとめられた伝説の英雄と考えられています。","明治以前には、鈴鹿市の «白鳥塚古墳»（加佐登神社の近く）などもヤマトタケルの墓の候補とされていました。","白鳥陵とされる場所は、奈良県御所市の琴弾原と大阪府羽曳野市の古市にもあり、三か所をあわせて «白鳥三陵» と呼ぶことがあります。","周りには小さな古墳（陪塚）が点在し、古墳群として広がっています。","能褒野神社は明治時代にヤマトタケルをまつって創建された神社で、古墳の拝所と並んで、地元の人々がヤマトタケルをしのぶ場所になっています。"],"look":["宮内庁の «能褒野墓» の拝所","森に包まれた墳丘の姿（外から）","能褒野神社","周りの小さな古墳"],"q":["古事記で、ヤマトタケルがふるさとをしのんで歌ったとされる歌の最初の言葉は？","«大和は国のまほろば» です。«まほろば» はすばらしい場所という意味です。"],"koji":[{"w":"大和は国のまほろば","m":"大和（奈良）は国の中でいちばんすばらしい所だ、という意味。ヤマトタケルがふるさとを思ってうたったと古事記に記される"}],"myth":"ヤマトタケルの墓であるかは不明。白鳥伝説は神話・伝承。","img":["日本武尊","白鳥陵","能褒野神社"],"wp":"能褒野王塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:4/4b/Nobono_Otsuka_Kofun_zenkei.JPG",6016,4000,"能褒野王塚古墳"],["c:3/3e/Yamato_Takeru%28bronze_statue%2COsaka%2901.jpg",768,1024,"日本武尊"],["c:4/42/Nobono-jinja_torii.JPG",6016,4000,"能褒野神社"]]},{"id":"24_ise_kokufu","n":"伊勢国府跡（長者屋敷遺跡）","yomi":"いせこくふあと（ちょうじゃやしきいせき）","cat":"遺跡","rank":"B","y":750,"era":["nara","heian"],"sh":"国指定史跡","ad":"鈴鹿市広瀬町","st":"近鉄鈴鹿線 平田町駅から車で約15分（車が便利）","la":34.888,"lo":136.47,"hook":"村の人たちは «長者の屋敷があった» と語り継いできた。掘ってみると、そこは奈良時代の伊勢国の «県庁» だった。","lead":"伊勢国府跡は、奈良時代に伊勢国を治める役所 «国府» が置かれた場所の跡です。地元では昔から «長者屋敷» と呼ばれていました。発掘調査で、国府の中心となる政庁の建物跡が見つかり、国の史跡に指定されています。","story":["奈良時代、日本は «国» に分けられ、それぞれに都から役人（国司）が送られて国を治めました。国司が仕事をした役所が «国府» です。今でいえば県庁のようなところでした。","鈴鹿市の広瀬町には、昔から «長者屋敷» と呼ばれる場所がありました。畑からは古い瓦がたくさん出てきます。«昔、ここにお金持ちの長者の屋敷があったそうな»。村の人たちはそう語り継いできたのです。","ところが調べてみると、そこにあったのは長者の屋敷ではなく、伊勢国の国府の中心、政庁の跡でした。瓦ぶきの立派な建物が整然と並んでいたことが分かり、人々を驚かせました。瓦をたくさん使った建物は、当時とても格式の高いものでした。","さらに周りからは、道で四角く区切られた町のような跡も見つかりました。«国府のまわりに、計画的な町が作られていたのではないか»。伊勢国府は、思っていたよりずっと大きな規模だった可能性があります。","伊勢国府は、奈良時代の間は広瀬町にあったと考えられていますが、平安時代以降の国府がどこにあったのかは、まだはっきりしていません。畑と林の広がる静かな場所で、1200年以上前の役人たちの仕事ぶりを想像してみてください。"],"tl":[["8世紀前半〜中ごろ","伊勢国府の政庁が築かれたと考えられる"],["奈良時代","国司が伊勢国を治める"],["平安時代","国府の場所が移ったとも考えられる"],["江戸〜昭和時代","«長者屋敷» と呼ばれ、瓦が見つかる場所として知られる"],["昭和の終わり〜平成時代","発掘調査で政庁の跡が確認される"],["平成時代","国の史跡に指定される"]],"who":[["国司","都から送られ、伊勢国を治めた役人"],["地元の人々","«長者屋敷» の言い伝えを残してきた"]],"deep":["政庁は、中心の建物（正殿）の前に広場があり、左右に建物（脇殿）が並ぶ «コの字» 形の配置だったと考えられています。これは各地の国府に共通するつくりです。","政庁の周りでは、道路で碁盤の目のように区切られた «方格地割» の跡が確認され、国府の町の広がりを考える手がかりになっています。","近くには鈴鹿市の «国府町» という地名があり、平安時代以降の国府がこちらにあった可能性も議論されています。","伊勢国分寺跡（鈴鹿市国分町）も同じ鈴鹿市内にあり、古代の伊勢国の中心が鈴鹿のあたりにあったことが分かります。","伊勢国府の瓦は、伊勢国分寺と同じ系統のものが使われたとも考えられ、両者の関係が研究されています。","政庁の跡は小高い台地の上にあり、周りを見わたせる場所が選ばれたと考えられます。古代の役所がどんな場所に置かれたかを考えるよい例です。","出土した瓦には、奈良の都の瓦と似た文様をもつものがあり、都と地方の役所の結びつきを示す手がかりになっています。"],"look":["政庁跡の説明板","広がる畑と林（遺跡の範囲）","鈴鹿市考古博物館（出土品の展示）","伊勢国分寺跡（あわせて）"],"q":["昔、国司が仕事をした国の役所を何という？","«国府» です。今の県庁のような役所でした。"],"koji":[],"myth":"平安時代以降の国府の位置、方格地割の性格は研究途上。","img":["国府","国司"],"wp":"伊勢国府跡","rel":{"ev":[],"grave":[]},"ph":[["c:4/49/Musashikokufuato.jpg",1600,1200,"国府"]]},{"id":"24_ise_kokubunji","n":"伊勢国分寺跡","yomi":"いせこくぶんじあと","cat":"遺跡","rank":"B","y":741,"era":["nara"],"sh":"国指定史跡","ad":"鈴鹿市国分町","st":"JR関西本線 河曲駅から歩いて約25分","la":34.868,"lo":136.552,"hook":"疫病と災いに苦しむ国を、仏の力で守りたい――。聖武天皇の願いが、全国に同じ名前の寺を生んだ。","lead":"伊勢国分寺跡は、奈良時代に聖武天皇の命令で建てられた伊勢国の国分寺の跡です。建物は残っていませんが、発掘調査で金堂や講堂の跡、寺を囲んだ塀の跡が見つかりました。国の史跡で、となりには出土品を展示する鈴鹿市考古博物館があります。","story":["奈良時代の日本は、疫病や飢き、反乱などが相次ぎ、人々は不安の中にありました。聖武天皇は «仏の力で国を守ろう» と考え、741年、全国の国ごとに寺を建てるよう命じました。これが国分寺と国分尼寺です。","伊勢国でも、鈴鹿の台地の上に国分寺が建てられました。広い敷地を土の塀で囲み、中には金堂や講堂などの大きな建物が並んでいたと考えられています。«国の平和を祈る寺»。国の役所と並ぶ、国の大切な施設でした。","時がたち、国を支える力が弱まると、国分寺もしだいにおとろえていきました。建物は失われ、跡地は畑になりました。それでも «国分» という地名が残り、ここに国分寺があったことを伝えてきました。","大正時代、この地は国の史跡に指定されました。その後の発掘調査で、金堂や講堂の跡、寺を四角く囲んだ築地塀の跡が見つかり、寺の広さやつくりが分かってきました。瓦もたくさん出土し、どんな屋根だったのかも少しずつ分かってきています。","いま史跡は広々とした公園として整備され、となりの鈴鹿市考古博物館では、出土した瓦などを見ることができます。広い空の下に立つと、1300年前、ここに大きな屋根の寺が並んでいた姿が目に浮かびます。"],"tl":[["741年","聖武天皇が国分寺建立の詔を出す"],["8世紀中ごろ","伊勢国分寺が建てられたと考えられる"],["平安時代以降","寺がしだいにおとろえる"],["1922年","国の史跡に指定される"],["昭和時代の終わりごろから","本格的な発掘調査が行われる"],["平成時代","となりに鈴鹿市考古博物館が開館する"]],"who":[["聖武天皇","国分寺建立の詔を出した天皇"],["光明皇后","聖武天皇の皇后。国分寺の建立を勧めたともいわれる"],["国司","国分寺の建立と運営に関わった伊勢国の役人"]],"deep":["国分寺の正式な名前は «金光明四天王護国之寺»、国分尼寺は «法華滅罪之寺» といいます。","伊勢国分寺では、寺の敷地を囲む築地塀が見つかり、敷地は一辺180mほどの四角形だったと考えられています。","聖武天皇の詔では、国分寺に七重の塔を建てることが求められました。伊勢国分寺の塔がどこにあったかは、今も研究が続いています。","近くには伊勢国分尼寺があったと考えられていますが、その場所はまだはっきりしていません。","伊勢国府跡（鈴鹿市広瀬町）とあわせて訪ねると、古代の伊勢国の中心が鈴鹿にあったことを実感できます。","国分寺の建立には、地方の豪族の協力が欠かせませんでした。伊勢でも、鈴鹿のあたりの有力な一族が寺の建設を支えたと考えられています。","鈴鹿市考古博物館では、国分寺の瓦のほか、鈴鹿市内の古墳や遺跡から出土した品々も展示され、古代の伊勢のようすをまとめて学べます。"],"look":["整備された史跡公園（金堂・講堂の跡）","築地塀の跡","鈴鹿市考古博物館の出土品","台地の上からの眺め"],"q":["国ごとに国分寺を建てるよう命じた天皇はだれ？","聖武天皇です。741年に命令（詔）を出しました。"],"koji":[],"myth":"伽藍配置や塔の有無は研究途上。","img":["国分寺","聖武天皇"],"wp":"伊勢国分寺","rel":{"ev":[],"grave":[]},"ph":[["c:c/c9/Ise_Kokubunji_sekihi.JPG",6004,3982,"伊勢国分寺"],["c:a/a0/Bitchu_Kokubunji%2C_zenkei.jpg",6010,3990,"国分寺"],["c:3/3f/Emperor_Shomu.jpg",1876,3132,"聖武天皇"]]},{"id":"24_kurube_kanga","n":"久留倍官衙遺跡（朝明郡家）","yomi":"くるべかんがいせき","cat":"遺跡","rank":"A","y":730,"era":["asuka","nara"],"sh":"国指定史跡","ad":"四日市市大矢知町","st":"近鉄名古屋線の駅から歩くと30分前後。車かタクシーが便利","la":35.0135,"lo":136.6185,"hook":"バイパス工事のブルドーザーの前に現れたのは、1300年前の «郡の役所»。しかもそこは、壬申の乱の大海人皇子ゆかりの地かもしれない。","lead":"奈良時代、伊勢国の «朝明郡（あさけぐん）» を治めた役所（郡家・ぐうけ）のあとです。役人が仕事をした «政庁»、税の稲をしまった «正倉（しょうそう）» のあとが見つかり、いまは史跡公園として整備されています。","story":["むかしの日本は «国» の下に «郡» があり、郡ごとに役所が置かれていました。ここは伊勢国朝明郡の役所。村から運ばれてきた稲や布を受け取り、記録をつけ、都からの命令を人びとに伝える、いわば «古代の市役所» です。丘の上からは伊勢湾がよく見え、役人たちは海と平野を見下ろしながら働いていたのでしょう。","遺跡が見つかったのは、国道1号の北勢バイパスをつくる工事の前に行われた発掘調査でした。«道路の下になってしまうのか?» ――調べるほどに、門や大きな建物の柱のあとが整然と並んでいることがわかり、ただの村ではないと判明します。保存を求める声が高まり、道路の計画を工夫して遺跡の中心部が守られました。","見つかった建物のなかで目をひくのが、政庁の東側にあった «八脚門（やつあしもん）»。柱を8本立てた格式の高い門で、ふつうの郡の役所ではあまり見られないつくりです。«なぜここだけ立派な門が東を向いているのか?» 研究者はこの問いに、ある歴史の大事件を重ねました。","『日本書紀』には、672年の壬申の乱のとき、大海人皇子（のちの天武天皇）が朝明郡の «迹太川（とほかわ）» のほとりで、伊勢の天照大神を遥かに拝んだと書かれています。東へ向いた門は、伊勢や天武天皇の記憶と関係があるのでは――という説です。ただし、決め手になる証拠はまだなく、ほかの考え方もあります。","いま遺跡は公園になり、建物の位置が地面に示され、ガイダンス施設で出土品や復元模型を見ることができます。丘に立って風に吹かれると、稲の束をかついで坂を上ってくる人びとの姿が目に浮かぶようです。"],"tl":[["672年","壬申の乱。『日本書紀』に大海人皇子が朝明郡の迹太川で天照大神を望拝したとある"],["7世紀後半〜8世紀","朝明郡の役所が整えられる"],["8世紀","政庁・八脚門・正倉などが営まれる"],["2000年代初め","北勢バイパス建設にともなう発掘で遺構が見つかる"],["2006年","国の史跡に指定"],["2020年ごろ","史跡公園として整備・公開"]],"who":[["大海人皇子（天武天皇）","壬申の乱で朝明郡を通り、天照大神を拝んだと『日本書紀』にある"],["郡司","郡を治めた地元の有力者。この役所の主"],["郡の役人たち","税の稲や布を受け取り、帳簿をつけた"]],"deep":["«官衙（かんが）» は古代の役所の総称。国の役所は «国府»、郡の役所は «郡家（郡衙）» と呼びます。久留倍は郡家の政庁と正倉の両方がそろって見つかった貴重な例です。","八脚門は、門の中心の柱4本の前後に控えの柱を立てた格式ある門。郡家クラスで確認されるのは珍しく、ここの特別さを示す手がかりとされます。","遺構はいくつかの時期に分かれ、はじめは政庁、のちに正倉が中心になるなど、役所の使われ方が時代とともに変わったと考えられています。","迹太川がどの川にあたるのかは確定していません。朝明川とする説などがあり、久留倍と壬申の乱を結びつける考えは «可能性» の段階です。","道路建設と遺跡保存が両立した例としても知られ、道路のルートや構造を工夫して中心部を残しました。"],"look":["政庁の建物の位置を示した表示","八脚門のあと（東向きの門）","正倉が並んでいた区域","丘の上から見る伊勢湾と四日市の平野","ガイダンス施設の復元模型と出土品"],"q":["郡の役所で、税として集めた稲をしまった倉を何という？","«正倉（しょうそう）»。郡家には正倉がいくつも並び、その数が地域の豊かさを示しました。"],"myth":"八脚門と壬申の乱・大海人皇子の望拝を結びつける説は仮説。迹太川の場所も諸説。","img":["郡衙","壬申の乱","天武天皇"],"wp":"久留倍官衙遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:c/c9/Kurube_Kanga_Site%2C_gaikan-1.jpg",5566,3710,"久留倍官衙遺跡"],["c:f/f3/Fuwanoseki2.JPG",4000,3000,"壬申の乱"],["c:b/b9/%E5%A4%A9%E6%AD%A6%E5%A4%A9%E7%9A%87%E5%BE%A1%E5%BD%B1%E3%80%81%E9%87%91%E5%89%9B%E5%B1%B1%E5%AF%BA%E6%89%80%E8%94%B5.jpg",425,591,"天武天皇"]]},{"id":"24_tsubaki_taisha","n":"椿大神社（伊勢国一宮・猿田彦の総本宮）","yomi":"つばきおおかみやしろ","cat":"寺社","rank":"A","y":-20,"era":["kofun","heian","showa"],"sh":"","ad":"鈴鹿市山本町","st":"近鉄四日市駅から三重交通バスで約1時間（椿大神社行き終点）。車が便利","la":34.9335,"lo":136.4695,"hook":"みちびきの神 «猿田彦大神» をまつる神社の総本宮。鈴鹿の山ふところで、道に迷う人の背中をそっと押してくれる。","lead":"鈴鹿山脈のふもとにある古い神社で、伊勢国の一宮（いちばん格の高い神社）の一つとされます。天孫降臨のとき神々を道案内したと伝わる猿田彦大神をまつり、«みちびきの神» として全国から参拝者が訪れます。","story":["神話によれば、天照大神の孫・ニニギノミコトが地上に降りてくるとき、天と地の分かれ道に、背が高く鼻の長い、目が光る神が立っていました。«あなたは誰か?» と問われて、その神は答えます。«わたしは猿田彦。天の御子が降りると聞いて、道案内にまいりました» ――これが «みちびきの神» 猿田彦大神です。","椿大神社の始まりは、はるか昔、垂仁天皇の時代に倭姫命（やまとひめのみこと）のお告げによって社が建てられたと伝わります。倭姫命は天照大神をまつる場所を探して各地を旅した皇女で、伊勢神宮のはじまりにかかわる人物です。神社の背後の入道ヶ岳・椿ヶ岳は、古くから神の山として拝まれてきました。","境内には、猿田彦大神の妻とされる天之鈿女命（あめのうずめのみこと）をまつる «椿岸神社» もあります。天の岩戸の前で踊って神々を笑わせた芸能の女神で、芸事の上達を願う人がお参りします。«なぜ夫婦神が並んでいるのか?» 神話では、道案内のあと猿田彦を送っていったのがアメノウズメでした。","昭和の経営者・松下幸之助もこの神社を深く敬い、境内には彼をまつる «松下幸之助社» や、寄進された茶室があります。«道をひらく» という言葉を大事にした人が «みちびきの神» にひかれたのは、なんだかうなずける話です。","杉の大木に囲まれた参道を歩き、鈴鹿の山から吹き下ろす風を感じると、ここが «神の山のふもと» だということを肌で感じます。"],"tl":[["垂仁天皇の代","倭姫命のお告げで創祀されたと伝わる"],["平安時代","『延喜式』神名帳に «椿神社» として記される"],["中世","伊勢国一宮の一つとされる"],["戦国時代","戦乱で社殿が焼けたと伝わる"],["昭和時代","松下幸之助が崇敬し、茶室などを寄進"]],"who":[["猿田彦大神","主祭神。天孫降臨で道案内をした «みちびきの神»"],["天之鈿女命","椿岸神社の祭神。芸能の女神で、猿田彦の妻とされる"],["倭姫命","お告げによりこの地に社を建てたと伝わる皇女"],["松下幸之助","パナソニック創業者。深く崇敬し、境内に松下幸之助社がある"]],"deep":["«延喜式内社» の «椿神社» にあたるとされ、平安時代には朝廷に知られた神社でした。","伊勢国一宮は、椿大神社と鈴鹿市一ノ宮町の都波岐奈加等神社の二社が名乗っています。どちらも猿田彦大神をまつる点が面白いところです。","猿田彦をまつる神社は全国に2000社以上あるといわれ、椿大神社は «猿田彦大本宮» を称しています。伊勢市の猿田彦神社も有名で、猿田彦ゆかりの地は伊勢に多いのです。","神社の名 «椿» は地名とも、神の «つばき（唾）» の伝承とも言われ、由来ははっきりしません。","境内の «かなえ滝» や «御船磐座（みふねいわくら）» は、ニニギノミコトが乗った船が着いたと伝わる岩で、古い磐座信仰のなごりと考えられます。"],"look":["杉並木の参道と本殿","椿岸神社（芸能の神）","御船磐座","松下幸之助社と茶室","かなえ滝"],"q":["天の岩戸の前で踊り、神々を笑わせた女神は？","天之鈿女命（アメノウズメノミコト）。境内の椿岸神社にまつられています。"],"koji":[{"w":"道ひらき","m":"猿田彦大神が道案内をしたことから、物事のはじまりや新しい門出に力を貸す神とされる"}],"myth":"創祀の年代・倭姫命のお告げ、御船磐座の由来はいずれも伝承。","img":["猿田彦神","天宇受売命","一宮","入道ヶ岳"],"wp":"椿大神社","rel":{"ev":[],"grave":[]},"ph":[["c:7/74/Tsubaki-shrine.jpg",480,640,"椿大神社"],["c:b/bf/Sarutahiko-Jinja_001.jpg",4288,2848,"猿田彦神"],["c:6/6a/Uzume.jpg",1536,2048,"天宇受売命"],["c:6/6d/Zenkoku-ichinomiya.jpg",600,800,"一宮"],["c:5/59/Nyuudougatake_from_kamagatake_2010_6_2.jpg",1280,853,"入道ヶ岳"]]},{"id":"24_tsubaki_jinja","n":"都波岐奈加等神社（伊勢国一宮）","yomi":"つばきなかとじんじゃ","cat":"寺社","rank":"B","y":470,"era":["kofun","heian"],"sh":"","ad":"鈴鹿市一ノ宮町","st":"JR関西本線 河曲駅から歩いて約15分","la":34.8715,"lo":136.5575,"hook":"一つの境内に二つの神社。«つばき» と «なかと»、ふしぎな名前をもつもう一つの伊勢国一宮。","lead":"«都波岐（つばき）神社» と «奈加等（なかと）神社» という、平安時代の記録にのる二つの古い神社が、同じ境内に並んでまつられています。伊勢国の一宮の一つとされ、町の名前 «一ノ宮» もこの神社から来ています。","story":["鈴鹿市の住宅地の中に、こんもりとした森があります。鳥居をくぐると、社殿は一つなのに、名前は二つ。«都波岐神社» と «奈加等神社» です。どちらも平安時代の『延喜式』という本に名前がのっている古い神社で、それが一つの場所で守られてきました。","都波岐神社がまつるのは、猿田彦大神。天孫降臨の道案内をした神さまです。奈加等神社のほうは、天椹野命（あめのくぬのみこと）と中筒之男命（なかつつのおのみこと）をまつると伝わります。«なかと» という名は «中筒» と関係があるのでは、ともいわれます。","社伝では、雄略天皇の時代に社が建てられたと伝わります。のちに戦国時代の戦火で社殿を失いますが、江戸時代に入って再建され、地域の人びとの手で守られてきました。«一ノ宮» の名が町名として残っているのは、この神社がいかに大切にされてきたかのしるしです。","伊勢国の一宮は、この神社と鈴鹿市山本町の椿大神社の二つが名乗っていて、どちらが本来の一宮なのか、昔から議論があります。«なぜ同じ国に一宮が二つ?» それだけ、どちらも古くから重んじられてきたということでしょう。","大きな観光地ではありませんが、秋祭りには獅子舞が奉納されるなど、今も地域の暮らしと結びついた «町の一宮» です。静かな境内で、二つの名前の由来に思いをめぐらせてみてください。"],"tl":[["雄略天皇の代","創建と伝わる"],["927年","『延喜式』完成。神名帳に都波岐神社・奈加等神社がのる"],["中世","伊勢国一宮の一つとされる"],["戦国時代","兵火で社殿を失ったと伝わる"],["江戸時代","社殿が再建される"]],"who":[["猿田彦大神","都波岐神社の祭神。みちびきの神"],["天椹野命","奈加等神社の祭神と伝わる"],["中筒之男命","奈加等神社の祭神と伝わる。住吉の神の一柱"]],"deep":["『延喜式』神名帳では河曲郡（かわわぐん）に «都波岐神社» «奈加等神社» が並んでのっています。二社が同じ境内にあるのは、それだけ関係の深い神社だったからでしょう。","伊勢国一宮をめぐっては、中世の一宮の一覧で名が挙がる神社をどちらと見るかで説が分かれ、椿大神社と並んで一宮を名乗っています。","河曲郡は現在の鈴鹿市東部あたり。近くには伊勢国府跡（国の史跡・鈴鹿市広瀬町ほか）もあり、この一帯が古代伊勢の政治の中心に近かったことがわかります。","獅子舞（獅子神楽）は地域に伝わる行事で、神社の祭礼とともに受け継がれています。","奈加等の祭神については、別の神をあげる説もあり、はっきりしない点があります。","椿大神社が鈴鹿山脈のふもとの «山の宮» なのに対し、こちらは伊勢湾に近い平野の «里の宮»。同じ猿田彦をまつる二つの一宮を、山と里で比べて歩くのも歴オタらしい楽しみ方です。"],"look":["二社の名を記した社号標","本殿と森の雰囲気","町名 «一ノ宮» のまち並み","近くの伊勢国府跡とあわせて古代の河曲郡を歩く"],"q":["都波岐奈加等神社の «都波岐» がまつる神は？","猿田彦大神。椿大神社と同じ «みちびきの神» です。"],"myth":"創建年代（雄略天皇の代）、奈加等神社の祭神は社伝・諸説。どちらが本来の一宮かも諸説。","img":["猿田彦神","一宮","伊勢国府跡","延喜式神名帳"],"wp":"都波岐奈加等神社","rel":{"ev":[],"grave":[]},"ph":[["c:b/b9/Tsubaki-jinja_Shaden1.jpg",3760,3008,"都波岐奈加等神社"],["c:b/bf/Sarutahiko-Jinja_001.jpg",4288,2848,"猿田彦神"],["c:6/6d/Zenkoku-ichinomiya.jpg",600,800,"一宮"],["c:c/c8/Engishiki_Jingi_cropped_Engishiki_Vol_2_Flame_37.jpg",2523,3524,"延喜式神名帳"]]},{"id":"24_kodayu","n":"大黒屋光太夫記念館（ロシアから帰った船頭）","yomi":"だいこくやこうだゆうきねんかん","cat":"学び","rank":"A","y":1792,"era":["edo"],"sh":"","ad":"鈴鹿市若松中","st":"近鉄名古屋線 伊勢若松駅から歩いて約15〜20分","la":34.8605,"lo":136.6075,"hook":"嵐で流され、アリューシャンからシベリアを越えて、女帝エカチェリーナ2世に会った船頭がいた。故郷に帰るまで、約10年。","lead":"江戸時代、白子の港から江戸へ向かった船が嵐にあい、ロシアへ流されました。船頭の大黒屋光太夫は仲間を失いながらもロシアの女帝に帰国を願い、約10年ぶりに日本へ戻ります。記念館はその出身地・若松にあり、光太夫の足どりや資料を紹介しています。","story":["1782年の暮れ、白子の港から «神昌丸» という船が江戸へ向けて出発しました。積み荷は紀州藩のお米や木綿。船頭は32歳の大黒屋光太夫、乗組員は光太夫を入れて17人です。ところが駿河沖で嵐にあい、舵も帆柱も失った船は、7か月以上も海をただよいました。","たどり着いたのは、アリューシャン列島のアムチトカ島。言葉も通じない北の島で、仲間はつぎつぎに亡くなっていきます。光太夫たちは流木で船をつくってカムチャツカへ渡り、さらにシベリアを越えてイルクーツクへ。«どうしたら日本へ帰れるのか?» 光太夫は役所に何度も願い出ましたが、答えはいつも «ロシアに残れ» でした。","助けてくれたのは学者のキリル・ラクスマンです。彼は光太夫をつれて首都サンクトペテルブルクへ向かい、1791年、ついに女帝エカチェリーナ2世への拝謁がかないました。«帰りたい» という願いを聞いた女帝は «かわいそうに» と言ったと伝わり、帰国が許されます。","1792年、キリルの息子アダム・ラクスマンの船で根室に到着。しかし根室で仲間の小市が亡くなり、生きて江戸にたどり着いたのは光太夫と磯吉の二人だけでした。二人は将軍・徳川家斉の前でロシアのことを語り、蘭学者・桂川甫周がその話をまとめて『北槎聞略（ほくさぶんりゃく）』という本にしました。","光太夫は江戸で暮らし、一度は故郷へ帰ったこともあったといわれます。記念館では、光太夫が持ち帰った品の資料や手紙を通して、世界を見た江戸の船乗りの姿に出会えます。"],"tl":[["1751年","伊勢国の南若松村に生まれる（1750年説もある）"],["1782年12月","神昌丸で白子港を出航、駿河沖で遭難"],["1783年","アリューシャン列島のアムチトカ島に漂着"],["1791年","サンクトペテルブルクでエカチェリーナ2世に拝謁"],["1792年","アダム・ラクスマンの船で根室に着く"],["1793年","江戸で将軍家斉の前で聞き取りを受ける"],["1794年","桂川甫周『北槎聞略』成る"],["1828年","江戸で没する"],["2005年","大黒屋光太夫記念館が開館"]],"who":[["大黒屋光太夫","神昌丸の船頭。約10年かけて帰国"],["磯吉","光太夫とともに帰国した乗組員"],["キリル・ラクスマン","博物学者。光太夫の帰国を助けた"],["エカチェリーナ2世","ロシアの女帝。光太夫の帰国を許した"],["桂川甫周","蘭学者。光太夫の話をまとめ『北槎聞略』を著す"],["アダム・ラクスマン","キリルの息子。光太夫を送り届け、通商を求めた使節"]],"deep":["乗組員17人のうち、1人は漂流中に亡くなり、多くはアムチトカ島やシベリアで病死。ロシアに残って正教の洗礼を受けた者も2人いました。","アダム・ラクスマンの来航は、ロシアが日本に正式に通商を求めた最初の使節です。幕府は松前で交渉し、長崎への入港許可証（信牌）を渡しました。","『北槎聞略』は、ロシアの政治・風俗・言葉を詳しく記した当時一級の海外情報で、長く一般には公開されませんでした。","光太夫は帰国後、江戸で «幽閉» されたという話が長く語られましたが、実際には番町の薬草園で暮らし、妻をもち、蘭学者らと交流していたことがわかっています。","井上靖の小説『おろしや国酔夢譚』（1968年）と、その映画化（1992年）で広く知られるようになりました。小説には創作も含まれます。"],"look":["光太夫の漂流ルートを示した地図展示","『北槎聞略』など関連資料","近くの光太夫の供養碑","白子港（出航の地）もあわせて訪ねる"],"q":["光太夫の話をまとめた本の名前は？","『北槎聞略（ほくさぶんりゃく）』。蘭学者・桂川甫周がまとめたロシア事情の本です。"],"myth":"女帝の «かわいそうに» の言葉は伝承。生年は1750年説もある。帰国後の「幽閉」説は現在では否定的。","img":["北槎聞略","エカチェリーナ2世","アダム・ラクスマン","おろしや国酔夢譚"],"wp":"大黒屋光太夫","rel":{"ev":[],"grave":[]},"ph":[["c:a/a5/Captain_Daikokuya_Kodayu_and_crewmate_Isokichi_1792.png",2855,3668,"大黒屋光太夫"],["c:7/72/Catherine_II_after_Roslin%2C_Rokotov_%281780s%2C_Kunsthistorisches_Museum%29.jpg",1132,1350,"エカチェリーナ2世"],["c:a/a8/Adam_Kirillovich_Laksman.jpg",2829,3526,"アダム・ラクスマン"]]},{"id":"24_ise_katagami","n":"伊勢型紙（白子・寺家）","yomi":"いせかたがみ","cat":"産業","rank":"A","y":1700,"era":["edo","showa"],"sh":"国の伝統的工芸品","ad":"鈴鹿市白子本町・寺家","st":"近鉄名古屋線 白子駅から歩いて約10分（伊勢型紙資料館）","la":34.8345,"lo":136.5885,"hook":"着物の細かな模様は、和紙に彫られた «型» から生まれる。その型紙の99%以上は、鈴鹿の小さな町でつくられてきた。","lead":"伊勢型紙は、着物や手ぬぐいに模様を染めるための «型紙» です。柿渋で貼り合わせた和紙に、小刀で気の遠くなるほど細かい模様を彫ります。白子・寺家は江戸時代から型紙づくりの中心地で、技は国の重要無形文化財にも指定されています。","story":["遠くから見ると無地に見える着物。近づくと、米粒よりも小さな点や、細い縞がびっしり並んでいます。«江戸小紋» と呼ばれるこの模様を染めるのに欠かせないのが、伊勢型紙です。型紙を布にのせ、上から糊を置き、染めると、糊のついていないところだけに色が入ります。","型紙のもとは、美濃和紙を柿渋で何枚も貼り合わせた «型地紙»。水にも強く、長く使えます。職人はこれに小刀を当て、息をととのえながら彫っていきます。1寸（約3cm）のあいだに何本もの縞を彫る «縞彫»、錐で小さな穴をあけ続ける «錐彫» ――一枚仕上げるのに何日もかかることもあります。","«なぜ海辺の白子で型紙が?» はっきりした起源はわかっていません。子安観音寺の «不断桜» の葉の虫くいを見て型紙を思いついた、という言い伝えもあります。確かなのは、江戸時代に紀州藩がこの地を治め、型紙の商人に特権を与えて保護したこと。商人たちは型紙を背負って全国の染め屋を回りました。","明治以降、着物を着る人が減ると、型紙の仕事も少なくなっていきます。それでも、1955年には彫りの技術が国の重要無形文化財に指定され、名人たちが «人間国宝» として認められました。1983年には国の伝統的工芸品にもなっています。","いま白子の町には、型紙問屋だった寺尾家の建物を使った «伊勢型紙資料館» があり、道具や作品を見ることができます。彫りの実演に出会えたら、職人の手もとをじっと見つめてみてください。"],"tl":[["江戸時代初め","白子・寺家で型紙づくりが盛んになる"],["江戸時代","紀州藩が型紙商人を保護し、全国に販路が広がる"],["1955年","伊勢型紙の彫刻技術などが国の重要無形文化財に指定、6人が保持者に"],["1983年","国の伝統的工芸品に指定"],["1997年","伊勢型紙資料館が開館"]],"who":[["型彫職人","型紙を彫る人。技法ごとに専門が分かれる"],["型紙商人","紀州藩の保護を受け、全国の染め屋に型紙を売り歩いた"],["紀州藩","白子を領地にもち、型紙業を保護した"]],"deep":["彫りの技法は «突彫（つきぼり）» «錐彫（きりぼり）» «道具彫» «縞彫（しまぼり）» の4つが代表で、職人はふつうどれか一つを専門にします。","細い縞の型紙は形が崩れやすいため、2枚の型紙のあいだに絹糸をはさんで補強する «糸入れ» という技がありました（のちに «紗張り» に代わる）。","紀州藩は型紙商人に通行手形などの便宜を与えたとされ、そのおかげで白子・寺家の型紙はほぼ全国を独占しました。","伊勢型紙は19世紀のパリ万博などをきっかけに欧米へ渡り、ジャポニスムやアール・ヌーヴォーのデザインに影響を与えたといわれます。","型紙は染めの道具であるため作者の名が残りにくいのですが、明治以降は美術品としての評価も高まりました。"],"look":["伊勢型紙資料館（旧寺尾家住宅）の建物と展示","彫刻の道具（小刀・錐・道具彫の刃）","子安観音寺の不断桜","白子の古い町並み"],"q":["伊勢型紙の «型地紙» は、和紙を何で貼り合わせる？","柿渋（かきしぶ）。水に強く丈夫になり、茶色い色もこれによるものです。"],"myth":"不断桜の虫くいから型紙が生まれたという話は伝承。起源は諸説。","img":["型紙","江戸小紋","子安観音寺","柿渋"],"wp":"伊勢型紙","rel":{"ev":[],"grave":[]},"ph":[["c:4/44/Japanese_Katagami_Stencil_Abstract_Text.jpg",2338,2953,"伊勢型紙"],["c:e/e5/Komon.jpg",320,385,"江戸小紋"]]},{"id":"24_suzuka_kosho","n":"鈴鹿海軍工廠跡（軍都鈴鹿の始まり）","yomi":"すずかかいぐんこうしょうあと","cat":"昭和","rank":"B","y":1943,"era":["showa"],"sh":"","ad":"鈴鹿市平田町周辺","st":"近鉄鈴鹿線 平田町駅周辺。遺構は点在し、車が便利","la":34.8645,"lo":136.5545,"hook":"«鈴鹿市» は、海軍の施設をつくるために生まれた町だった。田んぼの中に現れた巨大な兵器工場の記憶。","lead":"太平洋戦争中、鈴鹿に海軍の兵器工場 «鈴鹿海軍工廠» がつくられ、機銃などを生産しました。鈴鹿市はこうした軍の施設を置くため、1942年に町や村が合併して誕生した町です。工場の建物はほとんど残っていませんが、跡地は戦後、工場や住宅地に生まれ変わりました。","story":["1940年代のはじめ、伊勢湾に面した鈴鹿の平野に、海軍の施設がつぎつぎと計画されました。飛行場をもつ鈴鹿海軍航空隊、そして兵器をつくる鈴鹿海軍工廠。広い土地が必要だったため、田畑や集落が買い上げられ、景色は大きく変わっていきます。","1942年12月、白子町・神戸町など2町12村が合併して «鈴鹿市» が生まれました。«なぜこんなに急いで合併したのか?» 軍の施設を一つの自治体で受け入れ、道路や住宅を整えるためだったといわれます。鈴鹿は «軍都» として出発した町なのです。","1943年に開かれた工廠では、飛行機や艦船にのせる機銃やその弾などがつくられました。全国から工員が集められ、学業をやめて働く «勤労動員» の学生や、女子挺身隊の女性たちも工場に通いました。朝から夜まで、旋盤の音が鳴りやまなかったといいます。","戦争が終わると、工廠は役目を終えました。広い跡地と整った道路や水は、戦後の工場誘致に生かされ、鈴鹿は自動車などの工業都市として歩みはじめます。いま平和な町並みを歩いても、工廠の姿を思い浮かべるのは難しいほどです。","それでも、町のあちこちに残る記念碑や、市が集めた証言・資料が、あの時代を伝えています。働かされた若い人たちの暮らしと、戦争で失われた命に思いを寄せながら訪ねたい場所です。"],"tl":[["1938年","鈴鹿海軍航空隊が開隊"],["1942年12月1日","2町12村の合併で鈴鹿市が誕生"],["1943年","鈴鹿海軍工廠が開庁"],["1945年8月","終戦。工廠は廃止される"],["戦後","跡地が工場用地・住宅地などとして再利用される"]],"who":[["海軍の技術者・工員","工廠で兵器の生産にあたった"],["勤労動員の学生","学業を中断して工場で働いた若者たち"],["女子挺身隊の女性たち","工場の労働力として動員された"]],"deep":["«工廠（こうしょう）» は軍直営の兵器工場のこと。海軍には横須賀・呉・佐世保・舞鶴などの大工廠のほか、戦争中に新設された工廠がいくつもあり、鈴鹿はその一つです。","鈴鹿市の誕生は、海軍の施設を受け入れる «軍都計画» と深く結びついていました。合併した町村の数（2町12村）がそれを物語ります。","工廠では機銃（航空機銃）やその部品・弾薬がつくられたとされ、同じ時期に近くには海軍航空隊や飛行場もありました。","戦後、広い旧軍用地はまとまった工場用地として企業誘致に使われ、鈴鹿が工業都市になる土台になったといわれます。","工廠の建物はほとんど残っておらず、跡の範囲や遺構については、市の資料や郷土史の調査で確認するのが確実です。"],"look":["跡地周辺の記念碑・説明板（場所は市の資料で確認を）","鈴鹿市の平和関連の展示や資料","碁盤の目状に整った道路（旧軍用地の名ごり）"],"q":["鈴鹿市が誕生したのは何年？","1942年（昭和17年）。海軍の施設を受け入れるため、2町12村が合併しました。"],"myth":"工廠の正確な範囲・遺構の所在は資料で要確認。","img":["海軍工廠","鈴鹿市","鈴鹿海軍航空隊","勤労動員"],"wp":"鈴鹿海軍工廠","rel":{"ev":[],"grave":[]},"ph":[["c:2/26/%C3%86ON_MALL_Suzuka_%281%29.JPG",2004,1474,"鈴鹿海軍工廠"],["c:c/c5/SUZUKA_CIRCUIT_on_26th_November_2022.jpg",2560,1920,"鈴鹿市"]]},{"id":"24_senjuji","n":"専修寺（高田本山）と一身田寺内町","yomi":"せんじゅじ","cat":"寺社","rank":"A","y":1666,"era":["muromachi","edo"],"sh":"国宝","ad":"津市一身田町","st":"JR紀勢本線 一身田駅から歩いて約5分","la":34.7595,"lo":136.5135,"hook":"畳780枚をしきつめる巨大な御影堂。お寺をぐるりと堀が囲む «寺内町» は、今も町の形のまま残っている。","lead":"浄土真宗高田派の本山で、«高田本山» と呼ばれます。江戸時代の巨大な «御影堂» と «如来堂» は、2017年に国宝になりました。お寺のまわりには堀で囲まれた «一身田寺内町» が広がり、門前町の雰囲気を今に伝えています。","story":["鎌倉時代、親鸞聖人は関東で教えを広めていました。そのとき下野国高田（いまの栃木県真岡市）に建てたお堂が、専修寺の始まりとされます。のちに «高田派» と呼ばれる門徒たちは、東国で大きな力をもつようになりました。","室町時代の中ごろ、高田派の第10世・真慧（しんね）上人は、伊勢や近江で熱心に布教し、一身田に拠点を築きました。やがて本山の役割はこの地に移ります。«なぜ関東から伊勢へ?» 東国の本寺が戦乱で焼けたことや、伊勢・東海に多くの門徒がいたことが理由と考えられています。","お寺のまわりには堀がめぐらされ、その内側に門徒や商人が住む町ができました。これが «寺内町（じないちょう）»。堀は、戦国時代に寺と町を守る «城壁» の役目をはたしました。いまも堀の一部と、黒門などの門のあとが残り、町の形がよくわかります。","境内に入ると、まず圧倒されるのが «御影堂（みえいどう）»。1666年に完成した親鸞聖人の像をまつるお堂で、中は780畳もの広さがあります。となりの «如来堂» は1748年の完成で、細かな彫刻が見事です。«この大きさを木だけで?» 何百年も前の大工の技に、ただ驚くばかりです。","寺宝には、親鸞自筆の『三帖和讃』や『西方指南抄』など国宝の書物もあります。お堂の縁側に座り、広い境内をわたる風を感じると、門徒たちがここに集まった日々が少しだけ見えてくるようです。"],"tl":[["1226年ごろ","親鸞が下野国高田に専修寺を建てたと伝わる"],["15世紀後半","真慧が一身田に拠点を築く"],["戦国時代","一身田が高田派の中心となり、寺内町が形づくられる"],["1666年","御影堂が完成"],["1748年","如来堂が完成"],["2017年","御影堂・如来堂が国宝に指定"]],"who":[["親鸞","浄土真宗の開祖。高田の専修寺を開いたとされる"],["真慧","高田派第10世。一身田に拠点を移し、教団を大きくした"],["高田派の門徒","寺内町に住み、寺を支えた人びと"],["津藩主・藤堂家","江戸時代に寺と関わりをもった領主"]],"deep":["御影堂は間口約42m・奥行約33mで、現存する木造建築の中でも全国屈指の大きさとされます。","国宝の親鸞自筆本『三帖和讃』『西方指南抄』などが伝わり、親鸞研究の一級史料です。宝物は公開日が限られます。","一身田寺内町は、堀（環濠）に囲まれた寺内町の形がよく残る例として知られ、黒門などの門が町の出入口でした。","栃木県真岡市にも «本寺» として専修寺が残り、国の重要文化財の建物があります。高田派は «本寺» と «本山» が別にあるのが特徴です。","御影堂の内部の «畳780枚» は、多くの門徒が一度に集まるための広さでした。"],"look":["御影堂（国宝）の大広間","如来堂（国宝）の彫刻","唐門・山門","寺内町を囲む環濠と黒門","寺内町の古い町並み"],"q":["専修寺の御影堂の中は、畳何枚分の広さ？","約780畳。多くの門徒が集まれるよう、とても広くつくられています。"],"myth":"本山が一身田へ移った時期・理由は諸説。","img":["親鸞","真宗高田派","寺内町","専修寺 (真岡市)"],"wp":"専修寺","rel":{"ev":[],"grave":[]},"ph":[["c:a/ad/ShinranShonin.png",371,507,"親鸞"],["c:f/f9/Shinshu_Takada-ha_Shumuin.JPG",2560,1920,"真宗高田派"],["c:8/81/Isshinden_Jinaicho.JPG",2560,1920,"寺内町"]]},{"id":"24_tsu_kannon","n":"津観音（恵日山観音寺）","yomi":"つかんのん","cat":"寺社","rank":"B","y":709,"era":["nara","edo","showa"],"sh":"","ad":"津市大門","st":"近鉄名古屋線 津新町駅から歩いて約15分。津駅からバスで «大門» 下車すぐ","la":34.7155,"lo":136.5105,"hook":"浅草・名古屋の大須と並ぶ «日本三観音» の一つといわれるお寺。津の町は、この観音さまの門前町として育った。","lead":"津市の中心部・大門にある真言宗のお寺で、正式には恵日山観音寺。«津観音» の名で親しまれています。江戸時代は津藩主・藤堂家の祈願所として栄え、まわりの大門商店街はその門前町でした。","story":["寺の言い伝えでは、奈良時代の和銅年間、阿漕浦（あこぎうら）の漁師の網に、小さな観音像がかかりました。«これはただごとではない» と、人びとはお堂を建ててまつりました。これが津観音の始まりと伝わります。","戦国時代が終わり、藤堂高虎が津の城主になると、観音寺は藤堂家の祈願所として大切にされました。城下町の人びともお参りに集まり、門前には店が並んで «大門» のにぎわいが生まれます。伊勢参りの旅人も、ここに立ち寄ったといいます。","«日本三観音» ――東京の浅草寺、名古屋の大須観音と並べて、そう呼ばれることがあります。«なぜ津が?» 江戸時代の津観音がそれほど多くの人を集め、町の中心だったことのあらわれでしょう。ただし、三観音の顔ぶれには別の数え方もあります。","1945年7月、津の町は空襲で焼け野原になりました。観音寺も本堂や五重塔など多くの建物を失いました。それでも人びとはあきらめず、戦後に本堂が建て直され、のちには五重塔も再建されました。焼けあとから立ち上がる寺の姿は、戦後の津の町の復興とも重なっています。","いまの境内には、藤堂家ゆかりの品や仏像を伝える資料館もあります。大門の商店街を歩き、昔の門前町のにぎわいを想像しながらお参りしてみてください。"],"tl":[["708〜715年（和銅年間）","網にかかった観音像をまつったのが始まりと伝わる"],["江戸時代初め","藤堂高虎が津に入り、藤堂家の祈願所となる"],["江戸時代","門前町の大門がにぎわう"],["1945年7月","空襲で本堂・五重塔などを焼失"],["戦後","本堂・五重塔が再建される"]],"who":[["藤堂高虎","津藩の初代藩主。観音寺を祈願所として保護"],["藤堂家歴代藩主","寺を支え、位牌などが伝わる"],["阿漕浦の漁師","観音像を網で引き上げたと伝わる"]],"deep":["«日本三観音» の組み合わせには、浅草・大須・津のほか、ほかの寺を入れる数え方もあり、定まったものではありません。","津の地名は «安濃津（あのつ）» に由来し、中世には日本の «三津» の一つに数えられた港町でした。観音寺はその港町の信仰を集めたと考えられます。","藤堂家は日光東照宮など各地に縁のある一族で、観音寺には藤堂家の位牌などが伝わるといわれます。","1945年の津空襲は複数回にわたり、市街地の大部分が焼けました。観音寺の被災もその一つです。","境内の資料館では、戦火をくぐりぬけた仏像や寺宝が公開されることがあります（公開日は要確認）。","大門のにぎわいは戦前まで続き、津でいちばんの繁華街でした。観音寺の縁日には露店が並び、周辺の町や村からも人が集まったといわれます。お寺と商店街が一体になった «門前町» の典型です。"],"look":["本堂と再建された五重塔","大門商店街（門前町のなごり）","境内の資料館","近くの津城跡もあわせて","藤堂家ゆかりの寺宝（公開日は要確認）"],"q":["津観音のまわりに広がった門前町の地名は？","«大門（だいもん）»。いまも商店街の名前として残っています。"],"myth":"網にかかった観音像の由来は伝承。«日本三観音» の組み合わせは諸説。","img":["藤堂高虎","津城","安濃津","浅草寺"],"wp":"津観音","rel":{"ev":[],"grave":[]},"ph":[["c:9/90/Tsu_Kannon_2020-11_ac_%283%29.jpg",5863,3898,"津観音"],["c:e/e2/Toudou_Takatora.jpg",1056,1096,"藤堂高虎"],["c:d/d5/140405_Tsu_Castle_Tsu_MIe_pref_Japan16s3.jpg",6000,4000,"津城"],["c:8/8d/Asakusa_Senso-ji_2021-12_ac_%282%29.jpg",5863,3899,"浅草寺"]]},{"id":"24_yuki_jinja","n":"結城神社（南朝の忠臣 結城宗広の墓）","yomi":"ゆうきじんじゃ","cat":"墓所","rank":"A","y":1338,"era":["kamakura","muromachi","meiji"],"sh":"県指定史跡（結城宗広墓）","ad":"津市藤方","st":"近鉄名古屋線 津新町駅から歩いて約25分。車が便利","la":34.7045,"lo":136.5255,"hook":"奥州へ帰る船が嵐で戻された。病にたおれた老将が最期に願ったのは «朝敵を討て» ――しだれ梅の森に眠る南朝の忠臣。","lead":"南北朝時代、後醍醐天皇の南朝のために戦った奥州白河の武将・結城宗広をまつる神社です。宗広は伊勢から奥州へ船出しましたが、嵐で戻され、この地で亡くなりました。墓がある境内は、春には300本ほどのしだれ梅で知られます。","story":["結城宗広は、陸奥国白河（いまの福島県）の武士でした。鎌倉幕府をたおす戦いで後醍醐天皇の側につき、その後も北畠顕家とともに南朝のために戦います。顕家の軍は奥州から京をめざして長い道のりを進み、宗広はその中心にいました。","しかし1338年、顕家は和泉の石津の戦いで戦死します。南朝は立て直しをはかり、義良親王（のちの後村上天皇）を奉じて、伊勢の大湊から船で奥州へ向かう計画を立てました。宗広もその船団に加わります。«奥州で兵を集め、もう一度戦うのだ»。","ところが遠州灘で大嵐にあい、船団はばらばらになりました。宗広の船は伊勢に吹き戻され、老いた宗広はこの地で病にたおれます。『太平記』は、宗広が死の床で «朝敵の首を墓前にそなえよ» と言い残したと描き、その執念をすさまじい姿で語っています。","やがて地元の人びとは宗広の墓を守り、江戸時代には津藩主・藤堂高兌が墓所を整えて社を建てたとされます。明治になると南朝の忠臣をたたえる動きの中で、結城神社は別格官幣社となりました。«なぜ敵味方の話が、明治にこれほど重んじられたのか?» 時代ごとに歴史の見方が変わることも、この神社は教えてくれます。","春、境内をうめるしだれ梅は見事です。花の下で、遠い白河の地を思いながら亡くなった老将の心に、しばし思いを寄せてみてください。"],"tl":[["1333年","鎌倉幕府滅亡。宗広は後醍醐天皇方として活躍"],["1335〜1338年","北畠顕家とともに奥州から西上して戦う"],["1338年","顕家戦死。義良親王を奉じて伊勢から奥州へ出航するが嵐で伊勢に戻り、宗広は病没"],["1824年","津藩主・藤堂高兌が社殿を建てたとされる"],["1882年","別格官幣社となる"],["1945年","空襲で社殿を焼失、のちに再建"]],"who":[["結城宗広","祭神。陸奥白河の武将で南朝の忠臣とされる"],["北畠顕家","宗広が従った南朝の若き総大将。1338年に戦死"],["後醍醐天皇","南朝の天皇。宗広が仕えた"],["義良親王（後村上天皇）","宗広が奥州へ奉じようとした親王"],["藤堂高兌","津藩主。墓所を整え社を建てたとされる"]],"deep":["同じ船団には北畠親房や義良親王も乗っていました。親房は常陸へ、義良親王の船は伊勢に戻り、のちに吉野で即位して後村上天皇となります。","『太平記』の宗広の臨終の場面は、死後に地獄へ落ちたとまで描くなど誇張が多く、そのまま史実とは言えません。","宗広の子・親光は建武政権の «三木一草» の一人に数えられる忠臣で、京都で戦死しています。","結城神社は建武中興十五社（南朝の功臣をまつる神社）の一つです。","しだれ梅は300本ほどといわれ、2月下旬〜3月の見ごろには多くの人が訪れます。"],"look":["結城宗広の墓","しだれ梅の庭","本殿と境内の碑","近くの阿漕浦の海（出航・漂着の海を想像する）"],"q":["結城宗広が乗った船団が向かおうとした場所は？","奥州（陸奥国）。嵐で船団が散り、宗広の船は伊勢へ吹き戻されました。"],"koji":[{"w":"朝敵の首を墓前に","m":"『太平記』が伝える宗広の遺言。最期まで南朝のために戦おうとした執念を示すが、物語の脚色を含む"}],"myth":"『太平記』の臨終の描写は誇張・脚色を含む。墓所の由来と社殿の創建年は伝承を含む。","img":["結城宗広","北畠顕家","建武中興十五社","太平記"],"wp":"結城神社","rel":{"ev":[],"grave":[]},"ph":[["c:b/b2/Y%C5%ABki_Shrine.jpg",400,258,"結城神社"],["c:0/07/%E7%B5%90%E5%9F%8E%E5%AE%97%E5%BA%83.jpg",1215,1819,"結城宗広"],["c:8/8a/%E5%8C%97%E7%95%A0%E9%A1%95%E5%AE%B6.png",368,462,"北畠顕家"],["c:7/7c/Taiheiki_-_1698_-_1-5.jpg",2592,1728,"太平記"]]},{"id":"24_tanigawa_kotosuga","n":"谷川士清旧宅（日本初の五十音順国語辞典）","yomi":"たにかわことすがきゅうたく","cat":"学び","rank":"B","y":1750,"era":["edo"],"sh":"国指定史跡","ad":"津市八町","st":"近鉄名古屋線 津新町駅から歩いて約15分","la":34.7185,"lo":136.5025,"hook":"«あいうえお» の順にことばを並べた、日本で初めての本格的な国語辞典。作ったのは、津の町のお医者さんだった。","lead":"江戸時代の国学者で医者の谷川士清（ことすが）が住んだ家です。士清は日本初の五十音順の国語辞典『和訓栞（わくんのしおり）』をつくりました。旧宅は国の史跡で、近くには士清が書き損じの原稿を埋めた «反古塚» もあります。","story":["いま私たちは辞書で «あ» から順にことばを探します。あたりまえのようですが、江戸時代にはそうではありませんでした。ことばは «いろは» 順や意味のまとまりで並べるのがふつうだったのです。«もっと引きやすくできないか?» そう考えたのが、津の医者・谷川士清でした。","士清は1709年、津の町医者の家に生まれました。京都で医学を学んで家を継ぎ、患者を診るかたわら、日本の古い言葉や『日本書紀』の研究にうちこみます。やがて『日本書紀』の注釈書『日本書紀通証』をまとめ、学者として名を知られるようになりました。","士清がとりくんだもう一つの大仕事が『和訓栞』です。古典の言葉から方言、日常の言葉まで、2万語以上を集め、五十音順に並べて意味を記しました。何十年もかけた仕事は、士清が亡くなった翌年から刊行がはじまり、全部そろったのは明治時代のことでした。","士清は松坂の本居宣長とも手紙をやりとりし、学問を語り合いました。年齢は20歳以上離れていましたが、宣長は士清を先輩として敬ったといわれます。«言葉の研究は、昔の人の心を知ること» ――二人は同じ思いをもっていたのかもしれません。","旧宅は、江戸時代の町家のたたずまいを残しています。書き損じの原稿を埋めて供養したという «反古塚（ほごづか）» もあわせて見ると、一語一語を大切にした学者の姿が浮かんできます。"],"tl":[["1709年","津に生まれる"],["1751年","『日本書紀通証』が完成したとされる"],["1776年","没する"],["1777年","『和訓栞』の刊行がはじまる"],["1887年","『和訓栞』の刊行が完結"],["昭和時代","旧宅が国の史跡に指定される"]],"who":[["谷川士清","国学者・医者。『和訓栞』『日本書紀通証』の著者"],["本居宣長","松坂の国学者。士清と交流した"],["谷川家の人びと","士清の死後、『和訓栞』の刊行を続けた"]],"deep":["『和訓栞』は前編・中編・後編からなり、全93巻におよぶ大部の辞書です。刊行に100年以上かかりました。","五十音順の配列は、第2音節以下まで五十音順にした点で画期的とされ、近代の国語辞典の先がけと評価されます。","『日本書紀通証』は『日本書紀』全体に注をつけた大著で、垂加神道の影響も見られます。","反古塚は、士清が自分の書き損じの原稿を埋めた塚と伝わり、学問への敬意の表れとされます。","旧宅は町家の建物で、隣に谷川士清の資料を展示する施設があります（開館日は要確認）。","«和訓» とは、漢字に当てた日本語の読み（やまとことば）のこと。書名は «やまとことばを読み解くための道しるべ（栞）» という意味で、古典を読む人のための手引きとして長く使われました。"],"look":["旧宅の町家の建物","反古塚","『和訓栞』など資料の展示","近くの津観音・津城跡もあわせて","町家の間取り（医院と住まいを兼ねた暮らしを想像する）"],"q":["谷川士清がつくった五十音順の国語辞典の名前は？","『和訓栞（わくんのしおり）』。刊行完結は明治時代でした。"],"myth":"反古塚の由来は伝承を含む。","img":["和訓栞","本居宣長","国学","日本書紀"],"wp":"谷川士清","rel":{"ev":[],"grave":[]},"ph":[["c:9/9c/Tanigawa_Kotosuga_25.jpg",239,239,"谷川士清"],["c:f/f6/%E6%9C%AC%E5%B1%85%E5%AE%A3%E9%95%B702.jpg",1345,1544,"本居宣長"],["c:f/ff/%E5%A5%91%E6%B2%96%E3%80%81%E8%B3%80%E8%8C%82%E7%9C%9F%E6%B7%B5%E3%80%81%E6%9C%AC%E5%B1%85%E5%AE%A3%E9%95%B7%E5%AF%BE%E5%BA%A7%E7%94%BB%E5%83%8F.jpg",998,701,"国学"],["c:9/98/Nihonshoki_tanaka_version.jpg",1472,632,"日本書紀"]]},{"id":"24_mie_kaigun","n":"三重海軍航空隊（予科練）跡","yomi":"みえかいぐんこうくうたいあと","cat":"昭和","rank":"A","y":1942,"era":["showa"],"sh":"","ad":"津市香良洲町","st":"近鉄 津駅・津新町駅からバスまたは車で約20〜30分。車が便利","la":34.6455,"lo":136.5565,"hook":"«七つボタンは桜に錨» ――海辺の町に集められた15〜17歳の少年たち。空にあこがれ、多くが二度と戻らなかった。","lead":"太平洋戦争中、雲出川河口の香良洲（からす）に、海軍の飛行機乗りを育てる «予科練（海軍飛行予科練習生）» の航空隊がありました。全国から集まった少年たちがここで訓練を受け、その多くが戦場へ向かいました。いま跡地には慰霊碑が建ち、資料館が記憶を伝えています。","story":["1942年、伊勢湾に面した香良洲の砂浜の町に «三重海軍航空隊» が開かれました。ここは飛行機に乗る兵士を育てる学校のような場所で、全国から試験に合格した少年たちが集まりました。«予科練» と呼ばれた彼らは、まだ中学生や高校生くらいの年ごろです。","少年たちは朝早くから、手旗信号やモールス信号、体操、水泳、グライダーの訓練にはげみました。制服の «七つボタン» は、少年たちのあこがれでした。«早く空を飛びたい» ――家族へ出した手紙には、そんな言葉がつづられていたといいます。","しかし戦争が進むと、十分な飛行訓練を受ける前に戦場へ送られる者もふえ、やがて特別攻撃隊として出撃する若者も出ました。«なぜ、こんなに若い人たちが?» 訓練を終えた少年たちの多くが、20歳になる前後で命を落としました。","戦争が終わると航空隊はなくなり、跡地は町や田畑にもどりました。のちに、元予科練生や遺族の人びとが中心となって慰霊碑を建て、毎年、亡くなった仲間をしのぶ集まりが続けられてきました。","香良洲の資料館には、少年たちの写真や手紙、遺品が展示されています。一通一通の手紙に書かれた母への言葉を読むと、胸がしめつけられます。静かな海辺で、戦争で失われた若い命に手を合わせたい場所です。"],"tl":[["1930年","海軍の予科練の制度が始まる（横須賀）"],["1942年","香良洲に三重海軍航空隊が開隊"],["1943〜1945年","多くの予科練生が入隊し訓練を受ける"],["1945年8月","終戦。航空隊は解隊"],["戦後","元予科練生や遺族によって慰霊碑が建てられる"]],"who":[["予科練生","全国から集まった少年たち。飛行兵をめざして訓練を受けた"],["教官・下士官","少年たちを指導した海軍の軍人"],["遺族・元予科練生","戦後、慰霊碑を建て記憶を伝えてきた人びと"]],"deep":["«予科練» は «海軍飛行予科練習生» の略。飛行機乗りの基礎を学ぶ課程で、学歴などにより甲種・乙種などに分かれていました。","三重海軍航空隊は、土浦（茨城県）と並ぶ大規模な予科練の航空隊の一つで、多くの練習生を受け入れたといわれます。","戦争末期には飛行機や燃料が不足し、予科練生が飛行訓練ではなく陣地づくりや特攻兵器の訓練に回されることもありました。","軍歌『若鷲の歌』（1943年）は予科練をうたったもので、«若い血潮の予科練の 七つボタンは桜に錨» の歌詞で広く知られます。","香良洲は雲出川の河口にはさまれた土地で、広い砂地と海が水上機などの訓練に向いていたと考えられます。","戦後80年近くがたち、元予科練生の多くが世を去りました。証言を聞ける人が少なくなるなか、資料館の手紙や写真、地元の人びとの語り継ぎが、記憶をつなぐ大切な役目をはたしています。"],"look":["予科練の慰霊碑","香良洲歴史資料館の展示（手紙・遺品）","雲出川河口と伊勢湾の海辺","跡地周辺の説明板"],"q":["予科練生の制服の特徴として歌にうたわれたものは？","«七つボタン»。『若鷲の歌』で «七つボタンは桜に錨» とうたわれました。"],"myth":"","img":["海軍飛行予科練習生","若鷲の歌","特別攻撃隊","香良洲町"],"wp":"三重海軍航空隊","rel":{"ev":[],"grave":[]},"ph":[["c:b/b4/%E4%BA%88%E7%A7%91%E7%B7%B4%E5%88%B6%E6%9C%8D.jpg",421,601,"海軍飛行予科練習生"],["c:2/2d/USS_Missouri_Zero_Kamikaze.jpg",1850,2128,"特別攻撃隊"],["c:2/2e/Karasu%2Cmie.jpg",3072,2304,"香良洲町"]]},{"id":"24_matsuura_takeshiro","n":"松浦武四郎記念館（「北海道」の名付け親）","yomi":"まつうらたけしろうきねんかん","cat":"幕末","rank":"A","y":1869,"era":["edo","meiji"],"sh":"国の重要文化財（松浦武四郎関係資料）","ad":"松阪市小野江町","st":"近鉄山田線 伊勢中原駅から歩いて約25分。車が便利","la":34.6295,"lo":136.5265,"hook":"16歳で家出して日本中を歩き、蝦夷地を6回旅した男。«北海道» という名前は、この伊勢の旅人が考えた。","lead":"幕末から明治に活躍した探検家・松浦武四郎のふるさとにある記念館です。武四郎は蝦夷地（いまの北海道）を6回にわたって調べ、アイヌの人びとと交流しながら地図や記録を残しました。明治になって «北加伊道» という名前を提案し、それがもとになって «北海道» が生まれました。","story":["1818年、伊勢国の須川村（いまの松阪市小野江町）に生まれた武四郎は、伊勢参りの旅人が行き交う街道のそばで育ちました。«この道の先には何があるのだろう» ――16歳の時、とうとう家を飛び出して江戸へ。その後、日本各地を歩き回ります。","長崎で武四郎は、ロシアが北の蝦夷地に迫っているという話を耳にします。«このままでは蝦夷地が危ない。だれかがしっかり調べなければ»。1845年、28歳で初めて蝦夷地へ渡ると、彼の人生は北の大地と結びつきました。","武四郎の旅には、いつもアイヌの人びとの案内がありました。舟をこぎ、山を越え、村に泊まり、言葉や地名を書きとめます。そして彼は、和人の商人に苦しめられるアイヌの暮らしも見つめ、その姿を記録に残しました。«ここは本来、彼らの土地なのだ» という思いが、記録のあちこちににじみます。","明治2年（1869年）、新政府の開拓判官になった武四郎は、蝦夷地の新しい名前として «北加伊道» などの案を出しました。«カイ» はアイヌの人がこの地に生まれた者を呼ぶ言葉だと聞いた、と武四郎は記しています。この案がもとになり «北海道» が決まりました。しかし開拓使のやり方に反発し、翌年には職を辞してしまいます。","晩年は古いものを集め、各地の山に登り、70歳近くで大台ヶ原にも3度登りました。記念館では地図や日誌、愛用の品々を通して、生涯歩き続けた武四郎の姿に出会えます。近くの生家もあわせて訪ねたいところです。"],"tl":[["1818年","伊勢国須川村に生まれる"],["1834年","16歳で家を出て江戸へ"],["1845年","初めて蝦夷地へ渡る"],["1856〜1858年","幕府の御雇として蝦夷地を調査"],["1869年","開拓判官となり «北加伊道» を提案。«北海道» と命名される"],["1870年","開拓判官を辞める"],["1888年","東京で没する"],["1994年","松浦武四郎記念館が開館"],["2008年","関係資料が国の重要文化財に指定"]],"who":[["松浦武四郎","探検家・著述家。北海道の名付け親"],["アイヌの人びと","武四郎の旅を案内し、地名や暮らしを教えた"],["明治新政府","武四郎を開拓判官に任じ、北海道の命名に意見を求めた"]],"deep":["武四郎の蝦夷地の旅は6回。前半の3回は自分の意思で、後半の3回は幕府に雇われての調査でした。","『東西蝦夷山川地理取調図』は、約9800のアイヌ語地名を書き込んだ大きな地図で、北海道の地理を知る基本資料となりました。","『近世蝦夷人物誌』では、アイヌの人びとの暮らしや、場所請負制の下での苦しい状況を描きました。幕府の時代には出版が許されなかったといわれます。","«北加伊道» は武四郎が出した6つの案の一つで、そのうち «加伊» を «海» に改めて «北海道» に決まったとされます。道内の国名・郡名の多くも彼の案がもとになっています。","晩年につくった一畳の書斎 «一畳敷» は、全国の寺社から集めた古材を使ったもので、現在は東京の国際基督教大学の構内に移されています。"],"look":["記念館の地図・日誌などの展示","蝦夷地の旅の道具","近くの松浦武四郎誕生地（生家）","伊勢街道の町並み"],"q":["武四郎が «北海道» の名のもとになる案として出した名前は？","«北加伊道»。«加伊» を «海» にして «北海道» になりました。"],"koji":[{"w":"北加伊道","m":"«カイ» はこの地に生まれた者を指す言葉とアイヌの長老から聞いた、と武四郎が記した名。北海道の名の由来"}],"myth":"«カイ» の意味については、武四郎の記述によるもので、言語学的には諸説ある。","img":["北海道","アイヌ","大台ヶ原"],"wp":"松浦武四郎","rel":{"ev":[],"grave":[]},"ph":[["c:5/55/Matsuura_takeshiro.jpg",826,1180,"松浦武四郎"],["c:3/3a/Hokkai_D%C5%8Djin_juka_gosui_zu_by_Kawanabe_Ky%C5%8Dsai_%28Matsuura_Takeshir%C5%8D_Memorial_Museum%29.jpg",738,1300],["c:6/66/Tokachi_plain_01.jpg",800,536,"北海道"],["c:a/a2/Ainu_Marriage.jpg",1200,1117,"アイヌ"],["c:2/2f/Mount_Odaigahara_-_panoramio.jpg",674,449,"大台ヶ原"]]},{"id":"24_takarazuka_kofun","n":"宝塚1号墳（船形埴輪）","yomi":"たからづかいちごうふん","cat":"遺跡","rank":"A","y":410,"era":["kofun"],"sh":"国指定史跡","ad":"松阪市宝塚町","st":"JR・近鉄 松阪駅から車で約10分、歩くと約40分","la":34.5535,"lo":136.5145,"hook":"古墳のすそから、長さ約1.4mの «船» があらわれた。王のたましいを運ぶ船か、それとも王の権力のしるしか。","lead":"松阪市の丘の上にある、全長約111mの前方後円墳です。伊勢地方では最大級で、5世紀初めごろにつくられたと考えられています。発掘で見つかった大きな «船形埴輪» は全国でも珍しい豪華なもので、国の重要文化財になっています。","story":["松阪の町を見下ろす丘の上に、こんもりとした森があります。それが宝塚1号墳。上から見ると鍵穴の形をした «前方後円墳» で、長さはおよそ111m。伊勢地方をおさめた有力な王の墓だと考えられています。","古墳の整備にむけた発掘調査で、研究者たちは古墳のくびれの近くに «造り出し» と呼ばれる張り出し部分を見つけました。そこには家や囲い、動物などの埴輪がならび、まるで儀式の場面を再現したようでした。そして、その中から一艘の船があらわれたのです。","船形埴輪は長さ約1.4m。船の上には «大刀» や «きぬがさ（日傘）»、«威杖（いじょう）» のような飾りが立てられていました。«ただの船ではない。王の船だ!» ――発見は大きなニュースになり、全国から見学の人が集まりました。","«なぜ墓に船を?» 答えはひとつではありません。亡くなった王のたましいをあの世へ運ぶ船、という考え。伊勢湾の海をおさめ、船で大和や各地と結ばれていた王の力を示すもの、という考え。どちらにしても、この地の王と海との深い関係がうかがえます。","いま古墳は史跡公園として整えられ、墳丘に登ることができます。船形埴輪は松阪市文化財センターの «はにわ館» で見られます。丘の上で海の方角を眺め、船に乗った王の旅を想像してみてください。"],"tl":[["5世紀初めごろ","宝塚1号墳が築かれる"],["1932年","宝塚1号墳・2号墳が国の史跡に指定"],["1999〜2000年","発掘調査で船形埴輪など多数の埴輪が出土"],["2000年代","船形埴輪を含む出土埴輪が国の重要文化財に指定される"],["2000年代","史跡公園として整備"]],"who":[["伊勢の首長（王）","宝塚1号墳に葬られた人物。名前はわかっていない"],["埴輪づくりの工人","船形埴輪など高度な埴輪をつくった職人たち"],["発掘調査にあたった研究者","造り出しと埴輪群を明らかにした"]],"deep":["船形埴輪は全国で出土例が限られ、宝塚1号墳のものは大刀・きぬがさなどの立ち飾りがついた完全な姿に近い例として、特に重要とされます。","«造り出し» は前方後円墳のくびれ部分につく四角い張り出しで、祭りや儀式を行った場とする説があります。宝塚1号墳では造り出しと墳丘をつなぐ «土橋» も確認されました。","墳丘は3段に築かれ、斜面には葺石（ふきいし）がしかれ、埴輪が列をなして並べられていたと考えられます。","近くには帆立貝形の宝塚2号墳もあり、あわせて国の史跡です。","船形埴輪が王の «葬送の船» か «権威の船» かは諸説あり、決着していません。","宝塚1号墳の埴輪には、船のほかに家形・囲形・盾・きぬがさなどがあり、造り出しの上で «王の館と儀式» を表したような配置だったと考えられています。埴輪の «並べ方» そのものが研究の対象です。"],"look":["墳丘に登って見る前方後円墳の形","造り出しと土橋のあと","復元された埴輪列","松阪市文化財センター «はにわ館» の船形埴輪（実物）"],"q":["宝塚1号墳の船形埴輪の上に立てられていた飾りの一つは？","大刀（たち）や、きぬがさ（日傘）など。王の権威を表す飾りです。"],"myth":"船形埴輪の意味（葬送の船か権威の象徴か）は諸説。","img":["前方後円墳","埴輪","造り出し","松阪市"],"wp":"宝塚1号墳","rel":{"ev":[],"grave":[]},"ph":[["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"],["c:e/e4/%E5%A1%9A%E5%BB%BB%E3%82%8A%E5%8F%A4%E5%A2%B3_-_panoramio.jpg",1280,960,"埴輪"],["c:c/ca/%E6%9D%BE%E5%9D%82%E5%9F%8E1.jpg",1891,1186,"松阪市"]]},{"id":"24_kayumi_ijiri","n":"粥見井尻遺跡（日本最古級の土偶）","yomi":"かゆみいじりいせき","cat":"遺跡","rank":"A","y":-11000,"era":["jomon"],"sh":"","ad":"松阪市飯南町粥見","st":"JR・近鉄 松阪駅から車で約40分。公共交通は不便","la":34.4855,"lo":136.4185,"hook":"手のひらにのる、顔のない小さな土の人形。約1万3000年前、縄文の人びとが最初につくった «土偶» の一つがここで見つかった。","lead":"松阪市の山あい、櫛田川のほとりにある縄文時代草創期（約1万3000年前）の遺跡です。1996年、道路工事にともなう発掘で、日本最古級の土偶2点と、当時の竪穴住居のあとが見つかりました。","story":["1996年、国道の工事の前に、飯南町粥見の段丘で発掘が行われていました。土を少しずつ掘り下げていくと、とても古い時代の竪穴住居のあとが見つかります。そして、小さな土のかたまりが一つ、また一つ。«これは…土偶だ!»","見つかった土偶は高さ数センチ。頭はあるのに顔はなく、胸にふたつのふくらみがあらわされています。女性の体をかたどったものと考えられ、手のひらにすっぽり入る大きさです。当時、これが日本でいちばん古い土偶として大きく報道されました。","約1万3000年前といえば、氷河期が終わりに近づき、人びとが土器を使いはじめたばかりのころ。多くの人はまだ移動しながら暮らしていたと考えられています。そんな時代に、なぜ人は土で «人のかたち» をつくったのでしょう。","無事なお産や家族の健康を祈ったのか、それとも病やけがの身代わりにしたのか。土偶の使い道は、じつは今もはっきりわかっていません。«顔がない» のも、あとの時代の土偶にくらべて不思議な点です。","遺跡は道路になり、現地に大きな見どころが残っているわけではありません。けれど、櫛田川の流れと山々は、きっと1万年以上前とそう変わらないはず。土偶は博物館などで公開されることがあるので、ぜひ実物の小ささを確かめてみてください。"],"tl":[["約1万3000年前","縄文時代草創期。竪穴住居で人びとが暮らす"],["1996年","道路工事にともなう発掘で土偶2点・竪穴住居跡が出土"],["1996年","日本最古級の土偶として発表される"],["2010年","滋賀県の相谷熊原遺跡で同じころの土偶が見つかる"]],"who":[["縄文草創期の人びと","この地で暮らし、土偶をつくった"],["発掘調査の担当者","三重県の調査で土偶を見つけた"]],"deep":["粥見井尻の土偶は、縄文時代草創期の «隆起線文土器» などと同じ層から出たことから時期が推定されました。","土偶は頭部・胴部を表しますが、顔や手足の表現はなく、乳房だけがはっきり表されています。のちの時代の土偶とは大きく違う、原初の姿です。","2010年には滋賀県東近江市の相谷熊原遺跡でも同じころの土偶が見つかり、«最古の土偶» は一つに決められない状況です。","竪穴住居のあとが見つかったことも重要で、草創期にすでにある程度定住する暮らしがあった可能性を示します。","土偶の用途は、祈りの道具・身代わり・お守りなど諸説あり、決着していません。","草創期の土偶は全国でもごくわずかしか見つかっていません。粥見井尻の2点は、土偶という «人をかたどる文化» がどのように始まったかを考えるうえで、欠かせない資料になっています。"],"look":["櫛田川の段丘地形（遺跡があった場所の立地）","博物館などで公開される土偶（実物の大きさ）","周辺の山里の風景","近くの道の駅など、飯南の山里の町並み"],"q":["粥見井尻遺跡の土偶は、どんな特徴をもっている？","顔がなく、胸のふくらみが表されている小さな土偶です。高さは数センチほど。"],"myth":"«日本最古» は発見当時の評価で、現在は «最古級»。土偶の用途は諸説。","img":["土偶","縄文時代","相谷熊原遺跡","櫛田川"],"wp":"粥見井尻遺跡","rel":{"ev":[],"grave":[]},"ph":[["j:3/3d/%E9%9D%92%E6%A3%AE%E7%9C%8C%E3%81%A4%E3%81%8C%E3%82%8B%E5%B8%82%E6%9C%A8%E9%80%A0%E4%BA%80%E3%83%B6%E5%B2%A1%E5%87%BA%E5%9C%9F_%E9%81%AE%E5%85%89%E5%99%A8%E5%9C%9F%E5%81%B6-2.JPG",3711,4947,"土偶"],["c:0/00/Kushida_river.jpg",960,768,"櫛田川"]]},{"id":"24_tenpaku","n":"天白遺跡（縄文の祈りの場）","yomi":"てんぱくいせき","cat":"遺跡","rank":"B","y":-1500,"era":["jomon"],"sh":"国指定史跡","ad":"松阪市嬉野釜生田町","st":"近鉄 伊勢中川駅から車で約15分。車が便利","la":34.6055,"lo":136.4345,"hook":"川原の石を何百と並べた不思議な «石の広場»。3000年以上前の人びとは、ここで何を祈ったのだろう。","lead":"中村川のほとりにある縄文時代後期の遺跡で、石をたくさん並べた «配石遺構» が見つかりました。石の下からは土偶や石の道具、焼いた骨のかけらなども出ており、縄文人が祈りや祭りを行った場所と考えられています。国の史跡に指定されています。","story":["松阪市の北西、中村川がゆったりと流れる台地で、土地の整備にともなって発掘が行われました。土を取りのぞくと、川原の丸い石が円や列をつくって、あたり一面に並んでいたのです。«これは自然にできたものではない»。","石の並びは一つではなく、大小いくつものまとまりがありました。石の下や近くからは、土偶、石棒（せきぼう）、耳飾り、たくさんの土器、そして火で焼かれた骨の小さなかけら。«人が暮らした家のあとは少ないのに、祈りの道具ばかり» ――研究者たちは首をかしげました。","そこから考えられたのが、«ここは暮らしの場ではなく、祈りや祭りの場だったのでは» という説です。亡くなった人をとむらう場所、豊かな恵みを願う場所、仲間が集まって儀式をした場所――さまざまな見方があります。","縄文時代の後期は、東日本では環状列石（ストーンサークル）がさかんにつくられた時代でもあります。«なぜ西の伊勢に、東のような石の祭り場が?» 天白遺跡は、縄文の祈りの文化が広く日本列島に広がっていたことを示す手がかりです。","いまは田園の中の静かな場所ですが、川原の石を一つひとつ運び、並べていった人びとの姿を想像すると、3000年以上前の祈りの声が聞こえてくるようです。"],"tl":[["約4000〜3000年前","縄文時代後期。配石遺構がつくられる"],["平成のはじめごろ","発掘調査で配石遺構が見つかる"],["平成時代","国の史跡に指定"]],"who":[["縄文後期の人びと","石を並べ、祈りや祭りを行ったと考えられる"],["発掘調査の担当者","広い範囲の配石遺構を明らかにした"]],"deep":["配石遺構は、川原石を円形・帯状などに並べたもので、いくつものまとまりが確認されています。一つの場所が長い時間をかけて使われ続けたと考えられます。","出土した石棒は男性を、土偶は女性を象徴するともいわれ、生命や豊かさを願う祭りとの関係が指摘されています。","焼けた骨片が見つかっていることから、とむらい（葬送）の場と結びつける説があります。","縄文後期の配石遺構は東日本に多く、西日本でこれほどの規模のものは珍しいとされます。","遺跡の名 «天白» は地名で、東海地方に多い «天白信仰» との関係を想像する人もいますが、根拠ははっきりしません。","配石の中には、石をすき間なく敷きつめたものや、細長い石を立てたと考えられるものもあります。一つの形に決まっておらず、長いあいだに少しずつ石が加えられていった «祈りの積み重ね» と見る研究者もいます。","東日本の代表的な配石遺構には秋田県の大湯環状列石（特別史跡）などがあり、天白遺跡とくらべると、縄文の祈りの東西の違いと共通点が見えてきます。"],"look":["遺跡のある河岸段丘の地形","中村川の流れと川原石","説明板","出土品は県や市の施設で公開されることがある"],"q":["天白遺跡で見つかった、石をたくさん並べたあとを何という？","«配石遺構（はいせきいこう）»。祈りや祭り、とむらいの場と考えられています。"],"myth":"遺跡の性格（祭祀の場・墓域など）は諸説。","img":["配石遺構","環状列石","石棒","縄文時代"],"wp":"天白遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:3/38/Tsukiyono_Fukasawa_Archaeological_site_2.jpg",4608,3456,"配石遺構"],["c:6/63/Stonehenge_Closeup.jpg",1280,960,"環状列石"],["c:c/c9/Sekibou.jpg",3145,2203,"石棒"]]},{"id":"24_niu_kozan","n":"丹生鉱山（伊勢水銀のふるさと）","yomi":"にうこうざん","cat":"産業","rank":"B","y":698,"era":["nara","muromachi","showa"],"sh":"","ad":"多気郡多気町丹生","st":"JR紀勢本線 相可駅などから車で約15〜20分。車が便利","la":34.4745,"lo":136.4985,"hook":"赤い石 «辰砂» から生まれる銀色の液体 «水銀»。奈良の大仏を金色にかがやかせた水銀は、伊勢の山から来たともいわれる。","lead":"多気町丹生は、古代から水銀のもとになる鉱石 «辰砂（しんしゃ）» がとれた土地です。奈良時代には朝廷に献上され、室町〜江戸時代には水銀からつくるおしろい «伊勢白粉» の原料として栄えました。昭和の中ごろまで採掘が続いた鉱山のあとが残っています。","story":["地名の «丹生（にう）» の «丹» は、赤い色のこと。この山からは、まっ赤な鉱石 «辰砂» がとれました。辰砂を焼くと、銀色にかがやく液体の金属――水銀が取り出せます。古代の人びとにとって、赤い顔料にも薬にもなる、ふしぎで貴重な宝物でした。","『続日本紀』には、文武天皇の時代（698年）に伊勢国から «朱沙（すさ）» が献上されたことが記されています。朱沙は辰砂のこと。丹生はその産地の有力候補です。やがて奈良の東大寺の大仏がつくられると、金メッキには大量の水銀が必要でした。«その水銀はどこから?» 伊勢の丹生から運ばれたという説があります。","室町時代から江戸時代にかけて、水銀は «伊勢白粉（いせおしろい）» という化粧品や薬の原料になりました。丹生の近くの射和（いざわ）では、水銀から白粉をつくる窯がたくさん並び、商人たちは «伊勢の白粉» を全国へ売り歩いて大きな富をきずきました。伊勢参りのおみやげとしても人気でした。","けれど良い鉱石はやがてとりつくされ、白粉の生産もおとろえます。昭和になると、近代的な方法で再び採掘がはじまりましたが、それも1970年代に終わりました。山の中には、坑道のあとがひっそりと残っています。","丹生の里には、水銀の神をまつる丹生神社や、空海ゆかりと伝わる丹生大師（神宮寺）があります。赤い石が人びとの暮らしを支えてきた長い歴史を、静かな山里で感じてみてください。"],"tl":[["698年","『続日本紀』に伊勢国が朱沙を献上したとある"],["8世紀中ごろ","東大寺大仏の鍍金に伊勢の水銀が使われたという説がある"],["室町〜江戸時代","射和で伊勢白粉がつくられ、全国に広まる"],["江戸時代後期","鉱石の枯渇などで白粉生産がおとろえる"],["昭和時代","近代的な水銀採掘が行われる"],["1970年代","採掘が終わる"]],"who":[["丹生の鉱夫たち","辰砂を掘り出した人びと"],["射和の白粉商人","水銀から白粉をつくり全国へ売った"],["竹川竹斎","射和の豪商。幕末に地域の産業や学問を支えた"],["空海","丹生大師（神宮寺）の開創にかかわったと伝わる"]],"deep":["水銀の鉱石・辰砂は硫化水銀。焼いて気化させた水銀を冷やして集めます。昔の人は «朱» の顔料としても辰砂を使いました。","伊勢白粉は «軽粉（けいふん）» とも呼ばれ、水銀を原料とした白い粉。化粧のほか、薬としても使われましたが、体に害があることは当時はよく知られていませんでした。","各地の «丹生» という地名や «丹生神社» は、水銀の産地と関係があるとする説が有名です。","東大寺大仏の鍍金に使われた水銀の量は数トンにのぼるといわれ、その産地として伊勢丹生をあげる説がありますが、史料で確定しているわけではありません。","坑道跡などは私有地や危険な場所にあることが多く、無断で立ち入ることはできません。"],"look":["丹生神社","丹生大師（神宮寺）","丹生の山里の景色","近くの射和の町並み（白粉商人のまち）"],"q":["水銀のもとになる赤い鉱石を何という？","«辰砂（しんしゃ）»。«丹» という字も、この赤い色を表します。"],"myth":"東大寺大仏への水銀供給、丹生大師の空海開創は説・伝承。坑道跡は立入不可。","img":["辰砂","水銀","丹生","射和"],"wp":"丹生鉱山","rel":{"ev":[],"grave":[]},"ph":[["c:9/9e/Cinnabar_on_Dolomite.jpg",1763,1254,"辰砂"],["c:9/99/Pouring_liquid_mercury_bionerd.jpg",1209,1311,"水銀"]]},{"id":"24_takihara","n":"瀧原宮（皇大神宮別宮）","yomi":"たきはらのみや","cat":"寺社","rank":"A","y":-5,"era":["kofun","heian"],"sh":"","ad":"度会郡大紀町滝原","st":"JR紀勢本線 滝原駅から歩いて約30〜40分。道の駅 «奥伊勢木つつ木館» のとなり","la":34.3585,"lo":136.4085,"hook":"伊勢神宮の内宮から40km以上はなれた山の中。«遙宮（とおのみや）» と呼ばれる、杉木立に包まれたもう一つの天照大神の宮。","lead":"伊勢神宮・内宮（皇大神宮）の別宮で、天照大神の «御魂（みたま）» をまつります。内宮から遠くはなれていることから «遙宮» と呼ばれます。うっそうとした杉の森の中に、瀧原宮と瀧原竝宮（たきはらならびのみや）の二つの宮が並んで建っています。","story":["むかし、倭姫命は天照大神をまつる場所をさがして、各地を旅していました。『倭姫命世記』という書物によれば、姫は宮川をさかのぼり、この山あいの «瀧原» の地にたどりつきます。«ここは大河の瀧原の国なり» ――そして宮を建てたと伝わります。","けれど倭姫命の旅はここで終わりませんでした。やがて天照大神は、いまの五十鈴川のほとりに鎮まります。«なぜ遠く離れたこの地に、今も宮が残っているのか?» 旅の途中でまつられた場所が大切にされつづけた、とも、古くからこの地の人びとが天照大神をまつっていた、ともいわれます。","参道に入ると、樹齢数百年の杉の巨木がそびえ、昼でもうす暗いほど。とちゅうには頓登川（とんどがわ）の清流へ下りる «御手洗場（みたらし）» があり、参拝者はここで手を清めます。内宮の五十鈴川の御手洗場と、よく似た雰囲気です。","森の奥に、同じ形の二つの社殿が並んでいます。右が瀧原宮、左が瀧原竝宮。どちらも天照大神の御魂をまつりますが、それぞれの性格については昔から説があります。近くには、ほかの宮では見られない «御船倉（みふなぐら）» という建物もあります。","20年ごとの式年遷宮では、ここも新しい社殿に建て替えられます。観光客であふれる内宮とはちがい、鳥の声と川の音だけがひびく森。«伊勢神宮のもう一つの顔» に出会える場所です。"],"tl":[["垂仁天皇の代","倭姫命が宮を定めたと伝わる"],["804年","『皇太神宮儀式帳』に瀧原宮・瀧原竝宮が記される"],["927年","『延喜式』に大神宮の別宮として記される"],["2014年","第62回式年遷宮にともない遷宮"]],"who":[["天照大神","瀧原宮・瀧原竝宮にまつられる（御魂）"],["倭姫命","宮所をさがす旅でこの地に宮を建てたと伝わる"],["神宮の神職","今も祭りをつかさどる"]],"deep":["瀧原宮と瀧原竝宮はともに «天照大神御魂» をまつり、瀧原宮を «和魂（にぎみたま）»、竝宮を «荒魂（あらみたま）» とする説もあります。","«御船倉» は、ご神体を納める «御船代（みふなしろ）» を納める倉とされ、瀧原宮にしかないめずらしい建物です。","境内には所管社の若宮神社・長由介神社（ながゆけじんじゃ）などもあり、長由介神社には川島神社が同座しています。","内宮の別宮で、内宮から離れた場所にあるのは瀧原宮と伊雑宮（志摩市）で、どちらも «遙宮» と呼ばれます。","『皇太神宮儀式帳』は804年に神宮が朝廷に提出した記録で、瀧原宮の古さを示す重要な史料です。","瀧原宮は、宮川の支流・大内山川の流域にあり、古くから «瀧原» と呼ばれた広い地域の中心でした。宮の近くには神宮の神田や御料地があったとも考えられ、この地方と神宮のつながりの深さがうかがえます。"],"look":["杉の巨木の参道","頓登川の御手洗場","並んで建つ瀧原宮・瀧原竝宮","御船倉","若宮神社・長由介神社"],"q":["瀧原宮にしかないといわれる、ご神体を納める器を収めた建物は？","«御船倉（みふなぐら）»。ほかの宮では見られない建物です。"],"myth":"倭姫命の巡幸と創祀は『倭姫命世記』などの伝承。二宮の性格（和魂・荒魂）は諸説。","img":["倭姫命","皇大神宮","伊雑宮","式年遷宮"],"wp":"瀧原宮","rel":{"ev":[],"grave":[]},"ph":[["c:5/58/Takihara-no-miya_01.JPG",768,576,"瀧原宮"],["c:7/7d/PrincessYamatoHime.jpg",875,1000,"倭姫命"],["c:8/8d/Naiku_04.jpg",3000,2000,"皇大神宮"],["c:f/fa/Izawa-no-miya_07.jpg",3000,2000,"伊雑宮"],["c:1/1f/%E5%BC%8F%E5%B9%B4%E9%81%B7%E5%AE%AE%E8%A8%98%E5%BF%B5%E7%A5%9E%E5%AE%AE%E7%BE%8E%E8%A1%93%E9%A4%A8.jpg",1600,1200,"式年遷宮"]]},{"id":"24_futami","n":"二見興玉神社と夫婦岩","yomi":"ふたみおきたまじんじゃとめおといわ","cat":"寺社","rank":"A","y":1910,"era":["kofun","edo","meiji"],"sh":"","ad":"伊勢市二見町江","st":"JR参宮線 二見浦駅から歩いて約15分","la":34.5085,"lo":136.7885,"hook":"大小二つの岩を結ぶ太い注連縄。夏至の朝、その間から太陽がのぼる――二見浦は、お伊勢参りの «みそぎ» の浜だった。","lead":"伊勢市の二見浦にある神社で、海に立つ «夫婦岩» で有名です。夫婦岩は、沖合に沈む聖なる岩 «興玉神石（おきたましんせき）» を拝むための鳥居の役目をしているといわれます。江戸時代、伊勢参りの人びとはまずここで身を清めました。","story":["朝の二見浦。波の向こうに、大きな岩と小さな岩が寄りそうように立っています。大きい方が «男岩» で高さ約9m、小さい方が «女岩» で約4m。二つを結ぶ注連縄は長さ約35mもあり、夫婦の仲むつまじさにたとえられて «夫婦岩» と呼ばれてきました。","でも、夫婦岩の本当の役目は別のところにあります。岩の沖合約700mの海の底には、猿田彦大神ゆかりの «興玉神石» という聖なる岩が沈んでいると伝わります。夫婦岩は、その神石と、はるか昇る太陽を拝むための «鳥居» なのです。«岩が鳥居?» ――自然そのものを神聖なものとして拝む、古い信仰のかたちです。","江戸時代、お伊勢参りの人びとは、まず二見の浜で海に入り、体を清めてから外宮・内宮へ向かいました。これを «浜参宮（はまさんぐう）» といいます。いまでも神社では、海水で清める代わりに «無垢塩草（むくしおぐさ）» でおはらいを受けることができます。","境内には、たくさんの蛙の置物が並んでいます。蛙は猿田彦大神のお使いとされ、«無事かえる»«お金がかえる» の語呂合わせで人気です。旅人が無事に帰れるように――そんな願いが込められています。","夏至のころ、晴れた朝には夫婦岩の間から太陽がのぼり、条件がよければ遠くに富士山が見えることもあります。千年以上前から人びとが見つめてきた、海と太陽の神聖な風景です。"],"tl":[["古代","沖の興玉神石を拝む信仰があったと伝わる"],["江戸時代","伊勢参りの前に二見浦で身を清める «浜参宮» が広まる"],["1910年","興玉社と三宮神社を合わせ二見興玉神社となる"],["毎年5月・9月・12月","夫婦岩の大注連縄の張り替え神事"]],"who":[["猿田彦大神","主祭神。みちびきの神"],["宇迦御魂大神","あわせまつられる食物の神"],["お伊勢参りの旅人","浜参宮で身を清めた人びと"]],"deep":["夫婦岩の大注連縄は5本の縄を張ったもので、年3回張り替えられます。張り替え神事では、多くの人が岩に渡した縄を一斉に引きます。","夏至の前後（5〜7月ごろ）は夫婦岩の間から日の出を拝める季節として知られ、冬には満月が岩の間から昇るのが見られる時期もあります。","浜参宮は伊勢参りの正式な «手順» とされ、二見の旅館街は参宮客でにぎわいました。","蛙は、猿田彦大神の使いとされる理由ははっきりしませんが、境内には献納された蛙の像が数多く並びます。","興玉神石は、古くからの伝承で、海中に沈んだ岩として拝まれています。","二見の名は、倭姫命がこの浜の美しさを «二度見返した» ことに由来するという伝承があります。地名の由来の一説として語られてきたもので、確かな根拠はありません。","江戸時代の浮世絵にも二見浦の夫婦岩はたびたび描かれ、伊勢参りの名所として全国に知られていました。"],"look":["夫婦岩と大注連縄","境内にずらりと並ぶ蛙の像","天の岩屋（境内の岩窟）","二見浦の海岸と旅館街","夏至のころの日の出"],"q":["お伊勢参りの前に、二見浦で身を清めることを何という？","«浜参宮（はまさんぐう）»。今は無垢塩草でおはらいを受けられます。"],"koji":[{"w":"無事かえる","m":"蛙（かえる）と «帰る» の語呂合わせ。旅の安全を願う縁起かつぎ"}],"myth":"興玉神石の存在・由来は伝承。","img":["夫婦岩","猿田彦神","二見浦","お蔭参り"],"wp":"二見興玉神社","rel":{"ev":[],"grave":[]},"ph":[["c:a/a3/Futamiokitama_jinja_Haiden.jpg",4128,3096,"二見興玉神社"],["c:c/cb/Hiroshige%2C_Futamigaura_in_Ise_Province%2C_1858.jpg",5433,8164,"夫婦岩"],["c:b/bf/Sarutahiko-Jinja_001.jpg",4288,2848,"猿田彦神"],["c:8/8a/Ando_hiroshige_miyakawanowatashi.jpg",2400,1233,"お蔭参り"]]},{"id":"24_hinjitsukan","n":"賓日館（皇族も泊まった二見の休憩所）","yomi":"ひんじつかん","cat":"近代","rank":"B","y":1887,"era":["meiji","taisho"],"sh":"国の重要文化財","ad":"伊勢市二見町茶屋","st":"JR参宮線 二見浦駅から歩いて約15分","la":34.5075,"lo":136.7835,"hook":"120畳の大広間に、折り上げ格天井。明治の皇族や政治家が海をながめて休んだ、二見浦の «迎賓館»。","lead":"明治時代、伊勢神宮をお参りする皇族や身分の高い人のための休憩・宿泊所として建てられた建物です。明治末に大きく改築され、120畳の大広間などが加わりました。戦後は旅館として使われ、いまは国の重要文化財として公開されています。","story":["明治時代、伊勢神宮には皇族や政府の高官、外国の客人も参拝に訪れるようになりました。«大切なお客さまを迎える、ふさわしい建物がほしい»。そこで伊勢の «神苑会» という団体が、1887年、二見浦の海辺にこの館を建てました。名前の «賓日» は «日（太陽）を賓（まろうど）として迎える» という意味と伝わります。","朝日の名所・二見浦にふさわしい名前です。館には皇太子時代の大正天皇など皇族が訪れ、休憩や宿泊をしたといわれます。二見浦は、当時の日本で最初期の «海水浴場» の一つでもあり、療養や保養の地として知られていました。","1911年には大規模な改築が行われ、2階に120畳もの大広間がつくられました。天井は格子を組んだ格調高い «折り上げ格天井»、舞台もそなえています。«この広間で、どんな宴が開かれたのだろう?» 窓からは、夫婦岩の方角に広がる海が見えます。","戦後、賓日館は旅館 «二見館» の一部として使われ、多くの修学旅行生や観光客が泊まりました。その後、旅館が営業を終えると建物は地元に寄贈され、保存・修理を経て一般に公開されました。2010年ごろには国の重要文化財に指定されています。","廊下を歩くと、明治・大正の職人の技が細部に見えてきます。欄間の彫刻、手すりの意匠、ゆがんだ古いガラス窓。窓の外の海を眺めながら、ここを訪れた人びとの時間に思いをはせてください。"],"tl":[["1887年","神苑会が賓客の休憩・宿泊所として建てる"],["明治〜大正","皇族などが休憩・宿泊に利用"],["1911年","大改築。2階に120畳の大広間ができる"],["戦後","旅館 «二見館» の一部として使われる"],["2000年代","地元に寄贈され、修理のうえ公開"],["2010年ごろ","国の重要文化財に指定"]],"who":[["神苑会","伊勢神宮周辺の整備を進めた団体。賓日館を建てた"],["皇族","参宮のさいに休憩・宿泊したと伝わる"],["二見館","戦後に賓日館を旅館として使った"]],"deep":["神苑会は、明治時代に伊勢神宮の周辺を整えた民間の団体で、神宮徴古館や農業館の設立にもかかわりました。","大広間は折り上げ格天井で、能舞台のような舞台がついています。明治末の和風建築の格式の高さを示す部分です。","二見浦は1882年に «海水浴場» として公認されたといわれ、日本で最初期の海水浴場とされます。賓日館の立地もそれと関係があります。","建物は1階・2階の各部屋で意匠が異なり、部屋ごとに天井や欄間を見比べるのが面白いところです。","重要文化財の指定には、附属の建物なども含まれているとされます。","戦後の旅館時代には、多くの修学旅行生がこの建物に泊まりました。国の重要文化財に «泊まった» 思い出をもつ人がたくさんいる、ちょっと珍しい文化財です。"],"look":["2階の120畳の大広間と格天井","大広間の舞台","欄間や手すりの細工","窓から見える二見浦の海","近くの二見興玉神社・旅館街"],"q":["賓日館の2階にある大広間の広さは？","約120畳。1911年の改築でつくられました。"],"myth":"名前の由来、宿泊した皇族の詳細は伝承を含む。重要文化財指定年は要確認。","img":["二見興玉神社","二見浦","重要文化財","神宮徴古館"],"wp":"賓日館","rel":{"ev":[],"grave":[]},"ph":[["c:7/7c/Hinjitsukan%2Chutami-cho%2CIse_city%2CJapan.jpg",4437,2765,"賓日館"],["c:a/a3/Futamiokitama_jinja_Haiden.jpg",4128,3096,"二見興玉神社"],["c:8/8a/Reitai_Bridge_01.jpg",1024,768,"重要文化財"],["c:d/df/Jingu-Chokokan_02.JPG",1801,1201,"神宮徴古館"]]},{"id":"24_chokokan","n":"神宮徴古館（片山東熊設計）","yomi":"じんぐうちょうこかん","cat":"近代","rank":"B","y":1909,"era":["meiji","showa"],"sh":"登録有形文化財","ad":"伊勢市神田久志本町","st":"近鉄 宇治山田駅・伊勢市駅からバスで «徴古館前» 下車すぐ","la":34.4875,"lo":136.7165,"hook":"赤坂離宮を設計した片山東熊が、伊勢の森に建てたルネサンス様式の博物館。空襲の炎をくぐりぬけた白い壁が、今も立つ。","lead":"伊勢神宮の歴史や宝物を伝える博物館で、1909年に開館しました。設計は、赤坂離宮（迎賓館）を手がけた宮廷建築家・片山東熊。空襲で内部を焼かれましたが外壁は残り、戦後に修復されて、いまも神宮の宝物を展示しています。","story":["明治時代、伊勢神宮のまわりを美しく整えようとした «神苑会» の人びとは、こう考えました。«神宮の歴史と文化を、多くの人に伝える場所をつくろう»。倉田山の森の中に建てられたのが、神宮徴古館です。«徴古» とは «昔のことを明らかにする» という意味です。","設計したのは、片山東熊。東京の赤坂離宮（いまの迎賓館）を手がけた、明治を代表する宮廷建築家です。左右対称のルネサンス風の建物は、白い外壁に大きな窓、正面にどっしりとした玄関。森の緑の中に、洋風の宮殿のような姿が浮かびます。«伊勢神宮に洋館?» ――それこそが、新しい時代の博物館の姿でした。","1945年7月、伊勢の町は空襲にあい、徴古館も焼夷弾を受けて内部が燃え、多くの展示品が失われました。けれど、石とレンガでできた外壁は焼け残りました。戦後、その外壁を生かして修復が行われ、1953年に再び開館します。","館内では、式年遷宮で奉納された神宝や装束、神宮の祭りの道具などが展示されています。20年ごとに新しくつくりかえられる神宝は、日本の伝統工芸の技を今に伝えるものです。","近くには、同じく神苑会がつくった «農業館» や、美術館もあり、倉田山の森は «神宮の文化ゾーン» になっています。白い壁の前に立ち、戦火をこえて残った建物の強さを感じてください。"],"tl":[["1891年","神苑会が農業館を開く"],["1909年","神宮徴古館が開館"],["1945年7月","空襲で内部を焼失、外壁は残る"],["1953年","修復され再開館"],["1998年","国の登録有形文化財に登録"]],"who":[["片山東熊","設計者。赤坂離宮・奈良国立博物館などを設計した宮廷建築家"],["神苑会","徴古館の建設を進めた団体"],["神宮","現在の運営者"]],"deep":["片山東熊はジョサイア・コンドルに学んだ第一期生の一人で、赤坂離宮のほか、奈良・京都の帝室博物館（現在の国立博物館）の本館も設計しました。","徴古館は日本で最も早い時期の私立博物館の一つとされます。","戦後の修復では、焼け残った外壁を生かしつつ、屋根まわりなど元とは違う形になった部分があるといわれます。","農業館は日本で最初期の産業博物館とされ、農業や水産など神宮の神饌（しんせん）に関わる資料を展示しています。","展示の中心となる式年遷宮の神宝（御装束神宝）は、遷宮ごとに700種以上がつくりかえられるといわれます。","徴古館・農業館・美術館・神宮文庫などが集まる倉田山一帯は、神宮の «学びの森» として、参拝とは別の角度から神宮を知ることができる場所です。","片山東熊は宮内省の技師として皇室関係の建物を数多く手がけ、徴古館はその作品のなかで地方に残る貴重な一例です。赤坂離宮と見比べると、同じ建築家の «くせ» が見つかるかもしれません。"],"look":["ルネサンス様式の白い外壁と正面玄関","式年遷宮の神宝・装束の展示","となりの農業館","倉田山の森と庭園"],"q":["神宮徴古館を設計し、赤坂離宮も手がけた建築家は？","片山東熊（かたやまとうくま）。明治を代表する宮廷建築家です。"],"myth":"戦後修復時の屋根などの改変の詳細は要確認。","img":["片山東熊","迎賓館赤坂離宮","式年遷宮","奈良国立博物館"],"wp":"神宮徴古館","rel":{"ev":[],"grave":[]},"ph":[["c:d/df/Jingu-Chokokan_02.JPG",1801,1201,"神宮徴古館"],["c:b/b3/Katayama-Tokuma.jpg",305,449,"片山東熊"],["c:c/c0/2019_Akasaka_Palace_02.jpg",2500,1486,"迎賓館赤坂離宮"],["c:1/1f/%E5%BC%8F%E5%B9%B4%E9%81%B7%E5%AE%AE%E8%A8%98%E5%BF%B5%E7%A5%9E%E5%AE%AE%E7%BE%8E%E8%A1%93%E9%A4%A8.jpg",1600,1200,"式年遷宮"],["c:0/0b/140927_Nara_National_Museum_Nara_Japan03bs5.jpg",5850,3900,"奈良国立博物館"]]},{"id":"24_toyomiyazaki","n":"豊宮崎文庫（外宮の神職の学問所）","yomi":"とよみやざきぶんこ","cat":"学び","rank":"B","y":1648,"era":["edo"],"sh":"国指定史跡","ad":"伊勢市岡本","st":"JR・近鉄 伊勢市駅から歩いて約15分（外宮の南）","la":34.4835,"lo":136.7035,"hook":"«神職こそ学問を» ――江戸のはじめ、外宮の神主たちが自分たちの手で開いた図書館と学校。門と土塀が、その志を今に伝える。","lead":"江戸時代のはじめ、伊勢神宮・外宮の神職たちが建てた文庫（図書館）と講堂のあとです。神道や古典だけでなく、儒学・和歌など多くの学問が学ばれ、全国から学者も訪れました。いまは門や土塀が残り、国の史跡になっています。","story":["戦国の世が終わり、江戸時代が始まったころ。伊勢神宮は長い戦乱で荒れ、神宮に伝わる古い記録や書物も、たくさん失われていました。«このままでは、神宮の学問が消えてしまう» ――そう心配したのが、外宮の神職・出口延佳（でぐちのぶよし）たちでした。","1648年、延佳らは仲間の神職たちと力を合わせ、外宮の近くの宮崎の地に文庫を建てました。本を集めて収め、講堂では講義を開きます。«神に仕える者こそ、よく学ばなければならない»。これが «豊宮崎文庫» の始まりです。","文庫には、神道の書物だけでなく、儒学、歴史、和歌、漢詩などさまざまな本が集まりました。本を寄付する人も多く、蔵書はどんどんふえていきます。«なぜこんなに多くの本が集まったのか?» それは、伊勢神宮を大切に思う全国の人びとが、学問の場を応援しようとしたからでした。","文庫には各地から学者が訪れ、講義や歌会が開かれました。伊勢の町の人びとにとっても、学びの中心だったのです。明治になって神宮のしくみが大きく変わると、文庫はその役目を終え、蔵書の多くは神宮文庫に引き継がれました。","いま跡地には、表門や土塀などが残っています。中は公開されていないことが多いので、外から門をながめ、ここに集まった人びとの熱意を想像してみてください。"],"tl":[["1648年","外宮の神職・出口延佳らが豊宮崎文庫を創設"],["江戸時代","蔵書がふえ、講義や歌会が開かれる"],["明治時代","神宮制度の改革で文庫の役目を終える"],["明治以降","蔵書の多くが神宮文庫に引き継がれる"],["昭和時代","国の史跡に指定"]],"who":[["出口延佳（度会延佳）","外宮の神職で学者。文庫の創設の中心人物"],["外宮の神職たち","費用や本を出し合って文庫を支えた"],["全国の学者・寄進者","本を寄付したり講義に訪れたりした"]],"deep":["出口延佳は «度会延佳» とも呼ばれ、伊勢神道（度会神道）を立て直し、儒学を取り入れた学者として知られます。","文庫の名 «豊宮崎» は、外宮（豊受大神宮）の «豊» と、地名の «宮崎» を合わせたものとされます。","内宮側にも同じころ «林崎文庫» という学問所がつくられ、外宮の豊宮崎、内宮の林崎と並び称されました。","神宮文庫は倉田山にある神宮の図書館で、豊宮崎・林崎両文庫の旧蔵書などを受け継ぎ、貴重な古典籍を多く所蔵しています。","跡地は私有地や管理地の中にあり、見学は外からに限られることが多いので、案内板などで確認してから訪ねましょう。","江戸時代の伊勢には «御師（おんし）» と呼ばれる神職が全国の参宮客を案内・宿泊させていました。豊宮崎文庫の学問は、御師たちが各地の人びとに神宮の歴史を語る土台にもなったと考えられます。","豊宮崎文庫は、本を集めて保存するだけでなく、講義を開いて人を育てる場でもありました。«図書館» と «学校» をかねたこの形は、江戸時代の地方の学問所の先がけの一つとして語られます。"],"look":["表門と土塀","史跡の石碑","近くの外宮（豊受大神宮）","倉田山の神宮文庫（外観）"],"q":["豊宮崎文庫を創設した外宮の神職は？","出口延佳（度会延佳）。1648年に仲間と文庫を開きました。"],"myth":"","img":["度会延佳","豊受大神宮","神宮文庫","林崎文庫"],"wp":"豊宮崎文庫","rel":{"ev":[],"grave":[]},"ph":[["c:2/27/Toyomiyazaki-bunko_01.jpg",1801,1201,"豊宮崎文庫"],["c:8/80/%E5%87%BA%E5%8F%A3%E5%BB%B6%E4%BD%B3%E9%82%B8%E8%B7%A1.jpg",3504,4672,"度会延佳"],["c:2/2c/Geku_003.jpg",3000,2000,"豊受大神宮"],["c:0/0c/Jingu-bunko_16.jpg",4608,3456,"神宮文庫"]]},{"id":"24_yamada_bugyo","n":"山田奉行所跡","yomi":"やまだぶぎょうしょあと","cat":"大名屋敷","rank":"A","y":1712,"era":["edo"],"sh":"","ad":"伊勢市御薗町上條","st":"近鉄 宮町駅などから歩いて約20分。伊勢市駅から車で約10分","la":34.4815,"lo":136.6885,"hook":"のちの «大岡越前» こと大岡忠相も、ここで奉行をつとめた。伊勢神宮を守る幕府の出先機関があった場所。","lead":"江戸幕府が伊勢に置いた «山田奉行» の役所のあとです。山田奉行は伊勢神宮の警備や遷宮の管理、伊勢・志摩の港の取りしまりなどをになう重要な役職でした。建物は残っていませんが、跡地には山田奉行所記念館があり、奉行所の様子を再現しています。","story":["江戸時代、伊勢神宮には毎年何十万人もの参拝者がおとずれました。«これほど大切な場所を、幕府がしっかり見守らなければ»。1603年ごろ、幕府は伊勢の山田に奉行を置き、神宮と町の治安を任せました。これが山田奉行です。","山田奉行の仕事は多岐にわたりました。伊勢神宮の警備、20年ごとの遷宮の監督、町の訴えを聞く裁判、そして伊勢湾や鳥羽の港を出入りする船の取りしまり。江戸と大坂を結ぶ海の道を見張る役目もあったのです。","歴代の奉行の中で、いちばん有名なのが大岡忠相です。のちに江戸町奉行として «大岡越前» の名で知られる人物で、1712年から数年間、山田奉行をつとめました。«名奉行の腕は、伊勢でみがかれたのか?» ――そう想像したくなりますね。","伊勢には、大岡忠相が山田と紀州藩領の松坂との境界争いを公平にさばいた、という話が伝わっています。紀州藩主はのちの将軍・徳川吉宗で、«この公正な裁きが吉宗の目にとまり、江戸町奉行に抜てきされた» とも語られます。ただしこの話は、後の «大岡政談» などで広まったもので、確かな史料はありません。","跡地に建つ記念館では、奉行所の建物の一部が再現され、お白洲などを見ることができます。江戸幕府が伊勢をどれほど大切にしていたか、実感できる場所です。"],"tl":[["1603年ごろ","幕府が山田奉行を置く"],["江戸時代","神宮の警備・遷宮の監督・港の取りしまりを担う"],["1712年","大岡忠相が山田奉行に着任"],["1716年ごろ","大岡忠相が江戸へ移る（翌年江戸町奉行）"],["1868年","明治維新により廃止"],["平成時代","跡地に山田奉行所記念館が開館"]],"who":[["大岡忠相","山田奉行をつとめ、のちに江戸町奉行となった «大岡越前»"],["徳川吉宗","紀州藩主からのちの8代将軍。大岡を登用した"],["歴代の山田奉行","旗本から選ばれ、神宮と伊勢の町を治めた"]],"deep":["山田奉行は遠国奉行（おんごくぶぎょう）の一つで、長崎奉行や京都町奉行などと同じく、幕府の重要地点に置かれた役職です。","奉行所は、はじめ小林（いまの伊勢市小林）にあったといわれ、のちに移転したとする説もあり、場所の変遷には諸説あります。","大岡忠相が山田奉行をつとめたのは1712〜1716年ごろで、その後、普請奉行を経て1717年に江戸町奉行となりました。","山田と松坂の境界争いの話は «大岡政談» の一つとして有名ですが、同時代の史料では確認できず、後世の創作とみられています。","奉行所は鳥羽の港の «船改め» にも関わったとされ、伊勢湾の海運を見張る役目もありました。","山田奉行は、外宮側の «山田» と内宮側の «宇治» の町どうしの争いの調停もしました。両町は参宮客をめぐってたびたび対立しており、奉行の仲裁が欠かせなかったのです。"],"look":["山田奉行所記念館（復元されたお白洲など）","奉行所跡の石碑","周辺の宮川の流れ","外宮・内宮とあわせて奉行の役割を考える"],"q":["山田奉行をつとめたあと、江戸町奉行になった有名な人物は？","大岡忠相。«大岡越前» として時代劇でもおなじみです。"],"koji":[{"w":"大岡裁き","m":"公平で思いやりのある裁判のこと。大岡忠相の名裁きの話（大岡政談）から。多くは後世の創作"}],"myth":"大岡忠相の境界争い裁きと吉宗登用の話は後世の創作とみられる。奉行所の位置の変遷は諸説。","img":["大岡忠相","徳川吉宗","大岡政談"],"wp":"山田奉行","rel":{"ev":[],"grave":[]},"ph":[["c:4/4f/Yamada_Bugyosho_Memorial.jpg",3264,2448,"山田奉行"],["c:2/26/Oooka_tadasuke.jpg",1536,2048,"大岡忠相"],["c:5/50/Tokugawa_Yoshimune.jpg",2616,2550,"徳川吉宗"]]},{"id":"24_furuichi","n":"古市（伊勢の遊郭と油屋騒動）","yomi":"ふるいち","cat":"町","rank":"B","y":1796,"era":["edo"],"sh":"","ad":"伊勢市古市町・中之町","st":"近鉄 宇治山田駅から歩いて約20分。バスで «古市口» 下車","la":34.4795,"lo":136.7195,"hook":"外宮から内宮へ向かう坂道の途中に、江戸有数の歓楽街があった。«伊勢参り、大神宮にもちょっと寄り»。","lead":"古市は、伊勢神宮の外宮と内宮のあいだの丘の上にあった町で、江戸時代には遊郭や芝居小屋が並ぶ大きな歓楽街でした。1796年に起きた刃傷事件 «油屋騒動» は歌舞伎になり、全国に知られました。いまは静かな住宅地ですが、旅館や資料館に往時の面影が残ります。","story":["江戸時代、お伊勢参りの旅人は外宮を参ったあと、坂を上って内宮へ向かいました。その途中の丘の上にあったのが古市です。«せっかくの旅だ、少し楽しんでいこう» ――旅人たちは古市の町に足をとめ、にぎやかな夜を過ごしました。","最盛期には、大きな妓楼が何十軒も並び、たくさんの遊女がいたといわれます。有名なのは «伊勢音頭»。妓楼の座敷で、あでやかな衣装の女性たちが列になって踊る «総踊り» は、古市の名物でした。江戸の吉原、京の島原と並べて語られることもあったほどです。","1796年の夏、その古市の妓楼 «油屋» で事件が起きました。宇治の医者・孫福斎（まごふくいつき）が、なじみの遊女・お紺をめぐるいざこざから刀をふるい、何人もの人を死傷させたのです。斎はのちに自ら命を絶ちました。«恋のもつれか、それとも…?» 事件はすぐに歌舞伎『伊勢音頭恋寝刃（いせおんどこいのねたば）』になり、大当たりしました。","華やかな町の裏には、貧しさなどから遊女として働かされた女性たちの、つらい暮らしがありました。明治以降、古市はしだいにさびれ、戦争や時代の変化の中で遊郭はなくなっていきます。","いまも古市には、江戸時代から続く旅館 «麻吉» の、崖にしがみつくような木造の建物が残り、資料館では当時の町の様子を知ることができます。事件で亡くなった人びと、ここで生きた女性たちに思いを寄せながら歩きたい町です。"],"tl":[["江戸時代前期","参宮街道ぞいに古市の町が発展する"],["江戸時代中期","妓楼・芝居小屋が並ぶ一大歓楽街となる"],["1796年","油屋騒動（孫福斎による刃傷事件）"],["1796年","歌舞伎『伊勢音頭恋寝刃』が上演される"],["明治以降","しだいにさびれ、遊郭はなくなっていく"]],"who":[["孫福斎","宇治の医者。油屋騒動を起こした"],["お紺","油屋の遊女。事件の中心人物として語られる"],["近松徳三","歌舞伎『伊勢音頭恋寝刃』の作者"],["古市の遊女たち","伊勢音頭を踊り、町を支えた女性たち"]],"deep":["『伊勢音頭恋寝刃』は事件から間もなく大坂で上演され、主人公の名は «福岡貢» に変えられています。事件と芝居の内容は同じではありません。","古市の妓楼の座敷で踊られた «伊勢音頭» は、参宮客のおみやげ話として全国に広まり、各地の «伊勢音頭» のもとになったといわれます。","近くの大林寺には、お紺と斎の «比翼塚» があり、事件をしのぶ人がお参りします。","麻吉旅館の建物は国の登録有形文化財で、斜面に沿って何層にも重なる木造建築が見どころです（宿泊施設なので見学は外観から）。","«伊勢参り、大神宮にもちょっと寄り» という川柳は、古市のにぎわいを皮肉ったものとしてよく引かれます。"],"look":["麻吉旅館の木造の外観","伊勢古市参宮街道資料館","大林寺のお紺・斎の比翼塚","参宮街道の坂道","長峯神社など町の寺社"],"q":["油屋騒動をもとにつくられた歌舞伎の題名は？","『伊勢音頭恋寝刃（いせおんどこいのねたば）』。事件からまもなく上演されました。"],"koji":[{"w":"伊勢参り、大神宮にもちょっと寄り","m":"伊勢参りなのに遊びが目的で、神宮はついでという皮肉。古市のにぎわいを表した川柳"}],"myth":"事件の動機や死傷者数は資料により異なる。妓楼・遊女の数は «いわれる» 程度。","img":["伊勢音頭恋寝刃","伊勢音頭","お蔭参り","麻吉旅館"],"wp":"古市 (伊勢市)","rel":{"ev":[],"grave":[]},"ph":[["c:3/3b/Ise-ondo_Sadahide.jpg",2000,1031,"伊勢音頭"],["c:8/8a/Ando_hiroshige_miyakawanowatashi.jpg",2400,1233,"お蔭参り"]]},{"id":"24_kongoshoji","n":"朝熊山 金剛證寺","yomi":"あさまやまこんごうしょうじ","cat":"寺社","rank":"A","y":1392,"era":["heian","muromachi","edo"],"sh":"国の重要文化財（本堂）・国指定史跡（経塚群）","ad":"伊勢市朝熊町岳","st":"伊勢志摩スカイラインで車が便利。休日などにバスが運行される場合あり","la":34.4615,"lo":136.7855,"hook":"«お伊勢参らば朝熊をかけよ、朝熊かけねば片参り»。伊勢神宮の鬼門を守る、山の上の禅寺。","lead":"伊勢市と鳥羽市の境にそびえる朝熊山（あさまやま）の山頂近くにある臨済宗のお寺です。伊勢神宮の «鬼門（北東）» を守るお寺とされ、江戸時代には «朝熊にも参らなければ片参り» と歌われました。平安時代の経塚からは国宝の出土品も見つかっています。","story":["伊勢神宮の東北の方角に、ひときわ高い山があります。標高約555mの朝熊ヶ岳。その山頂近くに、金剛證寺はあります。寺の言い伝えでは、6世紀に開かれ、平安時代のはじめに弘法大師空海が堂を建てて栄えたとされます。","江戸時代、お伊勢参りの旅人たちは、こんな歌を口ずさみました。«お伊勢参らば朝熊をかけよ、朝熊かけねば片参り»。伊勢神宮にお参りしたら、朝熊山にも登らないと «片参り（半分だけのお参り）» になってしまう、というのです。«なぜお寺にまで?» ――それは、金剛證寺が伊勢神宮の鬼門を守る寺と考えられていたからでした。","本尊は福や知恵をさずける虚空蔵菩薩。室町時代に禅僧の東岳文昱（とうがくぶんいく）が寺を立て直し、臨済宗のお寺になりました。いまの本堂 «摩尼殿（まにでん）» は江戸時代のはじめに建てられたもので、国の重要文化財です。","寺の奥へ進むと、ふしぎな光景が広がります。高さ数メートルもある木の卒塔婆（そとば）が、ずらりと林のように立ち並んでいるのです。これは亡くなった人をしのんで家族が立てたもの。伊勢・志摩の人びとは «死者の魂は朝熊山に行く» と考え、ここでとむらってきました。","山頂近くの経ヶ峰（きょうがみね）には、平安時代の人びとがお経を埋めた «経塚» があり、国宝の出土品が見つかっています。晴れた日には伊勢湾の向こうに富士山が見えることも。神と仏と祖先を、一度に感じられる山です。"],"tl":[["6世紀","欽明天皇の代に開かれたと伝わる"],["825年","空海が堂を建て中興したと伝わる"],["1159年","経ヶ峰に経塚が営まれる（出土した経筒の銘による）"],["1392年","東岳文昱が再興し、臨済宗の寺となる"],["1609年","本堂（摩尼殿）が建てられる"],["昭和時代","経ヶ峰の経塚出土品が国宝に指定"]],"who":[["空海（弘法大師）","堂を建てて寺を興したと伝わる"],["東岳文昱","室町時代に寺を再興し、臨済宗の寺とした禅僧"],["お伊勢参りの旅人","«片参り» を避けるため朝熊山にも登った"]],"deep":["朝熊山経ヶ峰経塚群は国の史跡で、平安時代末期の経筒・仏像・鏡などが出土し、«伊勢朝熊山経ヶ峯経塚出土品» として国宝に指定されています。","出土した経筒には平治元年（1159年）などの年号が刻まれ、平安末の末法思想の広まりを示す資料とされます。","本堂の摩尼殿は1609年の建築とされ、国の重要文化財。慶長期の仏堂の姿をよく伝えます。","奥之院の巨大な卒塔婆は、亡くなった人の供養のため遺族が立てるもので、伊勢志摩に独特の «岳参り（たけまいり）» の風習と結びついています。","寺の鎮守として «雨宝童子（うほうどうじ）» がまつられ、天照大神が16歳の姿で現れたものとされる神仏習合の像として知られます。"],"look":["本堂 摩尼殿（重要文化財）","連間の池と太鼓橋","奥之院の卒塔婆の林","経ヶ峰（経塚群の史跡）","山上から見る伊勢湾と富士山（条件がよいとき）"],"q":["«朝熊かけねば○○参り»。○○に入ることばは？","«片（かた）»。伊勢神宮と朝熊山の両方に参ってこそ本当のお参り、という意味です。"],"koji":[{"w":"お伊勢参らば朝熊をかけよ、朝熊かけねば片参り","m":"伊勢参りをしたら、朝熊山の金剛證寺にも参らなければ不十分だという伊勢音頭の一節"}],"myth":"開創（欽明天皇の代）と空海の中興は寺伝。","img":["朝熊山","虚空蔵菩薩","経塚","伊勢志摩スカイライン"],"wp":"金剛證寺","rel":{"ev":[],"grave":[]},"ph":[["c:1/1b/Kongoshoji%28Mie%29_08.JPG",708,531,"金剛證寺"],["c:6/65/Mount_Asama_%28Ise_and_Toba%29.jpg",3284,2189,"朝熊山"],["c:5/54/Kok%C5%ABz%C5%8D_Bosatsu.jpg",8278,12797,"虚空蔵菩薩"],["c:8/8d/Katsuragi28shuku_dai15ban.jpg",2448,3264,"経塚"]]},{"id":"24_ozaki_yukio","n":"尾崎咢堂記念館（憲政の神様）","yomi":"おざきがくどうきねんかん","cat":"近代","rank":"B","y":1890,"era":["meiji","taisho","showa"],"sh":"","ad":"伊勢市川端町","st":"JR・近鉄 伊勢市駅から歩いて約20分","la":34.4955,"lo":136.6955,"hook":"衆議院議員を60年以上、25回連続当選。ワシントンの桜を贈った «憲政の神様» は、伊勢で少年時代を過ごした。","lead":"明治から昭和まで衆議院議員をつとめ、«憲政の神様» と呼ばれた尾崎行雄（号は咢堂）の記念館です。尾崎は相模国（神奈川県）の生まれですが、少年時代を伊勢で過ごし、のちに三重県から選挙に出続けました。記念館では、その生涯と議会政治への思いを紹介しています。","story":["1858年、尾崎行雄は相模国の津久井（いまの神奈川県相模原市）に生まれました。明治のはじめ、父が役人として伊勢に移ったため、少年行雄も伊勢へ。宮川のほとりの町で学び、やがて東京へ出て福沢諭吉の慶應義塾で学びます。","1890年、日本で初めての衆議院議員選挙が行われました。三重県から立候補した尾崎は当選し、国会へ。それから1953年の選挙で落選するまで、なんと25回連続で当選し、60年以上も議員を続けました。«国の政治は、国民の選んだ議会が決めるべきだ» ――尾崎はこの考えを生涯つらぬきました。","大正時代のはじめ、政治を思いのままに動かそうとする内閣に、尾崎は国会で厳しく迫りました。«玉座を以て胸壁となし、詔勅を以て弾丸に代えて政敵を倒さんとするものではないか» ――天皇の権威を盾にしていると批判したこの演説は、民衆の支持を集め、内閣は倒れます。これが «第一次護憲運動» です。","尾崎は東京市長もつとめ、1912年にはアメリカの首都ワシントンに桜の苗木を贈りました。いまも毎年春、ポトマック河畔の桜は多くの人を楽しませています。晩年、戦争に反対して不敬罪で起訴されたこともありましたが、信念を曲げませんでした。","記念館は、尾崎ゆかりの地・宮川に近い町に建てられています。«人生の本舞台は常に将来に在り» ――90歳をこえても前を向き続けた尾崎の言葉を、ここで味わってみてください。"],"tl":[["1858年","相模国津久井に生まれる"],["明治初め","父の赴任で伊勢に移り、少年時代を過ごす"],["1890年","第1回衆議院議員総選挙で当選"],["1903〜1912年","東京市長をつとめる"],["1912年","ワシントンに桜の苗木を贈る"],["1913年","桂内閣を弾劾する演説。第一次護憲運動"],["1953年","総選挙で落選し、議員生活を終える"],["1954年","没する"],["1959年","尾崎咢堂記念館が開館"]],"who":[["尾崎行雄（咢堂）","衆議院議員。«憲政の神様»"],["犬養毅","ともに護憲運動を率いた政治家。«憲政の神様» と並び称された"],["桂太郎","尾崎が演説で批判した内閣の首相"],["福沢諭吉","尾崎が学んだ慶應義塾の創立者"]],"deep":["号の «咢堂（がくどう）» は、はじめ «学堂» と名乗り、のちに «愕堂»、さらに «咢堂» と改めたといわれます。","連続25回当選・議員在職63年は、衆議院の歴史でも例のない記録として知られます。","1909年に贈った最初の桜は病害虫が見つかり焼却され、1912年にあらためて約3000本が贈られました。これがワシントンの桜のもとです。","1942年の選挙演説をめぐって不敬罪で起訴されましたが、のちに大審院で無罪となりました。","東京・憲政記念館（国会前）にも尾崎の記念展示があり、相模原市には «尾崎咢堂記念館» があります。三重と神奈川の二つの記念館を比べるのも面白いです。"],"look":["尾崎の遺品や書の展示","ワシントンの桜に関する資料","記念館の庭","近くの宮川の堤"],"q":["尾崎行雄が衆議院議員選挙で連続当選した回数は？","25回。第1回の1890年から、1953年に落選するまで当選を続けました。"],"koji":[{"w":"人生の本舞台は常に将来に在り","m":"尾崎行雄の言葉。いくつになっても、いちばん大事な舞台はこれからだ、という意味"}],"myth":"伊勢へ移った年や号の変遷の細部は諸説。","img":["護憲運動","ポトマック河畔の桜","犬養毅"],"wp":"尾崎行雄","rel":{"ev":[],"grave":[]},"ph":[["c:3/3e/Yukio_Ozaki.jpg",1024,1328,"尾崎行雄"],["c:c/c3/Inukai_Tsuyoshi.jpg",1024,1310,"犬養毅"]]},{"id":"24_akeno","n":"明野陸軍飛行学校跡","yomi":"あけのりくぐんひこうがっこうあと","cat":"昭和","rank":"B","y":1924,"era":["taisho","showa"],"sh":"","ad":"伊勢市小俣町明野","st":"近鉄明野駅から歩いて約15分（駐屯地の中は、ふだんは自由に入れない）","la":34.532,"lo":136.672,"hook":"伊勢神宮のすぐ近くの原っぱで、戦闘機乗りたちが空の戦い方を学んでいた。いまはヘリコプターの学校が、その空を受けついでいる。","lead":"大正時代の終わり、伊勢市の明野ヶ原に陸軍の飛行学校がつくられ、戦闘機の操縦や空中射撃を教えました。戦争が終わって学校はなくなりましたが、同じ場所に今は陸上自衛隊の明野駐屯地があり、ヘリコプターのパイロットが育てられています。","story":["大正時代の終わりごろ、飛行機はまだ «新しい乗り物» でした。第一次世界大戦で飛行機が戦いの主役になりはじめたのを見て、日本の陸軍も «空で戦える兵士» を育てる学校を急いでつくります。そのひとつが、伊勢平野に広がる明野ヶ原に開かれた明野陸軍飛行学校でした。平らで広い土地は、滑走路にぴったりだったのです。","ここで教えられたのは、主に戦闘機の操縦と、空を飛びながら的を撃つ «射撃» の技術でした。教官に «もっと低く、もっと速く» としかられながら、若い操縦者たちは何度も空へ飛び立ちました。明野は «戦闘機乗りのふるさと» とよばれ、全国の部隊から腕をみがきに人が集まったといわれます。","なぜ伊勢だったのでしょう? 広い平地があり、海にも近く、洋上で射撃の練習ができたことが理由の一つと考えられています。すぐ近くには伊勢神宮があり、訓練の合間に参拝した若者も多かったことでしょう。空を見上げる町の人たちにとって、飛行機の爆音はめずらしい «新しい時代の音» でした。","しかし昭和に入って戦争が長引くと、学校の役割も変わります。教えるだけでなく、実際の戦いに出る部隊としての性格が強まり、名前も «教導飛行師団» などへと変わっていきました。戦争の終わりが近づくと、ここで学んだ若者の中からも、帰らぬ出撃に向かった人がいました。その一人ひとりに家族がいたことを、忘れずにいたいものです。","1945年の敗戦で学校はなくなりました。やがて1950年代に、同じ土地に陸上自衛隊の航空学校が置かれ、今はヘリコプターの操縦士を育てています。«飛ぶことを教える場所» という役目だけは、100年近くたった今も続いているのです。基地の一般公開の日には、空を舞うヘリを見に多くの人がやってきます。"],"tl":[["1924年","明野ヶ原に明野陸軍飛行学校が開かれる"],["1930年代","戦闘機の操縦・射撃教育の中心として拡大"],["1944年ごろ","戦局の悪化で、実戦部隊（教導飛行師団）へと改編"],["1945年","敗戦により学校が廃止される"],["1955年ごろ","陸上自衛隊の航空学校が明野に置かれる"],["現在","陸上自衛隊明野駐屯地としてヘリ操縦士を育成"]],"who":[["陸軍の戦闘機操縦者たち","ここで操縦と射撃を学び、各地の部隊へ散っていった"],["教官たち","実戦経験をもとに空中戦の技術を伝えた"],["陸上自衛隊の隊員","戦後、同じ土地でヘリコプターの操縦を学ぶ"]],"deep":["«明野» は日本の陸軍戦闘機部隊にとって技術の本山のような存在で、新しい戦い方の研究もここで行われたといわれます。","学校の名前や組織は時期によって何度も変わりました。飛行学校から «教導飛行師団» へ、という流れは、戦争末期に教育機関まで前線に組み込まれていった様子を映しています。","戦後の陸上自衛隊航空学校は、戦前の学校とは組織として別のものです。土地が受けつがれたという点で «つながり» があります。","平地の広さは、飛行場の立地を決める大事な条件でした。三重県内には、ほかにも鈴鹿・香良洲などに海軍や陸軍の航空関係の施設がありました。","駐屯地の中は、ふだんは一般の人が自由に入れません。見学できるのはイベントや公開日などに限られるので、事前に確認しましょう。","近くには伊勢神宮外宮・内宮があり、神宮参拝と «近代の伊勢» をあわせて学ぶと、同じ町の別の顔が見えてきます。"],"look":["駐屯地の外から見える広い飛行場の風景","一般公開日に展示されるヘリコプター","近鉄明野駅から駐屯地までの、平らな明野ヶ原の地形"],"q":["明野陸軍飛行学校で主に教えられていたのは、どんな飛行機の操縦？","戦闘機です。操縦とともに、空を飛びながら撃つ «射撃» の技術も教えていました。"],"koji":[],"myth":"学校の改編の年や細かな組織名は資料により表記がゆれる。","img":["明野駐屯地","伊勢市"],"wp":"明野陸軍飛行学校","rel":{"ev":[],"grave":[]},"ph":[["c:f/f0/JGSDF_Camp_Akeno_Main_Gate_01.jpg",2592,1944,"明野駐屯地"],["c:5/56/Uji-bashi_03.JPG",768,576,"伊勢市"]]},{"id":"24_mikimoto","n":"ミキモト真珠島（真珠養殖の発祥）","yomi":"みきもとしんじゅしま","cat":"産業","rank":"S","y":1893,"era":["meiji"],"sh":"","ad":"鳥羽市鳥羽1丁目","st":"JR・近鉄鳥羽駅から歩いて約5分（橋を渡って島へ）","la":34.4816,"lo":136.8465,"hook":"«海の宝石» は偶然にしか見つからないもの――その常識を、鳥羽のうどん屋の息子がひっくり返した。","lead":"真珠は昔、貝の中にたまたまできた物を探すしかない、とても珍しい宝物でした。鳥羽に生まれた御木本幸吉は、何年も失敗をくり返したすえ、1893年に貝に真珠をつくらせる «養殖» に成功しました。その実験の舞台になった島が、いまのミキモト真珠島です。","story":["御木本幸吉は1858年、鳥羽のうどん屋の長男として生まれました。子どものころから商売上手で、青物の行商をしたり、横浜まで海産物の売りこみに出かけたりしたといいます。そこで彼が目にしたのが、真珠がとても高い値段で取り引きされていることでした。«伊勢志摩の海には真珠貝がいる。なのに、なぜ真珠は少ないのだろう?»","当時、アコヤ貝は真珠をとるためにとりつくされ、数が減っていました。幸吉は «貝がいなくなれば真珠もなくなる。ならば、真珠を人の手でつくらせればいい» と考えます。貝の中に小さな核を入れて、そのまわりに真珠の層を巻かせる――言葉にすれば簡単ですが、貝は死んでしまったり、核を吐き出したり。実験は失敗の連続でした。","さらに «赤潮» が海をおそい、育てていた貝が全滅したこともありました。借金はふくらみ、まわりからは笑われます。それでも、妻のうめが支え、研究者の助言も受けながら、実験を続けました。そして1893年、相島（おじま）とよばれた小さな島で、ついに貝の中に半円形の真珠ができているのが見つかったのです。","その後、幸吉は半円の真珠だけでなく、まん丸な «真円真珠» の養殖にも取り組みます。真円真珠の技術には、ほかの研究者たちも深くかかわっていて、だれが最初かについては議論があります。それでも、養殖真珠を世界に売りこみ、«MIKIMOTO» の名を広めたのは、まちがいなく幸吉の力でした。","戦後の1951年、相島は «ミキモト真珠島» として一般に公開されました。島には真珠の歴史を伝える博物館や、幸吉の生涯を紹介する記念館があり、白い磯着の海女が海にもぐる実演も見られます。«世界中の女性の首を真珠でしめてみせる» ――そんな大きな夢を語ったと伝わる男の島は、今も鳥羽湾に浮かんでいます。"],"tl":[["1858年","御木本幸吉、鳥羽のうどん屋に生まれる"],["1888年ごろ","神明浦などで真珠貝の養殖に取り組みはじめる"],["1893年","相島で半円真珠の養殖に成功"],["1896年","半円真珠の養殖法で特許を得る"],["1905年ごろ","真円真珠ができはじめる"],["1951年","相島がミキモト真珠島として公開される"],["1954年","幸吉、96歳で亡くなる"]],"who":[["御木本幸吉","真珠養殖を事業として成功させた «真珠王»"],["御木本うめ","幸吉の妻。苦しい実験の時代を支えた"],["見瀬辰平・西川藤吉","真円真珠の技術開発にかかわった研究者たち"],["海女たち","アコヤ貝の世話や採取を担った"]],"deep":["真珠は貝が体に入った異物を «真珠層» で包んでできます。養殖は、この仕組みを利用して核と外套膜の小片を人の手で入れる技術です。","真円真珠の技術は、見瀬辰平・西川藤吉らも開発しており、特許をめぐる経緯は複雑です。«発明者» を一人に決められない点が歴史のおもしろさです。","赤潮による大被害は明治の終わりごろにも起き、養殖場を英虞湾など各地に分散させるきっかけになったといわれます。","幸吉は海外の博覧会に積極的に出品し、養殖真珠を «ニセモノではない本物の真珠» として認めさせる努力を続けました。欧州では天然か養殖かをめぐる論争も起きました。","エジソンと会見したとき、エジソンが養殖真珠を «世界の驚異» とほめたという話が伝わります。","島の真珠博物館には、真珠で作られた工芸品も展示されています。明治の博覧会以来、真珠は «日本の技» を見せる品でもありました。"],"look":["御木本幸吉記念館（生涯と失敗の記録）","真珠博物館の養殖工程の展示","海女の実演（時間は要確認）","島から見る鳥羽湾と、幸吉の銅像"],"q":["御木本幸吉が最初に養殖に成功した真珠の形は？","半円形の真珠です。まん丸な «真円真珠» はその後、ほかの研究者の技術もあってできるようになりました。"],"koji":[],"myth":"«首をしめてみせる» の言葉やエジソンとの会話は伝わる逸話。真円真珠の «最初の発明者» は諸説。","img":["御木本幸吉","真珠","アコヤガイ"],"wp":"ミキモト真珠島","rel":{"ev":[],"grave":[]},"ph":[["c:6/6b/Mikimoto_Pearl_Island_from_Toba_Auqarium.jpg",3264,2448,"ミキモト真珠島"],["c:c/cc/MIKIMOTO_Kokichi.jpg",1024,1480,"御木本幸吉"],["c:5/5e/Various_pearls.jpg",600,600,"真珠"],["c:d/df/Akoya-gai_from_Ago_Bay.jpg",1280,960,"アコヤガイ"]]},{"id":"24_kamishima","n":"神島（「潮騒」の島と八代神社）","yomi":"かみしま","cat":"島","rank":"B","y":1954,"era":["heian","showa"],"sh":"","ad":"鳥羽市神島町","st":"鳥羽マリンターミナルから市営定期船で約40分","la":34.547,"lo":136.987,"hook":"漁師の若者と海女の少女の恋――三島由紀夫が小説の舞台に選んだ «歌島» は、伊勢湾の入り口に浮かぶこの小さな島だった。","lead":"神島は伊勢湾の入り口にある周囲4kmほどの島です。三島由紀夫の小説『潮騒』の舞台として知られ、島の中には物語に出てくる灯台や神社の石段が今もあります。昔から海の神をまつる八代神社があり、古い鏡などの神宝が伝わっています。","story":["1953年、作家の三島由紀夫はこの島をたずね、しばらく過ごしながら島の暮らしを見て回りました。船が着く港、坂と石段ばかりの集落、断崖の上の灯台。やがて書き上げられた小説『潮騒』では、島は «歌島» という名前で登場します。若い漁師の新治と、海女の初江の、まっすぐな恋の物語です。","«その火を飛び越して来い» ――嵐の日、焚き火をはさんで向き合う二人の場面は、小説の中でもっとも有名なシーンです。その舞台とされるのが、島の高台にある戦時中の «監的哨跡»。かつて近くの伊良湖で試射された大砲の弾が、どこに落ちるかを見張るための建物でした。","島の港から200段ほどの石段を上ると、八代神社に着きます。海の神・綿津見命をまつる神社で、島の人は漁の安全を祈ってきました。この神社には古い鏡など多くの神宝が伝わっていて、国の重要文化財に指定されたものもあります。なぜ小さな島にこれほどの宝が? 伊勢湾を行き来する船の «目印の島» として、昔から大切にされてきたからだと考えられています。","元日の夜明けには、«ゲーター祭» という不思議な行事があります。グミの木で作った «アワ» という大きな輪を、島の男たちが竹で突き上げて落とすのです。輪は太陽を表すともいわれ、1年の平和と豊漁を願う祭りとして受けつがれています。意味にはいくつもの説があって、そのなぞもまた島の魅力です。","『潮騒』は何度も映画になり、島には撮影のたびに多くの人が訪れました。それでも島の暮らしは、今も漁業を中心に続いています。定期船をおりて、石段を上り、灯台まで歩く一周コースは2時間ほど。小説の一場面を思い浮かべながら、潮風の中を歩いてみてください。"],"tl":[["平安時代以前","海の神をまつる八代神社が島の信仰の中心になる（創建は不詳）"],["1910年","神島灯台が初めて点灯する"],["1929年ごろ","陸軍の監的哨が建てられる"],["1953年","三島由紀夫が取材のため島に滞在"],["1954年","小説『潮騒』が刊行され、同年に最初の映画化"],["現在","元日のゲーター祭が続き、『潮騒』ゆかりの地を歩く人が訪れる"]],"who":[["三島由紀夫","島に滞在し、小説『潮騒』を書いた作家"],["新治と初江","『潮騒』の主人公（物語上の人物）"],["島の漁師と海女","八代神社をまつり、ゲーター祭を受けつぐ人々"]],"deep":["八代神社の神宝には、古墳時代から中世にわたる鏡などがあり、海上交通の祭祀の場だった可能性が指摘されています。","監的哨は、対岸の渥美半島・伊良湖にあった陸軍の試験場で試射された砲弾の着弾を観測する施設だったといわれます。","ゲーター祭の «アワ» は太陽を表すという説、«日輪を落として天下を平らにする» 意味という説などがあり、由来ははっきりしません。","『潮騒』は古代ギリシャの恋物語『ダフニスとクロエ』に着想を得たといわれ、南の島の素朴な恋を日本の島に置きかえています。","映画化は1954年を最初に何度も行われ、吉永小百合・山口百恵らが初江を演じました。","島は伊勢湾の入り口 «伊良湖水道» に面していて、潮の流れが速い海の難所でした。灯台が早くから置かれた理由もそこにあります。"],"look":["八代神社へ続く石段と、そこから見る伊勢湾","神島灯台と伊良湖水道の眺め","『潮騒』の焚き火の場面の舞台とされる監的哨跡","港と坂道の集落の風景"],"q":["『潮騒』の中で、神島はなんという名前で登場する？","«歌島（うたじま）» です。"],"koji":[],"myth":"八代神社の創建年は不詳。ゲーター祭の由来は諸説。監的哨が焚き火の場面の舞台とするのは一般的な見方。","img":["潮騒 (小説)","三島由紀夫","伊良湖水道"],"wp":"神島 (三重県)","rel":{"ev":[],"grave":[]},"ph":[["c:2/24/Kami-island.JPG",1197,856,"神島 (三重県)"],["c:d/d4/2016-08-05_Kami-shima_Island%2CKarst_topography_%E3%82%AB%E3%83%AB%E3%82%B9%E3%83%88%E5%9C%B0%E5%BD%A2_DSCF6494.jpg",2304,1536,"潮騒 (小説)"],["c:c/cf/Yukio_Mishima%2C_1955_%28cropped_850%C3%97950_px%29.jpg",850,950,"三島由紀夫"]]},{"id":"24_izawanomiya","n":"伊雑宮（志摩国一宮・御田植祭）","yomi":"いざわのみや","cat":"寺社","rank":"A","y":927,"era":["heian","edo"],"sh":"","ad":"志摩市磯部町上之郷","st":"近鉄上之郷駅から歩いてすぐ（約3分）","la":34.386,"lo":136.83,"hook":"1羽の鶴がくわえてきた稲穂――伊勢神宮の «遠い宮» には、お米のはじまりの物語が眠っている。","lead":"伊雑宮は伊勢神宮・内宮の別宮で、内宮から南へ約20km、志摩の地にあります。天照大御神の御魂をまつり、«遥宮（とおのみや）» ともよばれてきました。毎年6月には、日本三大田植祭の一つとされる «御田植祭» が行われます。","story":["伊雑宮には、こんな言い伝えがあります。昔、倭姫命が天照大御神のために食べ物をささげる土地を探して志摩を訪れたとき、1羽の鶴が鳴きながら飛んできました。見ると、鶴がくわえていたのは、みごとに実った稲穂。«これこそ神にささげるお米の地だ» と、倭姫命はこの地に宮を建てたといわれます。","だからこそ、伊雑宮の祭りでいちばん大切なのは «田植え» です。6月24日の御田植祭では、まず «竹取神事» が行われます。田んぼの中に立てた大きな竹を、男たちが泥だらけになって奪い合い、倒すのです。竹につけられた «ごんばうちわ» の破片は、漁の守りとして持ち帰られてきました。","どろんこの戦いが終わると、田んぼは急に静かになります。早乙女とよばれる女性たちが苗を植え、そのそばで太鼓や笛、ささらの音が鳴り響きます。«田楽» とよばれる古い芸能です。この祭りは国の重要無形民俗文化財に指定されていて、見物人は田のまわりをぐるりと囲んで見守ります。","伊雑宮は «志摩国の一宮» ともされてきました。一宮とはその国でいちばん格の高い神社のこと。ただし、志摩国の一宮は鳥羽の伊射波神社だという説もあり、昔から «ふたつの一宮» があるといわれています。どちらも海と米、つまり志摩の暮らしを支える神さまにかかわっているのが興味深いところです。","江戸時代の初めには、伊雑宮の関係者が «こちらこそ本当の天照大御神の宮だ» と訴え、大きな騒ぎになったことがありました。結局、その主張は退けられましたが、それほど伊雑宮が特別な宮と考えられていた証拠ともいえます。深い森に囲まれた境内を歩くと、内宮とはまた違う、ひっそりとした空気を感じられます。"],"tl":[["伝承の時代","倭姫命が鶴の稲穂を見てこの地に宮を定めたと伝わる"],["927年","『延喜式』に皇大神宮の別宮として記される"],["江戸時代前期","伊雑宮を本宮とする主張をめぐり、大きな争いが起きる"],["1990年","磯部の御神田（御田植祭）が国の重要無形民俗文化財に指定"],["現在","内宮と同じく、20年ごとに社殿が建て替えられる"]],"who":[["倭姫命","伝承で伊雑宮を定めたとされる皇女"],["天照大御神","伊雑宮にその御魂がまつられる神"],["磯部の人々","御田植祭を受けつぎ、竹取神事で竹を奪い合う"]],"deep":["伊雑宮は内宮の «別宮» 10社のうちの一つで、内宮から離れた場所にある別宮の代表例です。","«遥宮» という呼び名は、神宮から遠く離れた宮であることを表しています。瀧原宮も同じくそうよばれます。","御田植祭は、千葉県香取神宮・大阪府住吉大社の田植祭と並んで «日本三大田植祭» といわれます。","江戸時代前期の争いは、伊雑宮を天照大御神の本来の宮とする文書が出回ったことが背景にあり、関係者が処罰されたと伝わります。","境内には «巾着楠» とよばれる、根元がふくらんだ大きな楠があり、参拝者に親しまれています。","社殿は内宮・外宮と同じく、20年に一度の式年遷宮で建て替えられます。"],"look":["森に囲まれた社殿と、神明造の屋根","境内の «巾着楠»","境内の外にある御料田（御田植祭の舞台）","近鉄上之郷駅からの参道"],"q":["伊雑宮の伝説で、稲穂をくわえて飛んできた鳥は？","鶴です。倭姫命がこの稲穂を見て、この地を神にささげる米の地に定めたと伝わります。"],"koji":[],"myth":"鶴の稲穂の話や倭姫命による創建は伝承。志摩国一宮は伊射波神社とする説もある。","img":["皇大神宮","倭姫命","伊勢神宮"],"wp":"伊雑宮","rel":{"ev":[],"grave":[]},"ph":[["c:f/fa/Izawa-no-miya_07.jpg",3000,2000,"伊雑宮"],["c:8/8d/Naiku_04.jpg",3000,2000,"皇大神宮"],["c:7/7d/PrincessYamatoHime.jpg",875,1000,"倭姫命"],["c:e/e3/Naiku_001.jpg",4288,2848,"伊勢神宮"]]},{"id":"24_izawa_jinja","n":"伊射波神社（加布良古さん）","yomi":"いざわじんじゃ","cat":"寺社","rank":"B","y":927,"era":["heian"],"sh":"","ad":"鳥羽市安楽島町","st":"鳥羽駅から車で安楽島方面へ約15分、駐車場から山道を歩いて約20〜30分","la":34.505,"lo":136.884,"hook":"車の道は途中までしかない。森の山道を歩いた先、海に突き出た岬の上に、志摩のもう一つの «一宮» が待っている。","lead":"伊射波神社は、鳥羽市の加布良古崎（かぶらこざき）の森の中にある古い神社で、地元では «加布良古さん» と親しまれています。平安時代の『延喜式』に名前がのる神社で、志摩国の一宮ともいわれます。海の安全と縁結びの神さまとして信仰されています。","story":["伊射波神社に行くのは、ちょっとした冒険です。車で安楽島の集落をぬけ、駐車場から先は森の中の細い山道。木の根をまたぎ、ときどき木々のすき間から海を見ながら歩くと、やがて鳥居が見えてきます。昔の人は船で岬の下の浜に着き、そこから石段を上ってお参りしていたといわれます。","«なぜこんな不便な場所に?» と思うかもしれません。でも、ここは伊勢湾・鳥羽湾を行き来する船から見える岬の先。海で働く人にとって、岬の上の神さまは «海の道の守り神» でした。船が岬の前を通るとき、帆を下げて頭を下げたとも伝わります。","まつられているのは稚日女尊（わかひるめのみこと）など。稚日女尊は天照大御神の妹とも、天照大御神の若い姿ともいわれる女神です。そのため、女性の願いや縁結びにご利益があるとして、近年は遠くからお参りに来る人も増えています。","平安時代の『延喜式』という法令集には、志摩国の神社として «粟嶋坐伊射波神社» の名が記されています。志摩国の一宮には、この伊射波神社と、志摩市の伊雑宮の二つの説があります。どちらも «いざわ» と読むのは偶然でしょうか? 古い地名や神の名が関係しているのではないか、と考える人もいますが、はっきりしたことはわかっていません。","社殿は小さく素朴ですが、あたりは静かで、海風と木々のざわめきだけが聞こえます。帰りに岬の先へ回ると、鳥羽の島々と、遠くに答志島や菅島が見えることも。«ここまで来てよかった» と思える、昔ながらの参詣の道です。"],"tl":[["創建不詳","岬の上で海の神・女神をまつる信仰が始まったと考えられる"],["927年","『延喜式』神名帳に «粟嶋坐伊射波神社» として記される"],["中世以降","志摩国の一宮の一つとして信仰される"],["江戸時代","鳥羽の漁師・船乗りの守り神として崇敬を集める"],["現在","«加布良古さん» として縁結びの参拝者も訪れる"]],"who":[["稚日女尊","伊射波神社の主な祭神とされる女神"],["安楽島の人々","神社を守り、祭りを受けついできた"],["鳥羽の漁師・船乗り","岬の神に海の安全を祈った"]],"deep":["『延喜式』の «粟嶋坐» は «粟島にいます» という意味で、もとは島（または島のような岬）にまつられていたことを示すと考えられます。","志摩国は «御食国（みけつくに）» とよばれ、海の幸を朝廷や神宮にささげる国でした。そうした海の祭祀とこの神社の関係が注目されます。","祭神には稚日女尊のほか、伊佐波登美命などの名があげられることがあり、資料によって表記が違います。","一宮が二つあるという例は全国にもいくつかあり、国の中の地域ごとの勢力や信仰の違いを映すとも考えられます。","山道はぬかるみやすく、足元の悪い場所もあります。歩きやすい靴で、時間に余裕をもって訪ねましょう。","近くの安楽島は、鳥羽湾の真珠養殖やカキ養殖の風景も見られる地域です。"],"look":["駐車場から続く森の参道","岬の上の鳥居と素朴な社殿","岬の先から見る鳥羽湾の島々"],"q":["伊射波神社の地元での呼び名は？","«加布良古（かぶらこ）さん» です。神社がある加布良古崎の名前からきています。"],"koji":[],"myth":"祭神の構成や «船が帆を下げて礼をした» 話は伝承・資料により異なる。志摩国一宮は伊雑宮説もある。","img":["志摩国","延喜式神名帳","一宮","答志島"],"wp":"伊射波神社","rel":{"ev":[],"grave":[]},"ph":[["c:f/f2/Izawa_jinja_Haiden.JPG",2352,1568,"伊射波神社"],["c:c/c8/Engishiki_Jingi_cropped_Engishiki_Vol_2_Flame_37.jpg",2523,3524,"延喜式神名帳"],["c:6/6d/Zenkoku-ichinomiya.jpg",600,800,"一宮"]]},{"id":"24_shima_kokubunji","n":"志摩国分寺","yomi":"しまこくぶんじ","cat":"遺跡","rank":"B","y":741,"era":["nara"],"sh":"","ad":"志摩市阿児町国府","st":"近鉄鵜方駅からバスで約15分、下車後歩いて数分（車が便利）","la":34.318,"lo":136.852,"hook":"日本でいちばん小さな国の一つにも、天皇は «国の寺» を建てさせた。その名を受けつぐお寺が、国府の町に静かに立つ。","lead":"奈良時代、聖武天皇は国ごとに «国分寺» を建てるよう命じました。志摩国の国分寺は、今の志摩市阿児町国府のあたりにあったと考えられています。今も同じ名前のお寺があり、古い国分寺の歴史を伝えています。","story":["741年、聖武天皇は «国ごとに寺を建て、仏の力で国を守ろう» という詔を出しました。そのころ、都では病が流行し、反乱や災害も続いていました。«なぜ仏教だったのか?» それは、仏の教えで人々の心をまとめ、国の平和を祈ることが、天皇のいちばんの願いだったからです。","志摩国は、今の志摩市と鳥羽市あたりだけの、とても小さな国でした。それでも国は国。役所である国府が置かれ、そこに国分寺も建てられることになりました。«国府» という今の地名は、まさに志摩国の役所があった名残だと考えられています。","ただ、志摩の国分寺がいつ完成したのか、どんな大きさだったのかは、よくわかっていません。小さな国で財力が十分でなかったため、建設にはほかの国の助けがあったとする記録もあると伝わります。遠い都からの命令を、海の国の人々はどんな気持ちで受け止めたのでしょうか。","長い年月のあいだに、奈良時代の大きな伽藍は失われました。今、国府にある «国分寺» は、その名前と場所の記憶を受けついだお寺です。境内には古い仏像が伝わり、地域の人々に大切にされています。古代の建物が残っていなくても、地名とお寺の名前が、1200年以上前の歴史を静かに語っているのです。","国府の近くには白い砂浜が広がる «国府白浜» があり、サーフィンを楽しむ人の姿も見られます。古代の役人たちも、この海を見ていたのかもしれません。都から遠く離れた海辺で、国の平安を祈った人々のことを想像しながら歩いてみましょう。"],"tl":[["741年","聖武天皇が国分寺建立の詔を出す"],["8世紀","志摩国にも国分寺が建てられる（完成時期は不明）"],["平安時代以降","律令制のゆるみとともに、国分寺としての力が弱まる"],["中世〜近世","名を受けつぐ寺として地域で信仰される"],["現在","志摩市阿児町国府に国分寺が残る"]],"who":[["聖武天皇","国分寺建立の詔を出した天皇"],["光明皇后","聖武天皇の皇后。国分寺・国分尼寺の建立をすすめたといわれる"],["志摩国の国司たち","国府で政治を行い、国分寺の造営にかかわった"]],"deep":["国分寺の正式な名は «金光明四天王護国之寺»。国分尼寺は «法華滅罪之寺» とよばれました。","志摩国は «御食国» として海産物を朝廷に納めるのが大きな役目で、平城京跡から志摩国のアワビなどの荷札木簡が見つかっています。","志摩のような小国では国分寺の造営が難しく、隣の国の負担で建てたとする説があります。","古代の伽藍の位置や規模は発掘で十分に確かめられておらず、今後の調査が待たれます。","«国府» という地名は全国各地に残り、国の役所があった場所を探す手がかりになります。","今の国分寺は現役のお寺です。お参りする人の迷惑にならないよう静かに見学しましょう。"],"look":["国分寺の山門と本堂","«国府» の地名が残る町並み","近くの国府白浜の海岸"],"q":["聖武天皇が国分寺をつくるよう命じたのは何年？","741年です。国ごとに国分寺と国分尼寺を建てるよう命じました。"],"koji":[],"myth":"志摩国分寺の創建時期・規模・当初の位置は不明な点が多い。他国の負担で建てたとする説も確定ではない。","img":["国分寺","聖武天皇","志摩国"],"wp":"志摩国分寺","rel":{"ev":[],"grave":[]},"ph":[["c:2/29/Shima_Kokubunji%2C_hondou.jpg",6014,3998,"志摩国分寺"],["c:a/a0/Bitchu_Kokubunji%2C_zenkei.jpg",6010,3990,"国分寺"],["c:3/3f/Emperor_Shomu.jpg",1876,3132,"聖武天皇"]]},{"id":"24_daiozaki","n":"大王埼灯台と波切城跡","yomi":"だいおうざきとうだいとなきりじょうあと","cat":"近代","rank":"B","y":1927,"era":["muromachi","showa"],"sh":"","ad":"志摩市大王町波切","st":"近鉄鵜方駅からバスで約20分、«大王埼灯台» 下車、坂道を歩いて約10分","la":34.2765,"lo":136.8993,"hook":"«伊勢の神前、国崎の鎧、波切大王なけりゃよい» ――船乗りに恐れられた岬に、白い灯台が立つ。","lead":"大王埼は志摩半島の東の端にある岬で、昔から波が荒く、船の事故が多い «海の難所» でした。1927年、ここに大王埼灯台が建てられました。岬のそばには、戦国時代の水軍・九鬼氏がはじまったといわれる波切城の跡もあります。","story":["遠州灘と熊野灘のあいだにつき出た大王埼は、船乗りにとってこわい場所でした。沖には岩礁がかくれ、風が吹くと大波が岬にぶつかります。«伊勢の神前、国崎の鎧、波切大王なけりゃよい» ――このあたりの難所を並べた船乗りの唄は、そんな海の危うさを伝えています。","そこで1927年、岬の先に白い灯台がともされました。夜の海に光を投げかける灯台は、船乗りにとって «ここは危ないぞ» と教えてくれる命の目印です。今では中に入り、らせん階段を上って外に出ることのできる数少ない «のぼれる灯台» の一つ。上から見る太平洋は、まるで地球の丸さが見えるようです。","灯台へ向かう坂道の途中には、波切城の跡があります。ここは室町時代、紀伊の九鬼浦から移ってきた九鬼氏が拠点にしたといわれる場所です。«なぜ海の近くに城を?» それは九鬼氏が、海を舞台に戦う «水軍» の一族だったから。海を見張り、船を出すのに、岬の上は最高の場所でした。","やがて九鬼氏は勢力をのばし、戦国時代には九鬼嘉隆が織田信長に仕えて、大きな鉄の船を造ったことでも知られます。その一族の出発点が、この小さな岬だったのです。今、城跡には建物はなく、石碑などがその場所を伝えています。","波切の町は、坂と石垣と細い路地が入り組んだ漁師町。美しい景色にひかれて多くの画家が訪れ、«絵描きの町» ともよばれてきました。9月ごろには、大きなわらじを海に流す «わらじ祭» が行われます。«この村には大きなわらじをはく大男がいるぞ» と見せて、海の怪物を追い払ったという伝説にちなむ祭りです。"],"tl":[["室町時代","九鬼氏が波切に入り、波切城を拠点にしたと伝わる"],["戦国時代","九鬼嘉隆らが志摩の水軍をまとめる"],["1927年","大王埼灯台が初めて点灯する"],["戦後","画家が多く訪れ、«絵描きの町» として知られる"],["現在","のぼれる灯台として公開され、わらじ祭も続く"]],"who":[["九鬼氏","波切城を拠点にしたと伝わる水軍の一族"],["九鬼嘉隆","九鬼氏の武将。織田信長に仕え、志摩の水軍を率いた"],["波切の漁師たち","わらじ祭を受けつぎ、荒海で漁をしてきた人々"],["画家たち","波切の景色を描きに訪れた"]],"deep":["大王埼灯台は、中に入って上ることのできる全国でも数少ない «参観灯台» の一つです。","九鬼氏の起源は紀伊国の九木浦（今の尾鷲市九鬼町）とされ、そこから志摩に進出したと伝わります。","波切城の築城年や城主の系譜には諸説があり、確かな史料は多くありません。","わらじ祭の伝説に出てくる海の怪物 «ダンダラボッチ» は、一つ目の大男ともいわれ、波切神社の祭りとして続いています。","«波切» という地名は、打ち寄せる波を切るような岬の地形を思わせますが、由来は定かではありません。","灯台のある岬から熊野灘側を見ると、志摩半島のリアス海岸の複雑な海岸線がよくわかります。"],"look":["大王埼灯台の展望デッキ（上れる灯台）","灯台へ続く坂道と土産物屋の並ぶ路地","波切城跡の碑","石垣と坂の漁師町の風景"],"q":["大王埼のわらじ祭で、大きなわらじを見せて追い払った相手とされるのは？","海の怪物 «ダンダラボッチ» です。大男がいると思わせて追い払ったと伝わります。"],"koji":[],"myth":"九鬼氏の波切入りの時期、船乗りの唄の文句、わらじ祭の由来は伝承・諸説。","img":["九鬼嘉隆","九鬼氏","大王町"],"wp":"大王埼灯台","rel":{"ev":[],"grave":[]},"ph":[["c:6/6e/Daiosaki_Lighthouse_2021-02_ac_%283%29.jpg",2745,3660,"大王埼灯台"],["c:3/3c/Kukiyoshitaka2.jpg",1141,2101,"九鬼嘉隆"],["c:f/f5/Daiosaki_Lighthouse_2021-02_ac_%282%29.jpg",5696,3787,"大王町"]]},{"id":"24_ama","n":"相差の海女（海女小屋と石神さん）","yomi":"おうさつのあま","cat":"産業","rank":"B","y":2017,"era":["nara","heisei"],"sh":"国の重要無形民俗文化財（鳥羽・志摩の海女漁の技術）","ad":"鳥羽市相差町","st":"鳥羽駅からかもめバスで約40分、«相差» 下車すぐ","la":34.4735,"lo":136.8905,"hook":"息をとめて、海の底へ。1000年以上前から、鳥羽・志摩の女性たちは素もぐりでアワビをとってきた。","lead":"海女は、道具にたよらず自分の息だけで海にもぐり、アワビやサザエ、海藻をとる女性たちです。鳥羽市・志摩市には日本でいちばん多くの海女がいて、相差町はその代表的な町。海女が漁の合間に火を囲む «海女小屋» や、女性の願いをかなえるという «石神さん» で知られます。","story":["朝、相差の浜。白い磯着に身を包んだ海女たちが、磯桶をかかえて海に入っていきます。«ヒュー» ――海面に上がって息をはき出すとき、口笛のような音がします。«磯笛» とよばれるこの音は、呼吸をととのえるための海女の知恵です。一回のもぐりはおよそ1分ほど。それを何十回もくり返します。","海女の歴史はとても古く、奈良時代の都の跡からは、志摩から送られたアワビの荷札が見つかっています。志摩は «御食国（みけつくに）» ――天皇や神宮に食べ物をささげる国でした。今も伊勢神宮には、海女がとったアワビを加工した «熨斗鮑（のしあわび）» が納められています。","漁の合間、海女たちは «海女小屋» で火にあたり、冷えた体を温めます。そこは情報交換の場であり、笑い声のたえない休み場所でもありました。今は観光客が海女小屋で、海女さんの焼いた貝を食べながら話を聞く体験もできます。«昔は冬でも潜ったんよ» ――そんな言葉に、厳しい仕事の重みが感じられます。","相差の神明神社の中には、«石神さん» とよばれる小さなお社があります。«女性の願いを一つだけかなえてくれる» といわれ、海女たちが昔から漁の安全を祈ってきました。お守りには、星形の «セーマン» と格子の «ドーマン» という魔除けの印が描かれています。海女が手ぬぐいなどに縫いつけてきた、海の魔物から身を守るしるしです。","2017年、«鳥羽・志摩の海女漁の技術» は国の重要無形民俗文化財に指定されました。けれども、海女の数は年々減り、高齢化も進んでいます。資源を守るため、とる時期や大きさを自分たちで決めてきた海女たちの知恵を、どう次の世代につなぐか――それが今の大きな課題になっています。"],"tl":[["奈良時代","平城京に志摩国からアワビなどの海産物が送られる"],["平安時代","『延喜式』に志摩国が朝廷・神宮に海産物を納めることが定められる"],["江戸時代","伊勢参りの広まりとともに、志摩の海女が知られるようになる"],["戦後","鳥羽・志摩が海女漁の日本一の地域として知られる"],["2017年","«鳥羽・志摩の海女漁の技術» が国の重要無形民俗文化財に"],["現在","海女小屋体験などで海女文化を伝える取り組みが続く"]],"who":[["相差の海女たち","今も素もぐり漁を続け、海女小屋で文化を伝える"],["神明神社の石神さん","海女が安全と願いを祈ってきた小さな神さま"],["伊勢神宮","海女がとったアワビが熨斗鮑として納められる"]],"deep":["海女漁には、一人でもぐる «徒人（かちど）» と、夫などが船から命綱を操る «舟人（ふなど）» という方法があります。","ドーマン・セーマンの名は、陰陽師の芦屋道満と安倍晴明に由来するという説がありますが、確かではありません。","鳥羽市の国崎町では、今も伊勢神宮に納める熨斗鮑が作られていて、倭姫命がこの地を訪れた伝説と結びついています。","海女たちは、アワビをとる大きさの制限や漁の期間・時間を自分たちで決め、資源を守ってきました。","鳥羽市の «海の博物館» には、海女の道具や漁の歴史がくわしく展示されています。","海女は世界的にもめずらしい漁法で、韓国の済州島の海女（ヘニョ）との交流も行われています。"],"look":["神明神社の中の石神さん","海女小屋（体験は予約制が多い）","相差の漁港と海女が潜る磯","セーマン・ドーマンの描かれたお守り"],"q":["海女が海面に上がって息をはくときの、口笛のような音をなんという？","«磯笛（いそぶえ）» です。呼吸をととのえるための海女の知恵です。"],"koji":[],"myth":"石神さんのご利益、ドーマン・セーマンの名前の由来は伝承。","img":["熨斗","鳥羽市","アワビ"],"wp":"海女","rel":{"ev":[],"grave":[]},"ph":[["c:a/ac/Toba_Aquarium_front_view_2019.jpg",4608,3456,"鳥羽市"],["c:1/14/White_abalone_Haliotis_sorenseni.jpg",2836,1160,"アワビ"]]},{"id":"24_aekuni","n":"敢国神社（伊賀国一宮）","yomi":"あえくにじんじゃ","cat":"寺社","rank":"A","y":658,"era":["asuka","heian"],"sh":"","ad":"伊賀市一之宮","st":"JR佐那具駅から歩いて約30分（車が便利）","la":34.787,"lo":136.16,"hook":"伊賀の国でいちばん格の高い神社。その祭神の «お墓» といわれる巨大古墳が、すぐそばの丘にある。","lead":"敢国神社は伊賀国の一宮で、伊賀の人々にもっとも大切にされてきた神社です。祭神の大彦命は、伊賀の豪族・阿閉（あえ）氏の祖先ともいわれます。境内は伊賀盆地を見わたす丘の上にあり、近くには伊賀最大の古墳・御墓山古墳があります。","story":["伊賀盆地の北東、南宮山のふもとの森に、敢国神社は鎮まっています。«あえくに» という不思議な名前は、この地を治めた古い豪族 «阿閉（あえ）氏» の «あえ» に由来するともいわれます。«なぜ一宮なのに、神さまの名前ではなく人の名前?» ――そこに、この神社の古さのなぞがあります。","主な祭神は大彦命。『日本書紀』で、崇神天皇のころ北陸に遣わされた «四道将軍» の一人として登場する人物です。伝承では、大彦命の子孫がこの伊賀に住みつき、阿閉氏など伊賀の有力な一族になったといわれます。神社は658年に創建されたと伝わり、そのころ大彦命をまつったのが始まりとされます。","平安時代の『延喜式』では «敢国神社» は大社とされ、やがて伊賀国の一宮として信仰を集めました。戦国時代の «天正伊賀の乱» では、織田軍の攻撃で伊賀の多くの寺社が焼かれ、敢国神社も大きな被害を受けたと伝わります。しかし江戸時代、藤堂氏が伊賀を治めるようになると、社殿が再建されました。","この神社の名物が、«黒党祭（くろんどまつり）» と獅子神楽です。黒党祭は、中世に伊賀で力をもった武士団 «黒党» が行ったことに由来するといわれる祭りで、黒い装束の人々の行列が見られます。獅子神楽は伊賀各地に広まり、地域の祭りで今も舞われています。","神社の北東の丘には、全長およそ188mの御墓山古墳があります。«御墓» という名前のとおり、地元では大彦命のお墓と言い伝えられてきました。実際には5世紀ごろの有力者の墓と考えられていますが、神社と古墳がセットで伝わることで、伊賀の人々が «自分たちのはじまり» をどこに感じてきたかが見えてきます。"],"tl":[["5世紀ごろ","近くに御墓山古墳が築かれる"],["658年","敢国神社が創建されたと伝わる"],["927年","『延喜式』に大社として記される"],["1581年","天正伊賀の乱で伊賀の寺社の多くが焼かれる"],["江戸時代","藤堂氏の保護のもとで社殿が整えられる"],["現在","伊賀国一宮として、黒党祭・獅子神楽が受けつがれる"]],"who":[["大彦命","敢国神社の主祭神。『日本書紀』の四道将軍の一人"],["阿閉氏","伊賀の古い豪族。神社の名の由来ともいわれる"],["黒党","中世の伊賀の武士団。黒党祭の名の由来とされる"],["藤堂高虎","伊賀を治めた津藩の藩祖。藤堂家は神社を保護した"]],"deep":["祭神は大彦命のほか、少彦名命と金山比咩命をあわせてまつるとされます。金山比咩命はもと南宮山にまつられていたと伝わります。","«敢» の字は、古代の氏族名や郡名 «阿拝（あえ）郡» と関係すると考えられ、伊賀の古代史を知る手がかりです。","黒党は、東大寺領の荘園などとも関係のあった伊賀の武士団とされ、その由来には諸説あります。","伊賀の獅子神楽は、敢国神社を中心に地域へ広がったとされ、三重県の無形民俗文化財に指定されています。","天正伊賀の乱（1579・1581年）は、伊賀の地侍たちが織田信雄・信長の軍と戦った戦いで、伊賀の寺社に大きな被害を出しました。","御墓山古墳は国指定史跡。神社と古墳をあわせて歩くと、伊賀の古代の中心地の姿が想像できます。"],"look":["丘の上の本殿と、伊賀盆地を見下ろす参道","境内の獅子神楽にかかわる展示・案内","北東の御墓山古墳（あわせて訪ねたい）"],"q":["敢国神社の主祭神・大彦命は、『日本書紀』で何とよばれる将軍の一人？","«四道将軍» です。崇神天皇のころ、北陸に遣わされたとされます。"],"koji":[],"myth":"658年創建、阿閉氏の祖、御墓山古墳を大彦命の墓とする話は伝承。黒党の由来も諸説。","img":["大彦命","伊賀国","一宮","御墓山古墳"],"wp":"敢国神社","rel":{"ev":[],"grave":[]},"ph":[["c:4/4c/Aekuni-jinja_haiden.JPG",6016,4000,"敢国神社"],["c:0/09/%E5%A4%A7%E5%BD%A6%E5%91%BD_%C5%8Chiko_no_mikoto_%E6%97%A5%E6%9C%AC%E7%99%BE%E5%B0%86%E4%BC%9D.jpg",1145,1737,"大彦命"],["c:6/6d/Zenkoku-ichinomiya.jpg",600,800,"一宮"],["c:1/1f/Mihakayama-kofun_zenkei.JPG",6016,4000,"御墓山古墳"]]},{"id":"24_basho_seika","n":"芭蕉翁生家","yomi":"ばしょうおうせいか","cat":"学び","rank":"A","y":1644,"era":["edo"],"sh":"県指定史跡","ad":"伊賀市上野赤坂町","st":"伊賀鉄道 上野市駅から歩いて約15分","la":34.768,"lo":136.138,"hook":"«旅に病んで夢は枯野をかけ廻る» ――一生を旅に生きた俳人の出発点は、伊賀上野の小さな町家だった。","lead":"江戸時代の俳人・松尾芭蕉は、1644年に伊賀国（今の伊賀市）で生まれたとされます。伊賀上野の赤坂町に残る «芭蕉翁生家» は、芭蕉が育ち、旅の途中にもたびたび帰ってきた家と伝わります。裏には、若いころに最初の句集をまとめた «釣月軒» があります。","story":["松尾芭蕉――本名は松尾宗房。伊賀上野の、農民とも武士ともいえない «無足人» の家に生まれました。子どものころに父を亡くし、若くして藤堂家の一族・藤堂良忠に仕えます。良忠は «蝉吟（せんぎん）» という号をもつ俳諧好きで、宗房は良忠と句を作りあううちに、俳諧の楽しさにひかれていきました。","ところが良忠は若くして亡くなってしまいます。主を失った宗房は、やがて故郷を出る決心をしました。«このまま伊賀にいていいのか?» ――その迷いの答えを出す前に、生家の裏の «釣月軒（ちょうげつけん）» で、宗房は最初の句集『貝おほひ』をまとめたといわれます。これを上野天満宮に奉納して、江戸へと旅立ったのでした。","江戸での芭蕉は、ことば遊びが中心だった俳諧を、心の深いところを映す «芸術» へと高めていきます。«古池や蛙飛びこむ水の音»。深川の芭蕉庵を拠点に、『野ざらし紀行』『おくのほそ道』など、旅をしながら名句を生みました。","それでも芭蕉は、何度もふるさと伊賀に帰ってきています。1687年の暮れに帰郷したときには、«古里や臍の緒に泣く年の暮» と詠みました。生家で、自分のへその緒を見せられて涙した――母はもういなかったのです。遠くへ行けば行くほど、ふるさとは心の中で大きくなっていったのかもしれません。","1694年、芭蕉は旅先の大坂で病に倒れ、51歳で亡くなりました。«旅に病んで夢は枯野をかけ廻る»。遺言により、近江の義仲寺に葬られました。伊賀上野の生家は、芭蕉の «はじまりの場所» として大切に守られ、今は見学することができます。町のあちこちに句碑が立ち、芭蕉の気配を感じながら歩けます。"],"tl":[["1644年","伊賀国で松尾芭蕉（宗房）が生まれる"],["1660年代","藤堂良忠（蝉吟）に仕え、俳諧を学ぶ"],["1672年","句集『貝おほひ』を上野天満宮に奉納し、江戸へ"],["1687年","帰郷し «古里や臍の緒に泣く年の暮» を詠む"],["1689年","『おくのほそ道』の旅に出る"],["1694年","大坂で亡くなり、近江の義仲寺に葬られる"]],"who":[["松尾芭蕉","俳諧を芸術に高めた «俳聖»。この家で育ったと伝わる"],["藤堂良忠（蝉吟）","芭蕉の主君で、俳諧の仲間"],["服部土芳","伊賀の門人。芭蕉の教えを『三冊子』にまとめた"],["向井去来","芭蕉の高弟の一人。芭蕉の言葉を『去来抄』に残した"]],"deep":["芭蕉の生まれた場所は、伊賀上野の赤坂町とする説と、柘植（つげ、今の伊賀市柘植町）とする説があります。","«無足人» は、伊賀の藤堂藩で農民でありながら武士に近い身分を認められた人々で、芭蕉の家もそうだったといわれます。","『貝おほひ』は、二つの句を組み合わせて優劣を判定する «句合（くあわせ）» の形の作品で、若い芭蕉の才気がよく表れています。","«芭蕉» という号は、深川の庵に門人が植えた芭蕉（バナナの仲間の植物）に由来します。","伊賀市には芭蕉の生誕300年を記念して建てられた «俳聖殿» があり、芭蕉の旅姿をかたどった建物とされます。","芭蕉が伊賀忍者だったという話がありますが、これは旅の速さなどから生まれた俗説で、根拠となる史料はありません。"],"look":["生家の土間と部屋のつくり","裏庭の釣月軒","近くの愛染院（故郷塚）","上野公園の俳聖殿"],"q":["芭蕉が伊賀を出る前にまとめ、上野天満宮に奉納した句集の名前は？","『貝おほひ』です。生家の裏の釣月軒でまとめたといわれます。"],"koji":[{"w":"不易流行","m":"いつまでも変わらないものと、時代とともに新しく変わるもの。その両方が大切だという、芭蕉の俳諧の考え方"}],"myth":"生誕地（上野赤坂か柘植か）は諸説。釣月軒で『貝おほひ』をまとめた話は伝承。芭蕉忍者説は俗説。","img":["おくのほそ道","俳聖殿","義仲寺"],"wp":"松尾芭蕉","rel":{"ev":[],"grave":[]},"ph":[["c:c/ca/Basho_by_Morikawa_Kyoriku_%281656-1715%29.jpg",512,854,"松尾芭蕉"],["c:d/db/Haiseiden.jpg",2592,1944,"俳聖殿"],["c:9/97/Gichuji_hondo.jpg",3264,2448,"義仲寺"]]},{"id":"24_minomushian","n":"蓑虫庵（芭蕉の門人の庵）","yomi":"みのむしあん","cat":"学び","rank":"B","y":1688,"era":["edo"],"sh":"","ad":"伊賀市上野西日南町","st":"伊賀鉄道 茅町駅から歩いて約5分","la":34.764,"lo":136.124,"hook":"«蓑虫の音を聞きに来よ草の庵» ――師匠から贈られた一句が、そのまま庵の名前になった。","lead":"蓑虫庵は、松尾芭蕉の弟子・服部土芳が伊賀上野に結んだ小さな庵（すまい）です。芭蕉が訪れて句を詠んだことから、この名がつきました。芭蕉にゆかりのある庵の中で、今もその姿を伝える貴重な場所です。","story":["服部土芳は、芭蕉より13歳ほど年下の伊賀の人でした。藤堂藩に仕える武士でしたが、若いころから芭蕉を慕い、俳諧の道を歩みたいと願います。そしてついに武士の身分を捨て、伊賀上野の町はずれに小さな庵を建てて、俳諧に生きることにしたのです。","1688年、ふるさとに帰っていた芭蕉は、土芳の新しい庵をたずねました。庭の静けさの中で、芭蕉は一枚の絵に句を書きつけて贈ったといわれます。«蓑虫の音を聞きに来よ草の庵»。蓑虫は本当は鳴かない虫。«鳴かない虫の声を聞きに来なさい» ――それは、静けさそのものを味わいなさい、という師の心だったのかもしれません。","土芳はこの句を大切にし、庵を «蓑虫庵» と名づけました。«なぜ蓑虫なのか?» 蓑虫は枝にぶら下がり、ひっそりと冬を越す虫です。世の中から一歩しりぞいて、静かに俳諧に打ちこむ土芳の姿に、芭蕉は蓑虫を重ねたのでしょう。","芭蕉が亡くなったあと、土芳は師から聞いた言葉や教えを、ていねいに書き残しました。それが『三冊子（さんぞうし）』です。«松のことは松に習え、竹のことは竹に習え» という有名な言葉も、この本に伝えられています。芭蕉の考えを今の私たちが知ることができるのは、土芳のような弟子たちのおかげなのです。","庵は小さな茅ぶき屋根の建物と、静かな庭からなります。庭には芭蕉の句碑がいくつも立ち、池のほとりには季節の花が咲きます。伊賀上野の町の喧騒からほんの少しはなれただけで、時間の流れがゆっくりになるような場所。蓑虫の «聞こえない音» に、耳をすませてみてください。"],"tl":[["1657年","服部土芳が伊賀に生まれる"],["1685年ごろ","土芳が芭蕉と再会し、俳諧に打ちこむ"],["1688年","芭蕉が土芳の庵を訪れ、«蓑虫の» の句を贈る"],["1694年","芭蕉が亡くなる"],["1700年代初め","土芳が『三冊子』をまとめる"],["1730年","土芳が亡くなる"],["現在","芭蕉ゆかりの庵として公開されている"]],"who":[["服部土芳","芭蕉の伊賀の門人。蓑虫庵の主で『三冊子』の著者"],["松尾芭蕉","土芳の師。庵を訪れ、名の由来となる句を贈った"],["伊賀の俳人たち","土芳のもとに集い、伊賀蕉門を支えた"]],"deep":["『三冊子』は «白雙紙»«赤雙紙»«わすれ水（黒雙紙）» の3部からなり、芭蕉の俳論を知るための第一級の資料とされます。","«不易流行» や «松のことは松に習え» など、芭蕉の有名な教えの多くが『三冊子』によって伝えられています。","芭蕉には、門人たちが用意した庵がいくつかあり、蓑虫庵はその一つとして、今も当時の姿を伝える数少ない例といわれます。","蓑虫は実際には鳴きませんが、昔は秋に «ちちよ、ちちよ» と鳴くと考えられ、『枕草子』にもそう書かれています。芭蕉の句はこの古典を踏まえています。","土芳はもと藤堂藩の藩士で、武士をやめて俳諧に生きたことが、当時としては大きな決断でした。","庵の建物は長い年月の間に修理・再建をへています。当時のままの部分がどこかは、案内で確かめましょう。"],"look":["茅ぶき屋根の庵の建物","庭に並ぶ芭蕉の句碑","静かな池と庭の四季の花"],"q":["蓑虫庵の主・服部土芳が、芭蕉の教えをまとめた本の名前は？","『三冊子（さんぞうし）』です。"],"koji":[{"w":"松のことは松に習え","m":"ものの本当の姿を知るには、自分の思いこみを捨てて、そのものから直接学べという芭蕉の教え"}],"myth":"芭蕉の庵のうち «唯一現存» とする言い方があるが、建物は修理・再建をへている。","img":["松尾芭蕉","三冊子"],"wp":"服部土芳","rel":{"ev":[],"grave":[]},"ph":[["c:1/19/Minomushi-an%2C_Alias_Sach%C3%BB-an_-_A_stone_tablet_inscribed_with_a_haiku_of_Hattori_Toh%C3%B4_-_%22Wakana-zuka%22.jpg",3096,4128,"服部土芳"],["c:c/ca/Basho_by_Morikawa_Kyoriku_%281656-1715%29.jpg",512,854,"松尾芭蕉"]]},{"id":"24_iga_ninja","n":"伊賀流忍者博物館","yomi":"いがりゅうにんじゃはくぶつかん","cat":"伝承","rank":"A","y":1581,"era":["muromachi","azuchi","edo"],"sh":"","ad":"伊賀市上野丸之内（上野公園内）","st":"伊賀鉄道 上野市駅から歩いて約5分","la":34.7686,"lo":136.1287,"hook":"回る壁、床下の刀かくし、にげ道。«忍者屋敷» のしかけには、戦国の伊賀の人々の知恵がつまっている。","lead":"伊賀は、甲賀とならんで忍者のふるさととして知られます。上野公園の中にある伊賀流忍者博物館では、からくりのある忍者屋敷や、忍者の道具・資料を見ることができます。忍者ショーでは手裏剣や鎖鎌の技も見られます。","story":["戦国時代の伊賀には、大きな大名がいませんでした。かわりに、小さな領地をもつ地侍たちが話し合いで国を治め、外から攻められたときには力を合わせて戦いました。この «惣国一揆» とよばれるしくみの中で、情報を集めたり、夜にしのびこんだりする技が磨かれていった――それが伊賀の忍びだと考えられています。","忍者屋敷に入ると、案内役のくノ一が «さあ、どこにしかけがあるでしょう?» と問いかけます。壁の一部がくるりと回る «どんでん返し»、床下にかくした刀、はしごを引き上げてしまえる屋根裏。どれも、敵がふいに攻めてきたとき、家族や仲間を守るための工夫だったといわれます。","1579年と1581年、伊賀は大きな悲劇にみまわれます。織田信長の子・信雄が攻めこんで一度は伊賀勢に敗れ、2年後、信長みずからが大軍で伊賀を攻めたのです。これを «天正伊賀の乱» といいます。多くの人が亡くなり、寺や村が焼かれました。生き残った伊賀の人々は、各地に散っていきました。","翌1582年、本能寺の変が起きたとき、堺にいた徳川家康は伊賀の山道を通って三河へ逃げ帰りました。この «神君伊賀越え» を助けたのが、伊賀にゆかりのある服部半蔵正成や伊賀の者たちだったと伝わります。のちに江戸では、伊賀者が城の警備などをつとめるようになりました。","江戸時代の1676年には、伊賀・甲賀の忍術をまとめた『萬川集海（ばんせんしゅうかい）』という書物が書かれました。博物館では、こうした忍術書や手裏剣・水蜘蛛などの道具が展示されています。«忍者は黒装束で空を飛ぶ» ――そんなイメージの多くは、実は江戸時代の芝居や後のマンガが作ったもの。本物の忍びは、目立たない服で、情報を持ち帰ることこそが一番の仕事でした。"],"tl":[["室町〜戦国時代","伊賀の地侍が話し合いで国を治める «惣国一揆» の時代"],["1579年","織田信雄が伊賀に攻めこみ、伊賀勢が撃退する"],["1581年","織田信長の大軍が伊賀を攻める（天正伊賀の乱）"],["1582年","本能寺の変。徳川家康が伊賀の山道をぬけて三河へ戻る"],["1676年","忍術書『萬川集海』がまとめられる"],["1964年","伊賀流忍者屋敷が上野公園に開かれる"],["現在","伊賀流忍者博物館として忍者文化を伝える"]],"who":[["服部半蔵正成","伊賀にゆかりのある徳川家康の家臣。伊賀越えで家康を助けたと伝わる"],["織田信長","天正伊賀の乱で伊賀を攻めた"],["藤林保武","忍術書『萬川集海』の著者とされる"],["百地丹波","伊賀の上忍の一人として伝承に登場する"]],"deep":["«忍者» という言葉が広く使われるのは主に戦後で、それ以前は «忍び»«伊賀者»«乱波» などとよばれました。","『萬川集海』は伊賀・甲賀の忍術を集大成した書物とされ、心構えから道具・天文まで幅広く記されています。","伊賀越えのルートや、家康を助けた伊賀者の働きについては、史料ごとに内容が異なり、諸説あります。","服部半蔵正成自身は三河生まれとされ、父の代に伊賀から移ったといわれます。«忍者» というより、槍の名手の武将として知られていました。","忍者屋敷の建物は、伊賀の古い民家を移築したものと案内されています。","黒装束で手裏剣を投げる忍者像は、江戸時代の歌舞伎や近代の小説・映画によって広まったイメージです。"],"look":["忍者屋敷のどんでん返しや隠し戸","忍者伝承館の忍術書・道具の展示","忍者ショー（時間は要確認）","同じ上野公園の伊賀上野城"],"q":["1581年に織田信長が伊賀を攻めた戦いを何という？","«天正伊賀の乱» です。1579年の戦いを第一次、1581年を第二次ということもあります。"],"koji":[],"myth":"伊賀越えにおける伊賀者の役割、忍者屋敷のしかけの実際の使われ方、百地丹波の人物像には伝承が多い。","img":["忍者","天正伊賀の乱","服部正成","伊賀上野城"],"wp":"伊賀流忍者博物館","rel":{"ev":["jinshin"],"grave":[]},"ph":[["c:b/b2/%E4%BC%8A%E8%B3%80%E6%B5%81%E5%BF%8D%E8%80%85%E5%8D%9A%E7%89%A9%E9%A4%A8_1.JPG",2560,1920,"伊賀流忍者博物館"],["c:1/11/Eight_Hundred_Heroes_of_Our_Country_s_Suikoden_12.jpg",913,1318,"忍者"],["c:a/a0/Igauenozyo.jpg",800,600,"伊賀上野城"]]},{"id":"24_sukodo","n":"旧崇広堂（伊賀上野の藩校）","yomi":"きゅうすうこうどう","cat":"学び","rank":"B","y":1821,"era":["edo"],"sh":"国指定史跡","ad":"伊賀市上野丸之内","st":"伊賀鉄道 上野市駅から歩いて約5分","la":34.7695,"lo":136.131,"hook":"«功の崇きは志、業の広きは勤» ――江戸時代の伊賀の若侍たちは、この言葉の意味をかみしめながら机に向かった。","lead":"旧崇広堂は、江戸時代の終わりに津藩が伊賀上野につくった学校（藩校）です。藩士の子どもたちが漢学や礼儀、武芸などを学びました。講堂や表門などが今も残り、国の史跡に指定されています。","story":["江戸時代、伊賀国は津藩（藤堂家）の領地でした。本拠地は伊勢の津ですが、伊賀上野にも城と城下町があり、多くの藩士が住んでいました。1820年、藩主の藤堂高兌（たかさわ）は、津に藩校 «有造館» を開きます。«藩をよくするには、まず人を育てなければ» ――そう考えたのです。","翌1821年、高兌は伊賀上野にも同じような学校を建てました。それが崇広堂です。«なぜもう一つ?» 津から伊賀までは山を越えて遠く、伊賀の藩士の子どもたちが通うのはたいへんでした。そこで伊賀に、有造館の分校のような学校を置いたのです。","«崇広» という名前は、中国の古典『書経』にある «功崇惟志、業広惟勤»（大きな功績は志から、広い事業は勤勉から生まれる）から取られたといわれます。講堂では、先生が四書五経を講義し、生徒たちは声をそろえて読み上げました。礼儀作法や武芸の稽古も行われたと伝わります。","明治維新で藩がなくなると、崇広堂も藩校としての役目を終えました。けれども建物は、その後も学校や公共の施設として使われ、大切に守られてきました。津の有造館の建物はほとんど残っていないため、崇広堂は藩校の姿を今に伝える貴重な例となっています。","表門をくぐると、落ち着いた講堂の建物が現れます。広い畳の間に座ってみると、ここで学んだ若者たちの声が聞こえてくるようです。すぐ近くには伊賀上野城や忍者博物館もあり、«武士の学び» と «忍びの技»、二つの伊賀の顔を見比べてみるのもおもしろいでしょう。"],"tl":[["1820年","藤堂高兌が津に藩校・有造館を開く"],["1821年","伊賀上野に崇広堂を開く"],["江戸時代後期","伊賀の藩士の子弟が漢学・礼法などを学ぶ"],["1871年","廃藩置県で藩がなくなり、藩校の役目を終える"],["明治以降","学校・公共施設として建物が使われる"],["現在","国指定史跡として講堂・表門などが公開されている"]],"who":[["藤堂高兌","津藩の藩主。有造館と崇広堂をつくった"],["津藩の藩士の子どもたち","崇広堂で学んだ生徒たち"],["藤堂高虎","津藩の藩祖。伊賀上野城を大改修した"]],"deep":["崇広堂は、津の有造館の «支校» として位置づけられていたとされます。","講堂は江戸時代の藩校建築の姿を伝える建物で、全国的にも残る例は多くありません。","藤堂高兌は、財政の立て直しと教育に力を入れた藩主として知られています。","藩校の教育は儒学（朱子学）が中心でしたが、藩によっては医学・洋学・武術なども教えました。","伊賀上野城は、藤堂高虎が1611年ごろから大改修し、高さ約30mともいわれる高石垣が有名です。","見学は有料で、休館日があります。訪ねる前に開館時間を確認しましょう。","江戸時代の後半には、全国の多くの藩が藩校をつくりました。藩の財政難や社会の変化に対応できる人材を育てることが、どの藩にとっても急ぎの課題だったのです。崇広堂もその流れの中で生まれました。"],"look":["表門（藩校の正門）","講堂の広い畳の間と、生徒が座った位置の想像","近くの伊賀上野城の高石垣と、城下町の町割り"],"q":["崇広堂は、どこの藩の藩校（分校）？","津藩（藤堂家）です。津の有造館の分校のような役目でした。"],"koji":[{"w":"功崇惟志、業広惟勤","m":"大きな手柄は高い志から、広い事業は勤勉から生まれる。『書経』のことばで «崇広» の名の由来とされる"}],"myth":"名前の由来を『書経』とするのは一般的な説明。","img":["藤堂高兌","有造館","藩校"],"wp":"崇広堂","rel":{"ev":["jinshin"],"grave":[]},"ph":[["c:5/56/Iga_city_Suko-do_ac_%281%29.jpg",6016,4000,"崇広堂"],["c:e/ee/Todo_Takasawa.jpg",1346,1514,"藤堂高兌"],["c:6/6b/Koudoukan.JPG",1024,768,"藩校"]]},{"id":"24_iga_kokubunji","n":"伊賀国分寺跡","yomi":"いがこくぶんじあと","cat":"遺跡","rank":"B","y":741,"era":["nara"],"sh":"国指定史跡","ad":"伊賀市西明寺","st":"伊賀鉄道 上野市駅から車で約10分","la":34.779,"lo":136.151,"hook":"田畑の中にぽっかりと残る土の高まり。そこは奈良時代、伊賀の人々が見上げた大きな塔と金堂の跡だった。","lead":"伊賀国分寺跡は、奈良時代に聖武天皇の命で建てられた伊賀国の国分寺の跡です。今は建物はありませんが、金堂や講堂などの土台（基壇）や、まわりを囲む土塁の跡が残り、国の史跡に指定されています。","story":["奈良時代の741年、聖武天皇は全国に国分寺を建てるよう命じました。伊賀国でも、国府に近い上野台地の東の一角に、国分寺がつくられます。完成した寺には金堂や講堂がならび、瓦ぶきの屋根が朝日に光っていたことでしょう。«なぜこんなに立派な寺を?» ――仏の力で国を守る、というのが天皇の願いでした。","今、国分寺跡を訪ねると、そこにあるのは草におおわれた高まりと、静かな空だけです。でもよく見ると、建物の土台だった «基壇» の形がわかります。寺のまわりには土を盛った «土塁» の跡も残っていて、寺の広さをたどることができます。","伊賀国分寺跡は、地上に遺構がよく残っていることで知られています。多くの国分寺跡が、町の中にうもれたり、畑になってわからなくなったりしている中で、ここは古代の寺の «区画» を今も目で見ることができるのです。瓦も多く見つかり、当時の建物の様子を考える手がかりになっています。","国分寺と対になる «国分尼寺» は、どこにあったのでしょう? 近くにある長楽山廃寺が国分尼寺だったのではないかという説があり、研究が続けられています。二つの寺が並んで建っていたとすれば、このあたりは奈良時代の伊賀の «仏教の中心» だったことになります。","やがて律令の制度がゆるむと、国の援助がなくなった国分寺は、しだいにおとろえていきました。建物がなくなったあとも、人々は «ここは国分寺の跡» と言い伝え、土地を守ってきました。見わたす限りの田園の中で、1200年前の大寺院の姿を想像してみてください。"],"tl":[["741年","聖武天皇が国分寺建立の詔を出す"],["8世紀後半","伊賀国分寺が建てられる"],["平安時代以降","国の援助がなくなり、しだいにおとろえる"],["大正〜昭和","国の史跡に指定され、保護される"],["現在","基壇や土塁の跡が残る史跡として公開されている"]],"who":[["聖武天皇","国分寺建立の詔を出した天皇"],["伊賀国の国司","国分寺の造営・維持にかかわった役人"],["伊賀の人々","寺を支え、跡地を守り伝えてきた"]],"deep":["伊賀国分寺跡は、金堂・講堂などの基壇や寺域を囲む土塁が地表に残る点で、全国の国分寺跡の中でも保存状態がよい例とされます。","塔の跡がどこにあったかについては、はっきりしない点があるとされています。","近くの長楽山廃寺は、伊賀国分尼寺の跡とする説があります。","伊賀国府の跡は伊賀市坂之下の一帯で調査され、国分寺と国府の位置関係も研究されています。","出土した瓦の文様から、寺の造営時期や、都や他の国とのつながりが考えられています。","周辺は私有地の田畑も多いので、見学は史跡の範囲内で、農作業のじゃまにならないようにしましょう。"],"look":["金堂・講堂の基壇の高まり","寺の区画を囲む土塁の跡","史跡の説明板"],"q":["国分寺と対になって建てられた、尼さんのための寺を何という？","«国分尼寺» です。伊賀では近くの長楽山廃寺がそれではないかといわれています。"],"koji":[],"myth":"長楽山廃寺を国分尼寺とする説、塔の位置は確定していない。","img":["国分寺","伊賀国","聖武天皇"],"wp":"伊賀国分寺","rel":{"ev":[],"grave":[]},"ph":[["c:b/bd/Iga-kokubunji_sekihi.JPG",6016,4000,"伊賀国分寺"],["c:a/a0/Bitchu_Kokubunji%2C_zenkei.jpg",6010,3990,"国分寺"],["c:3/3f/Emperor_Shomu.jpg",1876,3132,"聖武天皇"]]},{"id":"24_jonokoshi","n":"城之越遺跡（古墳時代の水の祭場）","yomi":"じょのこしいせき","cat":"遺跡","rank":"A","y":380,"era":["kofun"],"sh":"国指定史跡・名勝","ad":"伊賀市比土","st":"伊賀鉄道 比土駅から歩いて約10分","la":34.705,"lo":136.131,"hook":"湧き水を石でかこみ、立石をすえた古代の «庭»。1600年前の水のまつりの場は、日本庭園のはじまりかもしれない。","lead":"城之越遺跡は、古墳時代の4世紀後半ごろにつくられた水のまつりの場です。わき出る泉から流れる溝の岸に石をはり、ところどころに大きな石を立てていました。その姿が日本庭園によく似ていることから、国の史跡と名勝の両方に指定されています。","story":["1990年ごろ、伊賀市比土で田んぼの整備のために発掘調査が行われました。土の中から現れたのは、石をていねいに並べた溝と、そのそばに立てられた大きな石。調査した人たちは目を見はりました。«これは、庭ではないか?» ――それが城之越遺跡の発見でした。","遺跡の中心は、地面からわき出す泉です。その水は溝となって流れ出し、ゆるやかに曲がりながら下っていきます。溝の岸には、平たい石がすきまなく貼られ、ところどころに «立石» がすえられていました。まるで、水の流れを美しく見せるように工夫されているのです。","«なぜこんなものを作ったのか?» 古墳時代の人々にとって、きれいな水がわき出る場所は、神さまが宿る特別な場所でした。ここでは、水の神に豊かな実りや人々の幸せを祈るまつりが行われたと考えられています。周りからは土器なども見つかり、たくさんの人が集まったようすがうかがえます。","研究者が注目したのは、この石の使い方でした。石を立てる、岸に石を貼る、流れを曲げて見せる――どれも、のちの日本庭園でよく使われる技です。飛鳥時代や奈良時代の庭園よりも古いことから、城之越遺跡は «日本庭園の源流» の一つとして考えられるようになりました。","遺跡は整備されて公園になり、発掘された溝や立石のようすが復元されています。そばには出土品を展示する学習館もあります。泉のほとりに立って、耳をすませてみてください。1600年前、同じ場所で水の音を聞きながら祈った人々の気持ちが、少しだけわかるような気がします。"],"tl":[["4世紀後半","泉と溝、立石をそなえた祭場がつくられる"],["古墳時代の中ごろ","祭場としての役目を終え、土に埋もれる"],["1990年ごろ","ほ場整備にともなう発掘調査で発見される"],["1992年","国の史跡に指定される"],["その後","国の名勝にも指定され、公園として整備される"],["現在","城之越学習館とともに公開されている"]],"who":[["古墳時代の伊賀の人々","泉のほとりで水のまつりを行った"],["発掘調査にあたった研究者","遺構を «庭園の源流» として評価した"],["地域の人々","遺跡の保存と整備を支えてきた"]],"deep":["史跡と名勝の両方に指定されている遺跡はめずらしく、«人が作った景色» としての価値が認められた例です。","溝の岸の貼石や立石の配置は、のちの日本庭園の «州浜» や «石組» の技法に通じると指摘されています。","祭場で出土した土器には、祭りの儀式に使われたとみられるものが含まれています。","同じ伊賀盆地には美旗古墳群や御墓山古墳があり、古墳時代の伊賀に有力な勢力がいたことがわかります。","水のまつりの遺跡は、奈良県の南郷大東遺跡など各地で見つかっていて、古墳時代の祭祀の研究が進んでいます。","指定年や発掘の年については、資料によって表記が少しずつ異なるため、現地の説明板で確認するとよいでしょう。"],"look":["湧水点（泉）と、そこから流れる溝","岸に貼られた石と立石","城之越学習館の出土品展示"],"q":["城之越遺跡は、史跡のほかに何に指定されている？","«名勝» です。石を使った景色が日本庭園の源流として評価されました。"],"koji":[],"myth":"«日本庭園の源流» は研究者による評価で、庭園と祭場の関係には議論がある。発見・指定の年は資料で確認を。","img":["日本庭園","古墳時代"],"wp":"城之越遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:f/f4/Jonokoshi_Site%2C_gaikan.jpg",6016,4000,"城之越遺跡"],["c:5/5c/Kare-sansui_zen_garden%2C_Ry%C5%8Dan-ji%2C_Kyoto_20190416_1.jpg",8120,5453,"日本庭園"]]},{"id":"24_mihata","n":"美旗古墳群","yomi":"みはたこふんぐん","cat":"遺跡","rank":"B","y":450,"era":["kofun"],"sh":"国指定史跡","ad":"伊賀市南部（名張市美旗町との境の近く）","st":"近鉄美旗駅から歩いて約20〜30分（古墳は点在するので車や自転車が便利）","la":34.655,"lo":136.108,"hook":"田んぼの中に、いくつもの小山がぽつりぽつり。それは、伊賀を治めた王たちが代々眠る «王の墓の列» だった。","lead":"美旗古墳群は、伊賀盆地の南の台地に、前方後円墳などが集まる古墳のグループです。5世紀から6世紀ごろ、伊賀の有力者が何代にもわたって墓をつくったと考えられています。いくつかの古墳が国の史跡に指定されています。","story":["伊賀盆地の南、名張に近いなだらかな台地を歩くと、田畑の中に木におおわれた小山がいくつも見えてきます。これが美旗古墳群です。小山の一つひとつが古墳で、中には上から見ると鍵穴の形をした前方後円墳もあります。«なぜこんなに集まっているのか?» ――それは、同じ一族が何代にもわたってこの地に墓を築いたからだと考えられています。","古墳群の中でもっとも大きいとされるのが殿塚古墳です。全長はおよそ90m。周りには水をたたえた濠（ほり）がめぐっていたと考えられています。そのほか、女良塚古墳、毘沙門塚古墳などが並びます。古墳の大きさや形の移り変わりを見ると、伊賀の «王» の力がどのように変わっていったかが見えてくるといわれます。","古墳が築かれた5世紀は、大和の大王（のちの天皇）の力が各地に広がった時代です。伊賀は大和のすぐ東どなり。大和と伊勢・東国を結ぶ道の途中にある伊賀の有力者は、大和の王とつながりを持ちながら、この地を治めていたのでしょう。","古墳の上には、かつて埴輪が並べられていたと考えられています。完成したばかりの古墳は、木の生えた今の姿とちがい、石でおおわれ、埴輪がずらりと並ぶ «白く光る人工の山» でした。周りの人々は、それを見上げて王の力を感じたにちがいありません。","今、古墳のまわりは田んぼや住宅地になっています。古墳の多くは私有地の中や近くにあるため、見学は外から静かに行いましょう。季節ごとに色を変える田んぼの中に浮かぶ古墳の姿は、1500年の時を越えて、今も伊賀の風景の一部になっています。"],"tl":[["5世紀前半ごろ","伊賀南部の台地に大きな前方後円墳が築かれはじめる"],["5世紀〜6世紀","殿塚古墳・女良塚古墳などが順に築かれたと考えられる"],["昭和時代","古墳群のうち主要な古墳が国の史跡に指定される"],["その後","周辺の開発にあわせて調査が行われる"],["現在","田園の中に点在する古墳として見学できる"]],"who":[["伊賀の古代の有力者","美旗古墳群に葬られたと考えられる «伊賀の王» たち"],["大和の大王","伊賀の有力者とつながりをもったと考えられる"],["考古学の研究者","古墳の形や順番から伊賀の古代史を読み解いてきた"]],"deep":["美旗古墳群は、殿塚古墳を中心に、女良塚古墳・毘沙門塚古墳・馬塚古墳などから構成されるとされます。","殿塚古墳の全長は約90mとされ、伊賀では御墓山古墳に次ぐ規模の前方後円墳と考えられています。","複数の前方後円墳が代々築かれた «首長墓系譜» として研究され、伊賀の首長権の移り変わりを考える材料になっています。","古墳の名前（殿塚・女良塚など）は後世につけられた呼び名で、実際に誰が葬られたかはわかっていません。","«美旗» という地名は、近鉄の駅名としても使われ、古墳群は伊賀市と名張市の境のあたりにまたがる地域にあります。","古墳の多くは私有地の中や近くにあるため、墳丘に上らず、外から見学するのがマナーです。"],"look":["殿塚古墳の前方後円形の墳丘","田園の中に点在する古墳の配置","周濠の跡と考えられる地形"],"q":["美旗古墳群でもっとも大きいとされる前方後円墳の名前は？","殿塚古墳です。全長はおよそ90mとされます。"],"koji":[],"myth":"古墳の被葬者は不明。築造順や規模の数値は資料によって異なる。","img":["前方後円墳","古墳時代","伊賀国"],"wp":"美旗古墳群","rel":{"ev":[],"grave":[]},"ph":[["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"]]},{"id":"24_omihakayama","n":"御墓山古墳（伊賀最大の前方後円墳）","yomi":"おはかやまこふん","cat":"遺跡","rank":"B","y":420,"era":["kofun"],"sh":"国指定史跡","ad":"伊賀市佐那具町・一之宮","st":"JR佐那具駅から歩いて約20分","la":34.797,"lo":136.17,"hook":"全長およそ188m。伊賀でいちばん大きな王の墓を、人々は «大彦命のお墓» とよんで守ってきた。","lead":"御墓山古墳は、伊賀市にある全長約188mの前方後円墳で、三重県で最大の古墳です。5世紀前半ごろにつくられたと考えられています。近くの敢国神社の祭神・大彦命の墓という言い伝えがあり、国の史跡に指定されています。","story":["伊賀盆地の北東、JR佐那具駅の近くに、こんもりと木が茂った長い丘があります。これが御墓山古墳。全長およそ188m、三重県でいちばん大きな前方後円墳です。遠くから見ると自然の山のようですが、実は1500年以上前に人の手で土を盛ってつくられた «人工の山» なのです。","«御墓山» ――御（おん）という字がつくのは、ただのお墓ではないからです。地元では昔から、すぐ近くの敢国神社にまつられる大彦命のお墓だと言い伝えられてきました。大彦命は『日本書紀』に登場する将軍で、伊賀の人々の祖先ともいわれる人物です。","«本当に大彦命のお墓なの?» 考古学では、古墳がつくられたのは5世紀前半ごろと考えられています。大彦命が活躍したとされる時代とは合わないため、実際にはこの時代に伊賀を治めた有力者の墓だろう、というのが一般的な見方です。それでも、人々がこの古墳を «ご先祖の墓» として大切にしてきたこと自体が、伊賀の歴史の一部なのです。","古墳の表面には石がふかれ、段をつくって土を盛っていたと考えられています。また、周りからは埴輪のかけらも見つかっています。これほどの古墳をつくるには、何千人もの人が何年も働いたことでしょう。それだけの人を動かせる力をもった王が、この伊賀にいたのです。","古墳は森におおわれ、なかなか全体を見わたすことはできません。でも、ふもとを歩きながら丘の長さを感じてみると、その大きさに驚かされます。敢国神社とあわせて訪ねれば、«神社と古墳» がセットで語り継がれてきた伊賀の古代の中心地を、肌で感じることができるでしょう。"],"tl":[["5世紀前半ごろ","御墓山古墳が築かれたと考えられる"],["658年","近くに敢国神社が創建されたと伝わる"],["江戸時代以前","大彦命の墓という言い伝えが語られる"],["1921年ごろ","国の史跡に指定される"],["現在","三重県最大の前方後円墳として保存されている"]],"who":[["大彦命","伝承でこの古墳に葬られたとされる人物（敢国神社の祭神）"],["伊賀の古代の王","考古学的にこの古墳の主と考えられる有力者"],["地元の人々","古墳を «御墓» として守ってきた"]],"deep":["全長約188mは三重県最大で、伊賀地方の古墳の中でも群をぬいた大きさです。","築造は5世紀前半ごろと考えられ、伊賀の首長墓としては美旗古墳群より古い段階に位置づけられるといわれます。","墳丘には葺石があり、埴輪が並べられていたと考えられています。","大彦命の墓とする伝承は古墳の年代と合わないため、あくまで言い伝えとして扱われます。","近くには敢国神社のほか、古代の伊賀国府や国分寺跡もあり、伊賀の政治・信仰の中心が長く北東部にあったことがうかがえます。","国史跡の指定年は資料で1921年とされることが多いですが、現地の説明板でも確認しましょう。"],"look":["森におおわれた墳丘の長さ","前方部と後円部の高さのちがい","近くの敢国神社（あわせて訪問）"],"q":["御墓山古墳の主と言い伝えられてきたのは誰？","敢国神社の祭神・大彦命です。ただし考古学的には、古墳の年代と合わないとされます。"],"koji":[],"myth":"被葬者を大彦命とするのは伝承。国史跡指定年はやや自信なし。","img":["前方後円墳","大彦命","敢国神社"],"wp":"御墓山古墳","rel":{"ev":[],"grave":[]},"ph":[["c:1/1f/Mihakayama-kofun_zenkei.JPG",6016,4000,"御墓山古墳"],["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"],["c:0/09/%E5%A4%A7%E5%BD%A6%E5%91%BD_%C5%8Chiko_no_mikoto_%E6%97%A5%E6%9C%AC%E7%99%BE%E5%B0%86%E4%BC%9D.jpg",1145,1737,"大彦命"],["c:4/4c/Aekuni-jinja_haiden.JPG",6016,4000,"敢国神社"]]},{"id":"24_natsumi_haiji","n":"夏見廃寺（大来皇女ゆかりの寺）","yomi":"なつみはいじ","cat":"遺跡","rank":"A","y":700,"era":["asuka","nara"],"sh":"国指定史跡","ad":"名張市夏見","st":"近鉄名張駅から歩いて約20分","la":34.627,"lo":136.115,"hook":"弟を失った姉が、亡き父のために建てたという寺。小さな仏たちのタイルが、1300年前の祈りを伝えている。","lead":"夏見廃寺は、飛鳥時代の終わりから奈良時代の初めごろに建てられたお寺の跡です。天武天皇の娘・大来皇女が、父のために建てた «昌福寺» ではないかといわれています。金堂の壁を飾った «塼仏（せんぶつ）» という焼き物の仏がたくさん見つかっています。","story":["大来皇女（おおくのひめみこ）は、天武天皇の娘です。673年、父が即位すると、彼女は伊勢の神宮に仕える «斎王» に選ばれ、13歳ほどで都を離れました。遠い伊勢で神に仕える日々。そんな彼女の心の支えは、ただ一人の同じ母をもつ弟・大津皇子だったといわれます。","686年、父の天武天皇が亡くなります。そのころ、大津皇子はひそかに伊勢の姉をたずねました。«わが背子を大和へ遣るとさ夜ふけて暁露にわが立ち濡れし» ――夜ふけに帰っていく弟を、朝露にぬれながら見送った姉の歌が『万葉集』に残ります。ほどなく、大津皇子は謀反の罪をきせられ、命を落としました。","斎王の役を解かれて都に戻った大来皇女は、二上山に葬られた弟を思い、歌を詠みました。«うつそみの人にある我や明日よりは二上山を弟世と我が見む»。明日からはあの山を弟と思って見よう――深い悲しみがこめられた一首です。","奈良の薬師寺に伝わる記録には、大来皇女が父・天武天皇のために «昌福寺» という寺を建てたことが書かれています。名張の夏見廃寺がその昌福寺ではないか、と考えられているのです。«なぜ名張に?» 名張は大和から伊勢へ向かう道の途中。斎王として通った道の近くに、父をしのぶ寺を建てたのかもしれません。","発掘では、金堂や塔の跡のほか、たくさんの塼仏が見つかりました。塼仏は、型に粘土を押しあてて仏の姿を浮き出させ、焼いた小さなタイルです。これを壁一面に並べ、金色に輝く «千の仏の壁» にしていたと考えられています。今、跡地は史跡公園になり、そばの展示館で塼仏や復元された金堂の壁を見ることができます。"],"tl":[["673年","大来皇女が斎王に選ばれる"],["686年","天武天皇が亡くなり、大津皇子が死を賜る"],["686年","大来皇女が斎王を退き、都へ戻る"],["7世紀末〜8世紀初め","夏見廃寺（昌福寺か）が建てられる"],["701年","大来皇女が亡くなる"],["現在","国指定史跡として整備され、展示館で塼仏などを公開"]],"who":[["大来皇女","天武天皇の娘で伊勢斎王。昌福寺を建てたと記される"],["天武天皇","大来皇女の父。寺はその供養のためとされる"],["大津皇子","大来皇女の弟。謀反の罪で死を賜った"],["持統天皇","天武天皇の皇后。大津皇子の事件の背景にいたとされる"]],"deep":["夏見廃寺を昌福寺とする説は、『薬師寺縁起』の記事にもとづくもので、有力ですが確定ではありません。","塼仏は、大型の «方形三尊塼仏» などが出土しており、中央の仏と両脇の菩薩を表したものがあります。","塼仏は同じ型からたくさん作ることができ、壁一面に同じ仏を並べて «千仏» のような壁面をつくったと考えられています。","大来皇女の歌は『万葉集』巻2に、大津皇子の事件にかかわる歌としてまとめて収められています。","大津皇子の死の背景には、皇后（のちの持統天皇）が我が子・草壁皇子を皇位につけたかったことがあるという見方が一般的ですが、史料は多くありません。","跡地の史跡公園では、基壇の位置が示され、寺の広がりを歩いて確かめることができます。"],"look":["史跡公園の金堂・塔の基壇跡","夏見廃寺展示館の塼仏と復元壁","名張の町と伊賀・大和を結ぶ道の地形"],"q":["型に粘土を押しあてて仏の姿を浮き出させた、小さな焼き物のタイルを何という？","«塼仏（せんぶつ）» です。夏見廃寺では金堂の壁を飾っていたと考えられています。"],"koji":[],"myth":"夏見廃寺＝昌福寺説は有力だが確定ではない。大津皇子事件の背景も諸説。","img":["大来皇女","大津皇子","斎宮","天武天皇"],"wp":"夏見廃寺","rel":{"ev":[],"grave":[]},"ph":[["c:9/9e/Natsumi_Haiji%2C_gaikan-1.jpg",6016,4000,"夏見廃寺"],["c:c/c3/Prince_Otsu.jpg",1342,1342,"大津皇子"],["c:b/ba/Saiku_Heian_no_Mori_1.jpg",4608,3456,"斎宮"],["c:b/b9/%E5%A4%A9%E6%AD%A6%E5%A4%A9%E7%9A%87%E5%BE%A1%E5%BD%B1%E3%80%81%E9%87%91%E5%89%9B%E5%B1%B1%E5%AF%BA%E6%89%80%E8%94%B5.jpg",425,591,"天武天皇"]]},{"id":"24_kuroda_sho","n":"黒田荘（東大寺の荘園と悪党）","yomi":"くろだのしょう","cat":"伝承","rank":"B","y":1250,"era":["nara","heian","kamakura"],"sh":"","ad":"名張市黒田","st":"近鉄名張駅からバス・車で約10分","la":34.643,"lo":136.095,"hook":"奈良の大仏を建てた寺が、伊賀の山を «自分の土地» にした。数百年後、その土地で «悪党» が立ち上がる。","lead":"黒田荘は、名張市の黒田あたりに広がっていた東大寺の荘園です。はじめは東大寺の建物に使う木材を切り出す山でしたが、やがて田畑をふくむ大きな荘園になりました。鎌倉時代には、東大寺に従わない «悪党» とよばれる人々が現れ、歴史研究の中でも有名な荘園になりました。","story":["奈良時代、東大寺は大仏殿をはじめ、たくさんの建物を建てていました。そのためには、大量の木材が必要です。そこで目をつけたのが、奈良から山をこえた伊賀の名張の山でした。この山は «板蝿杣（いたばえのそま）» とよばれ、切り出された木は名張川から木津川へと流され、奈良へ運ばれたといわれます。","«杣» とは、木を切り出すための山のこと。最初は山だけだった東大寺の土地は、平安時代になると、ふもとの田畑にまで広がっていきました。«山で働く人の食べ物をつくる田も、東大寺のものだ» ――そうした主張を重ねて、東大寺は «黒田荘» という大きな荘園をつくりあげたのです。","けれども、伊賀の国の役人（国司）は、東大寺が勝手に土地を広げていると考え、税を取ろうとしました。東大寺と国司の争いは、何十年、何百年も続きます。荘園の人々は、そのあいだで苦しい立場に置かれました。«私たちはいったい誰の民なのか?» ――そんな思いがあったかもしれません。","鎌倉時代の後半になると、荘園の中から東大寺の命令に従わず、年貢を納めず、武力で抵抗する人々が現れます。東大寺は彼らを «悪党» とよびました。«悪党» といっても、今でいう «悪人» とは少しちがい、«支配する側に逆らう強い者たち» という意味あいがありました。黒田の悪党は、何度も幕府に訴えられるほど手ごわい相手でした。","戦後、歴史学者の石母田正は、この黒田荘をくわしく研究し、『中世的世界の形成』という本を書きました。古い支配にしばられた荘園の中から、新しい時代の力が生まれてくる――黒田荘はその «舞台» として、教科書に名前がのるほど有名になりました。今の黒田の田園風景を歩くと、そこに生きた人々の長い戦いが思いうかびます。"],"tl":[["奈良時代","名張の山が東大寺の «板蝿杣» となる"],["平安時代","杣のふもとの田畑にも東大寺の支配が広がり、黒田荘が成立"],["平安〜鎌倉時代","東大寺と伊賀の国司が土地をめぐって争う"],["鎌倉時代後半","東大寺に従わない «黒田悪党» が現れる"],["南北朝・室町時代","荘園の支配がしだいに崩れていく"],["1946年","石母田正『中世的世界の形成』で黒田荘が論じられる"]],"who":[["東大寺","黒田荘の領主。木材と年貢を求めた"],["伊賀の国司","東大寺と土地・税をめぐって争った"],["黒田悪党","鎌倉時代後半、東大寺に抵抗した荘園の人々"],["石母田正","黒田荘を研究し、中世史研究に大きな影響を与えた歴史学者"]],"deep":["«杣» から «荘» へと支配が広がる過程は、寺社が荘園を拡大していく典型例として研究されています。","東大寺には黒田荘に関する多くの文書が伝わり（東大寺文書）、荘園研究の宝庫となっています。","«悪党» は鎌倉時代後期から南北朝期に各地で現れ、楠木正成も悪党的な武士だったとする見方があります。","黒田悪党の中心人物として、荘官の一族の名が文書に見えますが、人物像には不明な点が多いです。","石母田正の研究は、その後の研究者から批判や修正も受けており、黒田荘の理解は今も更新され続けています。","荘園の範囲ははっきりした遺構として残っているわけではなく、現地に «黒田荘跡» の大きな史跡があるわけではありません。地名と地形から当時を想像しながら歩きましょう。"],"look":["名張川と周辺の山々（杣の風景）","黒田の田園と集落の地形","名張の町から見る伊賀と大和の境の山並み"],"q":["東大寺が木材を切り出すための山として名張に持っていた土地を何という？","«板蝿杣（いたばえのそま）» です。これが黒田荘のはじまりとなりました。"],"koji":[],"myth":"木材の運搬ルートや悪党の人物像は史料解釈に諸説。荘園の範囲は確定的でない。","img":["荘園","悪党","東大寺","石母田正"],"wp":"黒田荘","rel":{"ev":[],"grave":[]},"ph":[["c:a/a7/%E6%9D%B1%E5%A4%A7%E5%AF%BA_%E5%A4%A7%E4%BB%8F%E6%AE%BF%EF%BC%882024%E5%B9%B4%EF%BC%89.jpg",4032,3024,"東大寺"]]},{"id":"24_nabari_todo","n":"名張藤堂家邸","yomi":"なばりとうどうけてい","cat":"大名屋敷","rank":"B","y":1636,"era":["edo"],"sh":"県指定史跡","ad":"名張市丸之内","st":"近鉄名張駅から歩いて約5分","la":34.6262,"lo":136.1,"hook":"大名にはなれなかった «殿さま» の屋敷。名張の町の中に、その家の200年あまりの暮らしが残っている。","lead":"名張藤堂家邸は、江戸時代に名張を治めた藤堂家（名張藤堂家）の屋敷の跡です。名張藤堂家は、津藩の一族で、大名ではなく藩の重臣という立場でした。屋敷の一部が残り、県の史跡として公開されています。","story":["名張藤堂家のはじまりは、藤堂高吉という人物です。高吉は、もとは織田信長の重臣・丹羽長秀の子として生まれ、のちに藤堂高虎の養子になりました。高虎にはまだ実の子がいなかったため、高吉は跡つぎとして期待されました。ところが、やがて高虎に実子の高次が生まれると、高吉の立場は大きく変わってしまいます。","高吉はその後、伊予の今治などを治めていましたが、1636年、伊賀の名張へ移ることになりました。«なぜ名張だったのか?» 津藩の領地の中に、高吉の家を置くためでした。こうして名張藤堂家は、津藩の中の重臣の家として、名張の町を治めることになったのです。","名張藤堂家は、1万5千石ほどを治める、大名に近い力をもつ家でした。それでも身分はあくまで津藩の家臣。«独立した大名になりたい» という思いは、代々の当主の中にくすぶっていたといわれます。江戸時代の中ごろには、その願いをめぐって津藩との間に大きな騒ぎが起こり、関係者が処罰されたと伝わります。","屋敷は、名張川にほど近い町の中心にありました。火事で焼けたこともありましたが、そのたびに建て直され、明治まで名張藤堂家の住まいとして使われました。今は屋敷の一部が残り、座敷や部屋を見学できます。当時の家具や道具、藤堂家に伝わった品も展示されています。","藤堂家の屋敷を中心に、名張の町は «城下町» のように発展しました。今も屋敷のまわりには古い町並みの雰囲気が残り、細い道を歩くと江戸時代の町割りを感じることができます。大名にはなれなかったけれど、名張の人々にとっては «うちの殿さま»。そんな家の歴史にふれられる場所です。"],"tl":[["1579年","藤堂高吉、丹羽長秀の子として生まれる"],["1580年代","藤堂高虎の養子となる"],["1636年","高吉が伊賀の名張に移る（名張藤堂家のはじまり）"],["江戸時代中期","独立をめぐって津藩との間で騒ぎが起こる（名張騒動）"],["1871年","廃藩置県により、名張藤堂家の支配が終わる"],["現在","屋敷の一部が県史跡として公開されている"]],"who":[["藤堂高吉","名張藤堂家の初代。丹羽長秀の子で、藤堂高虎の養子"],["藤堂高虎","津藩の藩祖。高吉の養父"],["藤堂高次","高虎の実子。津藩2代藩主"],["丹羽長秀","織田信長の重臣。高吉の実の父"]],"deep":["高吉は長生きした武将で、戦国の合戦から江戸時代の泰平までを見とどけた人物でした。","石高は約1万5千石とされ、大名の基準（1万石以上）に届く規模でしたが、独立は認められませんでした。","江戸時代中期の «名張騒動» は、名張藤堂家の独立の動きをめぐる事件とされ、家臣が処罰されたと伝わります。","屋敷の建物は、火災と再建をくり返したとされ、現存部分がいつの時代のものかは案内で確かめるとよいでしょう。","高吉の生涯は、戦国から江戸への移り変わりの中で «跡つぎ» をめぐって揺れた武将の典型例といえます。","名張の町には、屋敷を中心とした道の配置や町名など、名張藤堂家の時代の名残が見られます。"],"look":["残された座敷と部屋のつくり","名張藤堂家に伝わった資料の展示","屋敷周辺の古い町並み"],"q":["名張藤堂家の初代・藤堂高吉の実の父は誰？","織田信長の重臣・丹羽長秀です。のちに藤堂高虎の養子になりました。"],"koji":[],"myth":"名張騒動の年や経緯、屋敷の現存部分の年代は資料で確認を。","img":["藤堂高吉","藤堂高虎","名張市","丹羽長秀"],"wp":"名張藤堂家","rel":{"ev":[],"grave":[]},"ph":[["c:e/e2/Toudou_Takatora.jpg",1056,1096,"藤堂高虎"],["c:4/46/Akame48Taki_NinaiTaki.jpg",972,648,"名張市"],["c:5/5f/Niwa_Nagahide2.jpg",1692,3660,"丹羽長秀"]]},{"id":"24_momochi","n":"百地丹波の砦（伊賀忍者の伝承）","yomi":"ももちたんばのとりで","cat":"伝承","rank":"B","y":1581,"era":["muromachi","azuchi"],"sh":"","ad":"名張市竜口","st":"近鉄赤目口駅から車で約10分（公共交通では行きにくい）","la":34.595,"lo":136.085,"hook":"伊賀の «上忍» として語りつがれる百地丹波。山あいに残る砦の跡は、伝説と歴史の境目に立っている。","lead":"百地丹波は、戦国時代の伊賀で力をもった地侍の一人で、のちに «伊賀忍者の頭（上忍）» として有名になった人物です。名張市竜口には、百地氏が築いたと伝わる砦の跡が残っています。伊賀市喰代にも百地氏の城跡とされる場所があります。","story":["戦国時代の伊賀には、国をまとめる大名がいませんでした。かわりに、村々の地侍たちが寄り合いで物事を決めていました。百地氏もそうした地侍の一族で、名張の山あいに館と砦をかまえていたと伝わります。山の上から谷を見下ろせば、近づく敵の動きが一目でわかりました。","江戸時代以降、百地丹波は «伊賀の三大上忍» の一人として語られるようになります。服部氏・藤林氏とならび、多くの忍びを率いた «忍者の親分» というわけです。けれども、«忍者の親分» という姿のどこまでが本当なのかは、はっきりしません。確かな史料は少なく、多くは後の時代の書物や物語に頼っているのです。","1581年、織田信長の大軍が伊賀に攻めこみました。天正伊賀の乱です。伊賀の地侍たちは山や砦に立てこもって戦いましたが、圧倒的な数の前に敗れていきました。百地丹波もこの戦いに加わったと伝わり、名張の柏原城に最後まで立てこもった一人だったともいわれます。«伊賀の地は伊賀の者が守る» ――その覚悟は本物だったでしょう。","百地丹波には、ほかにも不思議な伝説がたくさんあります。大泥棒・石川五右衛門の忍術の師匠だった、あるいは «百地三太夫» と同じ人物だった、というのもその一つです。ただし、これらは江戸時代の芝居や講談、近代の小説などで広まった話と考えられています。","竜口の砦跡は、山の中に土塁や平らな段が残る静かな場所です。案内板を頼りに山道を歩くと、戦国の伊賀の人々が、どんな場所で暮らし、戦ったのかを想像できます。«忍者» という言葉のイメージからはなれて、山里を守った地侍の姿を思いうかべてみてください。"],"tl":[["室町時代","百地氏が伊賀南部で地侍として力をもつ"],["1579年","第一次天正伊賀の乱。伊賀勢が織田信雄の軍を退ける"],["1581年","第二次天正伊賀の乱。伊賀の地侍たちが敗れる"],["1581年","柏原城の籠城戦ののち、伊賀が降伏したと伝わる"],["江戸時代以降","百地丹波が «伊賀の上忍» として物語に描かれる"],["現在","名張市竜口などに砦跡・城跡が伝わる"]],"who":[["百地丹波","伊賀の地侍。伝承で «三大上忍» の一人とされる"],["織田信長","1581年に伊賀を攻めた"],["石川五右衛門","伝説で百地丹波の弟子とされる大泥棒（物語上の話）"],["服部氏・藤林氏","百地氏とならぶ伊賀の «上忍» の家として語られる"]],"deep":["«伊賀の三大上忍»（服部・藤林・百地）という言い方は、江戸時代以降の書物などで広まったもので、戦国時代の実際の身分制度とは言い切れません。","百地丹波の実名や生没年には諸説があり、確かな史料で確認できる点は多くありません。","伊賀市喰代には «百地氏城跡» があり、近くの青雲寺には百地丹波ゆかりの伝承があります。","«百地三太夫» は講談や小説で有名になった名前で、百地丹波と同一人物とする説としない説があります。","石川五右衛門が百地のもとで忍術を学んだという話は、江戸時代の芝居などで広まった創作と考えられています。","砦跡は山の中にあり、道がわかりにくい場所もあります。地元の案内や地図で確認し、単独での山歩きには注意しましょう。"],"look":["山中に残る土塁や曲輪（平らな段）の跡","砦から見下ろす谷の地形","伊賀市喰代の百地氏城跡（あわせて訪問）"],"q":["百地丹波とともに «伊賀の三大上忍» とされる家は？","服部氏と藤林氏です。ただし «三大上忍» は後の時代に広まった言い方です。"],"koji":[],"myth":"百地丹波の実名・柏原城籠城・石川五右衛門の師匠説・百地三太夫との同一視は伝承や創作を含む。","img":["天正伊賀の乱","石川五右衛門","忍者"],"wp":"百地丹波","rel":{"ev":[],"grave":[]},"ph":[["c:3/39/Excecution_of_Goemon_Ishikawa.jpg",1727,2471,"石川五右衛門"],["c:1/11/Eight_Hundred_Heroes_of_Our_Country_s_Suikoden_12.jpg",913,1318,"忍者"]]},{"id":"24_hana_iwaya","n":"花の窟神社（日本最古の神社伝承）","yomi":"はなのいわやじんじゃ","cat":"寺社","rank":"A","y":720,"era":["myth","nara"],"sh":"世界遺産「紀伊山地の霊場と参詣道」構成資産","ad":"熊野市有馬町","st":"JR熊野市駅から歩いて約25〜30分（バスや車も便利）","la":33.8736,"lo":136.1034,"hook":"社殿はない。見上げるほどの巨大な岩そのものが、国を生んだ女神イザナミの眠る場所として祈られてきた。","lead":"花の窟神社は、熊野灘に面した高さ約45mの大きな岩をご神体とする神社です。『日本書紀』に、イザナミノミコトが葬られた場所として書かれていることから、«日本最古の神社» ともいわれます。世界遺産の一部にもなっています。","story":["日本の神話で、イザナギとイザナミの夫婦の神は、日本の島々や多くの神々を生みました。ところが、火の神カグツチを生んだとき、イザナミは大やけどを負って亡くなってしまいます。«母なる女神はどこに葬られたのか?» ――『日本書紀』の一つの伝えには、«紀伊国の熊野の有馬村に葬った» と書かれています。","その場所こそが、ここ花の窟だといわれます。熊野灘の浜辺近く、そびえ立つ白っぽい岩壁。社殿はなく、岩そのものが神さまなのです。『日本書紀』には、土地の人々が «花の咲く時には花でまつり、鼓や笛を鳴らし、旗を立てて歌い舞ってまつる» と記されています。«花の窟» という名前は、この花のまつりからきているのです。","今も年に2回、2月2日と10月2日に «お綱かけ神事» が行われます。長さ170mほどもある大綱を、岩のてっぺんから浜の方へ張りわたすのです。綱には季節の花などを結んだ «旗» がつるされ、参拝者も一緒に綱を引きます。神話に書かれたまつりの形が、1300年たった今も生きているように感じられます。","岩の向かいには、火の神カグツチをまつる «王子の窟» もあります。母と子の神が、向かい合うようにまつられているのです。«子を生んで命を落とした母» と «母を死なせてしまった子»。神話の悲しい物語が、この静かな場所に重なっています。","2004年、花の窟は «紀伊山地の霊場と参詣道» の一部として世界遺産になりました。熊野古道の伊勢路の途中にあたり、昔から熊野三山へ向かう人々が立ち寄りました。浜に出ると、目の前には七里御浜の長い砂浜と熊野灘。波の音を聞きながら岩を見上げると、この地が «神話の舞台» として選ばれた理由がわかるような気がします。"],"tl":[["神話の時代","イザナミが熊野の有馬村に葬られたと伝わる"],["720年","『日本書紀』に有馬村での葬りと花のまつりが記される"],["平安時代以降","熊野詣の人々が立ち寄る"],["江戸時代","伊勢から熊野へ向かう伊勢路の名所として知られる"],["2004年","世界遺産 «紀伊山地の霊場と参詣道» の構成資産に"],["現在","2月2日と10月2日にお綱かけ神事が行われる"]],"who":[["イザナミノミコト","国生みの女神。この地に葬られたと伝わる"],["カグツチ","イザナミが最後に生んだ火の神。王子の窟にまつられる"],["有馬の人々","花のまつりとお綱かけ神事を受けついできた"],["熊野詣の旅人","伊勢路をたどって花の窟に立ち寄った"]],"deep":["イザナミを熊野に葬る話は『日本書紀』の本文ではなく «一書に曰く»（別の伝え）として記されたものです。『古事記』では出雲と伯耆の境の比婆山に葬ったとされます。","«日本最古の神社» という言い方は、『日本書紀』に祭りのようすが書かれていることからきた呼び名で、学問的に «最古» と確かめられたわけではありません。","お綱かけ神事は三重県の無形民俗文化財に指定されています。","ご神体の岩の高さは約45mとされ、岩肌には «ほと» とよばれるくぼみがあり、女神の象徴として拝まれてきたといわれます。","社殿をもたず、岩や山そのものを拝む形は、神社の古い姿を伝えると考えられています。","花の窟から熊野市駅方面へ続く七里御浜も、世界遺産の構成資産（熊野参詣道伊勢路の一部）です。"],"look":["ご神体の巨岩と、岩の上から張られた綱","向かいの王子の窟","浜に出て見る七里御浜と熊野灘","神事の日（2月2日・10月2日）の綱引き"],"q":["花の窟のお綱かけ神事は、年に何回行われる？","2回です。2月2日と10月2日に行われます。"],"koji":[],"myth":"イザナミの葬地は『古事記』では別の場所。«日本最古の神社» は伝承上の呼び名。","img":["伊邪那美命","紀伊山地の霊場と参詣道","七里御浜"],"wp":"花の窟神社","rel":{"ev":[],"grave":[]},"ph":[["c:0/0b/Hananoiwaya_Shrine03.jpg",1000,750,"花の窟神社"],["c:8/84/Kobayashi_Izanami_and_Izanagi.jpg",592,1307,"伊邪那美命"],["c:7/73/Daimonzaka25_2048.jpg",1536,2048,"紀伊山地の霊場と参詣道"],["c:8/8f/Shichirimihama-2.jpg",352,288,"七里御浜"]]},{"id":"24_maruyama_senmaida","n":"丸山千枚田","yomi":"まるやませんまいだ","cat":"産業","rank":"B","y":1601,"era":["azuchi","edo","heisei"],"sh":"","ad":"熊野市紀和町丸山","st":"JR熊野市駅から車で約40分（公共交通では行きにくい）","la":33.866,"lo":136.033,"hook":"山の斜面に、小さな田が階段のように1000枚以上。400年前の人々が、石と土で山をきざんだ «祈りの風景»。","lead":"丸山千枚田は、熊野市紀和町の山の斜面に広がる棚田です。江戸時代の初めにはすでに2000枚以上の田があったと記録されています。一時は荒れ地になりかけましたが、地元の人々の努力で1300枚ほどが復元されました。«日本の棚田百選» に選ばれています。","story":["熊野の山は深く、平らな土地はほとんどありません。それでも人々は、生きるためにお米をつくりたいと願いました。«平らな土地がないなら、つくればいい» ――山の斜面に石を積み、土を盛って、小さな平らな田を一枚、また一枚。こうして生まれたのが、丸山千枚田です。","1601年に行われた検地（田畑の調査）の記録には、この地に2000枚をこえる田があったと書かれているといいます。1600年といえば関ヶ原の戦いの年。天下分け目の戦いが起こっていたころ、熊野の山奥では、人々が黙々と田を耕していたのです。","田の一枚一枚はとても小さく、中には畳数枚ほどのものもあります。«なぜこんなに小さいの?» それは、斜面が急で、大きな田をつくると石垣が崩れてしまうからです。水は山の上から、田から田へと順に流れていきます。一枚の田の水の管理をおこたると、下の田すべてに影響が出る――村全体で力を合わせなければ、守れない田んぼでした。","しかし昭和の終わりごろになると、若い人は町へ出て、田を耕す人が減っていきました。田は荒れ、500枚ほどにまで減ってしまったといわれます。«このままでは、先祖が残した千枚田がなくなってしまう» ――そう考えた地元の人々は、1990年代に保存会をつくり、荒れた田をよみがえらせる活動を始めました。","今、千枚田にはオーナー制度があり、都会の人たちも田植えや稲刈りに参加しています。夏には «虫おくり» という行事があり、たいまつを持った行列が田のあぜを歩いて、害虫を追い払い豊作を祈ります。夕暮れの棚田に火の列がゆらめくようすは、まるで400年前にタイムスリップしたかのようです。"],"tl":[["1601年","検地の記録に2000枚以上の田が記されるといわれる"],["江戸時代","山あいの村の人々が棚田を耕し続ける"],["昭和後期","過疎化で耕作放棄が進み、田が大きく減る"],["1990年代","地元の保存会が結成され、復田の取り組みが始まる"],["1999年","«日本の棚田百選» に選ばれる"],["現在","約1300枚の田が耕され、虫おくりなどの行事が続く"]],"who":[["丸山の人々","400年にわたって棚田を耕し守ってきた"],["丸山千枚田保存会","荒れた田を復元し、棚田を守る活動を続ける"],["棚田オーナー","都会などから田植え・稲刈りに参加する人々"]],"deep":["1601年の検地の記録で2240枚とする数字がよく紹介されますが、記録の詳細は現地の資料で確かめるとよいでしょう。","棚田の石垣は、地元の石を積み上げたもので、崩れた石垣を積み直す技術の継承も課題になっています。","«虫おくり» は、稲につく害虫を村の外へ送り出すための農村行事で、全国各地に似た行事があります。","一時500枚ほどに減った田は、保存会の活動などによって約1300枚ほどにまで回復したとされます。","紀和町は、かつて紀州鉱山で栄えた町でもあり、農業と鉱業の二つの顔をもつ地域でした。","展望所からは千枚田全体を見わたすことができ、田植えのころの水鏡や稲刈り前の黄金色など、季節ごとに風景が変わります。"],"look":["展望所から見る千枚田の全景","小さな田と石垣のつくり","初夏の虫おくり（行事の日程は要確認）"],"q":["丸山千枚田で、害虫を追い払い豊作を祈る火の行事を何という？","«虫おくり» です。たいまつを持った行列があぜを歩きます。"],"koji":[],"myth":"1601年検地の枚数（2240枚）、減少・復元後の枚数は資料によって数字が異なる。","img":["棚田","日本の棚田百選","紀和町"],"wp":"丸山千枚田","rel":{"ev":[],"grave":[]},"ph":[["c:e/e6/2011_07_13%E4%B8%B8%E5%B1%B1%E5%8D%83%E6%9E%9A%E7%94%B0%E5%85%A8%E6%99%AF.jpg",1000,667,"丸山千枚田"],["c:f/ff/RiceTerracesVietnam.jpg",4752,3168,"棚田"],["c:7/77/Aragijima003.JPG",4032,3024,"日本の棚田百選"]]},{"id":"24_kishu_kozan","n":"紀州鉱山跡と英国人墓地","yomi":"きしゅうこうざんあととえいこくじんぼち","cat":"昭和","rank":"A","y":1944,"era":["showa"],"sh":"","ad":"熊野市紀和町板屋・入鹿","st":"JR熊野市駅から車で約40分（公共交通では行きにくい）","la":33.883,"lo":136.024,"hook":"山奥の銅山の町に、遠いイギリスの兵士たちが眠る墓がある。その墓を、町の人たちは70年以上守り続けてきた。","lead":"紀州鉱山は、熊野市紀和町にあった銅などをとる鉱山で、昭和の時代に大きく栄えました。第二次世界大戦中、この鉱山ではイギリス人の捕虜が働かされ、その中で亡くなった人たちの墓が今も残っています。地元の人々が長年、心をこめてお世話を続けてきました。","story":["紀和町の山は、昔から銅がとれることで知られていました。鉱山の歴史は古く、奈良時代にさかのぼるという言い伝えもあります。昭和の初めになると、石原産業が本格的な開発を始め、紀州鉱山は大きく発展しました。山あいに社宅や学校、病院ができ、一時は1万人をこえる人が暮らす «鉱山の町» になったといわれます。","第二次世界大戦中の1944年、この鉱山に300人ほどのイギリス人の捕虜が連れてこられました。東南アジアで捕らえられた兵士たちで、慣れない寒さと食料不足の中、鉱山での重い労働をさせられたのです。«なぜ、こんな山奥に?» 戦争で働き手が足りなくなった日本は、各地の鉱山や工場で捕虜を働かせていました。","厳しい環境の中で、捕虜のうち16人が命を落としたとされます。故郷から遠く離れた日本の山の中で、家族に会うこともかなわず亡くなった若者たち。戦争が終わると、生き残った人々は国へ帰っていきましたが、亡くなった人々の墓はこの地に残されました。","その墓を守り続けたのは、地元の人々でした。«異国の地で亡くなった人を、放っておくわけにはいかない» ――墓はきれいに整えられ、花が絶えることはなかったといいます。やがてこの話はイギリスにも伝わり、元捕虜や遺族、大使館の人たちが墓参りに訪れるようになりました。かつての敵と味方が、墓の前で一緒に祈る――戦争の悲しみを越えた交流が生まれたのです。","紀州鉱山は1978年に閉山し、町の人口は大きく減りました。今は «熊野市紀和鉱山資料館» で、鉱山の歴史や当時の暮らしを学ぶことができます。英国人墓地も静かに保たれています。鉱山の繁栄と戦争の記憶、そして人と人とのつながり。この小さな山あいの町は、たくさんのことを語りかけてくれます。"],"tl":[["古代〜近世","紀和の山で銅がとられていたと伝わる"],["1934年ごろ","石原産業が紀州鉱山の本格的な開発を始める"],["1944年","イギリス人捕虜約300人が鉱山に連れてこられる"],["1945年","終戦。捕虜のうち16人がこの地で亡くなっていた"],["1978年","紀州鉱山が閉山する"],["現在","紀和鉱山資料館が鉱山の歴史を伝え、英国人墓地が守られている"]],"who":[["イギリス人捕虜","戦時中に鉱山で働かされ、16人が亡くなった"],["石原産業","紀州鉱山を開発・経営した会社"],["紀和町の人々","英国人墓地を長年守り続けてきた"],["元捕虜と遺族","戦後、墓参りに訪れ交流を深めた"]],"deep":["紀州鉱山は銅のほか、硫化鉄などもとれる鉱山で、昭和期の日本の鉱業を支えた鉱山の一つでした。","英国人捕虜は、東南アジア（シンガポールなど）で捕虜となった兵士たちと考えられています。","地元の人々は戦後、墓を守るだけでなく、慰霊祭を行い、イギリスとの交流を続けてきました。","鉱山の廃止後、紀和町の人口は大きく減り、今は過疎の山里になっています。","鉱山で使われたトロッコの線路の一部は、観光用の «トロッコ電車» として活用されたこともあります。","紀和鉱山資料館では、鉱石の標本や採掘の道具、鉱山の町の暮らしの様子が展示されています。"],"look":["英国人墓地と慰霊碑","熊野市紀和鉱山資料館の展示","鉱山の町のなごりが残る紀和の町並み"],"q":["紀州鉱山で亡くなったイギリス人捕虜は何人とされる？","16人です。地元の人々が墓を守り続けてきました。"],"koji":[],"myth":"鉱山の起源（奈良時代説）は伝承。捕虜の人数・開発開始年は資料で数字に幅がある。","img":["石原産業","紀和町","捕虜"],"wp":"紀州鉱山","rel":{"ev":[],"grave":[]},"ph":[["c:f/f1/Yumoto_Sanso_Yunokuchi_Spa.jpg",4608,3456,"紀州鉱山"],["c:7/7d/Ishihara-Sangyo-hq_Osaka_Japan01-r.jpg",2672,4000,"石原産業"],["c:e/e6/2011_07_13%E4%B8%B8%E5%B1%B1%E5%8D%83%E6%9E%9A%E7%94%B0%E5%85%A8%E6%99%AF.jpg",1000,667,"紀和町"],["c:8/8b/Gorskii._Austrian_prisoners_of_war_in_Olonets_province.jpg",3234,2792,"捕虜"]]},{"id":"24_jofuku","n":"徐福の宮（波田須の徐福伝説）","yomi":"じょふくのみや","cat":"伝承","rank":"B","y":-219,"era":["yayoi","myth"],"sh":"","ad":"熊野市波田須町","st":"JR波田須駅から歩いて約15分","la":33.925,"lo":136.16,"hook":"«不老不死の薬を探してこい» ――秦の始皇帝の命を受けた男は、海をわたって熊野の小さな浜に着いた、と伝わる。","lead":"徐福は、今から2200年以上前、中国の秦の時代の人物です。始皇帝の命令で不老不死の薬を探しに東の海へ船出したと、中国の歴史書『史記』に書かれています。熊野市波田須町には、徐福がこの地にたどり着いたという伝説があり、«徐福の宮» がまつられています。","story":["紀元前3世紀、中国を初めて統一した秦の始皇帝は、ある願いをもっていました。«死にたくない»。そこで方士（仙人の術を研究する人）の徐福が、«東の海に仙人の住む三神山があり、そこに不老不死の薬があります» と申し出ます。始皇帝は、たくさんの若者や技術者、五穀の種をもたせて、徐福を船出させました。","しかし徐福は、二度と中国に戻りませんでした。『史記』には、徐福が «平原広沢» を得て王となり、帰らなかったと書かれています。«徐福はどこへ行ったのか?» ――その答えを求めて、日本の各地に «徐福がやって来た» という伝説が生まれました。そのうちの一つが、ここ熊野の波田須です。","波田須の伝説によれば、徐福の一行はこの浜に上陸し、村に住みついて、焼き物や農業、捕鯨などの技術を伝えたといいます。«波田須（はだす）» という地名は、«秦住（はたす）»、つまり «秦の人が住んだ» ことに由来するともいわれます。村の人々は徐福を恩人としてまつり、小高い丘の上に «徐福の宮» を建てました。","徐福の宮のあたりでは、秦の時代の貨幣 «半両銭» が見つかったという話も伝わっています。本当に徐福の一行が持ってきたものなのか、それとも後の時代に誰かが持ちこんだものなのか。はっきりとはわかりません。でも、そうした小さな «なぞ» が、伝説をさらに魅力的にしているのです。","熊野灘をはさんだ和歌山県新宮市にも、徐福の墓とされる場所があり、徐福公園として整えられています。日本全国に徐福の伝説が残る場所は、20か所以上ともいわれます。海のかなたからやってきた人々が、新しい技術や文化を伝えた――徐福の伝説は、弥生時代に大陸から多くの人が渡ってきた、そんな歴史の記憶を映しているのかもしれません。"],"tl":[["紀元前221年","秦の始皇帝が中国を統一する"],["紀元前219年ごろ","徐福が不老不死の薬を求めて東の海へ船出したと『史記』に記される"],["伝承の時代","徐福の一行が波田須に上陸し、技術を伝えたと伝わる"],["後世","波田須の人々が徐福の宮をまつる"],["現在","熊野・新宮など各地で徐福伝説が語りつがれている"]],"who":[["徐福","秦の方士。不老不死の薬を求めて船出した人物"],["秦の始皇帝","中国を統一した皇帝。徐福に薬を探させた"],["司馬遷","『史記』を書いた歴史家。徐福の話を記録した"],["波田須の人々","徐福を恩人としてまつってきた"]],"deep":["『史記』の «秦始皇本紀» や «淮南衡山列伝» に徐福（徐巿）の記事があり、実在の人物と考えられていますが、日本に来たことを示す確かな史料はありません。","«波田須＝秦住» という地名の由来は、伝承によるもので、学問的に確かめられたものではありません。","半両銭の発見の話は伝えられていますが、発見の状況や年代についてははっきりしません。","徐福伝説は、佐賀県・和歌山県・山梨県など全国各地にあり、それぞれ上陸地や墓の伝承をもっています。","徐福が不老不死の薬として探したものを «天台烏薬» とする伝承があり、新宮市などでその木が植えられています。","徐福の出航の年ははっきりせず、『史記』の記事の年などから紀元前219年ごろとされることが多いです。"],"look":["丘の上の徐福の宮","波田須の浜と熊野灘の眺め","熊野古道伊勢路の石畳（近くを通る）"],"q":["徐福に不老不死の薬を探させた中国の皇帝は？","秦の始皇帝です。中国を初めて統一した皇帝として知られます。"],"koji":[{"w":"不老不死","m":"年をとらず、死なないこと。始皇帝が求めた永遠の命"}],"myth":"徐福の日本渡来は伝説で確証なし。地名の由来、半両銭の発見の話も伝承。","img":["始皇帝","史記","熊野古道"],"wp":"徐福","rel":{"ev":[],"grave":[]},"ph":[["c:a/a0/Jo-Fuku.jpg",842,2024,"徐福"],["c:3/3f/QinShiHuang19century.jpg",2188,2944,"始皇帝"]]}];
